import { omit, pick } from 'radash'
import {
  createCoreTextFieldExternalProps,
  type IYCoreTextFieldExternalProps,
} from '~core/ui/textField/models/types'
import {
  createCoreFieldTextareaExternalProps,
  type IYCoreFieldTextareaExternalProps,
} from '~core/ui/fieldTextarea/models/types'

/**
 * Свойства компонента Textarea
 */
export interface IYCoreTextareaExternalProps extends
  Omit<IYCoreTextFieldExternalProps, 'type' | 'maskOptions' | 'annotationText' | 'labelOverflowMode' | 'ellipsis'>,
  Pick<IYCoreFieldTextareaExternalProps, 'rows' | 'resize' | 'autogrow'> {
}

export const createCoreTextareaExternalProps = (): IYCoreTextareaExternalProps => ({
  ...omit(createCoreTextFieldExternalProps(), ['type', 'maskOptions', 'annotationText', 'labelOverflowMode', 'ellipsis']),
  ...pick(createCoreFieldTextareaExternalProps(), ['rows', 'resize', 'autogrow']),
})
