import { css, LitElement, nothing, unsafeCSS } from 'lit'
import { html } from 'lit/static-html.js'
import { customElement, property, state } from 'lit/decorators.js'
import { ifDefined } from 'lit/directives/if-defined.js'
import { classMap } from 'lit/directives/class-map.js'
import { renderIcon } from '~core/renderers'

import {
  createCoreIconButtonProps,
  type IYCoreIconButtonProps,
} from '~core/ui/iconButton/models/types'
import { EYSizes } from '~shared/types/global'
import { YCoreIconButtonTagName as tagName, YCoreTooltipTagName } from '~shared/constants'
import { YC_COMPONENT_ATTRIBUTE_NAME } from '~web/shared/constants/attributes'
import { YC_ICON_BUTTON_ICON_SIZE_BOX_LG, YC_ICON_BUTTON_ICON_SIZE_BOX_SM } from '~shared/constants/tokens'

import YCoreIconButtonScopedCSS from '~core/ui/iconButton/css/IconButton.scoped.css?inline'
import YCoreIconButtonVarsCSS from '~core/ui/iconButton/css/IconButton.vars.css?inline'

import '~core/ui/simpleButton'
import '~core/ui/counter'
import '~core/ui/badge'
import '~core/ui/tooltip'

import { interceptEvents } from '~core/utils/event-interceptor'
import { booleanConverter } from '~core/utils/converters'
import { defineCustomElement } from '~web/shared/utils/components'
import { YCoreTooltip } from '~core/ui/tooltip'

const { disabled, href, icon, loading, size, variant, target, fullWidth, indicator, active, tooltipText, tooltipPlacement } = createCoreIconButtonProps()

@customElement(tagName)
@interceptEvents()
export class YCoreIconButton extends LitElement implements Required<IYCoreIconButtonProps> {
  @property({ type: String }) size: IYCoreIconButtonProps['size'] = size
  @property({ type: String, reflect: true }) variant: IYCoreIconButtonProps['variant'] = variant
  @property({ type: Boolean }) disabled: IYCoreIconButtonProps['disabled'] = disabled
  @property({ type: Boolean, reflect: true, converter: booleanConverter }) loading: IYCoreIconButtonProps['loading'] = loading
  @property({ type: Boolean, reflect: true, converter: booleanConverter }) active: IYCoreIconButtonProps['active'] = active
  @property({ type: String, attribute: 'tooltip-text' }) tooltipText: IYCoreIconButtonProps['tooltipText'] = tooltipText
  @property({ type: String, attribute: 'tooltip-placement' }) tooltipPlacement: IYCoreIconButtonProps['tooltipPlacement'] = tooltipPlacement
  @property({ type: String }) href: IYCoreIconButtonProps['href'] = href
  @property({ type: String }) target: IYCoreIconButtonProps['target'] = target
  @property({ type: Object }) icon: IYCoreIconButtonProps['icon'] = icon
  @property({ type: Boolean, reflect: true, attribute: 'full-width', converter: booleanConverter }) fullWidth: IYCoreIconButtonProps['fullWidth'] = fullWidth
  @property({ type: Object }) indicator: IYCoreIconButtonProps['indicator'] = indicator

  private readonly baseClass = tagName
  private readonly iconWrapperClass = `${this.baseClass}__icon-wrapper`
  private readonly iconClass = `${this.baseClass}__icon`
  private readonly counterWrapperClass = `${this.baseClass}__counter-wrapper`

  private static readonly TOOLTIP_SHOW_DELAY_MS = 1000
  private static readonly TOOLTIP_COOLDOWN_MS = 500

  /**
   * Соглашение по скоупу состояния тултипа:
   *
   * - `this[prop]`                          — состояние данного экземпляра IconButton
   * - `YCoreIconButton[prop]`               — глобальное состояние всех экземпляров IconButton
   * - `YCoreIconButton._activeInstance[prop]` — состояние текущего активного экземпляра IconButton
   */

  /** Глобальный флаг Warm-up: когда `true`, задержка Cold Start не применяется ни для одного экземпляра */
  private static _warmupActive = false

  /** Ссылка на экземпляр с активным тултипом — скрывается при переходе курсора на другую кнопку */
  private static _activeInstance: YCoreIconButton | null = null

  /** Глобальный таймер сброса Warm-up: если не было наведения 500 мс, все экземпляры возвращаются к Cold Start */
  private static _cooldownTimer: ReturnType<typeof setTimeout> | null = null

  @state() private _tooltipVisible = false
  private _showDelayTimer: ReturnType<typeof setTimeout> | null = null

  static readonly styles = [
    css`${unsafeCSS(YCoreIconButtonVarsCSS)}`,
    css`${unsafeCSS(YCoreIconButtonScopedCSS)}`,
  ]

  private resolveIconSize(size: IYCoreIconButtonProps['size']): number {
    switch (size) {
      case EYSizes.SMALL: return YC_ICON_BUTTON_ICON_SIZE_BOX_SM
      case EYSizes.MEDIUM: return YC_ICON_BUTTON_ICON_SIZE_BOX_SM
      case EYSizes.LARGE: return YC_ICON_BUTTON_ICON_SIZE_BOX_LG
      default: return YC_ICON_BUTTON_ICON_SIZE_BOX_SM
    }
  }

  private get computedIconSize() {
    return `${this.resolveIconSize(this.size)}px`
  }

  private get computedIconClass() {
    return [
      this.iconClass,
      this.isBadgeIndicator && `${this.iconClass}_masked`,
      this.disabled && `${this.iconClass}_disabled`,
    ].join(' ')
  }

  private get isIndicatorVisible() {
    return !!this.indicator && !this.disabled && !this.loading
  }

  private get isBadgeIndicator() {
    return this.isIndicatorVisible && this.indicator?.type === 'badge'
  }

  private get computedClasses() {
    return {
      [this.baseClass]: true,
      [`${this.baseClass}_${this.size}`]: true,
      [`${this.baseClass}_active`]: Boolean(this.active),
    }
  }

  private tryActivateTooltip = () => {
    // Курсор мог уйти до обработки callback — mouseleave и setTimeout могут оказаться в одном тике event loop
    if (!this.matches(':hover')) return

    YCoreIconButton._warmupActive = true
    YCoreIconButton._activeInstance = this
    YCoreIconButton._activeInstance._tooltipVisible = true
  }

  private showTooltipWarm = () => {
    if (YCoreIconButton._activeInstance !== null && YCoreIconButton._activeInstance !== this) {
      YCoreIconButton._activeInstance._tooltipVisible = false
    }
    YCoreIconButton._activeInstance = this
    YCoreIconButton._activeInstance._tooltipVisible = true
  }

  private handleMouseEnter = (event: Event) => {
    if (event.eventPhase !== Event.AT_TARGET || !this.tooltipText) return

    if (YCoreIconButton._cooldownTimer !== null) {
      clearTimeout(YCoreIconButton._cooldownTimer)
      YCoreIconButton._cooldownTimer = null
    }

    if (YCoreIconButton._warmupActive) {
      this.showTooltipWarm()
      return
    }

    this._showDelayTimer = setTimeout(() => {
      this._showDelayTimer = null
      this.tryActivateTooltip()
    }, YCoreIconButton.TOOLTIP_SHOW_DELAY_MS)
  }

  private handleMouseLeave = (event: Event) => {
    if (event.eventPhase !== Event.AT_TARGET) return

    if (this._showDelayTimer !== null) {
      clearTimeout(this._showDelayTimer)
      this._showDelayTimer = null
    }
    this._tooltipVisible = false

    if (YCoreIconButton._activeInstance === this) {
      YCoreIconButton._activeInstance = null
    }

    if (YCoreIconButton._warmupActive && YCoreIconButton._activeInstance === null) {
      YCoreIconButton._cooldownTimer = setTimeout(() => {
        YCoreIconButton._warmupActive = false
        YCoreIconButton._cooldownTimer = null
      }, YCoreIconButton.TOOLTIP_COOLDOWN_MS)
    }
  }

  private handleClick = () => {
    if (this._showDelayTimer !== null) {
      clearTimeout(this._showDelayTimer)
      this._showDelayTimer = null
    }
    this._tooltipVisible = false

    if (YCoreIconButton._activeInstance === this) {
      YCoreIconButton._activeInstance = null
    }
  }

  connectedCallback() {
    // Регистрируем до super.connectedCallback(), чтобы наши capture-обработчики
    // оказались в очереди раньше, чем EventInterceptorController добавит свои.
    // Это позволяет тултипу работать даже в состоянии disabled (офлайн-режим).
    this.addEventListener('mouseenter', this.handleMouseEnter, { capture: true })
    this.addEventListener('mouseleave', this.handleMouseLeave, { capture: true })
    this.addEventListener('click', this.handleClick, { capture: true })

    super.connectedCallback()

    this.dataset.locator = tagName
    this.dataset[YC_COMPONENT_ATTRIBUTE_NAME] = ''
  }

  disconnectedCallback() {
    this.removeEventListener('mouseenter', this.handleMouseEnter, { capture: true })
    this.removeEventListener('mouseleave', this.handleMouseLeave, { capture: true })
    this.removeEventListener('click', this.handleClick, { capture: true })

    if (this._showDelayTimer !== null) {
      clearTimeout(this._showDelayTimer)
      this._showDelayTimer = null
    }

    if (YCoreIconButton._activeInstance === this) {
      YCoreIconButton._activeInstance = null
    }

    super.disconnectedCallback()
  }

  protected firstUpdated(): void {
    defineCustomElement(YCoreTooltipTagName, YCoreTooltip)
  }

  private renderBadge() {
    if (!this.isBadgeIndicator) return nothing

    return html`<y-core-badge class="${this.baseClass}__badge"></y-core-badge>`
  }

  private renderCounter() {
    const { indicator } = this

    if (!this.isIndicatorVisible || indicator?.type !== 'counter') return nothing

    return html`
      <div class=${this.counterWrapperClass}>
        <y-core-counter
          .value=${indicator.value}
          .maxValue=${indicator.maxValue}
          size="small"
          variant="negative"
          bordered
        ></y-core-counter>
      </div>
    `
  }

  private renderIconContent() {
    return html`
      <span class=${this.computedIconClass} style="width: ${this.computedIconSize}; height: ${this.computedIconSize};">
        <slot name="custom-icon">
          ${renderIcon({ icon: this.icon, size: this.computedIconSize })}
        </slot>
      </span>
    `
  }

  private renderButton() {
    return html`
      <y-core-simple-button
        href=${ifDefined(this.href)}
        target=${ifDefined(this.target)}
        variant=${ifDefined(this.variant)}
        size=${ifDefined(this.size)}
        .disabled=${this.disabled}
        .loading=${this.loading}
        .fullWidth=${this.fullWidth}
        .hostStyles=${YCoreIconButtonVarsCSS}
        class=${classMap(this.computedClasses)}
      >
        <span class=${this.iconWrapperClass}>
          ${this.renderBadge()}

          ${this.renderIconContent()}
        </span>

        ${this.renderCounter()}
      </y-core-simple-button>
    `
  }

  protected render() {
    if (!this.tooltipText) return this.renderButton()

    return html`
      <y-core-tooltip
        .text=${this.tooltipText}
        .placement=${this.tooltipPlacement ?? 'top'}
        .showOnCondition=${this._tooltipVisible}
      >
        <div slot="activator">
          ${this.renderButton()}
        </div>
      </y-core-tooltip>
    `
  }
}
