const enum ECalendarDayLocators {
  UNAVAILABLE_DAY = 'unavailable_day',
  AVAILABLE_DAY = 'available_day',
}

type TMonthKey = string

type ConstraintsDatesMap = Record<TMonthKey, Set<string> | undefined>

type TDatesMapName = 'availableDatesMap' | 'disabledDatesMap' | 'checkedDatesMap'

const {
  date,
  isRange,
  isSelectedRangeReadOnly,
  uniformDatesColor,
  minDate,
  maxDate,
  disabled,
  headerSelectors,
  allowEmptyYear,
  emptyYearFormat,
  gridMode,
  size,
  availableDates,
  disabledDates,
  checkedDates,
  disabledDatesTooltipText,
  getTooltipTextForDate,
} = createCoreCalendarProps()

@customElement(tagName)
export class YCoreCalendar
  extends LocalizedElement
  implements Required<IYCoreCalendarProps> {
  @property() date: IYCoreCalendarProps['date'] = date
  @property({ type: Boolean }) disabled: IYCoreCalendarProps['disabled'] = disabled
  @property({ type: Boolean, attribute: 'is-range' }) isRange: IYCoreCalendarProps['isRange'] = isRange
  @property({ type: Boolean, attribute: 'is-selected-range-read-only' }) isSelectedRangeReadOnly: IYCoreCalendarProps['isSelectedRangeReadOnly'] = isSelectedRangeReadOnly
  @property({ type: Boolean, attribute: 'uniform-dates-color' }) uniformDatesColor: IYCoreCalendarProps['uniformDatesColor'] = uniformDatesColor
  @property({ type: String, attribute: 'min-date' }) minDate: IYCoreCalendarProps['minDate'] = minDate
  @property({ type: String, attribute: 'max-date' }) maxDate: IYCoreCalendarProps['maxDate'] = maxDate
  @property({ type: Boolean, attribute: 'header-selectors' }) headerSelectors: IYCoreCalendarProps['headerSelectors'] = headerSelectors
  @property({ type: Boolean, attribute: 'allow-empty-year' }) allowEmptyYear: IYCoreCalendarProps['allowEmptyYear'] = allowEmptyYear
  @property({ type: String, attribute: 'empty-year-format' }) emptyYearFormat: IYCoreCalendarProps['emptyYearFormat'] = emptyYearFormat
  @property({ type: String, attribute: 'grid-mode' }) gridMode: IYCoreCalendarProps['gridMode'] = gridMode
  @property({ type: String }) size: IYCoreCalendarProps['size'] = size
  @property({ attribute: false }) availableDates: IYCoreCalendarProps['availableDates'] = availableDates
  @property({ attribute: false }) disabledDates: IYCoreCalendarProps['disabledDates'] = disabledDates
  @property({ attribute: false }) checkedDates: IYCoreCalendarProps['checkedDates'] = checkedDates
  @property({ attribute: false }) disabledDatesTooltipText: IYCoreCalendarProps['disabledDatesTooltipText'] = disabledDatesTooltipText
  @property({ type: Object, attribute: 'get-tooltip-text-for-date' }) getTooltipTextForDate: IYCoreCalendarProps['getTooltipTextForDate'] = getTooltipTextForDate

  @state() private isMonthDropdownVisible = false
  @state() private isYearDropdownVisible = false
  @state() private isYearOmitted = false
  @state() private gridModeState = this.gridModeWithDefault

  @query('y-core-dropdown:first-of-type') private monthDropdown?: YCoreDropdown
  @query('y-core-dropdown:last-of-type') private yearDropdown?: YCoreDropdown

  private touchStartX = 0
  private touchStartY = 0
  private swipeDirection: 'horizontal' | 'vertical' | null = null
  private readonly swipeThreshold = 50 // Минимальное расстояние для срабатывания свайпа
  private readonly swipeDirectionThreshold = 10 // Минимальное расстояние для определения направления свайпа
  private readonly animationTime = 500 // Время анимации
  private readonly animationCurve = 'cubic-bezier(0.4, 0, 0.2, 1)' // Кривая анимации
  private isAnimating = false

  private cachedCellHeight = 0
  private cachedRowGap = 0
  private resizeObserver?: ResizeObserver

  @state() private availableDatesMap: ConstraintsDatesMap = {}

  @state() private disabledDatesMap: ConstraintsDatesMap = {}

  @state() private checkedDatesMap: ConstraintsDatesMap = {}

  @bubblingEvent(
    SelectEvent,
    { name: 'click-disabled-date' },
  )
  _disabledDateClick!: TDispatcher<SelectEvent>

  @bubblingEvent(
    SelectEvent,
    { name: 'select' },
  )
  _select!: TDispatcher<SelectEvent>

  @bubblingEvent(
    RangeStartEvent,
    { name: 'range-start' },
  )
  _rangeStart!: TDispatcher<RangeStartEvent>

  @bubblingEvent(
    RangeEndEvent,
    { name: 'range-end' },
  )
  _rangeEnd!: TDispatcher<RangeEndEvent>

  @bubblingEvent(
    GridModeChangedEvent,
    { name: 'grid-mode-changed' },
  )
  _gridModeChanged!: TDispatcher<GridModeChangedEvent>

  @bubblingEvent(
    NavigationEvent,
    { name: 'navigation' },
  )
  _navigation!: TDispatcher<NavigationEvent>

  private readonly baseClass = tagName

  private get textSize() {
    return this.size === EYSizes.SMALL ? EYCoreTextSize.A2_MEDIUM : EYCoreTextSize.P2_MEDIUM
  }

  private get yearButtonLabel() {
    return this.isDateWithoutYearMode
      ? this.getLocale().messages.yearNotSpecified
      : this.currentDate.format(FORMAT_YEAR)
  }

  private get computedMinDate(): Dayjs {
    return this.minDate ? parseDate(this.minDate) : getDefaultMinDate()
  }

  private get computedMaxDate(): Dayjs | undefined {
    return this.maxDate ? parseDate(this.maxDate) : undefined
  }

  private get effectiveMinDate() {
    // При isDateWithoutYearMode ограничение minDate полностью отключается
    if (this.isDateWithoutYearMode) return getDefaultMinDate()

    return this.computedMinDate
  }

  private get effectiveMaxDate() {
    // При isDateWithoutYearMode ограничение maxDate полностью отключается
    if (this.isDateWithoutYearMode) return undefined

    return this.computedMaxDate
  }

  private get minNavigationDate() {
    return this.effectiveMinDate.startOf('month')
  }

  private get isDisabledPrevButton() {
    if (this.gridModeState === EYGridModes.WEEK) {
      const weekStart = this.currentDate.startOf('week')
      return weekStart.isSameOrBefore(this.minNavigationDate, 'day')
    }
    return this.currentDate.isSameOrBefore(this.minNavigationDate, 'month')
  }

  private get isDisabledNextButton() {
    if (!this.effectiveMaxDate) return false

    const maxNavigationDate = this.effectiveMaxDate.startOf('month')

    if (this.gridModeState === EYGridModes.WEEK) {
      const weekEnd = this.currentDate.endOf('week')
      return weekEnd.isSameOrAfter(maxNavigationDate, 'day')
    }

    return this.currentDate.isSameOrAfter(maxNavigationDate, 'month')
  }

  private handleNavigation() {
    const year = this.isDateWithoutYearMode ? null : this.currentDate.year()
    const month = this.currentDate.month() + 1

    this._navigation({
      detail: {
        value: {
          year,
          month,
        },
      },
    })
  }

  private clampToInterval(date: Dayjs) {
    if (date.isBefore(this.effectiveMinDate, 'day')) return this.effectiveMinDate
    if (this.effectiveMaxDate && date.isAfter(this.effectiveMaxDate, 'day')) return this.effectiveMaxDate

    return date
  }

  private get isEmptyYearAllowed() {
    return Boolean(this.allowEmptyYear) && !this.isRange
  }

  private get isDateWithoutYearMode() {
    return this.isEmptyYearAllowed && this.isYearOmitted
  }

  private get yearsList() {
    const years = getYearsList(
      formatDate(this.computedMinDate),
      this.computedMaxDate ? formatDate(this.computedMaxDate) : undefined,
    )

    if (!this.isEmptyYearAllowed) return years

    return [
      {
        id: NO_YEAR_ID,
        label: this.getLocale().messages.yearNotSpecified,
      },
      ...years,
    ]
  }

  private get gridModeWithDefault() {
    return this.gridMode || EYGridModes.MONTH
  }

  private get gridClasses() {
    return {
      [`${this.baseClass}__grid`]: true,
      [`${this.baseClass}__grid-${this.size}`]: Boolean(this.size),
    }
  }

  private clearConstraintsDatesMapByProp(propName: TDatesMapName) {
    this[propName] = {}
  }

  private getMonthKeyForMap(date: Dayjs): TMonthKey {
    return date.format(FORMAT_MONTH_YEAR)
  }

  /**
   * Заполняет мапу доступных или недоступных дат по ключу MM.YYYY из массива дат
   * @param dates
   * @param propName
   * @private
   */
  private fillConstraintsDatesMapByPropFromArray(dates: string[], propName: TDatesMapName) {
    dates.forEach((date) => {
      const dateData = parseDate(date)

      const keyForMap = this.getMonthKeyForMap(dateData)

      if (!this[propName][keyForMap]) this[propName][keyForMap] = new Set<string>()

      this[propName][keyForMap].add(dateData.format(FORMAT_DATE_DMY))
    })
  }

  /**
   * Заполняет пошагово мапу доступных или недоступных дат по ключу MM.YYYY если
   * передана функция для валидации
   * @param propName
   * @param monthDelta
   * @private
   */
  private fillConstraintsDatesMapByPropWithFunction(propName: TDatesMapName, monthDelta?: EMonthDelta) {
    const callbackName = propName === 'availableDatesMap' ? 'availableDates' : 'disabledDates'

    if (typeof this[callbackName] !== 'function') return

    const dates = getCurrentPrevNextMonthDays(this.currentDate, monthDelta)

    dates.forEach((date) => {
      if (typeof this[callbackName] !== 'function') return

      const dateData = parseDate(date)

      const keyForMap = this.getMonthKeyForMap(dateData)

      if (!this[propName][keyForMap]) this[propName][keyForMap] = new Set<string>()

      if (this[callbackName](date.toDate())) this[propName][keyForMap].add(dateData.format(FORMAT_DATE_DMY))
    })
  }

  private fillAvailableDates(availableDates: IYCoreCalendarProps['availableDates']) {
    if (!availableDates || availableDates.length === 0) {
      this.clearConstraintsDatesMapByProp('availableDatesMap')
      return
    }

    if (Array.isArray(availableDates)) {
      this.clearConstraintsDatesMapByProp('availableDatesMap')
      this.fillConstraintsDatesMapByPropFromArray(availableDates, 'availableDatesMap')
      return
    }

    this.fillConstraintsDatesMapByPropWithFunction('availableDatesMap')
  }

  private fillDisabledDates(disabledDates: IYCoreCalendarProps['disabledDates']) {
    if (!disabledDates || disabledDates.length === 0) {
      this.clearConstraintsDatesMapByProp('disabledDatesMap')
      return
    }

    if (Array.isArray(disabledDates)) {
      this.clearConstraintsDatesMapByProp('disabledDatesMap')
      this.fillConstraintsDatesMapByPropFromArray(disabledDates, 'disabledDatesMap')
    }

    this.fillConstraintsDatesMapByPropWithFunction('disabledDatesMap')
  }

  private fillCheckedDates(checkedDates: IYCoreCalendarProps['checkedDates']) {
    if (Array.isArray(checkedDates)) {
      this.clearConstraintsDatesMapByProp('checkedDatesMap')
      this.fillConstraintsDatesMapByPropFromArray(checkedDates, 'checkedDatesMap')
    }

    this.fillConstraintsDatesMapByPropWithFunction('checkedDatesMap')
  }

  private fillAllConstraintsMapsWithFunction(monthDelta?: EMonthDelta) {
    this.fillConstraintsDatesMapByPropWithFunction('availableDatesMap', monthDelta)

    this.fillConstraintsDatesMapByPropWithFunction('disabledDatesMap', monthDelta)
  }

  private navigateTo(date: Dayjs, omitYear: boolean) {
    const isSameMonth = date.year() === this.currentDate.year() && date.month() === this.currentDate.month()

    if (isSameMonth && omitYear === this.isYearOmitted) return

    this.isYearOmitted = omitYear
    this.currentDate = this.clampToInterval(date)

    this.fillAllConstraintsMapsWithFunction()
    this.updateGridWrapperHeight()
    this.handleNavigation()
  }

  private handleMonthSelect = (itemEvent: ItemClickEvent) => {
    this.monthDropdown?.close()

    const month = parseInt(String(itemEvent.detail.item.id), 10)

    this.navigateTo(this.currentDate.month(month), this.isYearOmitted)
  }

  private handleYearSelect = (itemEvent: ItemClickEvent) => {
    this.yearDropdown?.close()

    const { id } = itemEvent.detail.item

    const omitYear = this.isEmptyYearAllowed && id === NO_YEAR_ID
    const year = omitYear ? LEAP_REFERENCE_YEAR : parseInt(String(id), 10)

    this.navigateTo(this.currentDate.year(year), omitYear)
  }

  private handleMonthDropdownClick = () => {
    this.isMonthDropdownVisible = !this.isMonthDropdownVisible
    this.isYearDropdownVisible = false
  }

  private handleYearDropdownClick = () => {
    this.isYearDropdownVisible = !this.isYearDropdownVisible
    this.isMonthDropdownVisible = false
  }

  private handleMonthDropdownVisibleChange = (event: VisibleEvent) => {
    this.isMonthDropdownVisible = event.detail.value
  }

  private handleYearDropdownVisibleChange = (event: VisibleEvent) => {
    this.isYearDropdownVisible = event.detail.value
  }

  private dateIsBeforeThenMinDate = (date: Dayjs) => {
    return !this.isYearOmitted && this.minDate && date.isBefore(parseDate(this.minDate), 'day')
  }

  private dateIsAfterThenMaxDate = (date: Dayjs) => {
    return !this.isYearOmitted && this.maxDate && date.isAfter(parseDate(this.maxDate), 'day')
  }

  private isNoNeedCheckForAvailable = () => {
    return !this.availableDates && !this.disabledDates
  }

  private isAvailableDate = (date: Dayjs): boolean => {
    // В режиме без года ограничения availableDates/disabledDates игнорируются — все даты доступны
    if (this.isDateWithoutYearMode) return true

    if (this.isNoNeedCheckForAvailable()) return true

    const keyForMap = this.getMonthKeyForMap(date)

    if (this.availableDates) {
      if (!this.availableDatesMap[keyForMap]) return false

      return this.availableDatesMap[keyForMap].has(date.format(FORMAT_DATE_DMY))
    }

    if (!this.disabledDatesMap[keyForMap]) return true

    return !this.disabledDatesMap[keyForMap].has(date.format(FORMAT_DATE_DMY))
  }

  private isCheckedDate = (date: Dayjs): boolean => {
    // В режиме без года отметки checkedDates игнорируются
    if (this.isDateWithoutYearMode) return false

    if (!this.checkedDates) return false

    const keyForMap = this.getMonthKeyForMap(date)

    if (!this.checkedDatesMap[keyForMap]) return false

    return this.checkedDatesMap[keyForMap].has(date.format(FORMAT_DATE_DMY))
  }

  private isDateDisabled(date: Dayjs) {
    return Boolean(this.disabled ||
      this.dateIsAfterThenMaxDate(date) ||
      this.dateIsBeforeThenMinDate(date) ||
      !this.isAvailableDate(date))
  }

  private isDateInReadonlySelectedRange(date: Dayjs, rangeStart: Dayjs, rangeEnd: Dayjs): boolean {
    if (!this.isSelectedRangeReadOnly) return false

    return date.isSameOrAfter(rangeStart, 'day') && date.isSameOrBefore(rangeEnd, 'day')
  }

  private getRangeClasses(date: Dayjs): Record<string, boolean> {
    if (!this.isRange || !Array.isArray(this.date)) return {}

    const [
      startDate,
      endDate,
    ] = this.date
    if (!startDate) return {}

    const startDateParsed = parseDate(startDate)
    const endDateParsed = endDate ? parseDate(endDate) : startDateParsed

    return {
      [`${this.baseClass}__day_in-range`]: date.isBetween(startDateParsed, endDateParsed, 'day'),
      [`${this.baseClass}__day_range-start`]: date.isSame(startDateParsed, 'day'),
      [`${this.baseClass}__day_range-end`]: date.isSame(endDateParsed, 'day'),
      [`${this.baseClass}__day_readonly`]: this.isDateInReadonlySelectedRange(date, startDateParsed, endDateParsed),
    }
  }

  /**
   * Сдвигает дату на интервал. В режиме без года фиксирует опорный (високосный) год,
   * чтобы сетка не уезжала из високосного года при переходе через его границу
   */
  private addDate = (date: Dayjs, value: number, unit?: ManipulateType) => {
    const newDate = date.add(value, unit)

    if (this.isDateWithoutYearMode) {
      return newDate.year(LEAP_REFERENCE_YEAR)
    }

    return newDate
  }

  private changeMonth = (delta: number) => {
    const newDate = this.addDate(this.currentDate, delta, 'month')
    this.currentDate = this.clampToInterval(newDate)

    this.handleNavigation()
  }

  private changeWeek = (delta: number) => {
    const newDate = this.addDate(this.currentDate, delta, 'week')
    this.currentDate = this.clampToInterval(newDate)

    this.handleNavigation()
  }

  private toPrevMonthOrWeek = () => {
    if (this.gridModeState === EYGridModes.WEEK) {
      this.changeWeek(-1)
      return
    }
    this.changeMonth(-1)

    this.fillAllConstraintsMapsWithFunction(EMonthDelta.PREV)
  }

  private toPrevMonthOrWeekWithAnimation = () => {
    if (this.isAnimating) return

    this.animateTransition(100, () => {
      this.toPrevMonthOrWeek()
    })
  }

  private toNextMonthOrWeek = () => {
    if (this.gridModeState === EYGridModes.WEEK) {
      this.changeWeek(1)
      return
    }

    this.changeMonth(1)

    this.fillAllConstraintsMapsWithFunction(EMonthDelta.NEXT)
  }

  private toNextMonthOrWeekWithAnimation = () => {
    this.animateTransition(-100, () => {
      this.toNextMonthOrWeek()
    })
  }

  private checkRangeDateValidity(date: IYCoreCalendarProps['date']): date is [string, string] {
    return Array.isArray(date) &&
      date.some(Boolean)
  }

  private handleSelectedRangeClick(date: Dayjs, startDate: string, endDate: string) {
    if (this.isDateInReadonlySelectedRange(date, parseDate(startDate), parseDate(endDate))) {
      return
    }

    this.date = [
      formatDate(date),
      '',
    ]

    this._rangeStart({ detail: { value: this.date[0] } })
  }

  private handleRangeClick(date: Dayjs) {
    if (!this.checkRangeDateValidity(this.date)) {
      this.date = [
        formatDate(date),
        '',
      ]

      this._rangeStart({ detail: { value: this.date[0] } })

      return
    }

    const [
      startDate,
      endDate,
    ] = this.date

    if (startDate && endDate) {
      this.handleSelectedRangeClick(date, startDate, endDate)

      return
    }

    if (startDate && date.isBefore(parseDate(startDate), 'day')) {
      this.date = [
        formatDate(date),
        startDate,
      ]


      this._rangeEnd({ detail: { value: this.date[0] } })
      this._select({ detail: { value: this.date } })

      return
    }

    this.date = [
      this.date[0],
      formatDate(date),
    ]

    this._rangeEnd({ detail: { value: this.date[1] } })
    this._select({ detail: { value: this.date } })
  }

  private handleDayClick(date: Dayjs) {
    if (this.disabled || this.isDateDisabled(date)) {
      this._disabledDateClick({ detail: { value: formatDate(date) } })

      return
    }

    if (!this.isRange) {
      if (this.isDateWithoutYearMode) {
        const dateWithoutYear = formatDate(date, this.emptyYearFormat)

        this.date = dateWithoutYear

        this._select({ detail: { value: dateWithoutYear } })

        return
      }

      this.date = formatDate(date)

      this._select({ detail: { value: formatDate(date) } })

      return
    }

    this.handleRangeClick(date)
  }

  private getGridSlider() {
    return this.shadowRoot?.querySelector<HTMLElement>(`.${this.baseClass}__grid-slider`)
  }

  private getGridWrapper() {
    return this.shadowRoot?.querySelector<HTMLElement>(`.${this.baseClass}__grid-wrapper`)
  }

  private getCellHeight() {
    return this.shadowRoot?.querySelector<HTMLElement>(`.${this.baseClass}__day`)?.offsetHeight || 0
  }

  private getRowGap() {
    const grid = this.shadowRoot?.querySelector<HTMLElement>(`.${this.baseClass}__grid`)
    return grid ? parseInt(getComputedStyle(grid).rowGap) || 0 : 0
  }

  /**
   * Сравнивает выбранную дату без года с переданной только по месяцу и дню
   */
  private isDateWithoutYearSelected(selectedDate: string, date: Dayjs): boolean {
    const selected = parseDateWithoutYear(selectedDate, this.emptyYearFormat)

    return selected.month() === date.month() && selected.date() === date.date()
  }

  private isDateSelected(date: Dayjs): boolean {
    if (typeof this.date !== 'string' || !this.date) return false

    if (this.isDateWithoutYearMode) {
      // В режиме без года выделяем только дату, выбранную без года; дата с годом — это навигация по виду
      return isDateWithoutYear(this.date, this.emptyYearFormat) && this.isDateWithoutYearSelected(this.date, date)
    }

    return parseDate(this.date).isSame(date, 'day')
  }

  /**
   * Неотмеченная дата при заданных checkedDates: приглушается цветом
   * как недоступная, но остаётся кликабельной
   */
  private isUncheckedDate(isChecked: boolean): boolean {
    return Boolean(this.checkedDates) && !this.isDateWithoutYearMode && !isChecked
  }

  private get rootClasses() {
    return {
      [this.baseClass]: true,
      [`${this.baseClass}_${this.size}`]: true,
      [`${this.baseClass}_uniform-dates-color`]: Boolean(this.uniformDatesColor),
    }
  }

  /**
   * Вариант текста даты. uniformDatesColor: доступные даты всегда основным
   * цветом (и в соседних месяцах), недоступные и неотмеченные — вторичным
   * (tertiary на датах почти не читался)
   */
  private getDayTextVariant(isDisabled: boolean, isCurrentMonth: boolean, isChecked: boolean): EYCoreTextVariant {
    if (this.uniformDatesColor) {
      return isDisabled || this.isUncheckedDate(isChecked) ? EYCoreTextVariant.SECONDARY : EYCoreTextVariant.PRIMARY
    }

    if (isDisabled) {
      return EYCoreTextVariant.TERTIARY
    }

    return isCurrentMonth ? EYCoreTextVariant.PRIMARY : EYCoreTextVariant.SECONDARY
  }

  private getCalendarDayDataWithClasses(dayData: IMonthDayData) {
    const { date, dayNumber, isCurrentMonth } = dayData

    const isSelected = this.isDateSelected(date)
    const isDisabled = this.isDateDisabled(date)
    const isChecked = this.isCheckedDate(date)

    const dayClasses = {
      [`${this.baseClass}__day`]: true,
      [`${this.baseClass}__day_disabled`]: isDisabled,
      [`${this.baseClass}__day_today`]: date.isToday(),
      [`${this.baseClass}__day_checked`]: isChecked,
      [`${this.baseClass}__day_selected`]: isSelected,
      [`${this.baseClass}__day_out-of-month`]: !isCurrentMonth,
      [`${this.baseClass}__day_sticky`]: isDateInCurrentWeek(date, this.currentDate),
      ...this.getRangeClasses(date),
    }

    const dayNumberClasses = {
      [`${this.baseClass}__day-number`]: true,
      [`${this.baseClass}__day-number_selected`]: isSelected,
    }

    const todayIndicatorClasses = { [`${this.baseClass}__day_today-indicator`]: true }
    const dayLocator = isDisabled ? ECalendarDayLocators.UNAVAILABLE_DAY : ECalendarDayLocators.AVAILABLE_DAY
    const dayDateLocator = formatDate(date)
    const textVariant = this.getDayTextVariant(isDisabled, isCurrentMonth, isChecked)
    const dayDateSelectedLocator = isSelected


    return {
      dayClasses,
      dayNumberClasses,
      todayIndicatorClasses,
      isSelected,
      isDisabled,
      dayNumber,
      isCurrentMonth,
      date,
      textVariant,
      dayLocator,
      dayDateLocator,
      dayDateSelectedLocator,
    }
  }

  private animateModeChange(callback?: () => void): void {
    const gridWrapper = this.getGridWrapper()

    if (!gridWrapper) return

    // Включаем анимацию и устанавливаем максимальную высоту
    gridWrapper.style.transition = `max-height ${this.animationTime}ms ${this.animationCurve}`
    gridWrapper.style.maxHeight = `${gridWrapper.offsetHeight}px`

    this.setGridWrapperMaxHeight()

    setTimeout(() => {
      callback?.()

      // Выключаем анимацию
      gridWrapper.style.transition = 'none'
    }, this.animationTime)
  }

  private cacheGridDimensions() {
    const newCellHeight = this.getCellHeight()

    if (newCellHeight > 0) {
      this.cachedCellHeight = newCellHeight
      this.cachedRowGap = this.getRowGap()
    }
  }

  /**
   * Fallback для расчёта высоты, когда элемент ещё не отрисован (getComputedStyle возвращает пустые значения).
   * Должны соответствовать Calendar.vars.css: --y-core-calendar-grid-row-height и --y-core-calendar-grid-row-gap.
   */
  private static readonly FALLBACK_ROW_HEIGHT = 32
  private static readonly FALLBACK_ROW_GAP = 4

  private calculateGridHeight(): number {
    const weekCountInMonth = getWeeksCountInMonth(this.currentDate)
    return this.cachedCellHeight * weekCountInMonth + this.cachedRowGap * (weekCountInMonth - 1)
  }

  private setGridsHeight(height: string) {
    const grids = this.shadowRoot?.querySelectorAll<HTMLElement>(`.${this.baseClass}__grid`)
    grids?.forEach((grid) => {
      grid.style.height = height
    })
  }

  private applyGridWrapperHeight() {
    const gridWrapper = this.getGridWrapper()

    if (!gridWrapper) return

    this.cacheGridDimensions()

    if (this.cachedCellHeight === 0) {
      this.cachedCellHeight = YCoreCalendar.FALLBACK_ROW_HEIGHT
      this.cachedRowGap = YCoreCalendar.FALLBACK_ROW_GAP
    }

    if (this.cachedCellHeight === 0) return

    if (this.gridMode === EYGridModes.WEEK) {
      gridWrapper.style.maxHeight = `${this.cachedCellHeight}px`
      this.setGridsHeight('')
      return
    }

    this.gridModeState = this.gridModeWithDefault
    const gridHeight = this.calculateGridHeight()
    gridWrapper.style.maxHeight = `${gridHeight}px`
    this.setGridsHeight(`${gridHeight}px`)
  }

  private setGridWrapperMaxHeight() {
    requestAnimationFrame(() => {
      this.applyGridWrapperHeight()
    })
  }

  private updateGridWrapperHeight() {
    requestAnimationFrame(() => {
      const gridWrapper = this.getGridWrapper()
      if (!gridWrapper) return

      const gridHeight = this.calculateGridHeight()
      gridWrapper.style.maxHeight = `${gridHeight}px`
      this.setGridsHeight(`${gridHeight}px`)
    })
  }

  private prepareGridWrapperForAnimation(gridWrapper: HTMLElement | null | undefined) {
    if (!gridWrapper || this.gridModeState !== EYGridModes.MONTH) return

    this.cacheGridDimensions()

    gridWrapper.style.transition = `max-height ${this.animationTime}ms ${this.animationCurve}`
    gridWrapper.style.maxHeight = `${gridWrapper.offsetHeight}px`
  }

  private finalizeGridWrapperAnimation(gridWrapper: HTMLElement | null | undefined) {
    if (!gridWrapper) return

    setTimeout(() => {
      gridWrapper.style.transition = 'none'
    }, 0)
  }

  private handleSwipeComplete(callback: (() => void) | undefined, gridWrapper: HTMLElement | null | undefined) {
    if (!callback) return

    callback()

    if (gridWrapper && this.gridModeState === EYGridModes.MONTH) {
      this.updateGridWrapperHeight()
    }
  }

  private animateTransition = (deltaX: number, callback?: () => void) => {
    const gridSlider = this.getGridSlider()
    const gridWrapper = this.getGridWrapper()
    if (!gridSlider || this.isAnimating) return

    this.isAnimating = true

    this.prepareGridWrapperForAnimation(gridWrapper)

    // Включаем анимацию
    gridSlider.style.transition = `transform ${this.animationTime}ms ${this.animationCurve}`

    // Определяем направление и конечную позицию: докручиваем до конца в направлении свайпа
    // или возвращаем в исходное положение
    const shouldCompleteSwipe = Math.abs(deltaX) > this.swipeThreshold
    const targetTransform = shouldCompleteSwipe ? deltaX < 0 ? -200 : 0 : -100

    gridSlider.style.transform = `translate3d(${targetTransform}%, 0px, 0px)`

    // После завершения анимации сбрасываем состояние
    setTimeout(() => {
      this.isAnimating = false
      // Выключаем анимацию
      gridSlider.style.transition = 'none'

      if (shouldCompleteSwipe) {
        this.handleSwipeComplete(callback, gridWrapper)
      }

      this.resetGridSliderTransform()
      this.finalizeGridWrapperAnimation(gridWrapper)
    }, this.animationTime)
  }

  private handleTouchStart = (event: TouchEvent) => {
    if (event.touches.length === 1) {
      this.touchStartX = event.touches[0].clientX
      this.touchStartY = event.touches[0].clientY
      this.swipeDirection = null
    }
  }

  private determineSwipeDirection(deltaX: number, deltaY: number): void {
    if (this.swipeDirection !== null) return

    const absDeltaX = Math.abs(deltaX)
    const absDeltaY = Math.abs(deltaY)

    if (absDeltaX > this.swipeDirectionThreshold || absDeltaY > this.swipeDirectionThreshold) {
      this.swipeDirection = absDeltaX > absDeltaY ? 'horizontal' : 'vertical'
    }
  }

  private applyHorizontalSwipeTransform(deltaX: number): void {
    const gridSlider = this.getGridSlider()
    if (!gridSlider) return

    const currentTransform = -100 + deltaX / gridSlider.offsetWidth * 100
    gridSlider.style.transform = `translate3d(${currentTransform}%, 0px, 0px)`
  }

  private handleTouchMove = (event: TouchEvent) => {
    if (event.touches.length !== 1 || this.isAnimating) return

    const touchCurrentX = event.touches[0].clientX
    const touchCurrentY = event.touches[0].clientY
    const deltaX = touchCurrentX - this.touchStartX
    const deltaY = touchCurrentY - this.touchStartY

    this.determineSwipeDirection(deltaX, deltaY)

    if (this.swipeDirection === 'vertical') return

    if (this.swipeDirection === 'horizontal') {
      event.preventDefault()
      this.applyHorizontalSwipeTransform(deltaX)
    }
  }

  private resetGridSliderTransform(): void {
    const gridSlider = this.getGridSlider()

    if (!gridSlider) return

    gridSlider.style.transform = 'translate3d(-100%, 0px, 0px)'
  }

  private handleTouchEnd = (event: TouchEvent) => {
    if (event.changedTouches.length !== 1 || this.isAnimating) return

    // Вертикальный скролл - не обрабатываем
    if (this.swipeDirection === 'vertical') {
      this.swipeDirection = null
      return
    }

    const touchEndX = event.changedTouches[0].clientX
    const deltaX = touchEndX - this.touchStartX

    // Недостаточное расстояние или не горизонтальный свайп
    if (this.swipeDirection !== 'horizontal' || Math.abs(deltaX) <= this.swipeThreshold) {
      this.resetGridSliderTransform()
      this.swipeDirection = null
      return
    }

    this.animateTransition(deltaX, () => {
      if (deltaX > 0) {
        this.toPrevMonthOrWeek()
      } else {
        this.toNextMonthOrWeek()
      }
    })

    this.swipeDirection = null
  }

  private resolveEmptyYearBaseDate(selectedDate: string | undefined): Dayjs | null {
    if (typeof selectedDate === 'string' && isDateWithoutYear(selectedDate, this.emptyYearFormat)) {
      return parseDateWithoutYear(selectedDate, this.emptyYearFormat)
    }

    if (!selectedDate) {
      return parseDate().year(LEAP_REFERENCE_YEAR)
    }

    return null
  }

  private tryApplyEmptyYearDate(selectedDate: string | undefined): boolean {
    if (!this.isEmptyYearAllowed) return false

    const base = this.resolveEmptyYearBaseDate(selectedDate)
    if (!base) return false

    this.isYearOmitted = true
    this.currentDate = this.clampToInterval(base)

    return true
  }

  private handleDatePropChange(): void {
    const selectedDate = Array.isArray(this.date) ? this.date[1] || this.date[0] : this.date

    if (this.tryApplyEmptyYearDate(selectedDate)) return

    this.isYearOmitted = false
    this.currentDate = this.clampToInterval(parseDate(selectedDate))
  }

  private syncDateOnPropChange(changedProperties: PropertyValues): void {
    if (changedProperties.has('date') || changedProperties.has('allowEmptyYear')) {
      const prevWeeksCount = getWeeksCountInMonth(this.currentDate)

      this.handleDatePropChange()

      // Высота сетки зависит только от числа недель в месяце. Пересчитываем её,
      // лишь когда оно изменилось (например, 5 → 6) — иначе max-height тот же,
      // а последняя неделя нового месяца обрезалась бы
      if (getWeeksCountInMonth(this.currentDate) !== prevWeeksCount) {
        this.setGridWrapperMaxHeight()
      }
    }

    if (changedProperties.has('allowEmptyYear')) {
      this.fillAllConstraintsMapsWithFunction()
    }
  }

  /**
   * Режим без года выключился, но дата всё ещё хранится без года —
   * её нужно разрешить (опорный високосный год — внутренняя деталь и наружу попадать не должен).
   * Конфликт с isRange отдельно гасит validateEmptyYearWithRange, поэтому здесь смотрим только на allowEmptyYear
   */
  private shouldHandleAllowEmptyYearPropChange(changedProperties: PropertyValues): boolean {
    if (!changedProperties.has('allowEmptyYear')) return false

    return this.isYearOmitted && !this.isEmptyYearAllowed
  }

  /**
   * При отключении allowEmptyYear подставляет текущий год в выбранную дату без года
   * (06-15 → 15.06.<текущий год>) и эмитит её полным значением
   */
  private handleAllowEmptyYearPropChange(): void {
    const base = typeof this.date === 'string' && isDateWithoutYear(this.date, this.emptyYearFormat)
      ? parseDateWithoutYear(this.date, this.emptyYearFormat)
      : this.currentDate

    const resolved = this.clampToInterval(base.year(parseDate().year()))

    this.isYearOmitted = false
    this.currentDate = resolved
    this.date = formatDate(resolved)

    this.fillAllConstraintsMapsWithFunction()

    this._select({ detail: { value: this.date } })
  }

  private handleGridModeChange(): void {
    const selectedDate = parseDate(this.date instanceof Array ? this.date[0] : this.date)

    const monthDays = getMonthDaysList(this.currentDate)
    const isSelectedDateVisible = monthDays.some((day) => day.date.isSame(selectedDate, 'day'))

    // Если выбранная дата видна в текущей сетке календаря, используем её
    if (isSelectedDateVisible) {
      this.currentDate = selectedDate
    }

    if (this.gridMode === EYGridModes.WEEK) {
      if (!isSelectedDateVisible) {
        // Если выбранная дата не видна в текущей сетке, выставляем первую неделю месяца
        this.currentDate = this.currentDate.startOf('month')
      }
    }

    this.animateModeChange(() => {
      this.gridModeState = this.gridModeWithDefault

      this._gridModeChanged({ detail: { value: this.gridModeWithDefault } })
    })
  }

  public updateDate(value: IYCoreCalendarProps['date']): void {
    this.date = value
  }

  public resetDropdowns(): void {
    // Сброс состояния
    this.isMonthDropdownVisible = false
    this.isYearDropdownVisible = false
  }

  protected getTooltipText(date: string | Dayjs): string | undefined {
    return this.getTooltipTextForDate
      ? this.getTooltipTextForDate(date)
      : this.disabledDatesTooltipText
  }

  private applyEmptyYearWithRangeConflict(): void {
    if (!this.allowEmptyYear || !this.isRange) return

    this.isYearOmitted = false
    console.warn(`[${tagName}] allowEmptyYear не поддерживается вместе с isRange — режим без года проигнорирован`)
  }

  private validateEmptyYearWithRange(changedProperties: PropertyValues): void {
    if (!changedProperties.has('allowEmptyYear') && !changedProperties.has('isRange')) return

    this.applyEmptyYearWithRangeConflict()
  }

  private hasEmptyYearRelevantChange(changedProperties: PropertyValues): boolean {
    return changedProperties.has('date') || changedProperties.has('emptyYearFormat') || changedProperties.has('allowEmptyYear')
  }

  private isEmptyYearDateValid(value: string): boolean {
    return isDateWithoutYear(value, this.emptyYearFormat) || parseDate(value).isValid()
  }

  private validateEmptyYearDateFormat(changedProperties: PropertyValues): void {
    if (!this.hasEmptyYearRelevantChange(changedProperties) || !this.isEmptyYearAllowed) return

    if (typeof this.date !== 'string' || !this.date || this.isEmptyYearDateValid(this.date)) return

    console.warn(`[${tagName}] Значение date "${this.date}" не соответствует формату emptyYearFormat ("${this.emptyYearFormat}") — будет Invalid Date. Передайте дату без года в формате "${this.emptyYearFormat}" или полную дату.`)
  }

  private refillConstraintsDatesOnChange(changedProperties: PropertyValues): void {
    if (changedProperties.has('availableDates')) {
      this.fillAvailableDates(this.availableDates)
    }

    if (changedProperties.has('disabledDates')) {
      this.fillDisabledDates(this.disabledDates)
    }

    if (changedProperties.has('checkedDates')) {
      this.fillCheckedDates(this.checkedDates)
    }
  }

  protected willUpdate(changedProperties: PropertyValues) {
    super.willUpdate(changedProperties)

    this.validateEmptyYearWithRange(changedProperties)
    this.validateEmptyYearDateFormat(changedProperties)
    this.refillConstraintsDatesOnChange(changedProperties)
  }

  updated(changedProperties: PropertyValues<this>): void {
    super.updated(changedProperties)

    if (this.shouldHandleAllowEmptyYearPropChange(changedProperties)) {
      this.handleAllowEmptyYearPropChange()
      return
    }

    this.syncDateOnPropChange(changedProperties)

    if (changedProperties.has('gridMode')) {
      const oldGridModeValue = changedProperties.get('gridMode')

      if (oldGridModeValue) {
        this.handleGridModeChange()
        return
      }

      this.setGridWrapperMaxHeight()
      this.gridModeState = this.gridModeWithDefault
    }
  }

  static readonly styles = [
    css`
      ${unsafeCSS(YCalendarVarsCss)}
      ${unsafeCSS(YCalendarScopedCss)}
    `,
  ]

  connectedCallback(): void {
    super.connectedCallback()

    this.dataset.locator = tagName
    this.dataset[YC_COMPONENT_ATTRIBUTE_NAME] = ''

    this.resizeObserver = new ResizeObserver(() => {
      const dayElement = this.shadowRoot?.querySelector<HTMLElement>(`.${this.baseClass}__day`)
      if (dayElement && dayElement.offsetHeight > 0 && this.cachedCellHeight === 0) {
        console.info('ResizeObserver: Calendar became visible, recalculating height')
        this.setGridWrapperMaxHeight()
      }
    })
    this.resizeObserver.observe(this)
  }

  disconnectedCallback() {
    super.disconnectedCallback()

    this.resetDropdowns()
    this.resizeObserver?.disconnect()
  }

  protected renderHeaderSelectors() {
    const monthList = (this.getLocaleService()?.getMonths('long') || []).map((month) => ({ ...month, label: capitalize(month.label) }))

    return html`
      <y-core-dropdown
        .trigger=${EYCoreDropdownTrigger.MANUAL}
        .isOpen=${this.isMonthDropdownVisible}
        @change-visible=${this.handleMonthDropdownVisibleChange}
        @click=${preventAndStopEvent}
      >
        <y-core-button
          class="${this.baseClass}__month-button"
          label=${capitalize(this.currentDate.format(FORMAT_MONTH))}
          variant="text"
          .size=${this.size}
          .iconRight=${this.isMonthDropdownVisible ? yChevronUp : yChevronDown}
          slot="activator"
          @click=${this.handleMonthDropdownClick}
        >
        </y-core-button>

        <y-core-dropdown-list
          slot="content"
          .items=${monthList}
          @item-click=${this.handleMonthSelect}
        >
        </y-core-dropdown-list>
      </y-core-dropdown>

      <y-core-dropdown
        .trigger=${EYCoreDropdownTrigger.MANUAL}
        .isOpen=${this.isYearDropdownVisible}
        @change-visible=${this.handleYearDropdownVisibleChange}
        @click=${preventAndStopEvent}
      >
        <y-core-button
          class="${this.baseClass}__year-button"
          label=${this.yearButtonLabel}
          variant="text"
          .size=${this.size}
          .iconRight=${this.isYearDropdownVisible ? yChevronUp : yChevronDown}
          slot="activator"
          @click=${this.handleYearDropdownClick}
        >
        </y-core-button>

        <y-core-dropdown-list
          slot="content"
          .items=${this.yearsList}
          @item-click=${this.handleYearSelect}
        >
        </y-core-dropdown-list>
      </y-core-dropdown>
    `
  }

  protected renderHeaderText() {
    const yearLabel = this.isDateWithoutYearMode ? '' : ` ${this.currentDate.format(FORMAT_YEAR)}`

    return html`
      <y-core-text
        .size=${this.textSize}
        variant=${EYCoreTextVariant.PRIMARY}
        class="${this.baseClass}__header-month-year"
        >${capitalize(this.currentDate.format(FORMAT_MONTH))}${yearLabel}
      </y-core-text>
    `
  }

  protected renderHeaderDate() {
    return this.headerSelectors ? this.renderHeaderSelectors() : this.renderHeaderText()
  }

  protected renderGridHeader() {
    if (this.isDateWithoutYearMode) {
      return nothing
    }

    return (this.getLocaleService()?.getWeekDays('short') || []).map((day) => html`
      <y-core-text
        size=${EYCoreTextSize.A2_REGULAR}
        variant=${EYCoreTextVariant.SECONDARY}
        class="${this.baseClass}__week-day"
      >${day}</y-core-text>
    `)
  }

  protected renderMonthDays(delta: number) {
    const monthDays = getMonthDaysList(this.currentDate.add(delta, 'month'))

    return repeat(
      monthDays,
      (dayData: IMonthDayData) => dayData.date.format(FORMAT_DATE),
      (dayData: IMonthDayData) => this.renderDay(dayData, delta === 0),
    )
  }

  protected renderWeekDays(delta: number) {
    const weekDays = getWeekDaysList(this.currentDate.add(delta, 'week'))

    return repeat(
      weekDays,
      (dayData) => dayData.date.format(FORMAT_DATE),
      (dayData) => this.renderDay(dayData, delta === 0),
    )
  }

  protected renderDay(dayData: IMonthDayData, isDayVisible: boolean) {
    const {
      date,
      dayNumber,
      dayClasses,
      dayNumberClasses,
      todayIndicatorClasses,
      textVariant,
      dayLocator,
      dayDateLocator,
      dayDateSelectedLocator,
      isDisabled,
    } = this.getCalendarDayDataWithClasses(dayData)

    const tooltipText = isDisabled && isDayVisible ? this.getTooltipText(date) : undefined

    return html`
      <y-core-tooltip
        .disabled=${!tooltipText}
        .text=${tooltipText}
        delay="500"
        placement="bottom"
      >
        <div slot="activator">
          <y-core-text
            variant=${textVariant}
            class=${classMap(dayClasses)}
            data-locator-date=${dayDateLocator}
            data-locator-date-selected=${dayDateSelectedLocator ? true : nothing}
            data-value=${dayNumber}
            .size=${this.textSize}
            .locator=${dayLocator}
            @click=${() => { this.handleDayClick(date) }}
          >
            <span class=${classMap(dayNumberClasses)}>
              ${dayNumber}
            </span>
            ${date.isToday() ? html`<span data-locator-date-today class=${classMap(todayIndicatorClasses)}></span>` : nothing}
          </y-core-text>
        </div>
      </y-core-tooltip>
    `
  }

  protected renderGridDays(delta: number) {
    if (this.gridModeState === EYGridModes.WEEK) {
      return html`
        ${this.renderWeekDays(delta)}
      `
    }

    return html`
      ${this.renderMonthDays(delta)}
    `
  }

  protected render() {
    return html`
      <div
        class=${classMap(this.rootClasses)}
        @click=${() => { this.resetDropdowns() }}
      >
        <div class="${this.baseClass}__header">
          <div class="${this.baseClass}__header-date">
            ${this.renderHeaderDate()}
          </div>

          <div class="${this.baseClass}__header-buttons">
            <y-core-icon-button
              .disabled=${this.isDisabledPrevButton}
              .icon=${yChevronLeft}
              .size=${this.size}
              variant="text"
              @click=${this.toPrevMonthOrWeekWithAnimation}
            >
            </y-core-icon-button>
  
            <y-core-icon-button
              .disabled=${this.isDisabledNextButton}
              .icon=${yChevronRight}
              .size=${this.size}
              variant="text"
              @click=${this.toNextMonthOrWeekWithAnimation}
            >
            </y-core-icon-button>
          </div>
        </div>

        <div 
          class="${this.baseClass}__grid-header"
          @touchstart=${this.handleTouchStart}
          @touchmove=${this.handleTouchMove}
          @touchend=${this.handleTouchEnd}
        >
          ${this.renderGridHeader()}
        </div>

        <div class="${this.baseClass}__grid-wrapper">
          <div
            class="${this.baseClass}__grid-slider"
            style="transform: translate3d(-100%, 0px, 0px);"
            @touchstart=${this.handleTouchStart}
            @touchmove=${this.handleTouchMove}
            @touchend=${this.handleTouchEnd}
          >
            <div class=${classMap(this.gridClasses)}>
              ${this.renderGridDays(-1)}
            </div>
            <div class=${classMap(this.gridClasses)}>
              ${this.renderGridDays(0)}
            </div>
            <div class=${classMap(this.gridClasses)}>
              ${this.renderGridDays(1)}
            </div>
          </div>
        </div>
      </div>
    `
  }
}
