import { html, css, unsafeCSS, nothing, type PropertyValues } from 'lit'
import { customElement, property, state, query } from 'lit/decorators.js'
import { classMap } from 'lit/directives/class-map.js'
import { Maskito, maskitoTransform, type MaskitoOptions } from '@maskito/core'
import { maskitoDateOptionsGenerator, maskitoDateRangeOptionsGenerator, type MaskitoDateParams } from '@maskito/kit'
import { provide } from '@lit/context'

import { disabledContextCreated, readonlyContextCreated, errorContextCreated, sizeContextCreated } from '~core/ui/fieldWrapper/providers'

import { type TDispatcher, bubblingEvent } from '~core/utils/event-decorator'
import {
  createCoreDatePickerProps,
  type IYCoreDatePickerProps,
  type IYCoreDatePickerExternalProps,
  PickEvent, ShowEvent, HideEvent,
  NavigationEvent, EYCoreDatePickerMode,
} from '~core/ui/datePicker/models/types'
import {
  YCoreDatePickerTagName as tagName,
  YCoreFieldInputTagName,
  YCoreCalendarTagName,
} from '~shared/constants'
import { YC_COMPONENT_ATTRIBUTE_NAME } from '~web/shared/constants/attributes'
import { yCalendar2, yClose } from '~shared/icons'

import { type YCoreFieldInput } from '~core/ui/fieldInput'

import '~core/ui/fieldWrapper'
import '~core/ui/fieldInput'
import '~core/ui/fieldIcon'
import '~core/ui/calendar'
import '~core/ui/popover'
import '~core/ui/simpleButton'

import type { InputEvent, KeydownEvent } from '~core/ui/fieldInput/models/types/events'
import type { YCoreCalendar } from '~core/ui/calendar'
import { booleanConverter } from '~core/utils/converters'
import { hasSlotContent } from '~core/utils/lit-slots'
import type { SelectEvent, RangeStartEvent } from '~core/ui/calendar/models/types/events'
import { renderLabel, renderError, renderAnnotation } from '~core/renderers'
import classMapToString from '~core/utils/classMapToString'
import { preventAndStopEvent } from '~shared/utils/helpers'
import {
  parseDate,
  formatDate,
  FORMAT_DATE_DMY,
  FORMAT_DATE_DM,
  getDefaultMinDate,
  getDefaultMaxDate,
  isDateWithoutYear,
  parseDateWithoutYear,
} from '~shared/utils/dateTime'

import { EYCoreDropdownPlacement, EYCoreDropdownTrigger } from '~core/ui/dropdown/models/types'

import YCoreDatePickerVarsCSS from '~core/ui/datePicker/css/DatePicker.vars.css?inline'
import YCoreDatePickerScopedCSS from '~core/ui/datePicker/css/DatePicker.scoped.css?inline'

import { LocalizedElement } from '~core/i18n/LocalizedElement'
import { EYCoreTipType } from '~core/ui/tip/models/types'
import { HANDLED_KEYS } from '../../utils/list-keyboard-navigation'
import { createDynamicMask } from '~web/shared/utils/createDynamicMask'

const {
  labelText,
  labelTooltipText,
  labelDebounce,
  annotationText,
  disabled,
  name,
  placeholder,
  readonly,
  required,
  size,
  error,
  errors,
  minDate,
  maxDate,
  date,
  allowEmptyDate,
  calendarHeaderSelectors,
  availableDates,
  disabledDates,
  checkedDates,
  mode,
  maskOptions,
  ellipsis,
  disabledDatesTooltipText,
  getTooltipTextForDate,
  labelTooltipPlacement,
  labelLocator,
  locator,
  allowEmptyYear,
  emptyYearFormat,
} = createCoreDatePickerProps()

const RANGE_SEPARATOR = ' - '

const DAY_MONTH_DIGITS_COUNT = (FORMAT_DATE_DM.match(/[A-Z]/gi) ?? []).length

/**
 * Полная маска (дд.мм.гггг) нужна, как только день и месяц введены целиком — дальше идёт год.
 * Считаем по количеству цифр, а не по второму разделителю: иначе на маске дд.мм (ровно 5 символов,
 * она «заполнена» на 22.07) некуда вписать разделитель года и ввод застревает. Цифровой порог
 * позволяет вводить дату подряд (22072024 → 22.07.2024) и при этом остановиться на дд.мм.
 */
const shouldUseFullDateMask = (value: string) => value.replace(/\D/g, '').length > DAY_MONTH_DIGITS_COUNT

@customElement(tagName)
export class YCoreDatePicker
  extends LocalizedElement
  implements Required<IYCoreDatePickerProps> {
  @provide({ context: disabledContextCreated })
  @property({ type: Boolean }) disabled: IYCoreDatePickerExternalProps['disabled'] = disabled
  @provide({ context: readonlyContextCreated })
  @property({ type: Boolean }) readonly: IYCoreDatePickerExternalProps['readonly'] = readonly
  @provide({ context: errorContextCreated })
  @property({ type: Boolean, reflect: true, converter: booleanConverter }) error: IYCoreDatePickerExternalProps['error'] = error
  @provide({ context: sizeContextCreated })
  @property({ type: String, reflect: true }) size: IYCoreDatePickerExternalProps['size'] = size
  @property({ type: String }) date: IYCoreDatePickerExternalProps['date'] = date
  @property({ type: String }) name: IYCoreDatePickerExternalProps['name'] = name
  @property({ type: String }) placeholder: IYCoreDatePickerExternalProps['placeholder'] = placeholder
  @property({ type: Boolean, reflect: true }) required: IYCoreDatePickerExternalProps['required'] = required
  @property({ type: Boolean, attribute: 'allow-empty-date' }) allowEmptyDate: IYCoreDatePickerExternalProps['allowEmptyDate'] = allowEmptyDate
  @property({ type: Boolean, attribute: 'allow-empty-year' }) allowEmptyYear: IYCoreDatePickerExternalProps['allowEmptyYear'] = allowEmptyYear
  @property({ type: String, attribute: 'empty-year-format' }) emptyYearFormat: IYCoreDatePickerExternalProps['emptyYearFormat'] = emptyYearFormat
  @property({ type: String, attribute: 'label-text' }) labelText: IYCoreDatePickerExternalProps['labelText'] = labelText
  @property({ type: String, attribute: 'label-tooltip-text' }) labelTooltipText: IYCoreDatePickerExternalProps['labelTooltipText'] = labelTooltipText
  @property({ type: String, attribute: 'label-tooltip-placement' }) labelTooltipPlacement: IYCoreDatePickerExternalProps['labelTooltipPlacement'] = labelTooltipPlacement
  @property({ type: Number, attribute: 'label-debounce' }) labelDebounce: IYCoreDatePickerExternalProps['labelDebounce'] = labelDebounce
  @property({ type: String, attribute: 'annotation-text' }) annotationText: IYCoreDatePickerExternalProps['annotationText'] = annotationText
  @property({ type: Array }) errors: IYCoreDatePickerExternalProps['errors'] = errors
  @property({ type: String, attribute: 'label-locator' }) labelLocator: IYCoreDatePickerExternalProps['labelLocator'] = labelLocator
  @property({ type: String }) locator: IYCoreDatePickerExternalProps['locator'] = locator
  @property({ type: Boolean, attribute: 'calendar-header-selectors' }) calendarHeaderSelectors: IYCoreDatePickerExternalProps['calendarHeaderSelectors'] = calendarHeaderSelectors
  @property({ type: String, attribute: 'min-date' }) minDate: IYCoreDatePickerExternalProps['minDate'] = minDate
  @property({ type: String, attribute: 'max-date' }) maxDate: IYCoreDatePickerExternalProps['maxDate'] = maxDate
  @property({ attribute: false }) availableDates: IYCoreDatePickerExternalProps['availableDates'] = availableDates
  @property({ attribute: false }) disabledDates: IYCoreDatePickerExternalProps['disabledDates'] = disabledDates
  @property({ attribute: false }) checkedDates: IYCoreDatePickerExternalProps['checkedDates'] = checkedDates
  @property({ attribute: false }) disabledDatesTooltipText: IYCoreDatePickerExternalProps['disabledDatesTooltipText'] = disabledDatesTooltipText
  @property({ type: String, reflect: true }) mode: IYCoreDatePickerExternalProps['mode'] = mode
  @property({ type: Object, attribute: 'mask-options' }) maskOptions: IYCoreDatePickerExternalProps['maskOptions'] = maskOptions
  @property({ type: Boolean }) ellipsis: IYCoreDatePickerExternalProps['ellipsis'] = ellipsis
  @property({ type: Object, attribute: 'get-tooltip-text-for-date' }) getTooltipTextForDate: IYCoreDatePickerExternalProps['getTooltipTextForDate'] = getTooltipTextForDate

  @state() private isOpened = false
  @state() private hasAnnotationSlot = false
  @state() private pickedDate: IYCoreDatePickerExternalProps['date'] | null = null
  @state() private hasIncompleteRangeInPicked = false

  @query(YCoreFieldInputTagName) public readonly fieldInput?: YCoreFieldInput
  @query(YCoreCalendarTagName) public readonly calendar?: YCoreCalendar

  @bubblingEvent(
    PickEvent,
    { name: 'pick' },
  )
  _pick!: TDispatcher<PickEvent>

  @bubblingEvent(
    ShowEvent,
    { name: 'show' },
  )
  _show!: TDispatcher<ShowEvent>

  @bubblingEvent(
    HideEvent,
    { name: 'hide' },
  )
  _hide!: TDispatcher<HideEvent>

  @bubblingEvent(
    NavigationEvent,
    { name: 'navigation' },
  )
  _navigation!: TDispatcher<NavigationEvent>

  private maskInstance?: Maskito

  private readonly baseClass = tagName

  static readonly styles = [
    css`
      ${unsafeCSS(YCoreDatePickerVarsCSS)}
      ${unsafeCSS(YCoreDatePickerScopedCSS)}
    `,
  ]

  private get computedClasses() {
    return { [this.baseClass]: true }
  }
  private get computedLabelClasses() {
    return { [`${this.baseClass}__label`]: true }
  }
  private get computedAnnotationClasses() {
    return {
      [`${this.baseClass}__annotation`]: true,
      [`${this.baseClass}__annotation_hide`]: !this.hasAnnotation,
    }
  }
  private get computedFieldWrapperClasses() {
    return { [`${this.baseClass}__field-wrapper`]: true }
  }

  private get hasAnnotation() {
    return this.annotationText || this.hasAnnotationSlot
  }

  private get isSingleMode() {
    return this.mode === EYCoreDatePickerMode.SINGLE
  }

  /**
   * Режим необязательного года доступен только для одиночной даты.
   */
  private get isEmptyYearAllowed(): boolean {
    return Boolean(this.allowEmptyYear) && this.isSingleMode
  }

  private get computedPlaceholder(): IYCoreDatePickerExternalProps['placeholder'] {
    if (!this.placeholder && this.isEmptyYearAllowed) {
      return this.getLocale().messages.dateWithoutYearPlaceholder
    }

    return this.placeholder
  }

  private get computedMinDate() {
    return this.minDate ? parseDate(this.minDate) : getDefaultMinDate()
  }

  private get computedMaxDate() {
    return this.maxDate ? parseDate(this.maxDate) : getDefaultMaxDate()
  }

  private get fullDateMaskParams(): MaskitoDateParams {
    return {
      mode: FORMAT_DATE_DMY.toLowerCase() as MaskitoDateParams['mode'],
      min: this.computedMinDate.toDate(),
      max: this.computedMaxDate.toDate(),
    }
  }

  private get dayMonthMaskParams(): MaskitoDateParams {
    return { mode: FORMAT_DATE_DM.toLowerCase() as MaskitoDateParams['mode'] }
  }

  private get emptyYearMaskOptions(): MaskitoOptions {
    const fullYearMaskOptions = maskitoDateOptionsGenerator(this.fullDateMaskParams)
    const dayMonthMaskOptions = maskitoDateOptionsGenerator(this.dayMonthMaskParams)
    const maskResolver = (value: string) => shouldUseFullDateMask(value)
      ? fullYearMaskOptions
      : dayMonthMaskOptions

    return {
      ...createDynamicMask(maskResolver),
      overwriteMode: dayMonthMaskOptions.overwriteMode,
    }
  }

  private get fieldMaskOptions(): MaskitoOptions {
    if (this.isEmptyYearAllowed) return this.emptyYearMaskOptions

    return this.isSingleMode
      ? maskitoDateOptionsGenerator(this.fullDateMaskParams)
      : maskitoDateRangeOptionsGenerator({ ...this.fullDateMaskParams, rangeSeparator: RANGE_SEPARATOR })
  }

  private get isEmptyRangeDate(): boolean {
    return Array.isArray(this.date) && !this.date.some(Boolean)
  }

  private get isEmptySingleDate(): boolean {
    return !this.date
  }

  private get isDeleteIcon() {
    const hasDate = Array.isArray(this.date) ? !this.isEmptyRangeDate : !this.isEmptySingleDate
    return hasDate && !this.disabled && !this.readonly && this.allowEmptyDate
  }

  private getArrayDateMaskedValue(): string {
    if (!Array.isArray(this.date)) return ''

    const mapDate = (date: string) => formatDate(parseDate(date), FORMAT_DATE_DMY)

    switch (this.mode) {
      case EYCoreDatePickerMode.MIXED:
        return this.date.filter(Boolean).map(mapDate).join(RANGE_SEPARATOR)
      case EYCoreDatePickerMode.RANGE:
        return this.date.map(mapDate).join(RANGE_SEPARATOR)
      default:
        return ''
    }
  }

  private get maskedValue() {
    if (Array.isArray(this.date) && !this.isEmptyRangeDate) {
      return maskitoTransform(this.getArrayDateMaskedValue(), this.fieldMaskOptions)
    }

    const dateString = typeof this.date === 'string'
      ? this.formatSingleDate(this.date)
      : ''

    return maskitoTransform(dateString, this.fieldMaskOptions)
  }

  /**
   * Форматирует одиночную дату для инпута. В режиме без года значение MM-DD
   * показывается как «дд.мм», полная дата — как «дд.мм.гггг».
   */
  private formatSingleDate(date: string): string {
    if (!date) return ''

    if (this.isEmptyYearAllowed && isDateWithoutYear(date, this.emptyYearFormat)) {
      return formatDate(parseDateWithoutYear(date, this.emptyYearFormat), FORMAT_DATE_DM)
    }

    return formatDate(parseDate(date), FORMAT_DATE_DMY)
  }

  private handleSlotAnnotationChange = (event: Event) => {
    preventAndStopEvent(event)

    const target = event.target as HTMLSlotElement

    this.hasAnnotationSlot = hasSlotContent(target)
  }

  private applyMask() {
    const { inputElement } = this.fieldInput ?? {}
    if (!inputElement) return

    this.destroyMask()

    this.maskInstance = new Maskito(
      inputElement,
      this.fieldMaskOptions,
    )
  }

  private destroyMask() {
    if (!this.maskInstance) return

    this.maskInstance.destroy()
  }

  private updateFieldInputValue = (value?: string) => {
    if (!this.fieldInput?.inputElement) return

    this.fieldInput.inputElement.value = value ?? ''
  }

  private handleCalendarRangeStart = (event: RangeStartEvent): void => {
    const date = event.detail.value

    if (this.mode === EYCoreDatePickerMode.MIXED) {
      this.date = [date, '']
    } else {
      const newValue = formatDate(parseDate(date), FORMAT_DATE_DMY) + RANGE_SEPARATOR
      this.updateFieldInputValue(newValue)
    }
  }

  private handleCalendarDateSelectSingle = (date: IYCoreDatePickerExternalProps['date']): void => {
    this.date = date
    this._pick({ detail: { value: this.date } })

    this.fieldInput?.inputElement?.blur()
  }

  private handleCalendarDateSelectRange = (date: IYCoreDatePickerExternalProps['date']): void => {
    this.date = date
    this._pick({ detail: { value: this.date } })

    this.fieldInput?.inputElement?.blur()
  }

  private handleCalendarDateSelectMixed = (date: IYCoreDatePickerExternalProps['date']): void => {
    if (this.hasIncompleteRangeInPicked) {
      const startDate = (date as [string, string]).find((item) => !this.pickedDate?.includes(item))

      this.date = [startDate || '', '']

      this.hasIncompleteRangeInPicked = false

      return
    }

    this.date = date
  }

  private handleCalendarDateSelect = (event: SelectEvent): void => {
    const date = event.detail.value

    switch (this.mode) {
      case EYCoreDatePickerMode.SINGLE:
        this.handleCalendarDateSelectSingle(date)
        break
      case EYCoreDatePickerMode.RANGE:
        this.handleCalendarDateSelectRange(date)
        break
      case EYCoreDatePickerMode.MIXED:
        this.handleCalendarDateSelectMixed(date)
        break
    }
  }

  private handleShow = () => {
    this.isOpened = true

    this._show()
  }

  private handleHide = () => {
    this.isOpened = false

    this._hide()

    this.calendar?.resetDropdowns()
  }

  private handleNavigation = (event: NavigationEvent) => {
    event.stopPropagation()

    this._navigation({ detail: { value: event.detail.value } })
  }

  private handleFocus = (): void => {
    if (this.disabled || this.readonly) return

    this.handleShow()

    this.pickedDate = this.date?.length ? this.date : null

    const isPartiallyFilled = (arr: [string, string]) => arr.some(Boolean) && !arr.every(Boolean)

    this.hasIncompleteRangeInPicked = Array.isArray(this.pickedDate) && isPartiallyFilled(this.pickedDate)
  }

  private handleBlur = (): void => {
    if (this.disabled || this.readonly) return

    this.handleHide()

    this.updateEmptyDate()

    if (this.mode === EYCoreDatePickerMode.MIXED) {
      this.resetMixedDate()
    }

    this.updateFieldInputValue(this.maskedValue)

    this.calendar?.updateDate(this.date)
  }

  private handleEsc = (event: KeydownEvent) => {
    if (!this.isOpened) return

    if (event.detail.code === HANDLED_KEYS.ESCAPE) {
      this.fieldInput?.inputElement?.blur()
    }
  }

  private updateEmptyDate = () => {
    if (this.allowEmptyDate) return

    if (!this.date && this.pickedDate) {
      this.date = this.pickedDate
    }
  }

  private validateDate = (date: IYCoreDatePickerExternalProps['date']): boolean => {
    if (!date) return false

    const dateArray = Array.isArray(date) ? date : [date]

    return dateArray.every((item) => parseDate(item).isValid())
  }

  private handleRangeInput = (value: string): void => {
    const [startDate, endDate] = value.split(RANGE_SEPARATOR)

    if (!startDate || !endDate) return

    const isStartDateValid = this.validateDate(startDate)
    const isEndDateValid = this.validateDate(endDate)

    if (!isStartDateValid || !isEndDateValid) return

    const dateStart = parseDate(startDate)
    const dateEnd = parseDate(endDate)

    if (dateEnd.isBefore(dateStart, 'date')) {
      this.date = [formatDate(dateEnd), formatDate(dateStart)]

      this._pick({ detail: { value: this.date } })

      return
    }

    this.date = [startDate, endDate]

    this._pick({ detail: { value: this.date } })
  }

  private handleMixedInput = (value: string): void => {
    const [startDate, endDate] = value.split(RANGE_SEPARATOR)

    const isStartDateValid = this.validateDate(startDate)
    const isEndDateValid = this.validateDate(endDate)

    if (!isStartDateValid && !isEndDateValid) return

    const getDateRange = (): IYCoreDatePickerExternalProps['date'] => {
      if (isStartDateValid && isEndDateValid) {
        return parseDate(endDate).isBefore(parseDate(startDate), 'date')
              ? [endDate, startDate]
              : [startDate, endDate]
      }

      return [
          isStartDateValid ? startDate : '',
          isEndDateValid ? endDate : '',
      ]
    }

    const dateRange = getDateRange()

    this.date = dateRange
    this.pickedDate = dateRange

    this._pick({ detail: { value: this.date } })
  }

  private pickDate(date: IYCoreDatePickerExternalProps['date']): void {
    this.date = date

    this._pick({ detail: { value: date } })
  }

  private handleSingleInput = (value: string): void => {
    if (!value) {
      this.resetDate()
      return
    }

    if (this.isEmptyYearAllowed) {
      this.handleEmptyYearInput(value)
      return
    }

    const inputDate = parseDate(value)

    if (!inputDate.isValid()) return

    this.pickDate(formatDate(inputDate))
  }

  private handleEmptyYearInput(value: string): void {
    const withoutYear = isDateWithoutYear(value, FORMAT_DATE_DM)
    const parsed = withoutYear ? parseDateWithoutYear(value, FORMAT_DATE_DM) : parseDate(value, FORMAT_DATE_DMY)

    if (!parsed.isValid()) return

    this.pickDate(withoutYear ? formatDate(parsed, this.emptyYearFormat) : formatDate(parsed))
  }

  private handleInput = (event: InputEvent): void => {
    const value = maskitoTransform(event.detail.value, this.fieldMaskOptions)

    requestAnimationFrame(() => {
      this.updateFieldInputValue(value)
    })

    switch (this.mode) {
      case EYCoreDatePickerMode.SINGLE:
        this.handleSingleInput(value)
        break
      case EYCoreDatePickerMode.RANGE:
        this.handleRangeInput(value)
        break
      case EYCoreDatePickerMode.MIXED:
        this.handleMixedInput(value)
        break
    }
  }

  private handleIconMouseDown = (event: Event): void => {
    event.preventDefault()

    if (!this.fieldInput?.inputElement) return

    if (this.fieldInput.focused && !this.isDeleteIcon) {
      this.fieldInput.inputElement.blur()

      return
    }

    this.fieldInput.inputElement.focus()
  }

  private resetDate = () => {
    this.date = ''

    if (!this.allowEmptyDate) return

    this.pickedDate = null

    this._pick({ detail: { value: this.date } })
    this.calendar?.updateDate(this.date)
  }

  private resetMixedDate = () => {
    this.date = this.pickedDate || undefined

    this._pick({ detail: { value: this.pickedDate || undefined } })
    this.calendar?.updateDate(this.pickedDate || undefined)
  }

  private handleIconClick = (): void => {
    if (!this.isDeleteIcon) {
      return
    }

    this.resetDate()
  }

  private handleCalendarMouseDown = (event: MouseEvent) => {
    event.preventDefault()
  }

  private handleLabelClick = () => {
    this.fieldInput?.inputElement?.focus()
  }

  private handleLabelMouseDown = (event: Event) => {
    if (this.isOpened) {
      event.preventDefault()
    }
  }

  private handleFieldInputRender = () => {
    this.applyMask()
  }

  private handleCancelClick = () => {
    this.resetMixedDate()
  }

  private handleSubmitClick = () => {
    if (this.validateDate(this.date)) {
      this.pickedDate = this.date
    }

    this.fieldInput?.inputElement?.blur()
  }

  private handleWrapperClickOutside = (e: Event) => {
    e.stopPropagation()
  }

  public focus(): void {
    this.fieldInput?.focus()
  }

  public blur(): void {
    this.fieldInput?.blur()
  }

  disconnectedCallback() {
    super.disconnectedCallback()
    this.destroyMask()
  }

  updated(changedProperties: PropertyValues<this>): void {
    super.updated(changedProperties)

    this.warnEmptyYearWithNonSingleMode(changedProperties)
    this.warnEmptyYearDateFormat(changedProperties)
  }

  private warnEmptyYearWithNonSingleMode(changedProperties: PropertyValues<this>): void {
    if (!changedProperties.has('allowEmptyYear') && !changedProperties.has('mode')) return

    if (this.allowEmptyYear && !this.isSingleMode) {
      console.warn(`[${tagName}] allowEmptyYear поддерживается только в режиме single — проигнорирован`)
    }
  }

  private hasEmptyYearRelevantChange(changedProperties: PropertyValues<this>): boolean {
    return changedProperties.has('date') || changedProperties.has('emptyYearFormat') || changedProperties.has('allowEmptyYear') || changedProperties.has('mode')
  }

  private isEmptyYearDateValid(value: string): boolean {
    return isDateWithoutYear(value, this.emptyYearFormat) || parseDate(value).isValid()
  }

  /**
   * В режиме allowEmptyYear предупреждаем, если переданный date не соответствует emptyYearFormat
   * (и не является полной датой) — чтобы причина Invalid Date была видна разработчику с тегом
   * самого DatePicker, а не внутреннего календаря.
   */
  private warnEmptyYearDateFormat(changedProperties: PropertyValues<this>): void {
    if (!this.hasEmptyYearRelevantChange(changedProperties) || !this.isEmptyYearAllowed) return

    if (typeof this.date !== 'string' || !this.date || this.isEmptyYearDateValid(this.date)) return

    console.warn(`[${tagName}] Значение date "${this.date}" не соответствует формату emptyYearFormat ("${this.emptyYearFormat}") — будет Invalid Date. Передайте дату без года в формате "${this.emptyYearFormat}" или полную дату.`)
  }

  protected renderPopoverActivator() {
    return html`
      <y-core-field-wrapper
        slot="activator"
        .disabled=${this.disabled}
        .readonly=${this.readonly}
        .error=${Boolean(this.errors?.length) || this.error}
        .size=${this.size}
        class=${classMap(this.computedFieldWrapperClasses)}
        @click-outside=${this.handleWrapperClickOutside}
        @blur=${this.handleBlur}
        @focus=${this.handleFocus}
      >
        <y-core-field-input
          .value=${this.maskedValue}
          .name=${this.name}
          .placeholder=${this.computedPlaceholder}
          .required=${this.required}
          .autofocus=${this.autofocus}
          .hideSpaceRight=${true}
          autocomplete="off"
          .maskOptions=${this.maskOptions}
          .ellipsis=${this.ellipsis}
          @input=${this.handleInput}
          @render=${this.handleFieldInputRender}
          @keydown=${this.handleEsc}
        ></y-core-field-input>
        <y-core-field-icon
          .icon=${this.isDeleteIcon ? yClose : yCalendar2}
          .clickable=${true}
          @mousedown=${this.handleIconMouseDown}
          @click=${this.handleIconClick}
        ></y-core-field-icon>
      </y-core-field-wrapper>
    `
  }

  protected renderPopoverContent() {
    return html`
      <div class="${this.baseClass}__calendar" @mousedown=${this.handleCalendarMouseDown}>
        <y-core-calendar
          .locale=${this.locale}
          .date=${this.date}
          .isRange=${!this.isSingleMode}
          .allowEmptyYear=${this.isEmptyYearAllowed}
          .emptyYearFormat=${this.emptyYearFormat}
          .headerSelectors=${this.calendarHeaderSelectors}
          .minDate=${formatDate(this.computedMinDate)}
          .maxDate=${formatDate(this.computedMaxDate)}
          .availableDates=${this.availableDates}
          .disabledDates=${this.disabledDates}
          .checkedDates=${this.checkedDates}
          .disabledDatesTooltipText=${this.disabledDatesTooltipText}
          .getTooltipTextForDate=${this.getTooltipTextForDate}
          @select=${this.handleCalendarDateSelect}
          @range-start=${this.handleCalendarRangeStart}
          @navigation=${this.handleNavigation}
        >
        </y-core-calendar>
      </div>
    `
  }

  protected renderPopoverActions() {
    if (this.mode !== EYCoreDatePickerMode.MIXED) return nothing

    return html`
      <y-core-simple-button
        slot="actions"
        variant="outline"
        @click=${this.handleCancelClick}
      >
        ${this.getLocale().messages.reset}
      </y-core-simple-button>
  
      <y-core-simple-button
        slot="actions"
        variant="primary"
        @click=${this.handleSubmitClick}
      >
        ${this.getLocale().messages.apply}
      </y-core-simple-button>
    `
  }

  connectedCallback() {
    super.connectedCallback()

    this.dataset.locator = tagName
    this.dataset[YC_COMPONENT_ATTRIBUTE_NAME] = ''
  }

  protected render() {
    return html`
      <div class=${classMap(this.computedClasses)}>
        ${renderLabel({
          text: this.labelText,
          tooltipText: this.labelTooltipText,
          tooltipPlacement: this.labelTooltipPlacement,
          debounce: this.labelDebounce,
          tooltipActive: !this.disabled,
          required: this.required,
          disabled: this.disabled,
          handleMouseDown: this.handleLabelMouseDown,
          handleClick: this.handleLabelClick,
          className: classMapToString(this.computedLabelClasses),
        })}
        <y-core-popover
          .type=${EYCoreTipType.PRIMARY}
          .isOpen=${this.isOpened}
          .trigger=${EYCoreDropdownTrigger.MANUAL}
          .placement=${EYCoreDropdownPlacement.BOTTOM_START}
          .offset=${{ mainAxis: 1 }}
          .disabled=${Boolean(this.disabled) || Boolean(this.readonly)}
          .hasArrow=${false}
          .ignoreNativeDropdownEvents=${true}
        >
          ${this.renderPopoverActivator()}

          <div slot="content" class="${this.baseClass}__dropdown-content">
            ${this.renderPopoverContent()}
          </div>
          
          ${this.renderPopoverActions()}
        </y-core-popover>
        ${renderAnnotation({
          text: this.annotationText,
          disabled: this.disabled,
          className: classMapToString(this.computedAnnotationClasses),
          handleSlotAnnotationChange: this.handleSlotAnnotationChange,
        })}
        ${renderError({ errors: this.errors })}
      </div>
    `
  }
}
