import { LitElement, html, css, unsafeCSS, nothing } from 'lit'
import { customElement, property, state } from 'lit/decorators.js'
import { classMap } from 'lit/directives/class-map.js'

import {
  YCoreChipTagName as tagName,
} from '~shared/constants'
import { YC_COMPONENT_ATTRIBUTE_NAME } from '~web/shared/constants/attributes'

import {
  createCoreChipProps,
  type IYCoreChipProps,
  IconRightClickEvent,
} from './models/types'

import YCoreChipVarsCSS from '~core/ui/chip/css/Chip.vars.css?inline'
import YCoreChipScopedCSS from '~core/ui/chip/css/Chip.scoped.css?inline'

import '~core/ui/text'
import '~core/ui/icon'

import { EYCoreTextSize, EYCoreTextVariant } from '~core/ui/text/models/types'
import { EYSizes } from '~shared/types/global'
import type { IYCoreIconExternalProps } from '~core/ui/icon/models/types'
import { interceptEvents } from '~core/utils/event-interceptor'
import { type TDispatcher, bubblingEvent } from '~core/utils/event-decorator'
import { hasSlotContent } from '~core/utils/lit-slots'

const { labelText, iconLeft, iconRight, size, variant, active, disabled, locator } = createCoreChipProps()

@customElement(tagName)
@interceptEvents()
export class YCoreChip extends LitElement implements Required<IYCoreChipProps> {
  @property({ type: String, attribute: 'label-text' }) labelText: IYCoreChipProps['labelText'] = labelText
  @property({ type: Object, attribute: 'icon-left' }) iconLeft: IYCoreChipProps['iconLeft'] = iconLeft
  @property({ type: Object, attribute: 'icon-right' }) iconRight: IYCoreChipProps['iconRight'] = iconRight
  @property({ type: String }) size: IYCoreChipProps['size'] = size
  @property({ type: String }) variant: IYCoreChipProps['variant'] = variant
  @property({ type: Boolean }) active: IYCoreChipProps['active'] = active
  @property({ type: Boolean }) disabled: IYCoreChipProps['disabled'] = disabled
  @property({ type: String }) locator: IYCoreChipProps['locator'] = locator
  @bubblingEvent(
    IconRightClickEvent,
    { name: 'icon-right-click' },
  )
  private _iconRightClick!: TDispatcher<IconRightClickEvent>

  private readonly baseClass = tagName

  static readonly styles = [
    css`
      ${unsafeCSS(YCoreChipVarsCSS)}
      ${unsafeCSS(YCoreChipScopedCSS)}
    `,
  ]

  private get computedClasses() {
    return {
      [this.baseClass]: true,
      [`${this.baseClass}_size_${this.size}`]: Boolean(this.size),
      [`${this.baseClass}_variant_${this.variant}`]: Boolean(this.variant),
      [`${this.baseClass}_active`]: Boolean(this.active),
      [`${this.baseClass}_disabled`]: Boolean(this.disabled),
    }
  }

  private get textSize(): EYCoreTextSize {
    if (this.size === EYSizes.LARGE) return EYCoreTextSize.P1_REGULAR
    if (this.size === EYSizes.MEDIUM) return EYCoreTextSize.P2_REGULAR

    return EYCoreTextSize.A2_REGULAR
  }

  private get textVariant(): EYCoreTextVariant {
    if (this.disabled) return EYCoreTextVariant.TERTIARY

    return EYCoreTextVariant.PRIMARY
  }

  private get iconSize(): IYCoreIconExternalProps['size'] {
    if (this.size === EYSizes.LARGE) return '24px'

    return '16px'
  }

  protected renderLeftIcon() {
    return this.iconLeft
      ? html`
        <y-core-icon
          class="${this.baseClass}__icon-left"
          .icon=${this.iconLeft}
          .size=${this.iconSize}
        ></y-core-icon>`
      : nothing
  }

  @state() private hasSlottedLeftContent = false

  protected renderLeftContent() {
    const hasLeft = !!this.iconLeft || this.hasSlottedLeftContent

    return html`
      <div class="${this.baseClass}__left" ?data-visible=${hasLeft}>
        <slot name="leftContent" @slotchange=${this.handleLeftSlotChange}>${this.renderLeftIcon()}</slot>
      </div>
    `
  }

  private handleLeftSlotChange = (e: Event) => {
    this.hasSlottedLeftContent = hasSlotContent(e.target as HTMLSlotElement)
  }

  private handleIconRightClick = (event: PointerEvent) => {
    event.stopPropagation()

    this._iconRightClick({ detail: { event } })
  }

  protected renderRightIcon() {
    return this.iconRight
      ? html`
        <div class="${this.baseClass}__right" @click=${this.handleIconRightClick}>
          <y-core-icon
            class="${this.baseClass}__icon-right"
            .icon=${this.iconRight}
            .size=${this.iconSize}
          ></y-core-icon>
        </div>`
      : nothing
  }

  connectedCallback() {
    super.connectedCallback()

    this.dataset.locator = this.locator ?? tagName
    this.dataset[YC_COMPONENT_ATTRIBUTE_NAME] = ''
  }

  protected render() {
    return html`
      <div
        class=${classMap(this.computedClasses)}
      >

        ${this.renderLeftContent()}

        <y-core-text
          class="${this.baseClass}__text"
          size=${this.textSize}
          variant=${this.textVariant}
          ellipsis
        >
          ${this.labelText}
        </y-core-text>

        ${this.renderRightIcon()}
      </div>
    `
  }
}
