export const HANDLED_KEYS = {
  ARROW_DOWN: 'ArrowDown',
  ARROW_UP: 'ArrowUp',
  ENTER: 'Enter',
  ESCAPE: 'Escape',
  SPACE: ' ',
} as const

export type THandledKey = (typeof HANDLED_KEYS)[keyof typeof HANDLED_KEYS]

export const isHandledKey = (key: string): key is THandledKey => {
  return Object.values(HANDLED_KEYS).some((value) => value === key)
}
