import { css, html, LitElement, nothing, unsafeCSS } from 'lit'
import { customElement, property } from 'lit/decorators.js'

import '~core/ui/text'
import '~core/ui/icon'
import '~core/ui/counter'
import './SnackbarIcon'

import { yClose } from '~shared/icons'

import YCoreToastScopedCSS from '~core/ui/toast/css/Toast.scoped.css?inline'
import YCoreToastVarsCSS from '~core/ui/toast/css/Toast.vars.css?inline'

import { YCoreToastTagName as tagName } from '~shared/constants'
import { YC_COMPONENT_ATTRIBUTE_NAME } from '~web/shared/constants/attributes'
import { createCoreToastProps, type IYCoreToastProps } from '~core/ui/toast/models/types'
import { EYCoreTextSize, EYCoreTextVariant } from '~core/ui/text/models/types'
import { EYCoreCounterVariant } from '~core/ui/counter/models/types'
import { CloseToastEvent } from '~core/ui/toast/models/events'
import { bubblingEvent, type TDispatcher } from '~core/utils/event-decorator'
import { YC_ICON_BASE_SIZE } from '~core/ui/icon/models/constants'
import { styleMap } from 'lit/directives/style-map.js'

const { counterValue, variant, titleText, description, maxWidth } = createCoreToastProps()

@customElement(tagName)
export class YCoreToast extends LitElement implements Required<IYCoreToastProps> {
  @property({ type: Number, attribute: 'counter-value' }) counterValue: IYCoreToastProps['counterValue'] = counterValue
  @property({ type: String, attribute: 'variant' }) variant: IYCoreToastProps['variant'] = variant
  @property({ type: String, attribute: 'title-text' }) titleText: IYCoreToastProps['titleText'] = titleText
  @property({ type: String, attribute: 'description' }) description: IYCoreToastProps['description'] = description
  @property({ type: String, attribute: 'max-width' }) maxWidth: IYCoreToastProps['maxWidth'] = maxWidth

  @bubblingEvent(CloseToastEvent, { name: 'close' })
  private _close!: TDispatcher<CloseToastEvent>

  private readonly baseClass = tagName

  static readonly styles = [
    css`${unsafeCSS(YCoreToastVarsCSS)}`,
    css`${unsafeCSS(YCoreToastScopedCSS)}`,
    css`${unsafeCSS(':host { --y-core-toast-base-icon-size: ' + YC_ICON_BASE_SIZE + '}')}`,
  ]

  connectedCallback() {
    super.connectedCallback()

    this.dataset.locator = tagName
    this.dataset[YC_COMPONENT_ATTRIBUTE_NAME] = ''
  }

  private get computedStyle() {
    return {
      maxWidth: this.maxWidth ? `min(100%, ${this.maxWidth})` : 'none',
      width: this.maxWidth ? 'max-content' : undefined,
    }
  }

  protected render() {
    return html`
      <div class=${this.baseClass} style=${styleMap(this.computedStyle)}>
        <y-core-snackbar-icon
          .variant=${this.variant}
          class="${this.baseClass}__type-icon"
        ></y-core-snackbar-icon>

        <div class="${this.baseClass}__content">
          <y-core-text
            size=${EYCoreTextSize.P2_MEDIUM}
            variant=${EYCoreTextVariant.PRIMARY_INVERT}
          >
            <div class="${this.baseClass}__title">${this.titleText}</div>
          </y-core-text>

          ${this.description
            ? html`
                <y-core-text
                  size=${EYCoreTextSize.P2_REGULAR}
                  variant=${EYCoreTextVariant.SECONDARY_INVERT}
                >
                  <div class="${this.baseClass}__description">
                    ${this.description}
                  </div>
                </y-core-text>
              `
            : nothing
          }
          
        </div>

        <y-core-icon
          .icon=${yClose}
          class="${this.baseClass}__close"
          role="button"
          tabindex="0"
          aria-label="Закрыть уведомление"
          @click=${this._close}
        ></y-core-icon>
          
        ${this.counterValue > 0
          ? html`
              <y-core-counter
                class="${this.baseClass}__counter"
                .value=${this.counterValue}
                .variant=${EYCoreCounterVariant.NEGATIVE}
              ></y-core-counter>`
          : nothing
        }
      </div>
    `
  }
}
