import { LitElement, html, css, unsafeCSS, nothing } from 'lit'
import { customElement, property } from 'lit/decorators.js'
import { classMap } from 'lit/directives/class-map.js'
import { styleMap } from 'lit/directives/style-map.js'

import {
  ClickIconEmitEvent,
  createCoreSimpleChipProps,
  type IYCoreSimpleChipProps,
} from '~core/ui/simpleChip/models/types'
import {
  YCoreSimpleChipTagName as tagName,
} from '~shared/constants'
import { YC_COMPONENT_ATTRIBUTE_NAME } from '~web/shared/constants/attributes'

import YCoreSimpleChipVarsCss from '~core/ui/simpleChip/css/SimpleChip.vars.css?inline'
import YCoreSimpleChipScopedCss from '~core/ui/simpleChip/css/SimpleChip.scoped.css?inline'

import { bubblingEvent, type TDispatcher } from '~core/utils/event-decorator'
import { renderIcon } from '~core/renderers'
import { yClose } from '~shared/icons'

const { size, variant, disabled, readonly, background, color } = createCoreSimpleChipProps()

@customElement(tagName)
export class YCoreSimpleChip extends LitElement implements Required<IYCoreSimpleChipProps> {
  @property({ type: String }) size: IYCoreSimpleChipProps['size'] = size
  @property({ type: String }) variant: IYCoreSimpleChipProps['variant'] = variant
  @property({ type: Boolean, reflect: true }) disabled: IYCoreSimpleChipProps['disabled'] = disabled
  @property({ type: Boolean }) readonly: IYCoreSimpleChipProps['readonly'] = readonly
  @property({ type: String }) background: IYCoreSimpleChipProps['background'] = background
  @property({ type: String }) color: IYCoreSimpleChipProps['color'] = color

  @bubblingEvent(
    ClickIconEmitEvent,
    { name: 'click-icon' },
  )
  _iconClick!: TDispatcher<ClickIconEmitEvent>

  private readonly baseClass = tagName
  private readonly baseIconClass = `${this.baseClass}__icon`

  static readonly styles = [
    css`
      ${unsafeCSS(YCoreSimpleChipVarsCss)}
      ${unsafeCSS(YCoreSimpleChipScopedCss)}
    `,
  ]

  private get computedClasses() {
    return {
      [this.baseClass]: true,
      [`${this.baseClass}_size_${this.size}`]: Boolean(this.size),
      [`${this.baseClass}_variant_${this.variant}`]: Boolean(this.variant && !this.color),
      [`${this.baseClass}_disabled`]: Boolean(this.disabled),
      [`${this.baseClass}_readonly`]: Boolean(this.readonly),
    }
  }

  private get computedStyle() {
    const styles: Record<string, string> = {}

    if (this.background) {
      styles['background-color'] = this.background
    }

    if (this.color) {
      styles.color = this.color
    }

    return styleMap(styles)
  }

  // Цвет текста <y-core-text> берёт из --y-core-text-color-primary,
  // поэтому переменную задаём на хосте — слот наследует её из light DOM
  protected updated() {
    if (this.color) {
      this.style.setProperty('--y-core-text-color-primary', this.color)
    } else {
      this.style.removeProperty('--y-core-text-color-primary')
    }
  }

  private handleIconClick = (event: PointerEvent) => {
    if (this.disabled) return

    this._iconClick({ detail: event })
  }

  connectedCallback() {
    super.connectedCallback()

    this.dataset.locator = tagName
    this.dataset[YC_COMPONENT_ATTRIBUTE_NAME] = ''
  }

  protected render() {
    return html`
      <div class=${classMap(this.computedClasses)} style=${this.computedStyle}>
        <slot></slot>

        ${!this.readonly
          ? html`
              <div @click=${this.handleIconClick} class=${this.baseIconClass}>
                  ${renderIcon({ icon: yClose, size: '16px' })}
              </div>  
            `
          : nothing
        }
      </div>
    `
  }
}
