import {
  createCoreCounterExternalProps,
  type IYCoreCounterExternalProps,
} from './external'
import {
  type IYCoreCounterInternalProps,
  createCorePopoverInternalProps,
} from './internal'

export * from './external'

export interface IYCoreCounterProps extends IYCoreCounterExternalProps, IYCoreCounterInternalProps {}

export const createCoreCounterProps = (): IYCoreCounterProps => {
  return { ...createCoreCounterExternalProps(), ...createCorePopoverInternalProps() }
}
