/**
 * @module ToastsPlugin/Constants
 * @description Константы и конфигурация по умолчанию для плагина очереди тостов
 */

import type { IToastQueueConfig } from '~core/ui/globalProvider/context/modules/ToastQueueModule'
import type { IToastQueueHostConfig } from './types'

/**
 * Конфигурация плагина очереди тостов по умолчанию
 * @constant
 * @type {IToastQueueHostConfig}
 * @property {number} maxVisible - Максимальное количество одновременно видимых тостов (по умолчанию 3)
 * @property {string} position - Позиция тостов на экране (по умолчанию 'top-center')
 * @property {number} defaultDuration - Длительность показа тоста в миллисекундах (по умолчанию 5000)
 * @property {boolean} pauseOnHover - Приостанавливать таймер при наведении курсора (по умолчанию true)
 * @property {string} host - Селектор DOM-элемента для размещения тостов (по умолчанию 'body')
 */
const BASE_TOAST_QUEUE_CONFIG: IToastQueueHostConfig = {
  maxVisible: 3,
  position: 'top-center',
  defaultDuration: 5000,
  pauseOnHover: true,
}

export const DEFAULT_TOAST_QUEUE_HOST_CONFIG: IToastQueueHostConfig = { ...BASE_TOAST_QUEUE_CONFIG }

export const DEFAULT_TOAST_QUEUE_PLUGIN_CONFIG: IToastQueueConfig = {
  ...BASE_TOAST_QUEUE_CONFIG,
  host: 'body',
}

export const TOASTS_PLUGIN_INITIALIZATION_TIMEOUT = 5000

export const TOAST_ENTER_LEAVE_DURATION_MS = 200

export const BASE_DELAY_BETWEEN_LEAVING_TOASTS = 500
