export interface ITransitionClasses {
  enter: string
  enterActive: string
  enterTo: string
  leave: string
  leaveActive: string
  leaveTo: string
  noTransition: string
}

export interface IElementTransition {
  enter: () => Promise<void>
  leave: () => Promise<void>
  abortLeave: () => void
  abortEnter: () => void
}

const MS_PER_SECOND = 1000
const FALLBACK_BUFFER_MS = 50

export const createTransition = (element: HTMLElement, classes: ITransitionClasses): IElementTransition => {
  let fallbackTimer: ReturnType<typeof setTimeout> | undefined
  let activeListener: ((event: TransitionEvent) => void) | undefined

  const cleanup = () => {
    if (fallbackTimer !== undefined) {
      clearTimeout(fallbackTimer)
      fallbackTimer = undefined
    }
    if (activeListener !== undefined) {
      element.removeEventListener('transitionend', activeListener)
      activeListener = undefined
    }
  }

  const handleTransition = (
    initialClass: string,
    activeClass: string,
    toClass: string,
  ): Promise<void> => {
    return new Promise((resolve) => {
      element.classList.add(initialClass)

      // Reflow разделяет initial- и active-состояния, иначе браузер объединит их и переход не запустится
      // eslint-disable-next-line @typescript-eslint/no-unused-expressions
      element.offsetHeight

      element.classList.add(activeClass)
      element.classList.add(toClass)
      element.classList.remove(initialClass)

      const computedStyle = window.getComputedStyle(element)
      const hasTransition = computedStyle.transitionDuration !== '0s'

      if (!hasTransition) {
        element.classList.remove(activeClass)
        element.classList.remove(toClass)
        resolve()
        return
      }

      const durationMs = parseFloat(computedStyle.transitionDuration) * MS_PER_SECOND

      const finish = () => {
        cleanup()
        element.classList.remove(activeClass)
        element.classList.remove(toClass)
        resolve()
      }

      const onTransitionEnd = (event: TransitionEvent) => {
        if (event.target !== element) return
        finish()
      }

      activeListener = onTransitionEnd
      element.addEventListener('transitionend', onTransitionEnd)
      // transitionend может не стрельнуть, если элемент удалён из DOM или перекрыт display: none
      fallbackTimer = setTimeout(finish, durationMs + FALLBACK_BUFFER_MS)
    })
  }

  const abort = (...abortClasses: string[]) => {
    cleanup()

    element.classList.add(classes.noTransition)
    element.classList.remove(...abortClasses)

    // Reflow фиксирует снятие классов без анимации, прежде чем requestAnimationFrame вернёт transitions
    // eslint-disable-next-line @typescript-eslint/no-unused-expressions
    element.offsetHeight

    requestAnimationFrame(() => {
      element.classList.remove(classes.noTransition)
    })
  }

  return {
    enter: () => handleTransition(
      classes.enter,
      classes.enterActive,
      classes.enterTo,
    ),
    leave: () => handleTransition(
      classes.leave,
      classes.leaveActive,
      classes.leaveTo,
    ),
    abortLeave: () => {
      abort(classes.leaveTo)
    },
    abortEnter: () => {
      abort(classes.enterTo)
    },
  }
}
