import { html } from 'lit'
import { renderIcon } from '~core/renderers'
import { yBigChevronUp, yBigChevronDown } from '~shared/icons'

export interface IRenderControlChevronOptions {
  baseClass: string
  isOpened?: boolean
}

export const renderControlChevron = ({ baseClass, isOpened }: IRenderControlChevronOptions) => {
  return html`
    <div class=${`${baseClass}__control`}>
      ${renderIcon({
        icon: isOpened ? yBigChevronUp : yBigChevronDown,
        size: '12px',
        className: `${baseClass}__chevron`,
      })}
    </div>
  `
}
