import { LitElement, css, nothing, unsafeCSS, type PropertyValues } from 'lit'
import { html } from 'lit/static-html.js'
import { customElement, property, query, state } from 'lit/decorators.js'
import { classMap } from 'lit/directives/class-map.js'

import '~core/ui/loader'
import '~core/ui/iconButton'
import { bubblingEvent, type TDispatcher } from '~core/utils/event-decorator'
import { isClickOutside } from '~core/utils/dom-events'
import { BreakpointsController } from '~core/utils/breakpoints'
import YCoreTransitionCss from '~core/assets/css/transitions.css?inline'

import { YCoreModalTagName as tagName } from '~shared/constants'
import { YC_COMPONENT_ATTRIBUTE_NAME } from '~web/shared/constants/attributes'
import { yBigClose } from '~shared/icons'
import { createTransition, type IElementTransition } from '~shared/utils/transition'

import { createCoreModalProps, type IYCoreModalProps } from './models/types'
import { OVERLAY_TRANSITION_CLASSES, BOTTOM_SHEET_TRANSITION_CLASSES } from './models/constants/transitions'
import {
  OpenEvent,
  CloseEvent,
  ClickCloseIconEvent,
  ClickOutsideEvent,
  ClickActivatorEvent,
  PressEscapeEvent,
} from './models/types/events'

import ModalVarsCSS from './css/Modal.vars.css?inline'
import ModalScopedCSS from './css/Modal.scoped.css?inline'

const { open, size, variant, width, preventEscape, hideOverlay, fullScreen, persistent, showGrabber } = createCoreModalProps()

@customElement(tagName)
export class YCoreModal extends LitElement implements Required<IYCoreModalProps> {
  @property({ type: Boolean }) open: IYCoreModalProps['open'] = open
  @property({ type: String }) size: IYCoreModalProps['size'] = size
  @property({ type: String }) variant: IYCoreModalProps['variant'] = variant
  @property({ type: String }) width: IYCoreModalProps['width'] = width
  @property({ type: Boolean, attribute: 'prevent-escape' }) preventEscape: IYCoreModalProps['preventEscape'] = preventEscape
  @property({ type: Boolean, attribute: 'hide-overlay' }) hideOverlay: IYCoreModalProps['hideOverlay'] = hideOverlay
  @property({ type: Boolean, attribute: 'full-screen' }) fullScreen: IYCoreModalProps['fullScreen'] = fullScreen
  @property({ type: Boolean, attribute: 'persistent' }) persistent: IYCoreModalProps['persistent'] = persistent
  @property({ type: Boolean, attribute: 'show-grabber' }) showGrabber: IYCoreModalProps['showGrabber'] = showGrabber

  @bubblingEvent(OpenEvent, { name: 'open' })
  protected _open!: TDispatcher<OpenEvent>

  @bubblingEvent(CloseEvent, { name: 'close' })
  protected _close!: TDispatcher<CloseEvent>

  @bubblingEvent(ClickCloseIconEvent, { name: 'click-close-icon' })
  protected _clickCloseIcon!: TDispatcher<ClickCloseIconEvent>

  @bubblingEvent(ClickOutsideEvent, { name: 'click-outside' })
  protected _clickOutside!: TDispatcher<ClickOutsideEvent>

  @bubblingEvent(ClickActivatorEvent, { name: 'click-activator' })
  protected _clickActivator!: TDispatcher<ClickActivatorEvent>

  @bubblingEvent(PressEscapeEvent, { name: 'press-escape' })
  protected _pressEscape!: TDispatcher<PressEscapeEvent>

  @query(`.${tagName}__overlay`) private overlay?: HTMLElement
  @query(`.${tagName}`) private modal?: HTMLElement

  @state() private isOpen = false
  @state() private overlayTransition?: IElementTransition
  @state() private bottomSheetTransition?: IElementTransition

  private swipe = {
    active: false,
    pointerId: -1,
    startX: 0,
    startY: 0,
    startTime: 0,
  }

  private readonly breakpoints = new BreakpointsController(this)

  protected get isBottomSheet() {
    return this.breakpoints.smallerOrEqual('XS')
  }

  protected get baseClass() {
    return tagName
  }

  protected get computedClasses() {
    return {
      [this.baseClass]: true,
      [`${this.baseClass}_size_${this.size}`]: !this.fullScreen && !this.isBottomSheet,
      [`${this.baseClass}_full-screen`]: Boolean(this.fullScreen),
      [`${this.baseClass}_variant_${this.variant}`]: true,
      [`${this.baseClass}_bottom-sheet`]: this.isBottomSheet,
    }
  }

  protected get computedStyles() {
    return this.width && !this.isBottomSheet ? `max-width: ${this.width};` : ''
  }

  connectedCallback() {
    super.connectedCallback()

    this.dataset.locator = tagName
    this.dataset[YC_COMPONENT_ATTRIBUTE_NAME] = ''

    window.addEventListener('keydown', this.handleKeydown)
  }

  disconnectedCallback() {
    super.disconnectedCallback()
    window.removeEventListener('keydown', this.handleKeydown)
  }

  private animateBottomSheetOnEnter = () => {
    if (!this.isBottomSheet || !this.modal) {
      this.bottomSheetTransition = undefined

      return
    }

    const transition = createTransition(this.modal, BOTTOM_SHEET_TRANSITION_CLASSES)
    transition.enter().then(() => {
      this.bottomSheetTransition = transition
    })
  }


  private animateOverlayOnEnter = () => {
    if (!this.overlay) {
      this.overlayTransition = undefined

      return
    }

    const transition = createTransition(this.overlay, OVERLAY_TRANSITION_CLASSES)
    transition.enter().then(() => {
      this.overlayTransition = transition
    })
  }

  private animateBottomSheetOnLeave = () => {
    if (!this.isBottomSheet || !this.modal) {
      this.bottomSheetTransition = undefined

      return
    }

    this.bottomSheetTransition = createTransition(this.modal, BOTTOM_SHEET_TRANSITION_CLASSES)
    this.bottomSheetTransition.leave().finally(() => {
      this.bottomSheetTransition = undefined
    })
  }

  private animateOverlayOnLeave = () => {
    if (!this.overlay) {
      this.overlayTransition = undefined

      return
    }

    this.overlayTransition = createTransition(this.overlay, OVERLAY_TRANSITION_CLASSES)
    this.overlayTransition.leave().finally(() => {
      this.overlayTransition = undefined
    })
  }

  private openModal() {
    this.isOpen = true
    this._open()

    requestAnimationFrame(() => {
      this.animateBottomSheetOnEnter()
      this.animateOverlayOnEnter()
    })
  }

  private closeModal() {
    this.isOpen = false
    this._close()

    requestAnimationFrame(() => {
      this.animateBottomSheetOnLeave()
      this.animateOverlayOnLeave()
    })
  }

  private handleCloseIconClick = (event: Event) => {
    event.stopPropagation()

    this._clickCloseIcon()
    this.closeModal()
  }

  private handleBackdropClick = (event: MouseEvent) => {
    if (!this.isOpen || event.defaultPrevented || this.persistent) return

    const modalElement = this.renderRoot.querySelector(`.${this.baseClass}`)
    if (!modalElement) return

    if (isClickOutside(event, modalElement)) {
      this._clickOutside()
      this.closeModal()
    }
  }

  private handleActivatorClick = (event: Event) => {
    event.stopPropagation()
    if (this.isOpen) return

    this._clickActivator()
    this.openModal()
  }

  private handleKeydown = (event: KeyboardEvent) => {
    event.stopPropagation()
    if (!this.isOpen || this.persistent) return

    if (!this.preventEscape && event.code === 'Escape') {
      this._pressEscape()
      this.closeModal()
    }
  }

  private removeSwipeListeners = () => {
    window.removeEventListener('pointermove', this.handleGrabberPointerMove)
    window.removeEventListener('pointerup', this.handleGrabberPointerUp)
    window.removeEventListener('pointercancel', this.handleGrabberPointerCancel)
  }

  private startGrabberSwipe = (event: PointerEvent) => {
    this.swipe.active = true
    this.swipe.pointerId = event.pointerId
    this.swipe.startX = event.clientX
    this.swipe.startY = event.clientY
    this.swipe.startTime = event.timeStamp

    const currentTarget = event.currentTarget as HTMLElement | null
    if (!currentTarget) return

    try {
      currentTarget.setPointerCapture(event.pointerId)
    } catch {
      //
    }
  }

  private isMostlyVerticalSwipe = (deltaX: number, deltaY: number) => {
    const absDeltaX = Math.abs(deltaX)
    const absDeltaY = Math.abs(deltaY)
    return deltaY > 0 && absDeltaY > absDeltaX && absDeltaX < absDeltaY * 0.6
  }

  private getSwipeMinDistance = (pointerType: PointerEvent['pointerType']) => {
    return pointerType === 'touch' ? 56 : 72
  }

  private shouldCloseFromSwipe = (event: PointerEvent) => {
    const deltaX = event.clientX - this.swipe.startX
    const deltaY = event.clientY - this.swipe.startY

    const minDistance = this.getSwipeMinDistance(event.pointerType)

    return (
      this.isOpen &&
      !this.persistent &&
      this.isBottomSheet &&
      this.showGrabber &&
      deltaY > minDistance &&
      this.isMostlyVerticalSwipe(deltaX, deltaY)
    )
  }

  private handleGrabberPointerDown = (event: PointerEvent) => {
    this.startGrabberSwipe(event)
    window.addEventListener('pointermove', this.handleGrabberPointerMove, { passive: false })
    window.addEventListener('pointerup', this.handleGrabberPointerUp)
    window.addEventListener('pointercancel', this.handleGrabberPointerCancel)

    event.stopPropagation()
    event.preventDefault()
  }

  private handleGrabberPointerMove = (event: PointerEvent) => {
    if (!this.swipe.active) return
    if (event.pointerId !== this.swipe.pointerId) return

    const deltaX = event.clientX - this.swipe.startX
    const deltaY = event.clientY - this.swipe.startY

    if (deltaY > 0 && Math.abs(deltaY) > Math.abs(deltaX)) {
      event.preventDefault()
    }
  }

  private handleGrabberPointerUp = (event: PointerEvent) => {
    if (!this.swipe.active) return
    if (event.pointerId !== this.swipe.pointerId) return

    this.swipe.active = false
    this.removeSwipeListeners()

    if (this.shouldCloseFromSwipe(event)) {
      event.stopPropagation()
      event.preventDefault()
      this.closeModal()
    }
  }

  private handleGrabberPointerCancel = (event: PointerEvent) => {
    if (!this.swipe.active) return
    if (event.pointerId !== this.swipe.pointerId) return

    this.swipe.active = false
    this.removeSwipeListeners()
  }

  protected updated(changedProperties: PropertyValues) {
    if (changedProperties.has('open') && this.open !== this.isOpen) {
      if (this.open) {
        this.openModal()
      } else {
        this.closeModal()
      }
    }
  }

  protected renderOverlay() {
    return html`<div class="${this.baseClass}__overlay"></div>`
  }

  protected renderModal() {
    return html`
      <div
        class=${classMap(this.computedClasses)}
        style=${this.computedStyles}
        role="dialog"
        aria-modal="true"
        aria-labelledby="modal-title"
      >
        <slot name="content"></slot>

        ${!this.persistent
          ? html`
            <div class="${this.baseClass}__close">
              <slot name="close">
                <y-core-icon-button
                  .icon=${yBigClose}
                  variant="text"
                  @click=${this.handleCloseIconClick}
                >
                </y-core-icon-button>
              </slot>

            </div>
            `
          : nothing}

          ${this.isBottomSheet && this.showGrabber
            ? html`<div
                class="${this.baseClass}__grabber"
                @pointerdown=${this.handleGrabberPointerDown}
              ></div>`
            : nothing}
      </div>
    `
  }

  protected get isModalContentVisible() {
    return this.isOpen || !!this.overlayTransition || !!this.bottomSheetTransition
  }

  protected get isModalVisible() {
    return this.isOpen || !!this.bottomSheetTransition
  }

  protected get isOverlayVisible() {
    return !this.hideOverlay && (this.isBottomSheet || !this.fullScreen)
  }

  protected render() {
    return html`
      <slot
        name="activator"
        @click=${this.handleActivatorClick}
      ></slot>

      ${this.isModalContentVisible
        ? html`
            <div
              class="${this.baseClass}__backdrop"
              @click=${this.handleBackdropClick}
            >
              ${this.isOverlayVisible ? this.renderOverlay() : nothing}
              ${this.isModalVisible ? this.renderModal() : nothing}
            </div>

          `
        : nothing}
    `
  }

  static readonly styles = [
    css`
      ${unsafeCSS(ModalVarsCSS)}
      ${unsafeCSS(ModalScopedCSS)}
      ${unsafeCSS(YCoreTransitionCss)}
    `,
  ]
}
