import type { TYSizes } from '~shared/types/global'

export const enum EYCoreCardBasicIconSize {
  SMALL = '16px',
  LARGE = '24px',
}

export enum EYCoreCardBasicAlignment {
  TOP = 'top',
  CENTER = 'center',
}

export type TYCoreCardBasicAlignment = `${EYCoreCardBasicAlignment}`

export interface IYCoreCardBasicLeftSideProps {

  /**
   * Размер карточки
   */
  size: Extract<TYSizes, 'small' | 'medium' | 'large'>
}

export interface IYCoreCardBasicTextContentProps {

  /**
   * Размер заголовка
   * @default 'default'
   */
  titleSize: 'small' | 'default'

  /**
   * Текст заголовка
   */
  titleText: string

  /**
   * Текст аннотации
   */
  annotationText: string | undefined

  /**
   * Текст подзаголовка
   */
  subheadText: string | undefined
}

export interface IYCoreCardBasicRightSideProps {

  /**
   * Показывать стрелку (chevron)
   */
  chevron: Extract<TYSizes, 'small' | 'large'> | undefined

  /**
   * Можно ли удалить карточку
   */
  removable: boolean | undefined
}

/**
 * Свойства компонента CardBasic
 */
export interface IYCoreCardBasicExternalProps extends
  IYCoreCardBasicLeftSideProps,
  IYCoreCardBasicTextContentProps,
  IYCoreCardBasicRightSideProps {

  /**
   * Внутренние отступы карточки
   */
  padding: Extract<TYSizes, 'small' | 'large'> | undefined

  /**
   * Выравнивание контента карточки по оси X
   */
  alignment: TYCoreCardBasicAlignment | undefined

  /**
   * Затемняет фон при событии hover, активно при заданном padding
   */
  hoverable: boolean | undefined

  /**
   * Выделяет карточку как выбранную
   */
  selected: boolean | undefined
}

export const createCoreCardBasicExternalProps = (): IYCoreCardBasicExternalProps => {
  return {
    size: 'small',
    titleSize: 'default',
    alignment: EYCoreCardBasicAlignment.CENTER,
    titleText: '',
    subheadText: undefined,
    annotationText: undefined,
    chevron: undefined,
    removable: undefined,
    padding: undefined,
    hoverable: undefined,
    selected: undefined,
  }
}
