import { createCoreSimpleButtonExternalProps, type IYCoreSimpleButtonExternalProps } from '~core/ui/simpleButton/models/types/external'
import { pick } from 'radash'

export enum EYCoreBrandButtonVariant {
  VK = 'vk',
}

/**
 * Свойства компонента BrandButton
 */
export interface IYCoreBrandButtonExternalProps extends Pick<IYCoreSimpleButtonExternalProps, 'size' | 'disabled' | 'loading' | 'fullWidth'> {

  /**
   * Вариант отображения кнопки бренда
   * @default 'vk'
   */
  variant: EYCoreBrandButtonVariant

  /**
   * Текст кнопки
   */
  text: string

  /**
   * Вспомогательный дата-атрибут для реализации BB-тестов
   */
  locator: string | undefined
}

export const createCoreBrandButtonExternalProps = (): IYCoreBrandButtonExternalProps => {
  return {
    ...pick(createCoreSimpleButtonExternalProps(), ['size', 'disabled', 'loading']),
    variant: EYCoreBrandButtonVariant.VK,
    text: '',
    fullWidth: false,
    locator: undefined,
  }
}
