/** Символ в паттерне маски, обозначающий позицию цифры (0-9) */
export const COUNTRY_MASK_DIGIT_SYMBOL = 'x'

/** Символ в паттерне маски, обозначающий знак `+` (начало международного номера) */
export const COUNTRY_MASK_FIRST_DIGIT_SYMBOL = '+'

/** Символ-маркер, делающий предшествующий символ паттерна опциональным */
export const OPTIONAL_MASK_SEPARATE_SYMBOL = '?'

/** Коды России, которые используются только в этой стране  */
export const RUSSIA_MASK_ENTIRE_CODE_DIGIT = '8'
export const RUSSIA_MASK_GLOBAL_CODE_DIGIT = '7'

/** Маппинг известных символов паттерна на пары RegExp (обязательный / опциональный) */
export const SYMBOL_REGEXP_MAP: Partial<Record<string, { required: RegExp; optional: RegExp }>> = {
  [COUNTRY_MASK_DIGIT_SYMBOL]: { required: /\d/, optional: /\d?/ },
  // eslint ругается на литеральную 8

  [COUNTRY_MASK_FIRST_DIGIT_SYMBOL]: { required: /\d|\+/, optional: /\d?|\+?/ },
}
