import { LitElement, html, css, unsafeCSS, nothing } from 'lit'
import { customElement, property, state } from 'lit/decorators.js'
import { classMap } from 'lit/directives/class-map.js'
import { ifDefined } from 'lit/directives/if-defined.js'
import { repeat } from 'lit/directives/repeat.js'
import type { PropertyValues } from 'lit'

import { interceptEvents } from '~core/utils/event-interceptor'
import { bubblingEvent } from '~core/utils/event-decorator'
import { booleanConverter } from '~core/utils/converters'
import type { TDispatcher } from '~core/utils/event-decorator'
import { isHandledKey, HANDLED_KEYS } from '~core/utils/list-keyboard-navigation'

import { yChevronUp, yChevronDown, yPlus } from '~shared/icons'
import {
  YCoreButtonDropdownTagName as tagName,
  YCoreDropdownCellTagName,
} from '~shared/constants'
import { YC_COMPONENT_ATTRIBUTE_NAME } from '~web/shared/constants/attributes'

import '~core/ui/dropdown'
import '~core/ui/dropdownCell'
import '~core/ui/dropdownList'
import '~core/ui/button'

import { EYCoreDropdownTrigger, EYCoreDropdownPlacement } from '~core/ui/dropdown/models/types'
import type { IDropdownListItem } from '~shared/types/global'
import { flip as flipMiddleware } from '~shared/utils/floating-ui'

import {
  createCoreButtonDropdownProps,
  type IYCoreButtonDropdownProps,
  ItemClickEvent,
  VisibleEvent,
} from '~core/ui/buttonDropdown/models/types'

import {
  EYCoreButtonDropdownIconTypes,
  type IYCoreButtonDropdownIconsSet,
} from '~core/ui/buttonDropdown/models/types/internal'

import YButtonDropdownScopedCss from '~core/ui/buttonDropdown/css/ButtonDropdown.scoped.css?inline'

const {
  disabled,
  loading,
  fullWidth,
  isOpen,
  autoClose,
  variant,
  size,
  label,
  alignment,
  placement,
  iconType,
  items,
} = createCoreButtonDropdownProps()

@customElement(tagName)
@interceptEvents()
export class YCoreButtonDropdown extends LitElement implements Required<IYCoreButtonDropdownProps> {
  @property({ type: Boolean }) disabled: IYCoreButtonDropdownProps['disabled'] = disabled
  @property({ type: Boolean }) loading: IYCoreButtonDropdownProps['loading'] = loading
  @property({ type: Boolean, attribute: 'full-width' }) fullWidth: IYCoreButtonDropdownProps['fullWidth'] = fullWidth
  @property({ type: Boolean, reflect: true, converter: booleanConverter, attribute: 'is-open' }) isOpen: IYCoreButtonDropdownProps['isOpen'] = isOpen
  @property({ type: Boolean, reflect: true, converter: booleanConverter, attribute: 'auto-close' }) autoClose: IYCoreButtonDropdownProps['autoClose'] = autoClose
  @property({ type: String, reflect: true }) variant: IYCoreButtonDropdownProps['variant'] = variant
  @property({ type: String, reflect: true }) size: IYCoreButtonDropdownProps['size'] = size
  @property({ type: String }) label: IYCoreButtonDropdownProps['label'] = label
  @property({ type: String }) alignment: IYCoreButtonDropdownProps['alignment'] = alignment
  @property({ type: String }) placement: IYCoreButtonDropdownProps['placement'] = placement
  @property({ type: String, attribute: 'icon-type' }) iconType: IYCoreButtonDropdownProps['iconType'] = iconType
  @property({ type: Array }) items: IYCoreButtonDropdownProps['items'] = items
  @property({ type: Boolean, attribute: 'no-max-height' }) noMaxHeight: IYCoreButtonDropdownProps['noMaxHeight'] = false

  @state() private isDropdownOpened = false
  @state() private focusedIndex: number | null = null

  private _isPointerDownInsideDropdown = false
  @state() private dynamicPlacement: IYCoreButtonDropdownProps['placement'] = EYCoreDropdownPlacement.BOTTOM_START

  @bubblingEvent(
    ItemClickEvent,
    { name: 'item-click' },
  )
  private _itemClick!: TDispatcher<ItemClickEvent>

  @bubblingEvent(
    VisibleEvent,
    { name: 'change-visible' },
  )
  private _visible!: TDispatcher<VisibleEvent>

  private readonly baseClass = tagName
  private readonly baseDropdownClass = `${tagName}__dropdown`
  private readonly offsetOptions = { mainAxis: 4 }

  static readonly styles = [
    css`
      ${unsafeCSS(YButtonDropdownScopedCss)}
    `,
  ]

  private get computedIconsSet(): IYCoreButtonDropdownIconsSet {
    let leftIcon = undefined
    let rightIcon = undefined

    if (this.iconType === EYCoreButtonDropdownIconTypes.LEFT) {
      leftIcon = yPlus
    } else {
      rightIcon = this.isDropdownOpened ? yChevronUp : yChevronDown
    }

    return { leftIcon, rightIcon }
  }

  private get computedClasses() {
    return {
      [this.baseClass]: true,
      [`${this.baseClass}_full-width`]: Boolean(this.fullWidth),
    }
  }

  private get computedPlacement(): IYCoreButtonDropdownProps['placement'] {
    return this.placement ?? this.dynamicPlacement
  }

  private get computedMiddlewares() {
    if (!this.placement) return undefined

    return [
      // Если placement задан явно, не переворачиваем позицию автоматически.
      flipMiddleware({ fallbackPlacements: [] }),
    ]
  }

  protected updated(changedProperties: PropertyValues): void {
    if (
      this.isDropdownOpened &&
      (changedProperties.has('placement') || changedProperties.has('fullWidth'))
    ) {
      window.dispatchEvent(new Event('resize'))
    }

    if (!changedProperties.has('isOpen')) return

    if (this.isOpen) {
      this.isDropdownOpened = true
      this.handleDropdownOpened()
    } else {
      this.resetDropdownState()
    }
  }

  /** Сброс состояния без события (напр. при синхронизации с change-visible из y-core-dropdown). */
  private resetDropdownState = () => {
    this.focusedIndex = null
    this.isDropdownOpened = false
    this.handleDropdownClosed()
  }

  /** Закрытие из логики хоста (выбор пункта, blur, Escape и т.д.) — с notify слушателям. */
  private closeDropdown = () => {
    if (!this.isDropdownOpened) return

    this.resetDropdownState()
    this._visible({ detail: { value: false } })
  }

  private handleItemClick = (event: ItemClickEvent, item: IDropdownListItem) => {
    event.stopPropagation()

    this.closeDropdown()

    this._itemClick({ detail: { item } })
  }

  private handleDropdownContentClick = (event: Event) => {
    if (!this.autoClose) return

    event.stopPropagation()

    this.closeDropdown()
  }

  private handleClickOutside = (event: VisibleEvent) => {
    event.stopPropagation()
  }

  private handleChangeVisible = (event: VisibleEvent) => {
    event.stopPropagation()

    // В activator могут быть вложенные y-core-dropdown (тултип YCoreTip и т.д.).
    // Без раннего stopPropagation их change-visible доходит до хоста y-core-button-dropdown.
    // deepest !== currentTarget отсекает всплытие из слота; target сверяем из‑за ретаргетинга shadow.
    const deepest = event.composedPath()[0]
    if (
      deepest !== event.currentTarget ||
      event.target !== event.currentTarget
    ) {
      return
    }

    if (event.detail.value) {
      this.isDropdownOpened = true
      this.handleDropdownOpened()
    } else {
      this.resetDropdownState()
    }

    this._visible({ detail: event.detail })
  }

  private handleDropdownPointerDown = () => {
    this._isPointerDownInsideDropdown = true
    requestAnimationFrame(() => {
      this._isPointerDownInsideDropdown = false
    })
  }

  private handleBlur = (event: FocusEvent) => {
    if (this._isPointerDownInsideDropdown) return
    const focusMovedInsideDropdown = event.relatedTarget instanceof Node && this.contains(event.relatedTarget)
    if (focusMovedInsideDropdown) return
    requestAnimationFrame(() => {
      this.closeDropdown()
    })
  }

  private handleNavigationKeyDown = (event: KeyboardEvent) => {
    if (!isHandledKey(event.key)) return

    event.preventDefault()

    if (event.key === HANDLED_KEYS.ARROW_DOWN) {
      this.handleArrowNext()
      return
    }

    if (event.key === HANDLED_KEYS.ARROW_UP) {
      this.handleArrowPrev()
      return
    }

    if (event.key === HANDLED_KEYS.ENTER || event.key === HANDLED_KEYS.SPACE) {
      this.handleSelectFocusedItem()
      return
    }

    this.closeDropdown()
  }

  private handleDropdownOpened() {
    window.addEventListener('keydown', this.handleNavigationKeyDown, { capture: true })
  }

  private handleDropdownClosed() {
    window.removeEventListener('keydown', this.handleNavigationKeyDown, { capture: true })
  }

  private tryScroll = (element: HTMLElement) => {
    element.scrollIntoView({
      behavior: 'smooth',
      block: 'nearest',
      inline: 'nearest',
    })
  }

  private getDropdownItemElementByIndex(index: number): HTMLElement | null {
    if (!this.items || index < 0 || index >= this.items.length) return null

    return this.shadowRoot?.querySelector<HTMLElement>(`${YCoreDropdownCellTagName}[data-item-index="${index}"]`) ?? null
  }

  private handleArrowNext = () => {
    if (!this.items) return

    const nextIndex = this.focusedIndex === null ? 0 : this.focusedIndex + 1

    if (nextIndex >= this.items.length) return

    this.focusedIndex = nextIndex

    const element = this.getDropdownItemElementByIndex(nextIndex)
    if (element) {
      this.tryScroll(element)
    }
  }

  private handleArrowPrev = () => {
    if (!this.items) return

    const nextIndex = this.focusedIndex === null ? 0 : this.focusedIndex - 1

    if (nextIndex < 0) return

    this.focusedIndex = nextIndex

    const element = this.getDropdownItemElementByIndex(nextIndex)
    if (element) {
      this.tryScroll(element)
    }
  }

  private handleSelectFocusedItem = () => {
    if (!this.items || this.focusedIndex === null || this.focusedIndex < 0 || this.focusedIndex >= this.items.length) return

    const item = this.items[this.focusedIndex]

    const event = new Event('click') as ItemClickEvent
    this.handleItemClick(event, item)
  }


  private updateDynamicPlacement = () => {
    if (this.placement) return

    const { left, width } = this.getBoundingClientRect()
    const viewportWidth = window.innerWidth || document.documentElement.clientWidth
    const centerPosition = left + width / 2

    this.dynamicPlacement = centerPosition > viewportWidth / 2
      ? EYCoreDropdownPlacement.BOTTOM_END
      : EYCoreDropdownPlacement.BOTTOM_START
  }

  private handleOpenIntentMouseDown = () => {
    if (this.disabled || this.isDropdownOpened) return

    this.updateDynamicPlacement()
  }

  private handleOpenIntentKeyDown = (event: KeyboardEvent) => {
    if (this.disabled || this.isDropdownOpened) return
    if (event.key !== HANDLED_KEYS.ENTER && event.key !== HANDLED_KEYS.SPACE) return

    this.updateDynamicPlacement()
  }

  protected renderDropdownList() {
    if (!this.items) return nothing

    return repeat(
      this.items,
      (item) => item.id,
      (item, index) => html`
        <y-core-dropdown-cell
          locator=${`${YCoreDropdownCellTagName}_${item.id}`}
          data-item-index=${index}
          .focused=${this.focusedIndex === index}
          class=${this.baseDropdownClass}
          @click=${(event: ItemClickEvent) => {
            this.handleItemClick(event, item)
          }}
        >
          <div slot="content" class=${`${this.baseDropdownClass}-content`}>
            <div slot="label" class=${`${this.baseDropdownClass}-label`} title=${String(item.label)}>
              ${item.label}
            </div>
          </div>
        </y-core-dropdown-cell>
      `,
    )
  }

  protected renderDropdownContent() {
    return html`
      <y-core-dropdown-list tabindex="-1" .noMaxHeight=${this.noMaxHeight} @pointerdown=${this.handleDropdownPointerDown}>
        <div slot="list">
          <slot
            name="content"
            @click=${this.handleDropdownContentClick}
          >
            ${this.isDropdownOpened ? this.renderDropdownList() : nothing}
          </slot>
        </div>
      </y-core-dropdown-list>`
  }

  connectedCallback() {
    super.connectedCallback()

    this.dataset.locator = tagName
    this.dataset[YC_COMPONENT_ATTRIBUTE_NAME] = ''

    this.updateDynamicPlacement()
  }

  disconnectedCallback() {
    this.handleDropdownClosed()
    super.disconnectedCallback()
  }

  protected render() {
    return html`
      <y-core-dropdown
        class=${classMap(this.computedClasses)}
        .offset=${this.offsetOptions}
        .trigger=${EYCoreDropdownTrigger.CLICK}
        .isOpen=${this.isDropdownOpened}
        .strictWidth=${this.fullWidth}
        .placement=${this.computedPlacement}
        .middlewares=${this.computedMiddlewares}
        inline
        @mousedown=${this.handleOpenIntentMouseDown}
        @keydown=${this.handleOpenIntentKeyDown}
        @click-outside=${this.handleClickOutside}
        @change-visible=${this.handleChangeVisible}
      >
        <slot
          slot="activator"
          name="activator"
        >
          <y-core-button
            class="${this.baseClass}__button"
            label=${ifDefined(this.label)}
            variant=${ifDefined(this.variant)}
            size=${ifDefined(this.size)}
            alignment=${ifDefined(this.alignment)}
            .disabled=${this.disabled}
            .loading=${this.loading}
            .fullWidth=${this.fullWidth}
            .iconLeft=${this.computedIconsSet.leftIcon}
            .iconRight=${this.computedIconsSet.rightIcon}
            @blur=${this.handleBlur}
          >
          </y-core-button>
          </slot>

        <div slot="content">
          ${this.renderDropdownContent()}
        </div>
      </y-core-dropdown>
    `
  }
}
