import { SYMBOL_REGEXP_MAP, OPTIONAL_MASK_SEPARATE_SYMBOL } from '../models/constants'

/**
 * Экранирует спецсимволы регулярных выражений в строке.
 *
 * @param value - строка для экранирования
 * @returns строка с экранированными спецсимволами
 */
export const escapeRegExp = (value: string): string => {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

/**
 * Конвертирует один символ паттерна маски в соответствующий {@link RegExp}.
 *
 * - `'x'` → `/\d/` (цифра) или `/\d?/` (опциональная цифра)
 * - `'+'` → `/\+/` (литерал плюса) или `/\+?/` (опциональный)
 * - Любой другой символ → экранированный литерал (например `(` → `/\(/`)
 *
 * @param symbol - символ паттерна маски
 * @param isOptional - является ли символ опциональным (за ним следует `?`)
 * @returns регулярное выражение для данного символа
 */
const getRegexpBySymbol = (symbol: string, isOptional: boolean): RegExp => {
  const mapped = SYMBOL_REGEXP_MAP[symbol]

  if (mapped) {
    return isOptional ? mapped.optional : mapped.required
  }

  const escaped = escapeRegExp(symbol)

  return new RegExp(isOptional ? `${escaped}?` : escaped)
}

/**
 * Конвертирует строковый паттерн маски в массив {@link RegExp},
 * совместимый с форматом `MaskitoMaskExpression`.
 *
 * Символ `?` после любого символа делает его опциональным.
 *
 * @example
 * ```ts
 * convertToRegexParts('+?xxxx')
 * // → [/\+?/, /\d/, /\d/, /\d/, /\d/]
 * ```
 *
 * @param pattern - строковый паттерн маски (например `'+?xxxxxxxxxxxx?x?x?'`)
 * @returns массив регулярных выражений для Maskito
 */
const convertToRegexParts = (pattern: string): RegExp[] => {
  const maskParts: RegExp[] = []

  for (let i = 0; i < pattern.length; i++) {
    if (pattern[i] === OPTIONAL_MASK_SEPARATE_SYMBOL) {
      continue
    }

    const isNextOptional = pattern[i + 1] === OPTIONAL_MASK_SEPARATE_SYMBOL

    maskParts.push(getRegexpBySymbol(pattern[i], isNextOptional))
  }

  return maskParts
}

/**
 * Создаёт маску Maskito из строкового паттерна с поддержкой опциональных символов.
 *
 * В паттерне используются следующие обозначения:
 * - `x` — обязательная цифра
 * - `+` — литерал `+`
 * - `?` после символа — делает его опциональным
 * - Любой другой символ — литеральный разделитель (пробел, дефис, скобки и т.д.)
 *
 * @example
 * ```ts
 * getMaskitoMaskByRegex('+?xxxxxxxxxxxx?x?x?')
 * // → [/\+?/, /\d/, /\d/, /\d/, /\d/, /\d/, /\d/, /\d/, /\d/, /\d/, /\d/, /\d/, /\d/, /\d?/, /\d?/, /\d?/]
 * ```
 *
 * @param pattern - строковый паттерн маски
 * @returns массив регулярных выражений, совместимый с `MaskitoOptions.mask`
 */
export const getMaskitoMaskByRegex = (pattern: string): RegExp[] => {
  return convertToRegexParts(pattern)
}
