import { EYSizes, type TYSizes } from '~shared/types/global'

export enum EYCoreModalVariant {
  PRIMARY = 'primary',
  SECONDARY = 'secondary',
}

/**
 * Свойства компонента Modal
 */
export interface IYCoreModalExternalProps {

  /**
   * Показать модальное окно
   * @default false
   */
  open: boolean | undefined

  /**
   * Размер модального окна
   * @default 'small'
   */
  size: Extract<TYSizes, 'small' | 'large'> | undefined

  /**
   * Вариант отображения модального окна
   * @default 'primary'
   */
  variant: `${EYCoreModalVariant}` | undefined

  /**
   * Ширина модального окна
   */
  width: string | undefined

  /**
   * Скрыть оверлей
   * @default false
   */
  hideOverlay: boolean | undefined

  /**
   * Предотвратить закрытие по Escape
   * @default false
   */
  preventEscape: boolean | undefined

  /**
   * Полноэкранный режим
   * @default false
   */
  fullScreen: boolean | undefined

  /**
   * Предотвращает скрытие модалки через backdrop/ крестик/ escape (только по клику на CTA button)
   * @default false
   */
  persistent: boolean | undefined

  /**
   * Показать grabber для закрытия модалки в режиме bottom-sheet
   * @default false
   */
  showGrabber: boolean | undefined
}

export const createCoreModalExternalProps = (): IYCoreModalExternalProps => {
  return {
    open: false,
    size: EYSizes.SMALL,
    variant: EYCoreModalVariant.PRIMARY,
    width: undefined,
    hideOverlay: false,
    preventEscape: false,
    fullScreen: false,
    persistent: false,
    showGrabber: false,
  }
}
