import { EYSizes, type TYSizes } from '~shared/types/global'

export enum EYCoreCounterVariant {
  PRIMARY = 'primary',
  SECONDARY = 'secondary',
  NEGATIVE = 'negative',
  OTHER_INVERT = 'other-invert',
}

export type TYCoreCounterVariant = `${EYCoreCounterVariant}`

export const COUNTER_MAX_VALUE_DEFAULT = 999

/**
 * Свойства компонента Counter
 */
export interface IYCoreCounterExternalProps {

  /**
   * Вариант отображения счетчика
   * @default 'primary'
   */
  variant: TYCoreCounterVariant

  /**
   * Размер счетчика
   * @default 'small'
   */
  size: Extract<TYSizes, 'small' | 'medium'> | undefined

  /**
   * Отключить счетчик
   * @default false
   */
  disabled: boolean | undefined

  /**
   * Числовое значение счетчика
   * @default 0
   */
  value: number

  /**
   * Показывать знак плюс для положительных значений
   */
  withPlusSign: boolean | undefined

  /**
   * Максимальное значение счетчика. При превышении отображается как «N+»
   * @default 999
   */
  maxValue: number | undefined

  /**
   * Вспомогательный дата-атрибут для реализации BB-тестов
   */
  locator: string | undefined
}

export const createCoreCounterExternalProps = (): IYCoreCounterExternalProps => {
  return {
    variant: EYCoreCounterVariant.PRIMARY,
    size: EYSizes.SMALL,
    disabled: false,
    value: 0,
    withPlusSign: undefined,
    maxValue: COUNTER_MAX_VALUE_DEFAULT,
    locator: undefined,
  }
}
