import { LitElement, html, css, unsafeCSS, nothing } from 'lit'
import { customElement, property, state } from 'lit/decorators.js'
import { classMap } from 'lit/directives/class-map.js'
import { ifDefined } from 'lit/directives/if-defined.js'

import {
  createCoreSimpleBannerProps,
  type IYCoreSimpleBannerProps,
} from './models/types'
import {
  YCoreSimpleBannerTagName as tagName,
} from '~shared/constants'
import { YC_COMPONENT_ATTRIBUTE_NAME } from '~web/shared/constants/attributes'

import { bubblingEvent, type TDispatcher } from '~core/utils/event-decorator'

import YSimpleBannerVarsCss from './css/SimpleBanner.vars.css?inline'
import YSimpleBannerScopedCss from './css/SimpleBanner.scoped.css?inline'
import { CloseEmitEvent, PrimaryButtonClickEmitEvent, SecondaryButtonClickEmitEvent } from './models/types/events'
import { EYCoreTextSize } from '~core/ui/text/models/types'
import '~core/ui/button'
import '~core/ui/iconButton'
import { yBigClose } from '~shared/icons'
import { preventAndStopEvent } from '~web/shared/utils/helpers'

const {
  description,
  descriptionSize,
  primaryButtonVariant,
  primaryButtonText,
  header,
  secondaryButtonVariant,
  secondaryButtonText,
  stretched,
  hostStyles,
  colorText,
  hideCloseIcon,
  truncateDescription,
} = createCoreSimpleBannerProps()


@customElement(tagName)
export class YCoreSimpleBanner
  extends LitElement
  implements Required<IYCoreSimpleBannerProps> {
  @property({ type: String }) description: IYCoreSimpleBannerProps['description'] = description
  @property({ type: String, attribute: 'description-size' }) descriptionSize: IYCoreSimpleBannerProps['descriptionSize'] = descriptionSize
  @property({ type: String }) header: IYCoreSimpleBannerProps['header'] = header
  @property({ type: Boolean }) stretched: IYCoreSimpleBannerProps['stretched'] = stretched
  @property({ type: String, attribute: 'color-text' }) colorText: IYCoreSimpleBannerProps['colorText'] = colorText
  @property({ type: String, attribute: 'primary-button-variant' }) primaryButtonVariant: IYCoreSimpleBannerProps['primaryButtonVariant'] = primaryButtonVariant
  @property({ type: String, attribute: 'primary-button-text' }) primaryButtonText: IYCoreSimpleBannerProps['primaryButtonText'] = primaryButtonText
  @property({ type: String, attribute: 'secondary-button-variant' }) secondaryButtonVariant: IYCoreSimpleBannerProps['secondaryButtonVariant'] = secondaryButtonVariant
  @property({ type: String, attribute: 'secondary-button-text' }) secondaryButtonText: IYCoreSimpleBannerProps['secondaryButtonText'] = secondaryButtonText
  @property({ type: String, attribute: 'host-styles' }) hostStyles: IYCoreSimpleBannerProps['hostStyles'] = hostStyles
  @property({ type: Boolean, attribute: 'hide-close-icon' }) hideCloseIcon: IYCoreSimpleBannerProps['hideCloseIcon'] = hideCloseIcon
  @property({ type: Boolean, attribute: 'truncate-description' }) truncateDescription: IYCoreSimpleBannerProps['truncateDescription'] = truncateDescription

  @bubblingEvent(
    CloseEmitEvent,
    { name: 'close' },
  )
  _close!: TDispatcher<CloseEmitEvent>

  @bubblingEvent(
    PrimaryButtonClickEmitEvent,
    { name: 'primary-button-click' },
  )
  _primaryButtonClick!: TDispatcher<PrimaryButtonClickEmitEvent>

  @bubblingEvent(
    SecondaryButtonClickEmitEvent,
    { name: 'secondary-button-click' },
  )
  _secondaryButtonClick!: TDispatcher<SecondaryButtonClickEmitEvent>

  private readonly baseClass = tagName
  @state() private hasActionsSlot = false

  connectedCallback() {
    super.connectedCallback()
    this.dataset.locator = tagName
    this.dataset[YC_COMPONENT_ATTRIBUTE_NAME] = ''
  }

  static readonly styles = [
    css`
      ${unsafeCSS(YSimpleBannerVarsCss)}
      ${unsafeCSS(YSimpleBannerScopedCss)}
    `,
  ]

  private get computedClasses() {
    return { [this.baseClass]: true }
  }

  private get hasActions() {
    return this.hasActionsSlot || Boolean(this.primaryButtonText || this.secondaryButtonText)
  }

  private get computedActionsClasses() {
    return {
      [`${this.baseClass}__actions`]: true,
      [`${this.baseClass}__actions_hidden`]: !this.hasActions,
    }
  }

  private handleCloseIconClick = (event: Event) => {
    preventAndStopEvent(event)
    this._close()
  }

  private handlePrimaryButtonClick = (event: Event) => {
    preventAndStopEvent(event)
    this._primaryButtonClick()
  }

  private handleSecondaryButtonClick = (event: Event) => {
    preventAndStopEvent(event)
    this._secondaryButtonClick()
  }

  private handleActionsSlotChange = (event: Event) => {
    const slot = event.target as HTMLSlotElement | null

    if (!slot) {
      this.hasActionsSlot = false
      return
    }

    const assigned = slot.assignedElements({ flatten: true })
    this.hasActionsSlot = assigned.length > 0
  }

  private get computedLineclamp() {
    const TRUNCATE_DESCRIPTION_LINECLAMP = 4
    return this.truncateDescription ? TRUNCATE_DESCRIPTION_LINECLAMP : undefined
  }

  private renderHeader() {
    if (!this.header) {
      return nothing
    }

    return html`
      <y-core-text
        class="${this.baseClass}__title"
        title=${ifDefined(this.header)}
        size=${EYCoreTextSize.S1_MEDIUM}
        variant=${ifDefined(this.colorText)}
      >
        ${this.header}
      </y-core-text>
    `
  }

  private renderActionButtons() {
    const hasPrimaryButton = Boolean(this.primaryButtonText)
    const hasSecondaryButton = Boolean(this.secondaryButtonText)

    if (!hasPrimaryButton && !hasSecondaryButton) return nothing

    return html`
      ${
        hasPrimaryButton
          ? html`
            <y-core-button
              class="${this.baseClass}__button"
              variant=${ifDefined(this.primaryButtonVariant)}
              label=${ifDefined(this.primaryButtonText)}
              @click=${this.handlePrimaryButtonClick}
            ></y-core-button>
          `
          : nothing
      }

      ${
        hasSecondaryButton
          ? html`
            <div class="${this.baseClass}__button-container" part="secondary-button">
              <y-core-button
                class="${this.baseClass}__button ${this.baseClass}__button_secondary"
                variant=${ifDefined(this.secondaryButtonVariant)}
                label=${ifDefined(this.secondaryButtonText)}
                @click=${this.handleSecondaryButtonClick}
              ></y-core-button>
            </div>
          `
          : nothing
      }
    `
  }

  private renderActions() {
    return html`
      <div
        class=${classMap(this.computedActionsClasses)}
        part="actions"
      >
        <slot
          name="actions"
          @slotchange=${this.handleActionsSlotChange}
        ></slot>

        ${this.hasActionsSlot ? nothing : this.renderActionButtons()}
      </div>
    `
  }

  private renderCloseIcon() {
    if (this.hideCloseIcon) {
      return nothing
    }

    return html`
      <y-core-icon-button
        part="close-icon"
        class="${this.baseClass}__close"
        .icon=${yBigClose}
        variant="text"
        @click=${this.handleCloseIconClick}
      >
      </y-core-icon-button>
    `
  }

  protected render() {
    return html`
      <div class=${classMap(this.computedClasses)} part="root">
        <div class="${this.baseClass}__content-wrapper" part="content-wrapper">
          <div class="${this.baseClass}__media">
            <slot
              name="media"
              class="${this.baseClass}__image"
            ></slot>
          </div>

          <div class="${this.baseClass}__content" part="content">
            <div class="${this.baseClass}__text" part="text">
              ${this.renderHeader()}
              <y-core-text
                class="${this.baseClass}__description"
                part="description"
                .size=${this.descriptionSize}
                .variant=${this.colorText}
                .ellipsis=${this.truncateDescription}
                .lineclamp=${this.computedLineclamp}
              >
                <slot name="description">${this.description}</slot>
              </y-core-text>
            </div>
            ${this.renderActions()}
          </div>
        </div>
        ${this.renderCloseIcon()}
      </div>
    `
  }
}
