import { LitElement, html, css, unsafeCSS } from 'lit'
import { consume } from '@lit/context'
import { customElement, property, state } from 'lit/decorators.js'
import { classMap } from 'lit/directives/class-map.js'

import {
  createCoreAvatarProps,
  type IYCoreAvatarExternalProps,
} from '~core/ui/avatar/models/types'
import {
  YCoreAvatarTagName as tagName,
} from '~shared/constants'
import { YC_COMPONENT_ATTRIBUTE_NAME } from '~web/shared/constants/attributes'

import '~core/ui/icon'
const { initials, photo, icon, disabled, color } = createCoreAvatarProps()

import { sizeContextCreated } from '~core/ui/cardWrapper/providers'
import YAvatarVarsCss from '~core/ui/avatar/css/Avatar.vars.css?inline'
import YAvatarScopedCss from '~core/ui/avatar/css/Avatar.scoped.css?inline'
import { ifDefined } from 'lit/directives/if-defined.js'
import { renderIcon } from '~core/renderers'
import { interceptEvents } from '~core/utils/event-interceptor'
import { yAvatarUser } from '~web/shared/icons'
import { AVATAR_ICON_SIZE } from './models/constants'
import type { TYAvatarSizes, TYSizes } from '~shared/types/global'

const CARD_WRAPPER_SIZE_TO_AVATAR_SIZE: Record<Extract<TYSizes, 'small' | 'medium' | 'large'>, TYAvatarSizes> = {
  small: '24px',
  medium: '40px',
  large: '48px',
}

@customElement(tagName)
@interceptEvents()
export class YCoreAvatar extends LitElement implements Required<IYCoreAvatarExternalProps> {
  @consume({ context: sizeContextCreated, subscribe: true })
  @property({ attribute: false }) legacySize?: Extract<TYSizes, 'small' | 'medium' | 'large'>

  @property({ type: String }) size: IYCoreAvatarExternalProps['size'] = undefined
  @property({ type: String }) initials: IYCoreAvatarExternalProps['initials'] = initials
  @property({ type: String }) photo: IYCoreAvatarExternalProps['photo'] = photo
  @property({ type: Object }) icon: IYCoreAvatarExternalProps['icon'] = icon
  @property({ type: Boolean }) disabled: IYCoreAvatarExternalProps['disabled'] = disabled
  @property({ type: String }) color: IYCoreAvatarExternalProps['color'] = color

  private readonly baseClass = tagName
  @state() imageError = false

  private get isPhoto() {
    return this.photo && !this.imageError
  }

  /**
   * Преобразует строку с именем пользователя в инициалы.
   *
   * @example
   * "Иван" -> "И"
   * "Иван Петров" -> "ИП"
   * "иван петров" -> "ИП"
   * "  Иван  Петров  " -> "ИП"
   * "" -> ""
   *
   * @returns {string} Инициалы пользователя в верхнем регистре.
   * Возвращает пустую строку, если this.initials не определено.
   * Для одного слова возвращает только первую букву.
   * Для нескольких слов берет первые буквы первых двух слов.
   */
  private get initialsFromString() {
    if (!this.initials) return ''

    const parts = this.initials.trim().split(' ')
    const firstName = parts[0] || ''
    const lastName = parts[1] || ''

    return `${firstName[0] || ''}${lastName[0] || ''}`.toUpperCase()
  }

  static readonly styles = [
    css`
      ${unsafeCSS(YAvatarVarsCss)}
      ${unsafeCSS(YAvatarScopedCss)}
    `,
  ]

  private handleImageError = () => {
    this.imageError = true
  }

  private get computedClasses() {
    return {
      [this.baseClass]: true,
      [`${this.baseClass}_size_${this.effectiveSize}`]: true,
      [`${this.baseClass}_type_photo`]: Boolean(this.isPhoto),
      [`${this.baseClass}_disabled`]: Boolean(this.disabled),
      [`${this.baseClass}_color_${this.color}`]: true,
    }
  }

  private get effectiveSize(): TYAvatarSizes {
    if (this.size == null && this.legacySize) {
      return CARD_WRAPPER_SIZE_TO_AVATAR_SIZE[this.legacySize]
    }
    return this.size ?? '40px'
  }

  private get iconSize(): string {
    return `${AVATAR_ICON_SIZE[this.effectiveSize]}px`
  }

  private get content() {
    if (this.isPhoto) return this.renderPhoto()
    if (this.icon) return this.renderIcon()
    if (this.initials) return this.renderInitials()

    return renderIcon({ icon: yAvatarUser, size: this.iconSize })
  }

  private renderPhoto() {
    return html`
      <img
        class="${this.baseClass}__image"
        src=${ifDefined(this.photo)}
        alt=${ifDefined(this.initials)}
        @error=${this.handleImageError}
      />
    `
  }

  private renderIcon() {
    return renderIcon({ icon: this.icon, size: this.iconSize })
  }

  private renderInitials() {
    return html`
      <span class="${this.baseClass}__initials">
        ${this.initialsFromString}
      </span>
    `
  }

  connectedCallback() {
    super.connectedCallback()

    this.dataset.locator = tagName
    this.dataset[YC_COMPONENT_ATTRIBUTE_NAME] = ''
  }

  protected render() {
    return html`
      <div class=${classMap(this.computedClasses)}>
        ${this.content}
      </div>
    `
  }
}

