import type { Placement } from '~shared/utils/floating-ui'
import { EYCoreDropdownPlacement } from '~core/ui/dropdown/models/types'

export enum EYCoreLabelOverflowMode {
  CLAMP = 'clamp',
  ELLIPSIS = 'ellipsis',
  NOWRAP = 'nowrap',
}

export type TYCoreLabelOverflowMode = `${EYCoreLabelOverflowMode}`

export enum EYCoreLabelAlignment {
  TOP = 'top',
  CENTER = 'center',
}

export type TYCoreLabelAlignment = `${EYCoreLabelAlignment}`

export interface IYCoreLabelExternalProps {
  text: string | undefined
  tooltipText: string | undefined
  alignment: TYCoreLabelAlignment | undefined
  disabled: boolean | undefined
  required: boolean | undefined
  debounce: number | undefined
  tooltipPlacement: Placement | undefined
  locator: string | undefined
  overflowMode: TYCoreLabelOverflowMode | undefined
}

export const createCoreLabelExternalProps = (): IYCoreLabelExternalProps => {
  return { text: '', tooltipText: '', alignment: EYCoreLabelAlignment.CENTER, disabled: false, required: false, debounce: 300, tooltipPlacement: EYCoreDropdownPlacement.RIGHT, locator: undefined, overflowMode: EYCoreLabelOverflowMode.CLAMP }
}
