import { EYSizes } from '~shared/types/global'
import type { TYSizes } from '~shared/types/global'
import type { IYIcon } from '~shared/icons'

export type TYCoreChipSize = Extract<TYSizes, 'small' | 'medium' | 'large'>

export enum EYCoreChipVariant {
  DEFAULT = 'default',
  ACCENT = 'accent',
}

export type TYCoreChipVariant = `${EYCoreChipVariant}`

/**
 * Свойства компонента Chip
 */
export interface IYCoreChipExternalProps {

  /**
   * Текст метки
   */
  labelText: string

  /**
   * Иконка слева
   */
  iconLeft: IYIcon | undefined

  /**
   * Иконка справа
   */
  iconRight: IYIcon | undefined

  /**
   * Размер чипа
   * @default 'small'
   */
  size: TYCoreChipSize | undefined

  /**
   * Вариант отображения чипа
   * @default 'default'
   */
  variant: TYCoreChipVariant | undefined

  /**
   * Активен ли чип
   */
  active: boolean | undefined

  /**
   * Отключить чип
   */
  disabled: boolean | undefined

  /**
   * Вспомогательный дата-атрибут для реализации BB-тестов
   */
  locator: string | undefined
}

export const createCoreChipExternalProps = (): IYCoreChipExternalProps => ({
  labelText: '',
  size: EYSizes.SMALL,
  iconLeft: undefined,
  iconRight: undefined,
  variant: EYCoreChipVariant.DEFAULT,
  active: undefined,
  disabled: undefined,
  locator: undefined,
})
