import { LitElement, html, css, unsafeCSS, nothing } from 'lit'
import { customElement, property, state } from 'lit/decorators.js'
import { classMap } from 'lit/directives/class-map.js'

import {
  createCoreCalloutProps,
  type IYCoreCalloutProps,
  EYCoreCalloutVariant,
} from './models/types'
import { YCoreCalloutTagName as tagName } from '~shared/constants'
import { YC_COMPONENT_ATTRIBUTE_NAME } from '~web/shared/constants/attributes'

import { bubblingEvent, type TDispatcher } from '~core/utils/event-decorator'
import { CloseEmitEvent, PrimaryButtonClickEmitEvent, SecondaryButtonClickEmitEvent } from '~core/ui/simpleBanner/models/types/events'
import { renderIcon } from '~core/renderers'
import { preventAndStopEvent } from '~web/shared/utils/helpers'
import YCalloutScopedCss from './css/Callout.scoped.css?inline'
import YCalloutVarsCss from './css/Callout.vars.css?inline'
import '~core/ui/simpleBanner'
import '~core/ui/icon'
import { yInfo, yWarning, yCheck, yDiscountPromotion } from '~shared/icons'
import type { IYCoreIconExternalProps } from '~core/ui/icon/models/types'
import { EYCoreTextSize } from '../text/models/types'

const {
  description,
  header,
  primaryButtonVariant,
  primaryButtonText,
  secondaryButtonVariant,
  secondaryButtonText,
  variant,
  hideCloseIcon,
  hideMedia,
  open,
} = createCoreCalloutProps()

@customElement(tagName)
export class YCoreCallout
  extends LitElement
  implements Required<IYCoreCalloutProps> {
  @property({ type: String }) description: IYCoreCalloutProps['description'] = description
  @property({ type: String }) header: IYCoreCalloutProps['header'] = header
  @property({ type: String, attribute: 'primary-button-variant' }) primaryButtonVariant: IYCoreCalloutProps['primaryButtonVariant'] = primaryButtonVariant
  @property({ type: String, attribute: 'primary-button-text' }) primaryButtonText: IYCoreCalloutProps['primaryButtonText'] = primaryButtonText
  @property({ type: String, attribute: 'secondary-button-variant' }) secondaryButtonVariant: IYCoreCalloutProps['secondaryButtonVariant'] = secondaryButtonVariant
  @property({ type: String, attribute: 'secondary-button-text' }) secondaryButtonText: IYCoreCalloutProps['secondaryButtonText'] = secondaryButtonText
  @property({ type: String, reflect: true }) variant: IYCoreCalloutProps['variant'] = variant
  @property({ type: Boolean, attribute: 'hide-close-icon' }) hideCloseIcon: IYCoreCalloutProps['hideCloseIcon'] = hideCloseIcon
  @property({ type: Boolean, attribute: 'hide-media' }) hideMedia: IYCoreCalloutProps['hideMedia'] = hideMedia
  @property({ type: Boolean, reflect: true }) open: IYCoreCalloutProps['open'] = open
  @state() private hasMediaSlot = false
  @state() private hasDescriptionSlot = false

  @bubblingEvent(
    CloseEmitEvent,
    { name: 'close' },
  )
  _close!: TDispatcher<CloseEmitEvent>

  @bubblingEvent(
    PrimaryButtonClickEmitEvent,
    { name: 'primary-button-click' },
  )
  _primaryButtonClick!: TDispatcher<PrimaryButtonClickEmitEvent>

  @bubblingEvent(
    SecondaryButtonClickEmitEvent,
    { name: 'secondary-button-click' },
  )
  _secondaryButtonClick!: TDispatcher<SecondaryButtonClickEmitEvent>

  private readonly baseClass = tagName

  connectedCallback() {
    super.connectedCallback()
    this.dataset.locator = tagName
    this.dataset[YC_COMPONENT_ATTRIBUTE_NAME] = ''
  }

  static readonly styles = [
    css`
      ${unsafeCSS(YCalloutScopedCss)}
      ${unsafeCSS(YCalloutVarsCss)}
    `,
  ]

  private get computedClasses() {
    return {
      [this.baseClass]: true,
      [`${this.baseClass}_variant_${this.variant}`]: Boolean(this.variant),
      [`${this.baseClass}_closable`]: !this.hideCloseIcon,
    }
  }

  private get shouldRenderMediaSlot() {
    return !this.hideMedia && this.hasMediaSlot
  }

  private get shouldRenderDescriptionSlot() {
    return this.description || this.hasDescriptionSlot
  }

  private get shouldRenderIcon() {
    return !this.hideMedia && !this.shouldRenderMediaSlot
  }

  private renderIcon() {
    const iconMap: Record<EYCoreCalloutVariant, IYCoreIconExternalProps['icon']> = {
      [EYCoreCalloutVariant.INFORMATION]: yInfo,
      [EYCoreCalloutVariant.SUCCESS]: yCheck,
      [EYCoreCalloutVariant.WARNING]: yWarning,
      [EYCoreCalloutVariant.ERROR]: yWarning,
      [EYCoreCalloutVariant.NEUTRAL]: yDiscountPromotion,
    }

    const icon = iconMap[this.variant]

    return html`
      <div slot="media" class="${this.baseClass}__icon">
        <div class="${this.baseClass}__icon-image">
          ${renderIcon({ icon, size: '24px' })}
        </div>
      </div>
    `
  }

  private handleMediaSlotChange = (event: Event) => {
    const slot = event.target as HTMLSlotElement | null

    if (!slot) {
      this.hasMediaSlot = false
      return
    }

    const assigned = slot.assignedElements({ flatten: true })
    this.hasMediaSlot = assigned.length > 0
  }

  private handleDescriptionSlotChange = (event: Event) => {
    const slot = event.target as HTMLSlotElement | null

    if (!slot) {
      this.hasDescriptionSlot = false
      return
    }

    const assigned = slot.assignedElements({ flatten: true })
    this.hasDescriptionSlot = assigned.length > 0
  }

  private handleClose = (event: Event) => {
    preventAndStopEvent(event)
    this._close()
  }

  private handlePrimaryButtonClick = (event: Event) => {
    preventAndStopEvent(event)
    this._primaryButtonClick()
  }

  private handleSecondaryButtonClick = (event: Event) => {
    preventAndStopEvent(event)
    this._secondaryButtonClick()
  }

  protected render() {
    if (!this.open) {
      return nothing
    }

    return html`
      <y-core-simple-banner
        class=${classMap(this.computedClasses)}
        .descriptionSize=${EYCoreTextSize.A2_REGULAR}
        .header=${this.header}
        .primaryButtonVariant=${this.primaryButtonVariant}
        .primaryButtonText=${this.primaryButtonText}
        .secondaryButtonVariant=${this.secondaryButtonVariant}
        .secondaryButtonText=${this.secondaryButtonText}
        .hideCloseIcon=${this.hideCloseIcon}
        @close=${this.handleClose}
        @primary-button-click=${this.handlePrimaryButtonClick}
        @secondary-button-click=${this.handleSecondaryButtonClick}
      >
        <slot
          slot="media"
          name="media"
          @slotchange=${this.handleMediaSlotChange}
          ?hidden=${!this.shouldRenderMediaSlot}
        ></slot>

        <slot
          slot="description"
          name="description"
          @slotchange=${this.handleDescriptionSlotChange}
          ?hidden=${!this.shouldRenderDescriptionSlot}
        >${this.description}</slot>

        <slot
          name="actions"
          slot="actions"
        ></slot>
        ${this.shouldRenderIcon ? this.renderIcon() : nothing}
      </y-core-simple-banner>
    `
  }
}
