import { customElement, property } from 'lit/decorators.js'
import { css, html, LitElement, unsafeCSS } from 'lit'
import { EYCoreToastType, type IYSnackbarIconProps } from '~core/ui/toast/models/types'
import { SnackbarVariantIcon } from '~core/ui/toast/models/constants'

import YCoreSnackbarIconScopedCSS from '~core/ui/toast/css/SnackbarIcon.scoped.css?inline'
import { YCoreSnackbarIconTagName } from '~shared/constants'
import { YC_ICON_BASE_SIZE } from '~core/ui/icon/models/constants'
import { styleMap } from 'lit/directives/style-map.js'

@customElement(YCoreSnackbarIconTagName)
export class YCoreSnackbarIcon extends LitElement implements Required<IYSnackbarIconProps> {
  @property({ type: String }) variant = EYCoreToastType.SUCCESS
  private readonly baseClass = YCoreSnackbarIconTagName

  static readonly styles = [css`${unsafeCSS(YCoreSnackbarIconScopedCSS)}`]

  connectedCallback() {
    super.connectedCallback()
  }

  private get svgString() {
    return SnackbarVariantIcon[this.variant]
  }

  private get computedStyle() {
    return { width: YC_ICON_BASE_SIZE, height: YC_ICON_BASE_SIZE }
  }

  protected render() {
    return html`
      <div
        class=${this.baseClass}
        style=${styleMap(this.computedStyle)}
        .innerHTML=${this.svgString}
      ></div>
    `
  }
}
