import type { IGlobalProviderPlugin, YCoreToastQueueHost } from '..'
import type { IGlobalContext } from '../../context'
import { ToastQueueModule } from '~core/ui/globalProvider/context'
import type {
  IToastQueueModule,
  IToastQueueConfig,
} from '~core/ui/globalProvider/context'
import {
  DEFAULT_TOAST_QUEUE_HOST_CONFIG,
  DEFAULT_TOAST_QUEUE_PLUGIN_CONFIG,
} from '~core/ui/globalProvider/plugins/toasts/constants'
import { ToastQueue } from '~core/ui/globalProvider/plugins/toasts/ToastQueue'

/**
 * @module ToastsPlugin
 * @description Плагин для GlobalProvider, реализующий систему очереди тостов
 */

export type {
  IToastOptions,
  IToastHandle,
  IToastQueueConfig,
  TToastQueuePosition,
} from '../../context/modules/ToastQueueModule'
export { EYCoreToastType } from '~core/ui/toast/models/types'
export type { IToastQueueHost, IToastQueueHostFactory, IToastQueueHostConfig } from './types'
export { YCoreToastQueueHost } from './ToastQueueHost.core'

/**
 * Конфигурация для плагина тостов.
 */
export interface IToastsPluginConfig {

  /**
   * Уникальный ID плагина среди других плагинов.
   */
  id: string

  /**
   * Конфигурация очереди тостов (рендер, таймеры, позиция и т.д.)
   */
  moduleConfig?: IToastQueueConfig
}

/**
 * ToastsPlugin — отдельный плагин GlobalProvider для показа очереди тостов.
 *
 * Отвечает за:
 * - Создание и регистрацию модуля ToastQueueModule в контексте
 * - Инициализацию UI хоста через фабрику
 * - Настройку связи между модулем и хостом
 *
 * Не зависит от конкретной реализации UI хоста (DIP)
 */
export class ToastsPlugin implements Required<IGlobalProviderPlugin> {
  id: string
  readonly toastQueue: ToastQueue
  private readonly config: IToastQueueConfig
  private toastQueueModule?: ToastQueueModule

  /**
   * Создает экземпляр плагина тостов
   * @param config - Конфигурация плагина
   */
  constructor(config: IToastsPluginConfig) {
    this.id = config.id
    this.config = {
      ...DEFAULT_TOAST_QUEUE_PLUGIN_CONFIG,
      ...config.moduleConfig,
    }
    this.toastQueue = new ToastQueue()
  }

  /**
   * Инициализирует плагин и добавляет модуль в контекст
   * @param context Глобальный контекст
   */
  init(context: IGlobalContext): void {
    try {
      // Проверяем, существует ли уже модуль с нашим ID
      const existingModule = context.getModule(this.id)

      if (!existingModule) {
        // Создаем модуль очереди с тем же ID, что и у плагина
        this.toastQueueModule = new ToastQueueModule(this.id, this.config)

        // Добавляем его в контекст
        context.putModule(this.toastQueueModule)
      } else {
        // Если модуль уже существует, сохраняем ссылку на него
        this.toastQueueModule = existingModule as ToastQueueModule
      }

      // Обновляем конфигурацию с учетом дефолтов
      this.toastQueueModule.updateConfig(this.config)

      const host = this.toastQueueModule.createHost()
      this.createToastHostAndAppend(host as YCoreToastQueueHost, this.config.host)

      // Передаем конфигурацию в хост
      const moduleConfig = this.toastQueueModule.getConfig()
      host.setConfig({
        ...DEFAULT_TOAST_QUEUE_HOST_CONFIG,
        ...moduleConfig,
      })

      // Подключаем модуль к хосту
      host.addQueueModule(this.toastQueueModule)

      // Инициализируем глобальный API для работы с тостами
      this.toastQueue.initialize(context, this.id)
    } catch(error) {
      console.warn('Ошибка инициализации ToastsPlugin:', error)
    }
  }

  /**
   * Создает и добавляет хост тостов в DOM
   * @param toastHost - Экземпляр хоста тостов
   * @param hostSelector - Селектор элемента для хоста тостов
   * @private
   */
  private createToastHostAndAppend(toastHost: YCoreToastQueueHost, hostSelector?: string) {
    let targetElement: HTMLElement | Element = document.body
    if (hostSelector) {
      const el = document.querySelector(hostSelector)

      if (el === null) {
        console.warn('Не удалось найти элемент для хоста тостов по селектору:', hostSelector, '. Будет добавлено в body')
      }

      targetElement = el || document.body
    }

    if (!toastHost.isConnected) {
      targetElement.appendChild(toastHost)
    }
  }

  /**
   * Уничтожает плагин и очищает состояние
   */
  destroy(context?: IGlobalContext): void {
    const module = this.toastQueueModule
    if (module) {
      const host = module.getHost()
      if (host) {
        host.removeQueueModule()
      }
      module.destroyHost()
      context?.removeModule(this.id)
    }

    // Очищаем ссылку на модуль
    this.toastQueueModule = undefined

    // Сбрасываем глобальный API
    this.toastQueue.reset()
  }

  /**
   * Получает модуль очереди тостов
   * @returns Модуль очереди тостов или undefined, если модуль не инициализирован
   */
  getModule(): IToastQueueModule | undefined {
    return this.toastQueueModule
  }
}
