import type { TEventsStoryArgs } from '~core/utils/helpers-utility-types'
import type { IDropdownListItem } from '~shared/types/global'

/**
 * Событие клика по элементу выпадающего списка
 */
export interface IYCoreDropdownListItemClickEvent {

  /**
   * Выбранный элемент
   */
  item: IDropdownListItem
}

/**
 * Событие клика по элементу выпадающего списка
 */
export class ItemClickEvent extends CustomEvent<IYCoreDropdownListItemClickEvent> {}
export class ArrowNextEvent extends CustomEvent<void> {}
export class ArrowPrevEvent extends CustomEvent<void> {}
export class SelectEvent extends CustomEvent<void> {}
export class CancelEvent extends CustomEvent<void> {}

export type TYCoreDropdownListEvents = TEventsStoryArgs<{
  ItemClickEvent: typeof ItemClickEvent
  ArrowNextEvent: typeof ArrowNextEvent
  ArrowPrevEvent: typeof ArrowPrevEvent
  SelectEvent: typeof SelectEvent
  CancelEvent: typeof CancelEvent
}>
