import type { TEventsStoryArgs } from '~core/utils/helpers-utility-types'

/**
 * Событие клика по элементу меню
 */
export class ClickEvent extends CustomEvent<{ event: Event }> {}

/**
 * Событие наведения мыши на элемент меню
 */
export class MouseEnterEvent extends CustomEvent<{ event: Event }> {}

/**
 * Событие ухода мыши с элемента меню
 */
export class MouseLeaveEvent extends CustomEvent<{ event: Event }> {}

/**
 * Событие получения фокуса
 */
export class FocusEvent extends CustomEvent<{ event: Event }> {}

/**
 * Событие потери фокуса
 */
export class BlurEvent extends CustomEvent<{ event: Event }> {}

/**
 * Событие изменения состояния opened (открыто/закрыто)
 * Диспатчится при клике на элемент с типом MAIN, когда есть дочерние элементы
 */
export class OpenedChangeEvent extends CustomEvent<{ value: boolean }> {}

export type TYCoreSideMenuItemEvents = TEventsStoryArgs<{
  ClickEvent: typeof ClickEvent
  MouseEnterEvent: typeof MouseEnterEvent
  MouseLeaveEvent: typeof MouseLeaveEvent
  FocusEvent: typeof FocusEvent
  BlurEvent: typeof BlurEvent
  OpenedChangeEvent: typeof OpenedChangeEvent
}>
