import { html } from 'lit'
import { renderIcon } from '~core/renderers'
import type { IYIcon } from '~web/shared/icons'

interface IRenderMediaSlotOptions {
  icon?: IYIcon
  hidden?: boolean
  onSlotChange: (event: Event) => void
}

export const renderMedia = ({ icon, hidden, onSlotChange }: IRenderMediaSlotOptions) => {
  return html`
    <slot
      name="media"
      ?hidden=${hidden}
      @slotchange=${onSlotChange}
    >
      ${renderIcon({ icon, size: '20px' })}
    </slot>
  `
}
