import { LitElement, html, css, unsafeCSS } from 'lit'
import { customElement, property } from 'lit/decorators.js'
import { classMap } from 'lit/directives/class-map.js'

import { YCoreCheckboxGroupTagName as tagName } from '~shared/constants'
import { YC_COMPONENT_ATTRIBUTE_NAME } from '~shared/constants/attributes'

import { renderLabel } from '~core/renderers'
import classMapToString from '~core/utils/classMapToString'

import {
  createCoreCheckboxGroupProps,
  type IYCoreCheckboxGroupProps,
} from './models/types'
import YCheckboxGroupVarsCss from './css/CheckboxGroup.vars.css?inline'
import YCheckboxGroupScopedCss from './css/CheckboxGroup.scoped.css?inline'

const { direction, labelText, labelAlignment, labelOverflowDebounce, labelTooltipText, labelTooltipActive, labelTooltipPlacement } = createCoreCheckboxGroupProps()

@customElement(tagName)
export class YCoreCheckboxGroup extends LitElement implements Required<IYCoreCheckboxGroupProps> {
  @property({ type: String, attribute: 'direction' }) direction: IYCoreCheckboxGroupProps['direction'] = direction
  @property({ type: String, attribute: 'label-text' }) labelText: IYCoreCheckboxGroupProps['labelText'] = labelText
  @property({ type: String, attribute: 'label-alignment' }) labelAlignment: IYCoreCheckboxGroupProps['labelAlignment'] = labelAlignment
  @property({ type: Number, attribute: 'label-overflow-debounce' }) labelOverflowDebounce: IYCoreCheckboxGroupProps['labelOverflowDebounce'] = labelOverflowDebounce
  @property({ type: String, attribute: 'label-tooltip-text' }) labelTooltipText: IYCoreCheckboxGroupProps['labelTooltipText'] = labelTooltipText
  @property({ type: Boolean, attribute: 'label-tooltip-active' }) labelTooltipActive: IYCoreCheckboxGroupProps['labelTooltipActive'] = labelTooltipActive
  @property({ type: String, attribute: 'label-tooltip-placement' }) labelTooltipPlacement: IYCoreCheckboxGroupProps['labelTooltipPlacement'] = labelTooltipPlacement

  private readonly baseClass = tagName

  static readonly styles = [
    css`
      ${unsafeCSS(YCheckboxGroupVarsCss)}
      ${unsafeCSS(YCheckboxGroupScopedCss)}
    `,
  ]

  private get computedClasses() {
    return {
      [this.baseClass]: true,
      [`${this.baseClass}_direction_${this.direction}`]: true,
    }
  }
  private get computedLabelClasses() {
    return { [`${this.baseClass}__label`]: true }
  }
  private get computedWrapperClasses() {
    return { [`${this.baseClass}__wrapper`]: true }
  }

  connectedCallback() {
    super.connectedCallback()

    this.dataset.locator = tagName
    this.dataset[YC_COMPONENT_ATTRIBUTE_NAME] = ''
  }

  disconnectedCallback() {
    super.disconnectedCallback()
  }

  protected render() {
    return html`
      <div class=${classMap(this.computedClasses)}>
        ${renderLabel({
          text: this.labelText,
          alignment: this.labelAlignment,
          debounce: this.labelOverflowDebounce,
          tooltipText: this.labelTooltipText,
          tooltipActive: this.labelTooltipActive,
          tooltipPlacement: this.labelTooltipPlacement,
          className: classMapToString(this.computedLabelClasses),
        })}

        <div class=${classMap(this.computedWrapperClasses)}>
          <slot></slot>
        </div>
      </div>
    `
  }
}
