import { LitElement, html, css, unsafeCSS, nothing } from 'lit'
import { customElement, property } from 'lit/decorators.js'
import { classMap } from 'lit/directives/class-map.js'
import { repeat } from 'lit/directives/repeat.js'

import {
  createCorePaginationProps,
  type IYCorePaginationProps,
  ChangePageEvent,
} from '~core/ui/pagination/models/types'
import {
  YCorePaginationTagName as tagName,
} from '~shared/constants'
import { YC_COMPONENT_ATTRIBUTE_NAME } from '~web/shared/constants/attributes'
import { interceptEvents } from '~core/utils/event-interceptor'
import { bubblingEvent } from '~core/utils/event-decorator'
import type { TDispatcher } from '~core/utils/event-decorator'

import '~core/ui/text'
import '~core/ui/simpleButton'
import '~core/ui/iconButton'

import YCorePaginationVarsCss from '~core/ui/pagination/css/Pagination.vars.css?inline'
import YCorePaginationScopedCss from '~core/ui/pagination/css/Pagination.scoped.css?inline'

import { yChevronLeft, yChevronRight, y3Dots } from '~shared/icons'
import {
  getPageAfterLeftGap,
  getPageAfterRightGap,
  getTotalPages,
  getVisiblePages,
  hasLeadingGap,
  hasTrailingGap,
  isFirstPage,
  isLastPage,
} from './utils'

const { page, itemsPerPage, total, disabled } = createCorePaginationProps()

@customElement(tagName)
@interceptEvents()
export class YCorePagination extends LitElement implements Required<IYCorePaginationProps> {
  @property({ type: Number }) page: IYCorePaginationProps['page'] = page
  @property({ type: Number, attribute: 'items-per-page' }) itemsPerPage: IYCorePaginationProps['itemsPerPage'] = itemsPerPage
  @property({ type: Number }) total: IYCorePaginationProps['total'] = total
  @property({ type: Boolean }) disabled: IYCorePaginationProps['disabled'] = disabled

  @bubblingEvent(
    ChangePageEvent,
    { name: 'change-page' },
  )
  private _changePage!: TDispatcher<ChangePageEvent>

  private readonly baseClass = tagName

  static readonly styles = [
    css`
      ${unsafeCSS(YCorePaginationVarsCss)}
      ${unsafeCSS(YCorePaginationScopedCss)}
    `,
  ]

  private get computedClasses() {
    return { [this.baseClass]: true }
  }

  private get computedPage() { return Number(this.page) }
  private get computedTotal() { return Number(this.total) }
  private get computedItemsPerPage() { return Number(this.itemsPerPage) }

  private get totalPages() {
    return getTotalPages(this.computedTotal, this.computedItemsPerPage)
  }

  private get visiblePages() {
    return getVisiblePages(this.computedPage, this.totalPages)
  }

  private get isLeftEllipsisVisible() {
    return hasLeadingGap(this.visiblePages)
  }

  private get isRightEllipsisVisible() {
    return hasTrailingGap(this.visiblePages, this.totalPages)
  }

  private get isPrevButtonDisabled() {
    return this.disabled || isFirstPage(this.computedPage)
  }

  private get isNextButtonDisabled() {
    return this.disabled || isLastPage(this.computedPage, this.totalPages)
  }

  private handleChangePage = (page: number) => (event: Event) => {
    event.stopPropagation()
    event.preventDefault()

    this._changePage({ detail: { page, event } })
  }

  private handlePreviousPage = (event: Event) => {
    this.handleChangePage(this.computedPage - 1)(event)
  }

  private handleNextPage = (event: Event) => {
    this.handleChangePage(this.computedPage + 1)(event)
  }

  private handleLeftEllipsisClick = (event: Event) => {
    const newPage = getPageAfterLeftGap(this.visiblePages)
    this.handleChangePage(newPage)(event)
  }

  private handleRightEllipsisClick = (event: Event) => {
    const newPage = getPageAfterRightGap(this.visiblePages, this.totalPages)
    this.handleChangePage(newPage)(event)
  }

  connectedCallback() {
    super.connectedCallback()

    this.dataset.locator = tagName
    this.dataset[YC_COMPONENT_ATTRIBUTE_NAME] = ''
  }

  protected renderEllipsis(clickHandler: (event: Event) => void) {
    return html`
      <y-core-icon-button
        .disabled=${this.disabled}
        variant="text"
        .icon=${y3Dots}
        @click=${clickHandler}
      ></y-core-icon-button>
    `
  }

  protected renderPages() {
    return repeat(
      this.visiblePages,
      (page) => `page-${page}`,
      (page) => {
        const isCurrentPage = page === this.computedPage

        return html`
          <y-core-simple-button
            .disabled=${this.disabled || isCurrentPage}
            variant=${isCurrentPage ? 'primary' : 'text'}
            class="y-core-pagination__page-button"
            @click=${this.handleChangePage(page)}
          >
            <y-core-text
              variant=${isCurrentPage ? 'primary' : 'secondary'}
              size="a2-medium"
            >${page}</y-core-text>
          </y-core-simple-button>
        `
      },
    )
  }

  protected render() {
    return html`
      <div class=${classMap(this.computedClasses)}>
        <y-core-icon-button
          .disabled=${this.isPrevButtonDisabled}
          variant="text"
          .icon=${yChevronLeft}
          @click=${this.handlePreviousPage}
        ></y-core-icon-button>

        ${this.isLeftEllipsisVisible
          ? this.renderEllipsis(this.handleLeftEllipsisClick)
          : nothing
        }

        ${this.renderPages()}

        ${this.isRightEllipsisVisible
          ? this.renderEllipsis(this.handleRightEllipsisClick)
          : nothing
        }

        <y-core-icon-button
          .disabled=${this.isNextButtonDisabled}
          variant="text"
          .icon=${yChevronRight}
          @click=${this.handleNextPage}
        ></y-core-icon-button>
      </div>
    `
  }
}
