import { renderControlSlot, type IRenderControlSlotOptions } from './controlSlot'
import { renderControlChevron, type IRenderControlChevronOptions } from './controlChevron'

interface IRenderControlOptions extends IRenderControlSlotOptions, IRenderControlChevronOptions {
  isChevron?: boolean
}

export const renderControl = ({
  isChevron,
  baseClass,
  isOpened,
  hidden,
  onSlotChange,
  onMouseEnter,
  onMouseLeave,
}: IRenderControlOptions) => {
  if (isChevron) {
    return renderControlChevron({ baseClass, isOpened })
  }

  return renderControlSlot({ hidden, onSlotChange, onMouseEnter, onMouseLeave })
}
