import { LitElement, css, unsafeCSS } from 'lit'
import { html } from 'lit/static-html.js'
import { customElement, property, query, state } from 'lit/decorators.js'
import { classMap } from 'lit/directives/class-map.js'

import '~core/ui/loader'

import {
  createCoreButtonGroupProps,
  type IYCoreButtonGroupProps,
} from '~core/ui/buttonGroup/models/types'

import { YCoreButtonGroupTagName as tagName, YCoreButtonTagName, YCoreButtonDropdownTagName } from '~shared/constants'
import { YC_COMPONENT_ATTRIBUTE_NAME } from '~web/shared/constants/attributes'

import ButtonGroupVarsCSS from '~core/ui/buttonGroup/css/ButtonGroup.vars.css?inline'
import ButtonGroupScopedCSS from '~core/ui/buttonGroup/css/ButtonGroup.scoped.css?inline'

const { size, variant } = { ...createCoreButtonGroupProps() }

@customElement(tagName)
export class YCoreButtonGroup extends LitElement implements Required<IYCoreButtonGroupProps> {
  @state() private slotNodes: Element[] = []
  @property({ type: String }) size: IYCoreButtonGroupProps['size'] = size
  @property({ type: String }) variant: IYCoreButtonGroupProps['variant'] = variant


  @query('slot')
  private buttons!: HTMLSlotElement | null

  private readonly baseClass = tagName

  private get computedClasses() {
    return { [this.baseClass]: true }
  }

  connectedCallback() {
    super.connectedCallback()

    this.dataset.locator = tagName
    this.dataset[YC_COMPONENT_ATTRIBUTE_NAME] = ''

    this.updateSlotNodes()
  }

  updated(changedProperties: Map<string | number | symbol, unknown>) {
    super.updated(changedProperties)
    if (changedProperties.has('size') || changedProperties.has('variant')) {
      this.updateSlotNodes()
    }
  }

  private updateSlotNodes() {
    if (!this.buttons) {
      return
    }

    const slotElements = this.buttons.assignedElements({ flatten: true })
    const buttonTagNamesUpperCase = [
      YCoreButtonTagName.toUpperCase(),
      YCoreButtonDropdownTagName.toUpperCase(),
    ]

    // Ищем элементы <y-core-button> и <y-core-button-dropdown> даже в тех случаях,
    // где есть обертки, например, YButton в Ng/ButtonGroup
    const buttonNodes: Element[] = []
    slotElements.forEach((el) => {
      if (buttonTagNamesUpperCase.includes(el.tagName)) {
        buttonNodes.push(el)
        return
      }

      const buttonEl = el.querySelector<HTMLElement>(`${YCoreButtonTagName}, ${YCoreButtonDropdownTagName}`)

      if (buttonEl) {
        buttonNodes.push(buttonEl)
      }
    })

    this.slotNodes = buttonNodes
    this.updateSlotProps(slotElements)
  }

  private updateElementProps(element: HTMLElement) {
    if ('size' in element) element.size = this.size
    if ('variant' in element) element.variant = this.variant
  }

  private updateSlotProps(slotElements: Element[]) {
    this.slotNodes.forEach((node, index) => {
      if (!(node instanceof HTMLElement)) return

      const wrapper = slotElements[index]
      const isWrapped = wrapper instanceof HTMLElement && wrapper !== node

      if (isWrapped) {
        // Обновляем property на обертке
        this.updateElementProps(wrapper)
        // Устанавливаем атрибут на обертке (для css селектора ::slotted)
        wrapper.setAttribute('variant', this.variant)
      }

      this.updateElementProps(node)
    })
  }

  protected render() {
    return html`
      <div class=${classMap(this.computedClasses)}>
        <slot></slot>
      </div>
    `
  }

  static readonly styles = [
    css`${unsafeCSS(ButtonGroupVarsCSS)}`,
    css`${unsafeCSS(ButtonGroupScopedCSS)}`,
  ]
}
