import type { IYIcon } from '~web/shared/icons'
import type { TAnchorTarget } from '~shared/types/global'
import type { IYCoreLabelExternalProps } from '~core/ui/label/models/types'

export enum EYCoreSideMenuItemVariant {
  FULL = 'full',
  COLLAPSE = 'collapse',
}

export type TYCoreSideMenuItemVariant = `${EYCoreSideMenuItemVariant}`

/**
 * Свойства компонента SideMenuItem
 */
export interface IYCoreSideMenuItemExternalProps {

  /**
   * Текст лейбла
   *
   * @default 'undefined'
   */
  label: string | undefined

  /**
   * Позиция тултипа при переполнении лейбла
   *
   * @default 'undefined'
   */
  labelTooltipPlacement: IYCoreLabelExternalProps['tooltipPlacement']

  /**
   * Текст аннотации
   *
   * @default 'undefined'
   */
  annotation: string | undefined

  /**
   * Иконка элемента меню
   *
   * Отображается слева от заголовка (в развернутом режиме)
   * или как единственный визуальный элемент (в свернутом режиме)
   *
   * @default 'undefined'
   */
  icon: IYIcon | undefined

  /**
   * Режим отображения элемента меню
   *
   * Доступные значения:
   * - **full**: развернутый режим
   * - **collapse**: свернутый режим
   *
   * @default 'full'
   */
  variant: TYCoreSideMenuItemVariant | undefined

  /**
   * Флаг активного состояния элемента меню
   *
   * @default false
   */
  isActive: boolean | undefined

  /**
   * URL ссылки
   *
   * @default 'undefined'
   */
  href: string | undefined

  /**
   * Атрибут target для ссылки
   *
   * @default 'undefined'
   */
  target: TAnchorTarget | undefined

  /**
   * Ручное управление открытием пункта меню, если у него есть вложенные элементы
   *
   * @default 'undefined'
   */
  opened: boolean | undefined

  /**
   * Заблокированное состояние элемента меню
   *
   * Блокирует переход по ссылке, раскрытие вложенных элементов и hover-меню
   * в свернутом режиме, а также визуально приглушает пункт
   *
   * @default false
   */
  disabled: boolean | undefined
}

export const createCoreSideMenuItemExternalProps = (): IYCoreSideMenuItemExternalProps => ({
  label: undefined,
  labelTooltipPlacement: 'top',
  annotation: undefined,
  icon: undefined,
  variant: EYCoreSideMenuItemVariant.FULL,
  isActive: false,
  href: undefined,
  target: undefined,
  opened: undefined,
  disabled: false,
})
