import { type Dayjs } from 'dayjs'

export const getWeeksCountInMonth = (currentDate: Dayjs) => {
  const startOfMonth = currentDate.startOf('month')
  const endOfMonth = currentDate.endOf('month')
  const startOfFirstWeek = startOfMonth.startOf('week')
  const endOfLastWeek = endOfMonth.endOf('week')

  return endOfLastWeek.diff(startOfFirstWeek, 'week') + 1
}

export const isDateInCurrentWeek = (date: Dayjs, currentDate: Dayjs): boolean => {
  const startOfCurrentWeek = currentDate.startOf('week')
  const endOfCurrentWeek = currentDate.endOf('week')

  return date.isSameOrAfter(startOfCurrentWeek, 'day') &&
    date.isSameOrBefore(endOfCurrentWeek, 'day')
}
