import { type TYAvatarSizes } from '~shared/types/global'
import type { IYIcon } from '~shared/icons'

/**
 * Свойства компонента Avatar
 */
export interface IYCoreAvatarExternalProps {

  /**
   * Размер аватара
   * @default '40px'
   */
  size: TYAvatarSizes | undefined

  /**
   * Инициалы для отображения
   */
  initials: string | undefined

  /**
   * URL аватара
   */
  photo: string | undefined

  /**
   * Иконка для отображения
   */
  icon: IYIcon | undefined

  /**
   * Отключить аватар
   * @default false
   */
  disabled: boolean | undefined

  /**
   * Цвет аватара
   * @default 'default'
   */
  color: 'default' | 'accent' | undefined
}

export const createCoreAvatarExternalProps = (): IYCoreAvatarExternalProps => ({
  size: '40px',
  initials: '',
  photo: '',
  icon: undefined,
  disabled: false,
  color: 'default',
})
