import { LitElement, html, css, unsafeCSS } from 'lit'
import { customElement, property } from 'lit/decorators.js'
import { consume } from '@lit/context'

import { YCoreCardSimpleIconTagName as tagName } from '~shared/constants'
import { YC_COMPONENT_ATTRIBUTE_NAME } from '~web/shared/constants/attributes'
import { EYSizes } from '~shared/types/global'
import { sizeContextCreated } from '~core/ui/cardWrapper/providers'
import { createCoreCardSimpleIconProps, EYCoreCardSimpleIconSize, type IYCoreCardSimpleIconProps } from './models/types'

import CardSimpleIconScopedCSS from '~core/ui/cardSimpleIcon/css/CardSimpleIcon.scoped.css?inline'

import '~core/ui/icon'

const { size } = createCoreCardSimpleIconProps()

const mapSizeToIconSize: Record<NonNullable<IYCoreCardSimpleIconProps['size']>, string> = {
  [EYSizes.SMALL]: EYCoreCardSimpleIconSize.SMALL,
  [EYSizes.MEDIUM]: EYCoreCardSimpleIconSize.MEDIUM,
  [EYSizes.LARGE]: EYCoreCardSimpleIconSize.LARGE,
}

@customElement(tagName)
export class YCoreCardSimpleIcon
  extends LitElement
  implements Required<IYCoreCardSimpleIconProps> {
  @property({ type: Object }) icon!: IYCoreCardSimpleIconProps['icon']
  @consume({ context: sizeContextCreated, subscribe: true })
  @property({ type: String, reflect: true }) size: IYCoreCardSimpleIconProps['size'] = size

  private get computedSize() {
    return this.size ?? EYSizes.MEDIUM
  }

  private get computedIconSize() {
    return mapSizeToIconSize[this.computedSize]
  }

  static readonly styles = css`${unsafeCSS(CardSimpleIconScopedCSS)}`

  connectedCallback() {
    super.connectedCallback()

    this.dataset.locator = tagName
    this.dataset[YC_COMPONENT_ATTRIBUTE_NAME] = ''
  }

  protected render() {
    return html`
      <y-core-icon
        .icon=${this.icon}
        .size=${this.computedIconSize}
      ></y-core-icon>
    `
  }
}
