export const FIRST_PAGE = 1
export const MIN_PAGES = 1
export const PAGES_AROUND = 2
export const PAGES_WINDOW_SIZE = PAGES_AROUND * 2 + 1

export const getTotalPages = (total: number, itemsPerPage: number): number => {
  return Math.max(MIN_PAGES, Math.ceil(total / itemsPerPage))
}

export const createPageRange = (from: number, to: number): number[] => {
  const pageCount = to - from + 1
  return Array.from({ length: pageCount }, (_, index) => from + index)
}

export const getVisiblePages = (currentPage: number, totalPages: number): number[] => {
  if (totalPages <= PAGES_WINDOW_SIZE) {
    return createPageRange(FIRST_PAGE, totalPages)
  }

  const maxStartPage = totalPages - PAGES_WINDOW_SIZE + 1
  const naturalStartPage = currentPage - PAGES_AROUND

  const from = Math.min(
    Math.max(naturalStartPage, FIRST_PAGE),
    maxStartPage,
  )

  const to = from + PAGES_WINDOW_SIZE - 1

  return createPageRange(from, to)
}

export const hasLeadingGap = (visiblePages: number[]): boolean => {
  const firstVisiblePage = visiblePages[0]
  return firstVisiblePage > FIRST_PAGE
}

export const hasTrailingGap = (visiblePages: number[], totalPages: number): boolean => {
  const lastIndex = visiblePages.length - 1
  const lastVisiblePage = visiblePages[lastIndex]
  return lastVisiblePage < totalPages
}

export const getPageAfterLeftGap = (visiblePages: number[]): number => {
  const pageBeforeGap = visiblePages[0] - 1
  return Math.max(FIRST_PAGE, pageBeforeGap)
}

export const getPageAfterRightGap = (visiblePages: number[], totalPages: number): number => {
  const lastIndex = visiblePages.length - 1
  const pageAfterGap = visiblePages[lastIndex] + 1
  return Math.min(totalPages, pageAfterGap)
}

export const isFirstPage = (page: number): boolean => {
  return page === FIRST_PAGE
}

export const isLastPage = (page: number, totalPages: number): boolean => {
  return page === totalPages
}
