import type { ReactiveController, ReactiveControllerHost } from 'lit'
import { BREAKPOINTS } from '~shared/constants/breakpoints'

export type TBreakpointKey = keyof typeof BREAKPOINTS
type TRafId = ReturnType<typeof requestAnimationFrame> | null

export class BreakpointsController implements ReactiveController {
  private width = window.document.documentElement.clientWidth
  private host: ReactiveControllerHost
  private raf: TRafId = null

  constructor(host: ReactiveControllerHost) {
    this.host = host
    host.addController(this)
  }

  hostConnected() {
    // Подписываемся на resize окна
    window.addEventListener('resize', this.onResize, { passive: true })
    // Подписываемся на resize visualViewport
    window.visualViewport?.addEventListener('resize', this.onResize, { passive: true })
    // Подписываемся на смену ориентации
    window.addEventListener('orientationchange', this.onResize, { passive: true })

    // Делаем первичное измерение при подключении контроллера.
    this.measureAndUpdate()
  }

  hostDisconnected() {
    window.removeEventListener('resize', this.onResize as EventListener)
    window.visualViewport?.removeEventListener('resize', this.onResize as EventListener)
    window.removeEventListener('orientationchange', this.onResize as EventListener)

    if (this.raf !== null) cancelAnimationFrame(this.raf)
    this.raf = null
  }

  private onResize = () => {
    // При сериях resize-событий (например, во время поворота экрана или ресайза окна)
    // не запускаем новый цикл, пока предыдущий кадр ещё не обработан.
    // Это защищает от лишних измерений и повторных requestUpdate()
    if (this.raf !== null) return

    // Ставим измерение в ближайший animation frame:
    // браузер успевает применить часть layout-изменений перед чтением размеров
    this.raf = requestAnimationFrame(() => {
      // Второй animation frame нужен как буфер:
      // на некоторых устройствах после orientation change финальные размеры
      // стабилизируются не в первый кадр, а в следующий
      requestAnimationFrame(() => {
        // Сбрасываем маркер активного rAF-цикла, чтобы разрешить
        // обработку следующих resize-событий.
        this.raf = null
        // Считываем актуальные размеры и, если есть изменения,
        // триггерим обновление хоста.
        this.measureAndUpdate()
      })
    })
  }

  private measureAndUpdate() {
    let newWidth = window.document.documentElement.clientWidth

    const visualViewport = window.visualViewport
    if (visualViewport) {
      newWidth = visualViewport.width
    }

    if (newWidth === this.width) return

    this.width = newWidth
    this.host.requestUpdate()
  }

  get active(): TBreakpointKey {
    const entries = Object.entries(BREAKPOINTS) as [TBreakpointKey, number][]
    entries.sort((a, b) => a[1] - b[1])
    let current: TBreakpointKey = entries[0][0]
    for (const [key, value] of entries) {
      if (this.width >= value) {
        current = key
      } else {
        break
      }
    }
    return current
  }

  between(minKey: TBreakpointKey, maxKey: TBreakpointKey): boolean {
    return this.width >= BREAKPOINTS[minKey] && this.width <= BREAKPOINTS[maxKey]
  }

  greater(key: TBreakpointKey): boolean {
    return this.width > BREAKPOINTS[key]
  }

  greaterOrEqual(key: TBreakpointKey): boolean {
    return this.width >= BREAKPOINTS[key]
  }

  smaller(key: TBreakpointKey): boolean {
    return this.width < BREAKPOINTS[key]
  }

  smallerOrEqual(key: TBreakpointKey): boolean {
    return this.width <= BREAKPOINTS[key]
  }
}
