import {
  createCoreSimpleBannerProps,
  type IYCoreSimpleBannerProps,
} from '~core/ui/simpleBanner/models/types'

export enum EYCoreCalloutVariant {
  INFORMATION = 'information',
  SUCCESS = 'success',
  WARNING = 'warning',
  ERROR = 'error',
  NEUTRAL = 'neutral',
}

export type TYCoreCalloutVariant = `${EYCoreCalloutVariant}`

/**
 * Свойства компонента Callout
 */
export interface IYCoreCalloutExternalProps extends Pick<IYCoreSimpleBannerProps, 'description' | 'header' | 'primaryButtonText' | 'primaryButtonVariant' | 'secondaryButtonText' | 'secondaryButtonVariant' | 'hideCloseIcon'> {

  /**
   * Вариант отображения callout
   * @default 'information'
   */
  variant: TYCoreCalloutVariant

  /**
   * Показать callout
   * @default true
   */
  open: boolean | undefined

  /**
   * Скрыть слот media и встроенную иконку
   * @default false
   */
  hideMedia: boolean | undefined
}

export const createCoreCalloutExternalProps = (): IYCoreCalloutExternalProps => {
  const {
    description,
    header,
    primaryButtonText,
    primaryButtonVariant,
    secondaryButtonText,
    secondaryButtonVariant,
    hideCloseIcon,
  } = createCoreSimpleBannerProps()

  return {
    description,
    header,
    primaryButtonText,
    primaryButtonVariant,
    secondaryButtonText,
    secondaryButtonVariant,
    hideCloseIcon,
    variant: EYCoreCalloutVariant.INFORMATION,
    open: true,
    hideMedia: false,
  }
}
