import { LitElement, html, css, unsafeCSS } from 'lit'
import type { PropertyValues } from 'lit'
import { customElement, property } from 'lit/decorators.js'
import { classMap } from 'lit/directives/class-map.js'

import {
  createCoreSkeletonProps,
  type IYCoreSkeletonProps,
} from '~core/ui/skeleton/models/types'
import { YCoreSkeletonTagName as tagName } from '~shared/constants'
import { YC_COMPONENT_ATTRIBUTE_NAME } from '~web/shared/constants/attributes'
import { defineCustomElement } from '~web/shared/utils/components'

import YCoreSkeletonVarsCss from '~core/ui/skeleton/css/Skeleton.vars.css?inline'
import YCoreSkeletonScopedCss from '~core/ui/skeleton/css/Skeleton.scoped.css?inline'

const { variant, width, height } = createCoreSkeletonProps()

/** Класс на хосте: shimmer в плее только внутри viewport */
export const YCoreSkeletonInViewportClass = `${tagName}_in-viewport`

@customElement(tagName)
export class YCoreSkeleton extends LitElement implements Required<IYCoreSkeletonProps> {
  @property({ type: String, reflect: true }) variant: IYCoreSkeletonProps['variant'] = variant

  @property({ type: String }) width: IYCoreSkeletonProps['width'] = width

  @property({ type: String }) height: IYCoreSkeletonProps['height'] = height

  private readonly baseClass = tagName

  private viewportObserver: IntersectionObserver | null = null

  static readonly styles = [
    css`${unsafeCSS(YCoreSkeletonVarsCss)}`,
    css`${unsafeCSS(YCoreSkeletonScopedCss)}`,
  ]

  private get computedClasses() {
    return { [this.baseClass]: true }
  }

  private setSizes() {
    this.style.setProperty('width', this.width)
    this.style.setProperty('height', this.height)
  }

  protected updated(_changedProperties: PropertyValues) {
    super.updated(_changedProperties)
    this.setSizes()
  }

  private setupViewportObserver(): void {
    this.teardownViewportObserver()

    if (typeof IntersectionObserver === 'undefined') {
      this.classList.add(YCoreSkeletonInViewportClass)

      return
    }

    this.viewportObserver = new IntersectionObserver(
      (entries) => {
        if (!entries.length) return

        this.classList.toggle(
          YCoreSkeletonInViewportClass,
          entries[0].isIntersecting,
        )
      },
      {
        root: null,
        rootMargin: '48px 0px', // добавляем запас к viewport, чтобы анимация включалась "заранее"
        threshold: 0,
      },
    )

    this.viewportObserver.observe(this)
  }

  private teardownViewportObserver(): void {
    if (this.viewportObserver) {
      this.viewportObserver.disconnect()
      this.viewportObserver = null
    }

    this.classList.remove(YCoreSkeletonInViewportClass)
  }

  connectedCallback(): void {
    super.connectedCallback()

    this.setSizes()
    this.dataset.locator = tagName
    this.dataset[YC_COMPONENT_ATTRIBUTE_NAME] = ''

    queueMicrotask(() => {
      this.setupViewportObserver()
    })
  }

  disconnectedCallback(): void {
    this.teardownViewportObserver()
    super.disconnectedCallback()
  }

  protected firstUpdated(): void {
    defineCustomElement(tagName, YCoreSkeleton)
  }

  protected render() {
    return html`
      <div
        class=${classMap(this.computedClasses)}
        role="presentation"
        aria-hidden="true"
      ></div>
    `
  }
}
