import type { MiddlewareData, Placement, Side } from '~shared/utils/floating-ui'

type TArrowStyles = Partial<
  Pick<
    CSSStyleDeclaration,
    'top' | 'left' | 'right' | 'bottom' | 'transform'
  >
>

// Минимальный отступ стрелки от края popup,
// чтобы она не заходила в зону скругления углов
export const TIP_ARROW_EDGE_PADDING = 8 // top || bottom
const TIP_ROTATED_ARROW_EDGE_PADDING = 12 // left || right

// Стрелка должна заходить в popup на 1px, чтобы между поверхностью и стрелкой
// не появлялась тонкая щель из-за рендера границ и сглаживания.
const TIP_ARROW_SURFACE_OVERLAP = 1

// Для left/right placement layout-box стрелки нужно сильнее увести внутрь popup
// после поворота, иначе основание стрелки визуально отрывается от карточки.
const TIP_ARROW_SIDE_OFFSET = 10

const toPx = (value: number): string => `${value}px`

const SIDE_ARROW_STYLES: Record<Side, TArrowStyles> = {
  top: { top: `calc(100% - ${TIP_ARROW_SURFACE_OVERLAP}px)` },
  right: {
    right: `calc(100% - ${TIP_ARROW_SIDE_OFFSET}px)`,
    transform: 'rotate(0.25turn)',
  },
  bottom: {
    bottom: `calc(100% - ${TIP_ARROW_SURFACE_OVERLAP}px)`,
    transform: 'rotate(0.5turn)',
  },
  left: {
    left: `calc(100% - ${TIP_ARROW_SIDE_OFFSET}px)`,
    transform: 'rotate(-0.25turn)',
  },
}

const ALIGNED_ARROW_STYLES: Partial<Record<Placement, TArrowStyles>> = {
  'top-start': {
    left: toPx(TIP_ROTATED_ARROW_EDGE_PADDING),
    right: '',
  },
  'top-end': {
    left: '',
    right: toPx(TIP_ROTATED_ARROW_EDGE_PADDING),
  },
  'bottom-start': {
    left: toPx(TIP_ROTATED_ARROW_EDGE_PADDING),
    right: '',
  },
  'bottom-end': {
    left: '',
    right: toPx(TIP_ROTATED_ARROW_EDGE_PADDING),
  },
  'left-start': {
    top: toPx(TIP_ROTATED_ARROW_EDGE_PADDING),
    bottom: '',
  },
  'left-end': {
    top: '',
    bottom: toPx(TIP_ROTATED_ARROW_EDGE_PADDING),
  },
  'right-start': {
    top: toPx(TIP_ROTATED_ARROW_EDGE_PADDING),
    bottom: '',
  },
  'right-end': {
    top: '',
    bottom: toPx(TIP_ROTATED_ARROW_EDGE_PADDING),
  },
}

// @floating-ui добавляет alignmentOffset, когда стрелка начинает вылезать за границу
const hasAlignmentOffset = (middlewareData: MiddlewareData): boolean => {
  return middlewareData.arrow?.alignmentOffset !== undefined
}

export const getArrowStyles = (middlewareData: MiddlewareData, placement: Placement): TArrowStyles => {
  const { arrow: arrowData } = middlewareData
  if (!arrowData) return {}

  const { x, y } = arrowData
  const side = placement.split('-')[0] as Side

  const baseStyles = {
    top: y != null
      ? `${y}px`
      : '',
    left: x != null
      ? `${x}px`
      : '',
    right: '',
    bottom: '',
    transform: '',
  }

  // Компенсация alignmentOffset от @floating-ui
  const alignmentStyles = !hasAlignmentOffset(middlewareData)
    ? ALIGNED_ARROW_STYLES[placement] ?? {}
    : {}

  return {
    ...baseStyles,
    ...SIDE_ARROW_STYLES[side],
    ...alignmentStyles,
  }
}
