import { pick } from 'radash'
import { createCoreCardWrapperProps, type IYCoreCardWrapperProps } from '~core/ui/cardWrapper/models/types'
import { createCoreIconExternalProps, type IYCoreIconExternalProps } from '~core/ui/icon/models/types'

export const enum EYCoreCardSimpleIconSize {
  SMALL = '20px',
  MEDIUM = '28px',
  LARGE = '32px',
}

export interface IYCoreCardSimpleIconExternalProps
  extends Pick<IYCoreCardWrapperProps, 'size'>, Pick<IYCoreIconExternalProps, 'icon'> {
}

export const createCoreCardSimpleIconExternalProps = (): IYCoreCardSimpleIconExternalProps => ({
  ...pick(createCoreCardWrapperProps(), ['size']),
  ...pick(createCoreIconExternalProps(), ['icon']),
})
