import { html, nothing } from 'lit'
import { virtualize } from '@lit-labs/virtualizer/virtualize.js'
import { repeat } from 'lit/directives/repeat.js'
import type { IDropdownListItem } from '~shared/types/global.ts'

export type TRenderListItem = (item: IDropdownListItem, index: number) => ReturnType<typeof html>

export const renderDropdownListContent = (
  items: IDropdownListItem[],
  renderListItem: TRenderListItem,
  options: {
    useVirtualScroll?: boolean
    keyFunction?: (item: IDropdownListItem) => string | number
  } = {},
) => {
  if (!items.length) {
    return html`${nothing}`
  }

  const keyFunction = options.keyFunction || ((item: IDropdownListItem) => item.id)

  if (options.useVirtualScroll) {
    return html`
      ${virtualize({
        items,
        keyFunction: (item) => keyFunction(item),
        renderItem: (item, index) => renderListItem(item, index),
      })}
    `
  }

  return repeat(
    items,
    keyFunction,
    (item, index) => renderListItem(item, index),
  )
}
