import {
  type IYCoreTipExternalProps,
  createCoreTipExternalProps,
} from '~core/ui/tip/models/types'

/**
 * Свойства компонента Popover
 */
export interface IYCorePopoverExternalProps extends IYCoreTipExternalProps {

  /**
   * Текст кнопки подтверждения
   */
  submitText: string | undefined

  /**
   * Текст кнопки отмены
   */
  cancelText: string | undefined

  /**
   * Отключить попап
   * @default false
   */
  disabled: boolean

  /**
   * Игнорировать закрытие по нажатию клавиши Esc
   * @default false
   */
  preventEscape: boolean

  /**
   * Задержка (мс) для триггера hover (проброс в Tip → Dropdown)
   * @default 150 — задаётся в Dropdown: HOVER_VISIBLE_DELAY_MS
   */
  delay: number | undefined
}

export const createCorePopoverExternalProps = (): IYCorePopoverExternalProps => ({
  ...createCoreTipExternalProps(),
  submitText: undefined,
  cancelText: undefined,
  disabled: false,
  preventEscape: false,
})
