import { html, LitElement, css, unsafeCSS, nothing, type PropertyValues } from 'lit'
import { customElement, property, state, query } from 'lit/decorators.js'
import { classMap } from 'lit/directives/class-map.js'
import { repeat } from 'lit/directives/repeat.js'
import { styleMap } from 'lit/directives/style-map.js'
import '@lit-labs/virtualizer'
import type { LitVirtualizer } from '@lit-labs/virtualizer/LitVirtualizer.js'
import type { RenderItemFunction } from '@lit-labs/virtualizer/virtualize.js'
import { provide } from '@lit/context'
import { flip as flipMiddleware } from '~shared/utils/floating-ui'

import { type TDispatcher, bubblingEvent } from '~core/utils/event-decorator'
import { interceptEvents } from '~core/utils/event-interceptor'

import {
  YCoreSelectFieldTagName as tagName,
  YCoreDropdownCellTagName,
  YCoreFieldInputTagName,
} from '~shared/constants'
import { YC_COMPONENT_ATTRIBUTE_NAME } from '~web/shared/constants/attributes'
import {
  type IYCoreSelectListItem,
  type TItemValue,
  type TYCoreSelectFieldItemValue,
  type IYCoreSelectFieldExternalProps,
  createCoreSelectFieldExternalProps,
  isValueEqualListItem,
  SelectEvent, FocusEvent, BlurEvent, InputEvent,
  type VisibleEvent,
} from '~core/ui/selectField/models/types'
import YCoreSelectFieldVarsCSS from '~core/ui/selectField/css/SelectField.vars.css?inline'
import YCoreSelectFieldScopedCSS from '~core/ui/selectField/css/SelectField.scoped.css?inline'

import { disabledContextCreated, readonlyContextCreated, errorContextCreated, sizeContextCreated } from '~core/ui/fieldWrapper/providers'

import type { YCoreFieldInput } from '~core/ui/fieldInput'

import '~core/ui/fieldWrapper'
import '~core/ui/fieldInput'
import '~core/ui/fieldIcon'
import '~core/ui/fieldAvatar'
import '~core/ui/avatar'
import '~core/ui/tag'
import '~core/ui/dropdown'
import '~core/ui/dropdownList'
import '~core/ui/dropdownCell'

import { yChevronDown, yCheck } from '~shared/icons'
import { renderIcon, renderLabel, renderError, renderAnnotation } from '~core/renderers'
import classMapToString from '~core/utils/classMapToString'
import { hasSlotContent } from '~core/utils/lit-slots'
import { booleanConverter } from '~core/utils/converters'
import { isHandledKey, HANDLED_KEYS, type THandledKey } from '~core/utils/list-keyboard-navigation'
import { EYCoreDropdownPlacement, EYCoreDropdownTrigger } from '~core/ui/dropdown/models/types'

const {
  value,
  name,
  placeholder,
  autofocus,
  disabled,
  readonly,
  error,
  errors,
  size,
  required,
  labelText,
  labelTooltipText,
  annotationText,
  labelDebounce,
  isMapOptions,
  items,
  itemLabel,
  itemValue,
  isCustomFilter,
  isFilterable,
  filterValue,
  useVirtualScroll,
  maskOptions,
  ellipsis,
  labelTooltipPlacement,
  filterCallback,
  locator,
  labelLocator,
  displayValue,
} = createCoreSelectFieldExternalProps()

@customElement(tagName)
@interceptEvents()
export class YCoreSelectField extends LitElement implements Required<IYCoreSelectFieldExternalProps> {
  @provide({ context: disabledContextCreated })
  @property({ type: Boolean }) disabled: IYCoreSelectFieldExternalProps['disabled'] = disabled
  @provide({ context: readonlyContextCreated })
  @property({ type: Boolean, converter: booleanConverter }) readonly: IYCoreSelectFieldExternalProps['readonly'] = readonly
  @provide({ context: errorContextCreated })
  @property({ type: Boolean, reflect: true, converter: booleanConverter }) error: IYCoreSelectFieldExternalProps['error'] = error
  @provide({ context: sizeContextCreated })
  @property({ type: String, reflect: true }) size: IYCoreSelectFieldExternalProps['size'] = size

  @property({ type: Object }) value: IYCoreSelectFieldExternalProps['value'] = value
  @property({ type: String, attribute: 'filter-value' }) filterValue: IYCoreSelectFieldExternalProps['filterValue'] = filterValue
  @property({ type: String }) name: IYCoreSelectFieldExternalProps['name'] = name
  @property({ type: String }) placeholder: IYCoreSelectFieldExternalProps['placeholder'] = placeholder
  @property({ type: Boolean, reflect: true }) autofocus: NonNullable<IYCoreSelectFieldExternalProps['autofocus']> = Boolean(autofocus)
  @property({ type: Boolean, reflect: true }) required: IYCoreSelectFieldExternalProps['required'] = required
  @property({ type: Array }) errors: IYCoreSelectFieldExternalProps['errors'] = errors
  @property({ type: Number, attribute: 'label-debounce' }) labelDebounce: IYCoreSelectFieldExternalProps['labelDebounce'] = labelDebounce
  @property({ type: Boolean, attribute: 'is-map-options' }) isMapOptions: IYCoreSelectFieldExternalProps['isMapOptions'] = isMapOptions
  @property({ type: String, attribute: 'label-text' }) labelText: IYCoreSelectFieldExternalProps['labelText'] = labelText
  @property({ type: String, attribute: 'label-tooltip-text' }) labelTooltipText: IYCoreSelectFieldExternalProps['labelTooltipText'] = labelTooltipText
  @property({ type: String, attribute: 'label-tooltip-placement' }) labelTooltipPlacement: IYCoreSelectFieldExternalProps['labelTooltipPlacement'] = labelTooltipPlacement
  @property({ type: String, attribute: 'annotation-text' }) annotationText: IYCoreSelectFieldExternalProps['annotationText'] = annotationText
  @property({ type: Array }) items: NonNullable<IYCoreSelectFieldExternalProps['items']> = items ?? []
  @property({ type: String, attribute: 'item-label' }) itemLabel: NonNullable<IYCoreSelectFieldExternalProps['itemLabel']> = String(itemLabel)
  @property({ type: String, attribute: 'item-value' }) itemValue: NonNullable<IYCoreSelectFieldExternalProps['itemValue']> = String(itemValue)
  @property({ type: String, attribute: 'display-value' }) displayValue: NonNullable<IYCoreSelectFieldExternalProps['displayValue']> = String(displayValue)
  @property({ type: Boolean, attribute: 'is-custom-filter' }) isCustomFilter: IYCoreSelectFieldExternalProps['isCustomFilter'] = isCustomFilter
  @property({ type: Boolean, attribute: 'is-filterable' }) isFilterable: IYCoreSelectFieldExternalProps['isFilterable'] = isFilterable
  @property({ attribute: 'filter-callback' }) filterCallback: IYCoreSelectFieldExternalProps['filterCallback'] = filterCallback
  @property({ type: Boolean, converter: booleanConverter, attribute: 'use-virtual-scroll' }) useVirtualScroll: IYCoreSelectFieldExternalProps['useVirtualScroll'] = useVirtualScroll
  @property({ type: Object, attribute: 'mask-options' }) maskOptions: IYCoreSelectFieldExternalProps['maskOptions'] = maskOptions
  @property({ type: Boolean }) ellipsis: IYCoreSelectFieldExternalProps['ellipsis'] = ellipsis
  @property({ type: String }) locator: IYCoreSelectFieldExternalProps['locator'] = locator
  @property({ type: String, attribute: 'label-locator' }) labelLocator: IYCoreSelectFieldExternalProps['labelLocator'] = labelLocator

  @bubblingEvent(
    FocusEvent,
    { name: 'focus' },
  )
  _focus!: TDispatcher<FocusEvent>

  @bubblingEvent(
    SelectEvent,
    { name: 'select' },
  )
  _select!: TDispatcher<SelectEvent>

  @bubblingEvent(
    InputEvent,
    { name: 'input' },
  )
  _input!: TDispatcher<InputEvent>

  @bubblingEvent(
    BlurEvent,
    { name: 'blur' },
  )
  _blur!: TDispatcher<BlurEvent>

  @query(YCoreFieldInputTagName) public readonly fieldInput?: YCoreFieldInput
  @query('lit-virtualizer') private _virtualizer?: LitVirtualizer

  @state() private isOpened = false
  @state() private hasAnnotationSlot = false
  @state() private hasBeforeSlot = false
  @state() private lastFocusTime = 0
  @state() private focusedIndex: number | null = null
  @state() private virtualizerHeightPx: number | null = null
  @state() private virtualizerContentHeightPx: number | null = null

  private readonly dropdownCellPadding = 16
  private readonly baseClass = tagName
  private readonly baseDropdownActivatorClass = `${this.baseClass}__activator`
  private readonly baseDropdownContentClass = `${this.baseClass}__content`
  private readonly baseDropdownListClass = `${this.baseClass}__dropdown-list`
  private readonly baseDropdownListItemClass = `${this.baseClass}__list-item`
  private readonly baseDropdownListItemsClass = `${this.baseClass}__list-items`
  private readonly baseVirtualizerClass = `${this.baseClass}__virtualizer`
  private readonly baseAnnotationClass = `${this.baseClass}__annotation`
  private readonly baseArrowIconClass = `${this.baseClass}__arrow-icon`
  private readonly baseInputClass = `${this.baseClass}__input`

  static readonly styles = [
    css`
      ${unsafeCSS(YCoreSelectFieldVarsCSS)}
      ${unsafeCSS(YCoreSelectFieldScopedCSS)}
    `,
  ]

  private get dropdownListContainer(): HTMLElement | null {
    return this.shadowRoot?.querySelector<HTMLElement>(`.${this.baseDropdownListItemsClass}`) ?? null
  }

  private get selectedItemByValue(): IYCoreSelectListItem | undefined {
    if (this.value === undefined) {
      return undefined
    }

    if (this.isValueEqualListItem(this.value)) {
      return this.value
    }

    return this.findItemByValue(this.value)
  }

  private get inputValue(): string {
    if (this.isFilterable && this.isOpened) {
      return this.filterValue ?? ''
    }

    if (this.displayValue) {
      return this.displayValue
    }

    return this.selectedItemByValue ? String(this.selectedItemByValue[this.itemLabel]) : ''
  }

  private get computedClasses() {
    return {
      [this.baseClass]: true,
      [`${this.baseClass}_focused`]: this.isOpened,
      [`${this.baseClass}_size_${this.size}`]: true,
    }
  }
  private get computedLabelClasses() {
    return { [`${this.baseClass}__label`]: true }
  }
  private get computedAnnotationClasses() {
    return {
      [this.baseAnnotationClass]: true,
      [`${this.baseAnnotationClass}_hidden`]: !this.hasAnnotation,
    }
  }
  private get computedActivatorClasses() {
    return {
      [this.baseDropdownActivatorClass]: true,
      [`${this.baseDropdownActivatorClass}_readonly`]: Boolean(this.readonly),
      [`${this.baseDropdownActivatorClass}_disabled`]: Boolean(this.disabled),
      [`${this.baseDropdownActivatorClass}_hide-before`]: !this.hasBeforeSlot,
    }
  }
  private get computedArrowIconClasses() {
    return {
      [this.baseArrowIconClass]: true,
      [`${this.baseArrowIconClass}_rotated`]: this.isOpened,
    }
  }
  private get computedInputClasses() {
    return {
      [this.baseInputClass]: true,
      [`${this.baseInputClass}_disabled`]: Boolean(this.disabled),
      [`${this.baseInputClass}_readonly`]: Boolean(this.readonly),
    }
  }

  private get computedDisabledOrReadonly() {
    return this.disabled || this.readonly
  }

  private get computedRenderedItemMaxHeight() {
    if (!this.useVirtualScroll) return 0

    const hasAvatar = this.items.some((el) => this.hasAvatarState(el))
    return hasAvatar ? 32 : 24 // размер внутреннего контента
  }

  /**
   * Расчёт height виртулизированного списка, так как height lit-virtualizer это 0
   */
  private readCssVariable(element: Element, variable: string, fallback: number): number {
    const raw = getComputedStyle(element).getPropertyValue(variable).trim()
    const value = parseFloat(raw)

    return Number.isFinite(value) ? value : fallback
  }

  private getDropdownListHeightLimits(): { minHeight: number; maxHeight: number } {
    // Токены читаем с :host — во время render() y-core-dropdown-list ещё может отсутствовать в DOM
    return {
      minHeight: this.readCssVariable(this, '--y-core-select-field-dropdown-list-min-height', 36),
      maxHeight: this.readCssVariable(this, '--y-core-select-field-dropdown-list-max-height', 404),
    }
  }

  private readVirtualizerSizerHeight(virtualizer: LitVirtualizer): number {
    const sizer = virtualizer.querySelector('[virtualizer-sizer]')
    if (!(sizer instanceof HTMLElement)) return 0

    const translateMatch = (/translate\(([^)]+)\)/).exec(sizer.style.transform)
    if (!translateMatch) return 0

    const coords = translateMatch[1].split(',').map((part) => parseFloat(part.trim()))
    const y = coords.length > 1 ? coords[1] : coords[0]

    return Number.isFinite(y) ? y : 0
  }

  private calculateVirtualizerContentHeight(): number {
    if (this.dropdownItems.length === 0 || this.computedRenderedItemMaxHeight === 0) return 0
    const { maxHeight } = this.getDropdownListHeightLimits()

    const renderedCellHeight = this.computedRenderedItemMaxHeight + this.dropdownCellPadding

    return Math.min(renderedCellHeight * this.dropdownItems.length, maxHeight * 2)
  }

  private getVirtualizerContentHeightPx(virtualizer: LitVirtualizer): number {
    const sizerHeight = this.readVirtualizerSizerHeight(virtualizer)
    const calculatedHeight = this.calculateVirtualizerContentHeight()

    return Math.min(sizerHeight, calculatedHeight, virtualizer.scrollHeight)
  }

  private applyVirtualizerMeasuredHeight(virtualizer: LitVirtualizer): void {
    const { minHeight, maxHeight } = this.getDropdownListHeightLimits()
    const contentHeight = this.getVirtualizerContentHeightPx(virtualizer)
    const viewportHeight = Math.min(Math.max(contentHeight, minHeight), maxHeight)

    this.virtualizerContentHeightPx = contentHeight
    this.virtualizerHeightPx = viewportHeight
  }

  private get computedVirtualizerStyles() {
    const { minHeight, maxHeight } = this.getDropdownListHeightLimits()
    const viewportHeight = Math.min(Math.max(this.virtualizerHeightPx ?? minHeight, minHeight), maxHeight)
    const contentHeight = this.virtualizerContentHeightPx ?? viewportHeight

    return {
      maxHeight: `${maxHeight}px`,
      minHeight: `${viewportHeight}px`,
      overflowY: contentHeight > viewportHeight ? 'auto' : 'hidden',
    }
  }

  private getUpdatesPromise = async() => {
    await Promise.race([
      this.updateComplete,
      this._virtualizer?.layoutComplete,
    ])
  }

  private get computedDropdownCellStyles() {
    if (!this.useVirtualScroll || !this.computedRenderedItemMaxHeight) {
      return { '--y-core-dropdown-cell-default-height': 'auto' }
    }

    return { '--y-core-dropdown-cell-default-height': `${this.computedRenderedItemMaxHeight}px` }
  }

  private resetVirtualizerHeight(): void {
    this.virtualizerHeightPx = null
    this.virtualizerContentHeightPx = null
  }

  private async syncVirtualizerHeight(): Promise<void> {
    await this.updateComplete

    const virtualizer = this._virtualizer
    if (!virtualizer) return

    try {
      await virtualizer.layoutComplete
      this.applyVirtualizerMeasuredHeight(virtualizer)

      await new Promise<void>((resolve) => {
        requestAnimationFrame(() => {
          this.applyVirtualizerMeasuredHeight(virtualizer)
          resolve()
        })
      })

      await this.getUpdatesPromise()
    } catch {
      // virtualizer disconnected from DOM before layout completed
    }
  }

  private get canToggleDropdown() {
    return !this.computedDisabledOrReadonly && this.fieldInput?.inputElement
  }

  private get isDropdownOpened() {
    if (this.computedDisabledOrReadonly) return false

    return this.isOpened
  }

  private get hasAnnotation() {
    return this.annotationText || this.hasAnnotationSlot
  }

  private get dropdownMiddlewares() {
    return [flipMiddleware({ fallbackAxisSideDirection: 'none' })]
  }

  private get shouldSkipFiltering() {
    return (this.filterValue ?? '').length === 0 ||
      this.isCustomFilter ||
      this.filterValue === this.selectedItemByValue?.[this.itemLabel]
  }

  private get filteredItems() {
    if (this.shouldSkipFiltering) return this.items

    const filterFn = this.filterCallback ?? this.defaultItemsFilter

    return filterFn(
      this.items,
      this.filterValue ?? '',
    )
  }

  private get dropdownItems() {
    return this.isFilterable ? this.filteredItems : this.items
  }

  private hasAvatarState = (item: IYCoreSelectListItem | undefined) => {
    if (!item) return false

    return Boolean(item.img || item.icon || item.initials)
  }

  private handleSlotBeforeChange = (e: Event) => {
    const target = e.target as HTMLSlotElement

    this.hasBeforeSlot = hasSlotContent(target)
  }

  private handleSlotAnnotationChange = (e: Event) => {
    const target = e.target as HTMLSlotElement

    this.hasAnnotationSlot = hasSlotContent(target)
  }

  private setFilterValue(label: string) {
    this.filterValue = label
  }

  private isValueEqualListItem(value: TYCoreSelectFieldItemValue): value is IYCoreSelectListItem {
    return isValueEqualListItem(
      value,
      this.isMapOptions,
    )
  }

  private findItemByValue(value: IYCoreSelectListItem[TItemValue]): IYCoreSelectListItem | undefined {
    return this.items.find((item) => item[this.itemValue] === value)
  }

  private isItemSelected(item: IYCoreSelectListItem): boolean {
    if (!this.selectedItemByValue) return false


    return this.selectedItemByValue[this.itemValue] === item[this.itemValue]
  }

  private getValueFromItem = (item: IYCoreSelectListItem): IYCoreSelectFieldExternalProps['value'] => {
    this.changeDropdownVisible(false)

    const value = this.isMapOptions ? item[this.itemValue] : item

    return value as IYCoreSelectFieldExternalProps['value']
  }

  private handleSelect = (item: IYCoreSelectListItem) => (event: Event) => {
    if (this.computedDisabledOrReadonly || !event.currentTarget) return

    event.stopPropagation()

    const value = this.getValueFromItem(item)

    this.value = value
    this._select({ detail: { value, item, event } })
    this.changeDropdownVisible(false)
  }

  private tryScrollToCenter = (element: HTMLElement) => {
    if (!this.isOpened || !this.dropdownListContainer) return
    // Скроллим список элементов, чтоб выбранный элемент отображался по центру списка
    const listContainer = this.dropdownListContainer

    const relativeTop = element.getBoundingClientRect().top - listContainer.getBoundingClientRect().top
    const maxScroll = listContainer.scrollHeight - listContainer.clientHeight
    const desiredScroll = relativeTop + listContainer.scrollTop - listContainer.clientHeight / 2 + element.clientHeight / 2

    listContainer.scrollTop = Math.max(0, Math.min(maxScroll, Math.round(desiredScroll)))
  }

  private scrollVirtualizerToIndex = async(index: number, position: 'nearest' | 'start' = 'nearest'): Promise<void> => {
    const virtualizer = this._virtualizer
    if (!virtualizer || index < 0 || index >= this.dropdownItems.length) return

    await this.getUpdatesPromise()
    virtualizer.element(index)?.scrollIntoView({ block: position })
  }

  private async scrollSelectedItemElementIntoView() {
    await this.updateComplete // Ждём рендер Lit

    // Ищем в shadowRoot, так как элементы рендерятся там
    const selectedItemElement = this.shadowRoot?.querySelector<HTMLElement>('[data-selected="true"]')

    if (!selectedItemElement) return

    requestAnimationFrame(() => { this.tryScrollToCenter(selectedItemElement) })
  }

  private async scrollToSelectedItem() {
    if (!this.selectedItemByValue) return

    const selectedIndex = this.getSelectedIndex(this.dropdownItems)
    if (this.useVirtualScroll) {
      await this.scrollVirtualizerToIndex(selectedIndex, 'nearest')
      return
    }

    await this.scrollSelectedItemElementIntoView()
  }

  private changeDropdownVisible = (value: boolean) => {
    if (!this.canToggleDropdown) return

    this.focusedIndex = null

    if (this.isFilterable && value) {
      this.setFilterValue('')
    }

    this.isOpened = value

    if (this.isOpened) {
      this.handleDropdownOpened()
      return
    }

    this.resetVirtualizerHeight()
    this.handleDropdownClosed()
  }

  private handleNavigationKeyDown = (event: KeyboardEvent) => {
    // Дропдаун могли закрыть в обход changeDropdownVisible (например, click-outside) —
    // в этом случае снимаем слушатель и не блокируем ввод на странице
    if (!this.isOpened) {
      this.removeNavigationKeyDownListener()
      return
    }

    if (!isHandledKey(event.key)) return

    event.preventDefault()
    this.handleNavigationKey(event.key)
  }

  private handleNavigationKey = (key: THandledKey) => {
    if (key === HANDLED_KEYS.ARROW_DOWN) {
      this.handleArrowNext()
      return
    }

    if (key === HANDLED_KEYS.ARROW_UP) {
      this.handleArrowPrev()
      return
    }

    if (key === HANDLED_KEYS.ENTER || key === HANDLED_KEYS.SPACE) {
      this.handleSelectFocusedItem()
      return
    }

    this.changeDropdownVisible(false)
  }

  private handleDropdownOpened() {
    if (!this.fieldInput?.inputElement) return

    window.addEventListener('keydown', this.handleNavigationKeyDown, { capture: true })
    this.handleDropdownOpenedAsync()
  }

  private async handleDropdownOpenedAsync() {
    if (this.useVirtualScroll) {
      await this.syncVirtualizerHeight()
    }

    await this.scrollToSelectedItem()
  }

  private removeNavigationKeyDownListener = () => {
    window.removeEventListener('keydown', this.handleNavigationKeyDown, { capture: true })
  }

  private handleDropdownClosed() {
    this.removeNavigationKeyDownListener()

    if (!this.fieldInput?.inputElement) return

    this.fieldInput.inputElement.blur()
  }

  private handleBlur = (event: BlurEvent) => {
    if (this.computedDisabledOrReadonly) return

    this.changeDropdownVisible(false)

    this._blur({ detail: { event } })
  }

  private handleLabelClick = () => {
    this.fieldInput?.inputElement?.focus()
  }

  private handleFocus = (event: FocusEvent) => {
    if (this.computedDisabledOrReadonly) return

    this.lastFocusTime = event.timeStamp
    this.changeDropdownVisible(true)

    this._focus({ detail: { event } })
  }

  private handleClick = (event: Event) => {
    if (this.computedDisabledOrReadonly) return
    // Если дропдаун только что открылся по фокусу, не закрываем его.
    const diffTimeBetweenFocusAndClick = event.timeStamp - this.lastFocusTime
    if (this.isOpened && diffTimeBetweenFocusAndClick < 150) return

    this.changeDropdownVisible(!this.isOpened)
  }

  private handleInput = (event: InputEvent) => {
    event.stopPropagation()

    if (this.disabled || this.readonly) return

    if (!this.isCustomFilter) {
      this.setFilterValue(event.detail.value)
      return
    }

    this._input({ detail: { value: event.detail.value, event } })
  }

  private handleClickOutside = (event: VisibleEvent) => {
    event.stopPropagation()

    if (this.computedDisabledOrReadonly) return

    // Если дропдаун только что открылся по фокусу, не закрываем его
    const diffTimeBetweenFocusAndClick = event.timeStamp - this.lastFocusTime
    if (this.isOpened && diffTimeBetweenFocusAndClick < 150) return

    this.changeDropdownVisible(event.detail.value)
  }

  private handleDropdownMouseDown = (event: MouseEvent) => {
    event.preventDefault()
  }


  private defaultItemsFilter = (items: IYCoreSelectListItem[], value: string) => {
    return items.filter((item) => String(item[this.itemLabel])
      .toLowerCase()
      .includes(value.toLowerCase()))
  }

  private getSelectedIndex(items: IYCoreSelectListItem[]) {
    if (!this.selectedItemByValue) return 0

    const selectedIndex = items.findIndex((item) => this.isItemSelected(item))

    return selectedIndex === -1 ? 0 : selectedIndex
  }

  private getDropdownItemElementByIndex(index: number): HTMLElement | null {
    if (index < 0 || index >= this.dropdownItems.length) return null

    return this.shadowRoot?.querySelector<HTMLElement>(`${YCoreDropdownCellTagName}[data-item-index="${index}"]`) ?? null
  }

  private getNextFocusedIndex(step: 1 | -1) {
    const nextIndex = this.focusedIndex === null ? this.getSelectedIndex(this.dropdownItems) : this.focusedIndex + step

    if (nextIndex < 0 || nextIndex >= this.dropdownItems.length) return null

    return nextIndex
  }

  private scrollItemIntoViewByIndex(index: number) {
    if (this.useVirtualScroll) {
      this.scrollVirtualizerToIndex(index, 'nearest')
      return
    }

    const element = this.getDropdownItemElementByIndex(index)
    if (element) {
      this.tryScrollToCenter(element)
    }
  }

  private moveFocusedIndex(step: 1 | -1) {
    const nextIndex = this.getNextFocusedIndex(step)
    if (nextIndex === null) return

    this.focusedIndex = nextIndex
    this.scrollItemIntoViewByIndex(nextIndex)
  }

  private handleArrowNext = () => {
    this.moveFocusedIndex(1)
  }

  private handleArrowPrev = () => {
    this.moveFocusedIndex(-1)
  }

  private handleSelectFocusedItem = () => {
    if (this.focusedIndex === null) return

    const item = this.dropdownItems[this.focusedIndex]

    const value = this.getValueFromItem(item)

    this.value = value
    this._select({ detail: { value, item, event: new Event('click') } })
    this.changeDropdownVisible(false)
  }

  public focus(): void {
    this.fieldInput?.focus()
  }

  public blur(): void {
    this.fieldInput?.blur()
  }

  connectedCallback() {
    super.connectedCallback()

    this.dataset.locator = this.locator ?? tagName
    this.dataset[YC_COMPONENT_ATTRIBUTE_NAME] = ''

    if (!this.value || !this.selectedItemByValue) return

    this.filterValue = String(this.selectedItemByValue[this.itemLabel])
  }

  disconnectedCallback() {
    super.disconnectedCallback()

    this.removeNavigationKeyDownListener()
  }

  protected updated(changedProperties: PropertyValues<this>): void {
    if (!this.isOpened || !this.useVirtualScroll) return

    const shouldSyncHeight = changedProperties.has('items') ||
      changedProperties.has('filterValue') ||
      changedProperties.has('size')

    if (shouldSyncHeight) {
      this.syncVirtualizerHeight()
    }
  }

  protected renderFieldAvatar(item: IYCoreSelectListItem | undefined) {
    if (!this.hasAvatarState(item)) return nothing

    return html`
      <y-core-field-avatar
        .photo=${item?.img}
        .icon=${item?.icon}
        .initials=${item?.initials}
      ></y-core-field-avatar>
    `
  }

  protected renderItemAvatar(item: IYCoreSelectListItem) {
    return html`
      <y-core-avatar
        .photo=${item.img}
        .icon=${item.icon}
        .initials=${item.initials}
        size="32px"
      ></y-core-avatar>
    `
  }

  protected renderPrependContent(item: IYCoreSelectListItem) {
    if (!this.hasAvatarState(item)) return nothing

    return html`
      <div slot="prepend" class=${`${this.baseDropdownListItemClass}__prepend`}>
        ${this.renderItemAvatar(item)}
      </div>
    `
  }

  protected renderAppendContent(item: IYCoreSelectListItem) {
    if (!this.isItemSelected(item)) return nothing

    return html`
      <div slot="append" class=${`${this.baseDropdownListItemClass}__append`}>
        ${renderIcon({ icon: yCheck, size: '16px' })}
      </div>
    `
  }

  protected renderDropdownList() {
    const renderListItem = (item: IYCoreSelectListItem, index: number) => {
      return html`
        <y-core-dropdown-cell
          locator=${`${YCoreDropdownCellTagName}_${item.id}`}
          data-item-index=${index}
          data-selected=${this.isItemSelected(item)}
          .focused=${this.focusedIndex === index}
          style=${styleMap(this.computedDropdownCellStyles)}
          @click=${this.handleSelect(item)}
          class=${this.baseDropdownListItemClass}
        >
          ${this.renderPrependContent(item)}

          <div slot="content" class=${`${this.baseDropdownListItemClass}__content`}>
            <div slot="label" class=${classMap({
              [`${this.baseDropdownListItemClass}__label`]: true,
              [`${this.baseDropdownListItemClass}__label_single-line`]: Boolean(this.useVirtualScroll),
            })} title=${String(item[this.itemLabel])}>
              ${item[this.itemLabel]}
            </div>
          </div>

          ${this.renderAppendContent(item)}
        </y-core-dropdown-cell>
      `
    }

    if (this.useVirtualScroll) {
      return html`
        <lit-virtualizer
          scroller
          class=${this.baseVirtualizerClass}
          style=${styleMap(this.computedVirtualizerStyles)}
          .items=${this.dropdownItems}
          .renderItem=${renderListItem as RenderItemFunction}
        ></lit-virtualizer>
      `
    }

    return repeat(this.dropdownItems, (item) => item.id, renderListItem)
  }

  protected renderDropdownActivator() {
    return html`
      <y-core-field-wrapper
        .disabled=${this.disabled}
        .readonly=${this.readonly}
        .error=${Boolean(this.errors?.length) || this.error}
        .size=${this.size}
        clickable
        @click=${this.handleClick}
      >
        <slot
          name="before"
          @slotchange=${this.handleSlotBeforeChange}
        ></slot>
        ${this.renderFieldAvatar(this.selectedItemByValue)}
        <y-core-field-input
          .value=${this.inputValue}
          .name=${this.name}
          .placeholder=${this.placeholder}
          .required=${this.required}
          .readonly=${!this.isFilterable}
          .autofocus=${this.autofocus}
          .hideSpaceLeft=${this.hasAvatarState(this.selectedItemByValue) || this.hasBeforeSlot}
          .hideSpaceRight=${!this.readonly}
          .maskOptions=${this.maskOptions}
          .ellipsis=${this.ellipsis}
          class=${classMapToString(this.computedInputClasses)}
          @input=${this.handleInput}
          @focus=${this.handleFocus}
          @blur=${this.handleBlur}
        ></y-core-field-input>
        ${!this.readonly
          ? html`
            <y-core-field-icon
              .icon=${yChevronDown}
              hoverable
              class=${classMap(this.computedArrowIconClasses)}
            ></y-core-field-icon>
          `
          : nothing
        }
      </y-core-field-wrapper>
    `
  }

  protected renderDropdownContent() {
    return html`
      <y-core-dropdown-list
        tabindex="-1"
        class=${this.baseDropdownListClass}
        @mousedown=${this.handleDropdownMouseDown}
      >
        <!-- Этот слот недоступен при виртуализации -->
        ${html`
          <slot name="dropdown-list-top" slot="top">
          </slot>
        `}

        <div class=${this.baseDropdownListItemsClass} slot="list">
          <slot name="list">
            ${this.renderDropdownList()}
          </slot>
        </div>

        <!-- Этот слот недоступен при виртуализации -->
        ${html`
          <slot name="dropdown-list-bottom" slot="bottom">
          </slot>
        `}
      </y-core-dropdown-list>`
  }

  protected render() {
    return html`
      <div class=${classMap(this.computedClasses)}>
        ${renderLabel({
          text: this.labelText,
          tooltipText: this.labelTooltipText,
          debounce: this.labelDebounce,
          tooltipActive: !this.disabled,
          required: this.required,
          disabled: this.disabled,
          tooltipPlacement: this.labelTooltipPlacement,
          handleClick: this.handleLabelClick,
          className: classMapToString(this.computedLabelClasses),
        })}
        <y-core-dropdown
          .isOpen=${this.isDropdownOpened}
          .placement=${EYCoreDropdownPlacement.BOTTOM}
          .trigger=${EYCoreDropdownTrigger.MANUAL}
          .middlewares=${this.dropdownMiddlewares}
          strict-width
          @click-outside=${this.handleClickOutside}
        >
          <div slot="activator" class=${classMap(this.computedActivatorClasses)}>
              ${this.renderDropdownActivator()}
          </div>

          ${this.isDropdownOpened
            ? html`
              <div slot="content" class=${this.baseDropdownContentClass}>
                ${this.renderDropdownContent()}
              </div>
            `
            : nothing}
        </y-core-dropdown>
        ${renderAnnotation({
          text: this.annotationText,
          disabled: this.disabled,
          className: classMapToString(this.computedAnnotationClasses),
          handleSlotAnnotationChange: this.handleSlotAnnotationChange,
        })}
        ${renderError({ errors: this.errors })}
      </div>
    `
  }
}
