import dayjs, { type Dayjs } from 'dayjs'
import customParseFormat from 'dayjs/plugin/customParseFormat'
import isToday from 'dayjs/plugin/isToday'
import isBetween from 'dayjs/plugin/isBetween'
import weekday from 'dayjs/plugin/weekday'
import locale from 'dayjs/locale/ru'
import isSameOrBefore from 'dayjs/plugin/isSameOrBefore'
import isSameOrAfter from 'dayjs/plugin/isSameOrAfter'

dayjs.extend(customParseFormat)
dayjs.extend(isToday)
dayjs.extend(isBetween)
dayjs.extend(customParseFormat)
dayjs.extend(weekday)
dayjs.locale(locale)
dayjs.extend(isSameOrBefore)
dayjs.extend(isSameOrAfter)

export const FORMAT_YEAR = 'YYYY'
export const FORMAT_MONTH = 'MMMM'
export const FORMAT_WEEKDAY_SHORT = 'dd'
export const FORMAT_DATE_DMY = 'DD.MM.YYYY'
export const FORMAT_DATE = 'YYYY-MM-DD'
export const FORMAT_MONTH_YEAR = 'MM.YYYY'
export const FORMAT_DATE_DM = 'DD.MM'
// Формат даты без года по умолчанию: месяц-день, big-endian ("MM-DD", напр. "07-20")
export const FORMAT_DATE_MD = 'MM-DD'

// Високосный опорный год для дат без года: позволяет представить 29 февраля
export const LEAP_REFERENCE_YEAR = 2000

export const getDefaultMinDate = () => dayjs('01.01.1900', FORMAT_DATE_DMY)
export const getDefaultMaxDate = () => dayjs().add(1, 'year').endOf('year')

export const parseDate = (date?: string | Date | Dayjs, format: string | string[] = [FORMAT_DATE_DMY, FORMAT_DATE]): Dayjs => {
  if (!date) return dayjs()

  return typeof date === 'string' ? dayjs(date, format) : dayjs(date)
}

export function formatDate(date: string | Date | Dayjs, format = FORMAT_DATE): string {
  return dayjs.isDayjs(date)
    ? date.format(format)
    : dayjs(date).format(format)
}

/**
 * Проверяет, что строка — корректная дата без года в формате `format` (по умолчанию "MM-DD"):
 * строка должна полностью разбираться этим форматом, напр. "07-20". Полные даты
 * ("20.07.1999", "1999-07-20") и мусор → false.
 * @param value проверяемая строка
 * @param format формат даты без года (dayjs); по умолчанию FORMAT_DATE_MD ("MM-DD")
 * @returns true, если строка — дата без года в заданном формате
 */
export const isDateWithoutYear = (value: string, format: string = FORMAT_DATE_MD): boolean => parseDateWithoutYear(value, format).isValid()

/**
 * Парсит дату без года, подставляя опорный (високосный) год.
 *
 * Порядок и разделитель заданы параметром `format` (по умолчанию "MM-DD").
 * Чтобы корректно представить 29 февраля, опорный год подставляется ещё на этапе разбора:
 * и значение, и формат дополняются годом, поэтому Feb 29 не «уезжает» в невисокосный год.
 *
 * @param value дата без года, например "07-20" (MM-DD) или "20.07" при format="DD.MM"
 * @param format формат входной строки (dayjs); по умолчанию FORMAT_DATE_MD ("MM-DD")
 * @param year опорный год; по умолчанию високосный (LEAP_REFERENCE_YEAR)
 * @returns объект Dayjs (Invalid Date, если value не соответствует format)
 */
export const parseDateWithoutYear = (
  value: string,
  format: string = FORMAT_DATE_MD,
  year: number = LEAP_REFERENCE_YEAR,
): Dayjs => {
  return dayjs(`${value} ${year}`, `${format} ${FORMAT_YEAR}`, true)
}
