import { DELAY_BEFORE_SHOW, MIN_SHOW_TIME } from './models/constants'
import type { ILoader, ILoaderOptions, ILoaderState } from './models/types'
import { EYCoreLoaderVariant } from './models/types'
import { EYSizes } from '~shared/types/global'

import GlobalLoaderOverlayVarsCss from './css/GlobalLoaderOverlay.vars.css?inline'
import GlobalLoaderOverlayScopedCss from './css/GlobalLoaderOverlay.scoped.css?inline'

/**
 * GlobalLoader - класс для управления глобальным overlay лоадером
 *
 * Ответственность:
 * 1. Создание/удаление overlay элемента в DOM
 * 2. Управление таймингами 300ms/500ms на уровне mount/unmount
 * 3. Гарантия единственного экземпляра
 *
 * @example
 * const proxy = LoaderProxy.getInstance()
 * proxy.show() // referenceCount = 1, вызывает GlobalLoader.show()
 * proxy.show() // referenceCount = 2, НЕ вызывает GlobalLoader.show()
 * proxy.hide() // referenceCount = 1, НЕ вызывает GlobalLoader.hide()
 * proxy.hide() // referenceCount = 0, вызывает GlobalLoader.hide()
 *
 * @internal Не используется напрямую
 */
export class GlobalLoader implements Required<ILoader> {
  private static instance: GlobalLoader | null = null
  private static stylesInjected = false

  private overlayElement: HTMLElement | null = null
  private loaderElement: HTMLElement | null = null

  private showTimer: ReturnType<typeof setTimeout> | null = null
  private hideTimer: ReturnType<typeof setTimeout> | null = null
  private shownAt: number | null = null

  private state: ILoaderState = {
    isMounted: false,
    isVisible: false,
  }

  private options: Required<Pick<ILoaderOptions, 'size' | 'variant'>> = {
    size: EYSizes.MEDIUM,
    variant: EYCoreLoaderVariant.PRIMARY,
  }

  private constructor() {
    this.injectStyles()
  }

  /**
   * Внедряет стили overlay в head
   * @private
   */
  private injectStyles(): void {
    if (GlobalLoader.stylesInjected) return

    const varsCss = GlobalLoaderOverlayVarsCss
    const scopedCss = GlobalLoaderOverlayScopedCss

    const styleElement = document.createElement('style')
    styleElement.textContent = `${varsCss}\n${scopedCss}`
    document.head.appendChild(styleElement)

    GlobalLoader.stylesInjected = true
  }

  /**
   * Получить единственный экземпляр GlobalLoader
   */
  static getInstance(): GlobalLoader {
    if (!GlobalLoader.instance) {
      GlobalLoader.instance = new GlobalLoader()
    }
    return GlobalLoader.instance
  }

  /**
   * Обновляет опции лоадера (size, variant)
   * @private
   */
  private updateOptions(options?: ILoaderOptions): void {
    if (!options) return

    if (options.size) this.options.size = options.size
    if (options.variant) this.options.variant = options.variant
  }

  /**
   * Проверяет, виден ли уже лоадер
   * @private
   */
  private isAlreadyVisible(): boolean {
    return this.state.isMounted && this.state.isVisible
  }

  /**
   * Запускает задержку перед показом лоадера
   * @private
   */
  private scheduleShow(): void {
    this.showTimer = setTimeout(() => {
      // Монтируем overlay, если не смонтирован
      if (!this.state.isMounted) {
        this.mountOverlay()
        this.state.isMounted = true
      }

      this.setLoaderVisible(true)
      this.state.isVisible = true
      this.shownAt = Date.now()
      this.showTimer = null
    }, DELAY_BEFORE_SHOW)
  }

  /**
   * Показать глобальный лоадер
   *
   * Логика:
   * 1. Обновляет опции (size, variant)
   * 2. Ждет DELAY_BEFORE_SHOW (300ms) перед монтированием overlay
   * 3. Монтирует overlay, если не смонтирован
   * 4. Показывает лоадер (is-visible=true)
   *
   * Правило 300ms: overlay не появляется для быстрых запросов (< 300ms)
   *
   *
   * @param options - опции лоадера (size, variant, и т.д.)
   */
  show(options?: ILoaderOptions): void {
    this.updateOptions(options)

    // Если уже видим — отменяем скрытие (show во время hideTimer)
    if (this.isAlreadyVisible()) {
      if (this.hideTimer) {
        clearTimeout(this.hideTimer)
        this.hideTimer = null
      }
      return
    }

    // Если таймер показа уже запущен — не перезапускаем
    if (this.showTimer) return

    // Запускаем задержку DELAY_BEFORE_SHOW (300ms)
    this.scheduleShow()
  }

  /**
   * Скрыть глобальный лоадер
   *
   * Логика:
   * 1. Если show таймер активен - отменяет (быстрый запрос)
   * 2. Если loader виден - соблюдает MIN_SHOW_TIME (500ms)
   * 3. Демонтирует overlay после завершения
   *
   * Правило 500ms: loader виден минимум 500ms после появления
   */
  hide(): void {
    // 1. Если show таймер активен - отменяем (быстрый запрос < 300ms)
    if (this.showTimer) {
      clearTimeout(this.showTimer)
      this.showTimer = null
      return
    }

    // 2. Если лоадер виден - соблюдаем MIN_SHOW_TIME (500ms)
    if (this.state.isVisible && this.shownAt) {
      const elapsed = Date.now() - this.shownAt
      const remaining = Math.max(MIN_SHOW_TIME - elapsed, 0)

      if (this.hideTimer) clearTimeout(this.hideTimer)

      this.hideTimer = setTimeout(() => {
        // Скрываем лоадер
        this.setLoaderVisible(false)
        this.state.isVisible = false
        this.shownAt = null

        // Демонтируем overlay
        this.unmountOverlay()
        this.state.isMounted = false

        this.hideTimer = null
        this.cleanup()
      }, remaining)

      return
    }

    // 3. Если не показан - сразу очищаем
    this.state.isVisible = false
    this.shownAt = null
    this.cleanup()
  }

  /**
   * Уничтожить GlobalLoader и очистить все ресурсы
   */
  destroy(): void {
    this.cleanup()
    this.unmountOverlay()
    this.state = {
      isMounted: false,
      isVisible: false,
    }
    GlobalLoader.instance = null
  }

  /**
   * Монтирует overlay контейнер в DOM
   * @private
   */
  private mountOverlay(): void {
    // Создаем overlay контейнер
    this.overlayElement = document.createElement('div')
    this.overlayElement.className = 'y-global-loader-overlay'
    this.overlayElement.setAttribute('data-testid', 'global-loader-overlay')

    this.loaderElement = document.createElement('y-core-loader')
    this.loaderElement.setAttribute('size', this.options.size)
    this.loaderElement.setAttribute('variant', this.options.variant)
    this.loaderElement.setAttribute('is-visible', 'false')

    this.overlayElement.appendChild(this.loaderElement)
    document.body.appendChild(this.overlayElement)
  }

  /**
   * Демонтирует overlay из DOM
   * @private
   */
  private unmountOverlay(): void {
    if (this.overlayElement?.parentNode) {
      this.overlayElement.parentNode.removeChild(this.overlayElement)
    }
    this.overlayElement = null
    this.loaderElement = null
  }

  /**
   * Устанавливает видимость loader
   * @private
   */
  private setLoaderVisible(visible: boolean): void {
    if (this.loaderElement) {
      this.loaderElement.setAttribute('is-visible', String(visible))
    }
  }

  /**
   * Очищает таймеры
   * @private
   */
  private cleanup(): void {
    if (this.showTimer) {
      clearTimeout(this.showTimer)
      this.showTimer = null
    }
    if (this.hideTimer) {
      clearTimeout(this.hideTimer)
      this.hideTimer = null
    }
  }
}
