import type { TEventsStoryArgs } from '~core/utils/helpers-utility-types'

export type TCardBasicClickZone = 'card' | 'right-slot'

/**
 * Событие удаления карточки
 */
export class RemoveEvent extends CustomEvent<{ event: Event }> {}

/**
 * Событие клика по карточке
 */
export class CardBasicClickEvent extends CustomEvent<{ event: Event; zone: TCardBasicClickZone }> {}

export type TYCoreCardBasicEvents = TEventsStoryArgs<{
  RemoveEvent: typeof RemoveEvent
  CardBasicClickEvent: typeof CardBasicClickEvent
}>
