import { css, html, LitElement, nothing, unsafeCSS } from 'lit'
import { customElement, property, state } from 'lit/decorators.js'
import { ifDefined } from 'lit/directives/if-defined.js'
import { classMap } from 'lit/directives/class-map.js'

import { booleanConverter } from '~core/utils/converters'

import YCoreLinkScopedCSS from '~core/ui/link/css/Link.scoped.css?inline'
import YCoreLinkVarsCSS from '~core/ui/link/css/Link.vars.css?inline'

import { YCoreLinkTagName as tagName } from '~shared/constants'
import { YC_COMPONENT_ATTRIBUTE_NAME } from '~web/shared/constants/attributes'
import { createCoreLinkProps, type IYCoreLinkProps } from '~core/ui/link/models/types'
import '~core/ui/icon'
import '~core/ui/text'
import { renderIcon } from '~core/renderers'

const { href, target, icon, text, size, textWrap } = createCoreLinkProps()

@customElement(tagName)
export class YCoreLink extends LitElement implements Required<IYCoreLinkProps> {
  @property({ type: String }) href: IYCoreLinkProps['href'] = href
  @property({ type: String }) target: IYCoreLinkProps['target'] = target
  @property({ type: Object }) icon: IYCoreLinkProps['icon'] = icon
  @property({ type: String }) text: IYCoreLinkProps['text'] = text
  @property({ type: String }) size: IYCoreLinkProps['size'] = size
  @property({ type: Boolean, converter: booleanConverter, attribute: 'text-wrap' }) textWrap: IYCoreLinkProps['textWrap'] = textWrap
  @state() private hasDefaultSlotContent = false

  private readonly baseClass = tagName

  static readonly styles = [
    css`${unsafeCSS(YCoreLinkVarsCSS)}`,
    css`${unsafeCSS(YCoreLinkScopedCSS)}`,
  ]

  private get computedClasses() {
    return {
      [this.baseClass]: true,
      [`${this.baseClass}_text-wrap`]: Boolean(this.textWrap),
    }
  }

  connectedCallback() {
    super.connectedCallback()

    this.dataset.locator = tagName
    this.dataset[YC_COMPONENT_ATTRIBUTE_NAME] = ''
  }

  protected firstUpdated() {
    const defaultSlotElement = this.renderRoot.querySelector<HTMLSlotElement>(`slot.${this.baseClass}__text-slot`)
    if (!defaultSlotElement) return

    this.updateDefaultSlotState(defaultSlotElement)
  }

  private updateDefaultSlotState(slotElement: HTMLSlotElement) {
    this.hasDefaultSlotContent = slotElement
      .assignedNodes({ flatten: true })
      .some((node) => {
        if (node.nodeType === Node.ELEMENT_NODE) return true

        return node.nodeType === Node.TEXT_NODE && Boolean(node.textContent?.trim())
      })
  }

  private onDefaultSlotChange = (event: Event) => {
    this.updateDefaultSlotState(event.target as HTMLSlotElement)
  }

  private renderTextContent() {
    const textFallback = this.text && !this.hasDefaultSlotContent
      ? html`<y-core-text class="${this.baseClass}__text-fallback" .size=${this.size}>${this.text}</y-core-text>`
      : nothing

    return html`<slot
      class="${this.baseClass}__text-slot"
      @slotchange=${this.onDefaultSlotChange}
    ></slot>${textFallback}`
  }

  protected render() {
    return html`
      <a
        class=${classMap(this.computedClasses)}
        href=${ifDefined(this.href)}
        target=${ifDefined(this.target)}
      >
        <slot name="left" class="${this.baseClass}__left">${renderIcon({ icon: this.icon, size: '16px', className: `${this.baseClass}__icon` })}</slot>${this.renderTextContent()}
      </a>
    `
  }
}
