import type { TEventsStoryArgs } from '~core/utils/helpers-utility-types'

/**
 * Событие получения фокуса выбором карточки
 */
export class FocusEvent extends CustomEvent<{ event: Event }> {}

/**
 * Событие потери фокуса выбором карточки
 */
export class BlurEvent extends CustomEvent<{ event: Event }> {}

/**
 * Событие клика по выбору карточки
 */
export class ClickEvent extends CustomEvent<{ event: Event }> {}

export type TYCoreCardSelectEvents = TEventsStoryArgs<{
  FocusEvent: typeof FocusEvent
  BlurEvent: typeof BlurEvent
  ClickEvent: typeof ClickEvent
}>
