import { html } from 'lit'
import { EYCoreTextSize, EYCoreTextVariant } from '~core/ui/text/models/types'
import type { OverflowChangeEvent } from '~core/ui/text/models/types/events'

import '~core/ui/text'

interface IRenderContentOptions {
  baseClass: string
  label?: string
  annotation?: string
  isAnnotationHidden?: boolean
  onLabelOverflowChange: (event: OverflowChangeEvent) => void
  onAnnotationSlotChange: (event: Event) => void
}

export const renderContent = ({
  baseClass,
  label,
  annotation,
  isAnnotationHidden,
  onLabelOverflowChange,
  onAnnotationSlotChange,
}: IRenderContentOptions) => {
  return html`
    <div class=${`${baseClass}__content`}>
      <y-core-text
        size=${EYCoreTextSize.A1_MEDIUM}
        ellipsis
        lineclamp="2"
        track-overflow
        class="${baseClass}__label"
        @overflow-change=${onLabelOverflowChange}
      >
        <slot name="label">
          ${label}
        </slot>
      </y-core-text>

      <y-core-text
        size=${EYCoreTextSize.A3_MEDIUM}
        variant=${EYCoreTextVariant.SECONDARY}
        ellipsis
        ?hidden=${isAnnotationHidden}
        class="${baseClass}__annotation"
      >
        <slot
          name="annotation"
          @slotchange=${onAnnotationSlotChange}
        >
          ${annotation}
        </slot>
      </y-core-text>
    </div>
    `
}
