import { capitalize } from 'radash'
import { type Dayjs } from 'dayjs'

import { parseDate, FORMAT_MONTH, FORMAT_WEEKDAY_SHORT, getDefaultMaxDate, getDefaultMinDate } from '~shared/utils/dateTime'
import type { IDropdownListItem } from '~shared/types/global'

export interface IWeekDayData {
  date: Dayjs
  dayNumber: number
  isCurrentMonth: boolean
}

export interface IMonthDayData {
  date: Dayjs
  dayNumber: number
  isCurrentMonth: boolean
}

export const enum EMonthDelta {
  PREV = -1,
  DEFAULT = 0,
  NEXT = 1,
}

/**
 * Идентификатор пункта «Год не указан» в селекторе годов (режим allowEmptyYear)
 */
export const NO_YEAR_ID = 'no-year'

export const getWeekDays = () => {
  return Array.from({ length: 7 }, (_, i) => parseDate().weekday(i)
    .format(FORMAT_WEEKDAY_SHORT))
}

export const getMonthList = (): IDropdownListItem[] => {
  return [...Array(12).keys()].map((key) => {
    return {
      id: key.toString(),
      label: capitalize(parseDate().month(key)
        .format(FORMAT_MONTH)),
    }
  })
}

/**
 * Получить список годов в заданном диапазоне
 * @param minDate Минимальная дата
 * @param maxDate Максимальная дата
 */
export const getYearsList = (minDate = '', maxDate = ''): IDropdownListItem[] => {
  const minYear = minDate ? parseDate(minDate).year() : getDefaultMinDate().year()
  const maxYear = maxDate ? parseDate(maxDate).year() : getDefaultMaxDate().year()

  return Array.from({ length: maxYear - minYear + 1 }, (_, i) => maxYear - i).map((year) => ({
    id: year.toString(),
    label: year,
  }))
}

/**
 * Получить дни недели для текущей даты
 * @param currentDate Текущая дата
 */
export const getWeekDaysList = (currentDate: Dayjs): IWeekDayData[] => {
  const startOfWeek = currentDate.startOf('week')
  return Array.from({ length: 7 }, (_, i) => {
    const day = startOfWeek.add(i, 'day')
    return {
      date: day,
      dayNumber: day.date(),
      isCurrentMonth: day.month() === currentDate.month(),
    }
  })
}

/**
 * Получить все дни месяца для отображения в календаре (включая дни предыдущего и следующего месяца)
 * @param currentDate Текущая дата
 */
export const getMonthDaysList = (currentDate: Dayjs): IMonthDayData[] => {
  const startOfMonth = currentDate.startOf('month')
  const endOfMonth = currentDate.endOf('month')

  const startDate = startOfMonth.startOf('week')
  const endDate = endOfMonth.endOf('week')

  const days: IMonthDayData[] = []
  let currentDay = startDate

  while (currentDay.isSameOrBefore(endDate, 'day')) {
    days.push({
      date: currentDay,
      dayNumber: currentDay.date(),
      isCurrentMonth: currentDay.month() === currentDate.month(),
    })
    currentDay = currentDay.add(1, 'day')
  }

  return days
}

/**
 * Получить все дни месяца (включая дни предыдущего и следующего месяца)
 * @param currentDate Текущая дата
 * @param monthDelta Смещение относительно текущего месяца
 *  -1 - вернет дни предыдущего месяца
 *  0 - вернет дни предыдущего, текущего, будущего месяца
 *  1 - вернет дни будущего месяца
 */
export const getCurrentPrevNextMonthDays = (currentDate: Dayjs, monthDelta: EMonthDelta = EMonthDelta.DEFAULT): Dayjs[] => {
  let startDate = currentDate.subtract(1, 'month').startOf('month')
  let endDate = currentDate.add(1, 'month').endOf('month')

  if (monthDelta === EMonthDelta.NEXT) {
    startDate = endDate.startOf('month')
  }

  if (monthDelta === EMonthDelta.PREV) {
    endDate = startDate.endOf('month')
  }


  const days: Dayjs[] = []
  let currentDay = startDate

  while (currentDay.isSameOrBefore(endDate, 'day')) {
    days.push(currentDay)

    currentDay = currentDay.add(1, 'day')
  }

  return days
}
