import { type TAnchorTarget } from '~shared/types/global'
import type { IYCoreIconExternalProps } from '~core/ui/icon/models/types'
import { createCoreTextExternalProps, type IYCoreTextExternalProps } from '~core/ui/text/models/types'

/**
 * Свойства компонента Link
 */
export interface IYCoreLinkExternalProps {

  /**
   * URL ссылки
   */
  href: string | undefined

  /**
   * Атрибут target для ссылки
   */
  target: TAnchorTarget | undefined

  /**
   * Иконка слева от текста
   */
  icon: IYCoreIconExternalProps['icon'] | undefined

  /**
   * Текст ссылки
   */
  text: string | undefined

  /**
   * Размер текста ссылки
   * @default 'p2-regular'
   */
  size: IYCoreTextExternalProps['size']

  /**
   * Перенос текста ссылки
   */
  textWrap: boolean | undefined
}

export const createCoreLinkExternalProps = (): IYCoreLinkExternalProps => {
  const { size } = createCoreTextExternalProps()

  return {
    href: undefined,
    target: undefined,
    icon: undefined,
    text: undefined,
    size,
    textWrap: undefined,
  }
}
