import type { TEventsStoryArgs } from '~core/utils/helpers-utility-types'
import type { IYCoreCalendarExternalProps } from './external'

/**
 * Событие выбора даты в календаре
 */
export interface IYCoreCalendarSelectEvent {

  /**
   * Выбранная дата или диапазон дат
   */
  value: IYCoreCalendarExternalProps['date']
}

/**
 * Событие начала выбора диапазона дат
 */
export interface IYCoreCalendarRangeStartEvent {

  /**
   * Начальная дата диапазона
   */
  value: Extract<IYCoreCalendarExternalProps['date'], string>
}

/**
 * Событие окончания выбора диапазона дат
 */
export interface IYCoreCalendarRangeEndEvent {

  /**
   * Конечная дата диапазона
   */
  value: Extract<IYCoreCalendarExternalProps['date'], string>
}

/**
 * Событие изменения режима отображения сетки календаря
 */
export interface IYCoreCalendarGridModeChangedEvent {

  /**
   * Новый режим отображения сетки
   */
  value: Extract<IYCoreCalendarExternalProps['gridMode'], string>
}

/**
 * Событие переключения года/месяца в календаре
 */
export interface IYCoreCalendarNavigationEvent {

  /**
   * Выбранный год/месяц в календаре.
   * year равен null в режиме без года (allowEmptyYear) — год не указан
   */
  value: {
    year: number | null
    month: number
  }
}

/**
 * Событие выбора даты в календаре
 */
export class SelectEvent extends CustomEvent<IYCoreCalendarSelectEvent> {}

/**
 * Событие начала выбора диапазона дат
 */
export class RangeStartEvent extends CustomEvent<IYCoreCalendarRangeStartEvent> {}

/**
 * Событие окончания выбора диапазона дат
 */
export class RangeEndEvent extends CustomEvent<IYCoreCalendarRangeEndEvent> {}

/**
 * Событие изменения режима отображения сетки календаря
 */
export class GridModeChangedEvent extends CustomEvent<IYCoreCalendarGridModeChangedEvent> {}

/**
 * Событие переключения года/месяца в календаре
 */
export class NavigationEvent extends CustomEvent<IYCoreCalendarNavigationEvent> {}

/**
 * Событие клика по недоступной дате в календаре
 */
export class ClickDisabledDateEvent extends CustomEvent<IYCoreCalendarSelectEvent> {}

export type TYCoreCalendarEvents = TEventsStoryArgs<{ SelectEvent: typeof SelectEvent; RangeStartEvent: typeof RangeStartEvent; RangeEndEvent: typeof RangeEndEvent; GridModeChangedEvent: typeof GridModeChangedEvent; ClickDisabledDateEvent: typeof ClickDisabledDateEvent; NavigationEvent: typeof NavigationEvent }>
