import {
  createCoreSimpleBannerProps,
  type IYCoreSimpleBannerProps,
} from '~core/ui/simpleBanner/models/types'

export enum EYCoreBannerVariant {
  INFORMATION = 'information',
  MARKETING = 'marketing',
  WARNING = 'warning',
  ERROR = 'error',
  NEUTRAL = 'neutral',
}

export type TYCoreBannerVariant = `${EYCoreBannerVariant}`

/**
 * Свойства компонента Banner
 */
export interface IYCoreBannerExternalProps extends Pick<IYCoreSimpleBannerProps, 'description' | 'primaryButtonText' | 'hideCloseIcon'> {

  /**
   * Вариант отображения баннера
   * @default 'information'
   */
  variant: TYCoreBannerVariant | undefined

  /**
   * Показать баннер
   * @default true
   */
  open: boolean | undefined
}

export const createCoreBannerExternalProps = (): IYCoreBannerExternalProps => {
  const { description, primaryButtonText } = createCoreSimpleBannerProps()

  return {
    description,
    primaryButtonText,
    variant: EYCoreBannerVariant.INFORMATION,
    open: true,
    hideCloseIcon: false,
  }
}
