/**
 * @module ToastsPlugin/ToastQueue
 * @description API для работы с очередью тостов. Реализует паттерн Facade.
 */

import type { IToastOptions, IToastHandle } from '~core/ui/globalProvider/context/modules/ToastQueueModule'
import type { IGlobalContext } from '~core/ui/globalProvider/context'
import type { IToastQueueModule } from '~core/ui/globalProvider/context'
import { EYCoreToastType } from '~core/ui/toast/models/types'
import { TOASTS_PLUGIN_INITIALIZATION_TIMEOUT } from '~core/ui/globalProvider/plugins/toasts/constants'

/**
 * Ошибка, выбрасываемая когда плагин тостов не установлен
 * @class ToastsPluginNotInstalledError
 * @extends Error
 */
export class ToastsPluginNotInstalledError extends Error {
  /** Создает экземпляр ошибки */
  constructor() {
    super('ToastsPlugin is not installed. Please add ToastsPlugin to GlobalProvider plugins.')
    this.name = 'ToastsPluginNotInstalledError'
  }
}

/**
 * API для работы с очередью тостов
 * Реализует паттерн Facade для удобного использования
 * @class ToastQueue
 */
export class ToastQueue {
  /** Глобальный контекст, устанавливается при инициализации */
  private context: IGlobalContext | null = null

  /** ID плагина тостов в контексте */
  private pluginId = 'toasts'

  /** Очередь колбэков, ожидающих инициализации модуля */
  private pendingCallbacks: ((module: IToastQueueModule) => void)[] = []

  /**
   * Инициализирует ToastQueue с контекстом и ID плагина
   * Вызывается автоматически при установке плагина
   * @param context - Глобальный контекст GlobalProvider
   * @param pluginId - Уникальный ID плагина тостов
   */
  initialize(context: IGlobalContext, pluginId: string): void {
    this.context = context
    this.pluginId = pluginId

    // Выполняем все ожидающие колбэки
    const module = this.getModule()
    if (module) {
      this.pendingCallbacks.forEach((callback) => { callback(module) })
      this.pendingCallbacks = []
    }
  }

  /**
   * Сбрасывает состояние ToastQueue
   * Вызывается при уничтожении плагина
   */
  reset(): void {
    this.context = null
    this.pendingCallbacks = []
  }

  /**
   * Получает модуль очереди тостов из контекста
   * @private
   * @returns Модуль очереди тостов или undefined, если контекст не инициализирован
   */
  private getModule(): IToastQueueModule | undefined {
    if (!this.context) {
      return undefined
    }
    return this.context.getModule(this.pluginId) as IToastQueueModule | undefined
  }

  /**
   * Выполняет действие с модулем, ожидая его установки если необходимо
   * Если модуль еще не установлен, ожидает его инициализации до таймаута (5 секунд)
   * @private
   * @template T - Тип возвращаемого значения
   * @param action - Функция для выполнения с модулем
   * @returns Promise с результатом выполнения действия
   * @throws {ToastsPluginNotInstalledError} Если модуль не установлен за 5 секунд
   */
  private async withModule<T>(action: (module: IToastQueueModule) => T): Promise<T> {
    const module = this.getModule()

    if (module) {
      return action(module)
    }

    // Если модуль не установлен, ждем его установки
    return new Promise((resolve, reject) => {
      const timeout = setTimeout(() => {
        const index = this.pendingCallbacks.indexOf(callback)
        if (index > -1) {
          this.pendingCallbacks.splice(index, 1)
        }
        reject(new ToastsPluginNotInstalledError())
      }, TOASTS_PLUGIN_INITIALIZATION_TIMEOUT) // Таймаут 5 секунд

      const callback = (mod: IToastQueueModule) => {
        clearTimeout(timeout)
        try {
          resolve(action(mod))
        } catch(error) {
          reject(error as Error)
        }
      }

      this.pendingCallbacks.push(callback)
    })
  }

  /**
   * Показывает тост с указанными опциями
   * @param options - Опции для отображения тоста (текст, вариант и т.д.)
   * Позиция и длительность задаются в конфигурации плагина
   * @returns Promise с handle тоста для программного управления
   */
  async notify(options: IToastOptions): Promise<IToastHandle> {
    return this.withModule((module) => module.notify(options))
  }

  /**
   * Показывает успешный тост
   * @param options - Опции для отображения тоста (без указания варианта)
   * @returns Promise с handle тоста для программного управления
   */
  async success(options: Omit<IToastOptions, 'variant'>): Promise<IToastHandle> {
    return this.notify({ ...options, variant: EYCoreToastType.SUCCESS })
  }

  /**
   * Показывает информационный тост
   * @param options - Опции для отображения тоста (без указания варианта)
   * @returns Promise с handle тоста для программного управления
   */
  async info(options: Omit<IToastOptions, 'variant'>): Promise<IToastHandle> {
    return this.notify({ ...options, variant: EYCoreToastType.INFO })
  }

  /**
   * Показывает предупреждающий тост
   * @param options - Опции для отображения тоста (без указания варианта)
   * @returns Promise с handle тоста для программного управления
   */
  async warning(options: Omit<IToastOptions, 'variant'>): Promise<IToastHandle> {
    return this.notify({ ...options, variant: EYCoreToastType.WARNING })
  }

  /**
   * Показывает тост с ошибкой
   * @param options - Опции для отображения тоста (без указания варианта)
   * @returns Promise с handle тоста для программного управления
   */
  async error(options: Omit<IToastOptions, 'variant'>): Promise<IToastHandle> {
    return this.notify({ ...options, variant: EYCoreToastType.ERROR })
  }

  /**
   * Очищает все активные тосты из очереди
   * @returns Promise, который разрешается после очистки всех тостов
   */
  async clearAll(): Promise<void> {
    return this.withModule((module) => { module.clearAll() })
  }
}
