import {
  createCoreTextFieldExternalProps,
  type IYCoreTextFieldExternalProps,
} from '~core/ui/textField/models/types'
import type { IYCoreFieldInputExposes } from '~core/ui/fieldInput/models/types'
import { omit } from 'radash'

export interface IYCoreCountFieldExternalProps extends Omit<IYCoreTextFieldExternalProps, 'clearable' | 'type' | 'maxlength' | 'maskOptions' | 'labelOverflowMode'> {
  min: number | undefined
  max: number | undefined
}

export const createCoreCountFieldExternalProps = (): IYCoreCountFieldExternalProps => ({
  ...omit(createCoreTextFieldExternalProps(), ['clearable', 'type', 'maxlength', 'labelOverflowMode']),
  min: undefined,
  max: undefined,
})

export interface IYCoreCountFieldExposes extends IYCoreFieldInputExposes {}
