import { html, nothing } from 'lit'
import { ifDefined } from 'lit/directives/if-defined.js'

import {
  createCoreLabelExternalProps,
  type IYCoreLabelProps,
} from '~core/ui/label/models/types'

import { EYCoreTextSize, EYCoreTextVariant } from '~core/ui/text/models/types/external'

import '~core/ui/label'

export interface IRenderLabelOptions extends Partial<IYCoreLabelProps> {
  className?: string
  handleClick?: (event: Event) => void
  handleMouseDown?: (event: Event) => void
}

/**
 * Опции для рендеринга лейбла
 * @interface IRenderLabelOptions
 */
export default ({ className, handleClick, handleMouseDown, ...props }: IRenderLabelOptions) => {
  if (!props.text) return nothing

  const labelProps = {
    ...createCoreLabelExternalProps(),
    ...props,
  }

  return html`
    <y-core-label
      .text=${labelProps.text}
      .tooltipText=${labelProps.tooltipText}
      .debounce=${labelProps.debounce}
      .size=${labelProps.size || EYCoreTextSize.A2_REGULAR}
      .variant=${labelProps.variant || EYCoreTextVariant.SECONDARY}
      .tooltipActive=${labelProps.tooltipActive}
      .required=${labelProps.required}
      .disabled=${labelProps.disabled}
      .tooltipPlacement=${labelProps.tooltipPlacement}
      .locator=${labelProps.locator}
      .overflowMode=${labelProps.overflowMode}
      class=${ifDefined(className)}
      @click=${handleClick}
      @mousedown=${handleMouseDown}
    >
      <slot slot="tooltip-content" name="tooltip-content"></slot>
    </y-core-label>
  `
}
