import { LitElement, html, css, unsafeCSS, nothing } from 'lit'
import { provide } from '@lit/context'
import { customElement, property, state } from 'lit/decorators.js'
import { classMap } from 'lit/directives/class-map.js'

import { YCoreCardBasicTagName as tagName } from '~shared/constants'
import { YC_COMPONENT_ATTRIBUTE_NAME } from '~web/shared/constants/attributes'
import { preventAndStopEvent } from '~shared/utils/helpers'
import { renderIcon } from '~core/renderers'
import { EYSizes } from '~shared/types/global'
import { hasSlotContent } from '~core/utils/lit-slots'
import { bubblingEvent, type TDispatcher } from '~core/utils/event-decorator'
import { EYCoreTextSize, EYCoreTextVariant, type TYCoreTextSize } from '~core/ui/text/models/types'

import { createCoreCardBasicProps, EYCoreCardBasicIconSize, RemoveEvent, CardBasicClickEvent, type IYCoreCardBasicProps } from '~core/ui/cardBasic/models/types'

import YCardBasicVarsCss from '~core/ui/cardBasic/css/CardBasic.vars.css?inline'
import YCardBasicScopedCss from '~core/ui/cardBasic/css/CardBasic.scoped.css?inline'

import { yBigChevronRight, yClose } from '~shared/icons'

import '~core/ui/text'
import '~core/ui/iconButton'

import { sizeContextCreated } from '~core/ui/cardWrapper/providers'

const { titleSize, titleText, annotationText, subheadText, size, chevron, removable, padding, alignment, hoverable, selected } = createCoreCardBasicProps()

const mapChevronIconSize: Record<NonNullable<IYCoreCardBasicProps['chevron']>, string> = {
  [EYSizes.SMALL]: EYCoreCardBasicIconSize.SMALL,
  [EYSizes.LARGE]: EYCoreCardBasicIconSize.LARGE,
}

const mapTitleTextSize: Record<NonNullable<IYCoreCardBasicProps['titleSize']>, TYCoreTextSize> = {
  small: EYCoreTextSize.P2_REGULAR,
  default: EYCoreTextSize.P0_REGULAR,
}

const mapAnnotationTextSize: Record<NonNullable<IYCoreCardBasicProps['titleSize']>, TYCoreTextSize> = {
  small: EYCoreTextSize.A2_REGULAR,
  default: EYCoreTextSize.P2_REGULAR,
}

@customElement(tagName)
export class YCoreCardBasic
  extends LitElement
  implements Required<IYCoreCardBasicProps> {
  @property({ type: String, reflect: true }) padding: IYCoreCardBasicProps['padding'] = padding
  @property({ type: String, reflect: true }) alignment: IYCoreCardBasicProps['alignment'] = alignment
  @property({ type: String, reflect: true, attribute: 'title-size' }) titleSize: IYCoreCardBasicProps['titleSize'] = titleSize
  @property({ type: String, reflect: true, attribute: 'title-text' }) titleText: IYCoreCardBasicProps['titleText'] = titleText
  @property({ type: String, reflect: true, attribute: 'annotation-text' }) annotationText: IYCoreCardBasicProps['annotationText'] = annotationText
  @property({ type: String, reflect: true, attribute: 'subhead-text' }) subheadText: IYCoreCardBasicProps['subheadText'] = subheadText
  @provide({ context: sizeContextCreated })
  @property({ type: String, reflect: true }) size: IYCoreCardBasicProps['size'] = size
  @property({ type: String }) chevron: IYCoreCardBasicProps['chevron'] = chevron
  @property({ type: Boolean }) removable: IYCoreCardBasicProps['removable'] = removable
  @property({ type: Boolean }) hoverable: IYCoreCardBasicProps['hoverable'] = hoverable
  @property({ type: Boolean }) selected: IYCoreCardBasicProps['selected'] = selected
  @state() private hasLeftSideSlot = false
  @state() private hasRightSideSlot = false

  @bubblingEvent(
    RemoveEvent,
    { name: 'remove' },
  )
  private _remove!: TDispatcher<RemoveEvent>

  @bubblingEvent(
    CardBasicClickEvent,
    { name: 'card-click' },
  )
  private _cardClick!: TDispatcher<CardBasicClickEvent>

  private readonly baseClass = tagName

  static readonly styles = [
    css`
      ${unsafeCSS(YCardBasicVarsCss)}
      ${unsafeCSS(YCardBasicScopedCss)}
    `,
  ]

  private get computedClasses() {
    return {
      [this.baseClass]: true,
      [`${this.baseClass}_hoverable`]: Boolean(this.hoverable && this.padding),
      [`${this.baseClass}_selected`]: Boolean(this.selected),
      [`${this.baseClass}_align-${this.alignment}`]: true,
      [`${this.baseClass}_padding-${this.padding}`]: !!this.padding,
    }
  }

  private get leftSideClasses() {
    return {
      [`${this.baseClass}__left-side`]: true,
      [`${this.baseClass}__left-side_${this.size}`]: !!this.size,
      [`${this.baseClass}__left-side_empty`]: !this.hasLeftSideSlot,
    }
  }

  private get titleClasses() {
    return {
      [`${this.baseClass}__text-content-title`]: true,
      [`${this.baseClass}__text-content-title_${this.size}`]: true,
    }
  }

  private get rightSideClasses() {
    return {
      [`${this.baseClass}__right-side`]: true,
      [`${this.baseClass}__right-side_empty`]: !this.hasRightSideSlot,
    }
  }

  private get computedTitleSize() {
    return mapTitleTextSize[this.titleSize]
  }

  private get computedAnnotationSize() {
    return mapAnnotationTextSize[this.titleSize]
  }

  private handleRemove = (event: RemoveEvent) => {
    preventAndStopEvent(event)

    this._remove({ detail: { event } })
  }

  private handleLeftSideSlotChange = (event: Event) => {
    preventAndStopEvent(event)

    const target = event.target as HTMLSlotElement

    this.hasLeftSideSlot = hasSlotContent(target)
  }

  private handleRightSideSlotChange = (event: Event) => {
    preventAndStopEvent(event)

    const target = event.target as HTMLSlotElement

    this.hasRightSideSlot = hasSlotContent(target)
  }

  private handleRightSideClick = (event: Event) => {
    preventAndStopEvent(event)

    this._cardClick({ detail: { event, zone: 'right-slot' } })
  }

  private handleCardClick = (event: Event) => {
    this._cardClick({ detail: { event, zone: 'card' } })
  }

  connectedCallback() {
    super.connectedCallback()

    this.dataset.locator = tagName
    this.dataset[YC_COMPONENT_ATTRIBUTE_NAME] = ''
  }

  private renderSubhead() {
    return this.subheadText
      ? html`
        <y-core-text
          .variant=${EYCoreTextVariant.SECONDARY}
          .size=${this.computedAnnotationSize}
        >
          ${this.subheadText}
        </y-core-text>
      `
      : nothing
  }

  private renderTitleContent() {
    return html`
      <div class=${classMap(this.titleClasses)}>
        ${
          this.titleText
          ? html`
              <y-core-text .size=${this.computedTitleSize} .ellipsis=${true}>
                ${this.titleText}
              </y-core-text>
            `
          : nothing
        }
        <slot name="title-info"></slot>
      </div>

      <slot name="title-below"></slot>
    `
  }

  private renderAnnotation() {
    return html`
      <div class=${classMap(this.titleClasses)}>
        ${
          this.annotationText
          ? html`
            <y-core-text
              .variant=${EYCoreTextVariant.SECONDARY}
              .size=${this.computedAnnotationSize}
            >
              ${this.annotationText}
            </y-core-text>
          `
          : nothing
        }
        <slot name="annotation-info"></slot>
      </div>
    `
  }

  private renderRemoveIconButton() {
    return this.removable
      ? html`
          <y-core-icon-button
            .icon=${yClose}
            variant="text"
            class=${`${this.baseClass}__close`}
            @click=${this.handleRemove}
          ></y-core-icon-button>
        `
      : nothing
  }

  protected render() {
    return html`
      <div class=${classMap(this.computedClasses)} @click=${this.handleCardClick}>
        <div class=${classMap(this.leftSideClasses)}>
          <slot
            name="left-side"
            @slotchange=${this.handleLeftSideSlotChange}
          ></slot>
        </div>

        <div class=${`${this.baseClass}__text-content`}>
          ${this.renderSubhead()}

          ${this.renderTitleContent()}

          ${this.renderAnnotation()}
        </div>

        <div class=${classMap(this.rightSideClasses)}>
          <slot
            name="right-side"
            @slotchange=${this.handleRightSideSlotChange}
            @click=${this.handleRightSideClick}
            @checked=${this.handleRightSideClick}
          ></slot>

          ${this.chevron && renderIcon({
            icon: yBigChevronRight,
            size: mapChevronIconSize[this.chevron],
            className: `${this.baseClass}__chevron`,
          })}

          ${this.renderRemoveIconButton()}
        </div>
      </div>
    `
  }
}
