import { html } from 'lit'

export interface IRenderControlSlotOptions {
  hidden?: boolean
  onSlotChange: (event: Event) => void
  onMouseEnter: (event: MouseEvent) => void
  onMouseLeave: (event: MouseEvent) => void
}

export const renderControlSlot = ({ hidden, onSlotChange, onMouseEnter, onMouseLeave }: IRenderControlSlotOptions) => {
  return html`
    <slot
      name="control"
      ?hidden=${hidden}
      @slotchange=${onSlotChange}
      @mouseenter=${onMouseEnter}
      @mouseleave=${onMouseLeave}
    >
    </slot>
  `
}
