import { type TYSizes, type TPrimitive, EYSizes } from '~shared/types/global'

export enum EYCoreCollapseItemVariant {
  SURFACE = 'surface',
  PLAIN = 'plain',
}

export type TCollapseItemVariant = `${EYCoreCollapseItemVariant}`

/**
 * Свойства компонента CollapseItem
 */
export interface IYCoreCollapseItemExternalProps {

  /**
   * Текст метки
   */
  label: string | undefined

  /**
   * Текст аннотации
   */
  annotation: string | undefined

  /**
   * Открыт ли элемент
   * @default false
   */
  opened: boolean | undefined

  /**
   * Показывать индикатор загрузки
   */
  loading: boolean | undefined

  /**
   * Значение элемента
   */
  value: NonNullable<TPrimitive> | undefined

  /**
   * Вариант отображения
   * @default 'surface'
   */
  variant: TCollapseItemVariant | undefined

  /**
   * Варианты вертикальных паддингов компонента
   * @default 'medium'
   */
  spacingSize: Extract<TYSizes, 'small' | 'medium' | 'large'> | undefined

  /**
   * Варианты размеров лейбла
   * @default 'medium'
   */
  labelSize: Extract<TYSizes, 'small' | 'medium' | 'large'> | undefined

  /**
   * Отображать многоточие для основного текста
   * @default true
   */
  textEllipsis: boolean | undefined

  /**
   * максимальное количество строк основного текста, при котором будет отображаться многоточие
   * @default 1
   */
  textLineClamp: number | undefined

  /**
   * Оптимизация рендера вложенного контента. Если `true`, то контент будет отрисован только при открытии элемента. Если `false`, то контент будет отрисован всегда.
   * @default false
   */
  lazyMode: boolean | undefined
}

export const createCoreCollapseItemExternalProps = (): IYCoreCollapseItemExternalProps => ({
  label: undefined,
  annotation: undefined,
  opened: false,
  loading: undefined,
  value: undefined,
  variant: EYCoreCollapseItemVariant.SURFACE,
  spacingSize: EYSizes.MEDIUM,
  labelSize: EYSizes.MEDIUM,
  textEllipsis: true,
  textLineClamp: 1,
  lazyMode: false,
})
