import { LitElement, html, css, unsafeCSS, nothing } from 'lit'
import { customElement, property, state } from 'lit/decorators.js'
import { ifDefined } from 'lit/directives/if-defined.js'
import { classMap } from 'lit/directives/class-map.js'

import '~core/ui/tooltip'
import '~core/ui/dropdown'
import '~core/ui/tip'
import '~core/ui/text'

import { hasSlotContent } from '~core/utils/lit-slots'
import type { TDispatcher } from '~core/utils/event-decorator'
import type { OverflowChangeEvent } from '~core/ui/text/models/types/events'
import { EYCoreTextSize } from '~core/ui/text/models/types'

import {
  createCoreSideMenuItemExternalProps,
  EYCoreSideMenuItemVariant,
  type IYCoreSideMenuItemExternalProps,
} from './models/types'
import type {
  ClickEvent,
  MouseEnterEvent,
  MouseLeaveEvent,
  FocusEvent,
  BlurEvent,
  OpenedChangeEvent,
} from './models/types/events'
import { Events } from './models/types/events.decorators'
import type { TYCoreSideMenuItemSlot, TYCoreSideMenuItemSlotsState } from './models/types/slots'
import { renderMedia, renderContent, renderControl } from './models/renderers'

import { preventAndStopEvent } from '~web/shared/utils'
import { YCoreSideMenuItemTagName as tagName } from '~shared/constants'

import YSideMenuItemVarsCss from './css/SideMenuItem.vars.css?inline'
import YSideMenuItemScopedCss from './css/SideMenuItem.scoped.css?inline'

const { label, labelTooltipPlacement, annotation, icon, variant, isActive, href, target, opened, disabled } = createCoreSideMenuItemExternalProps()

@customElement(tagName)
export class YCoreSideMenuItem extends LitElement implements Required<IYCoreSideMenuItemExternalProps> {
  @property({ type: String, attribute: 'label' }) label: IYCoreSideMenuItemExternalProps['label'] = label
  @property({ type: String, attribute: 'label-tooltip-placement' }) labelTooltipPlacement: IYCoreSideMenuItemExternalProps['labelTooltipPlacement'] = labelTooltipPlacement
  @property({ type: String, attribute: 'annotation' }) annotation: IYCoreSideMenuItemExternalProps['annotation'] = annotation
  @property({ type: Object }) icon: IYCoreSideMenuItemExternalProps['icon'] = icon
  @property({ type: String, attribute: 'variant' }) variant: IYCoreSideMenuItemExternalProps['variant'] = variant
  @property({ type: Boolean, attribute: 'is-active' }) isActive: IYCoreSideMenuItemExternalProps['isActive'] = isActive
  @property({ type: String }) href: IYCoreSideMenuItemExternalProps['href'] = href
  @property({ type: String }) target: IYCoreSideMenuItemExternalProps['target'] = target
  @property({ type: Boolean, attribute: 'opened' }) opened: IYCoreSideMenuItemExternalProps['opened'] = opened
  @property({ type: Boolean, attribute: 'disabled' }) disabled: IYCoreSideMenuItemExternalProps['disabled'] = disabled

  @state() private slotsState: TYCoreSideMenuItemSlotsState = {
    media: false,
    annotation: false,
    control: false,
    children: false,
    collapseContent: false,
  }

  @Events.click private _click!: TDispatcher<ClickEvent>
  @Events.mouseEnter private _mouseenter!: TDispatcher<MouseEnterEvent>
  @Events.mouseLeave private _mouseleave!: TDispatcher<MouseLeaveEvent>
  @Events.focus private _focus!: TDispatcher<FocusEvent>
  @Events.blur private _blur!: TDispatcher<BlurEvent>
  @Events.openedChange private _openedChange!: TDispatcher<OpenedChangeEvent>

  private readonly baseClass = tagName

  private readonly HIDE_MENU_TIME = 500 // delay перед закрытием меню в collapse mode
  private readonly TOOLTIP_DELAY = 500

  @state() private _internalOpened = false
  @state() private isLabelOverflowed = false

  @state() private isBodyHovered = false
  @state() private isControlHovered = false
  @state() private isMenuHovered = false

  private _onMediaSlotChange!: (event: Event) => void
  private _onAnnotationSlotChange!: (event: Event) => void
  private _onControlSlotChange!: (event: Event) => void
  private _onChildrenSlotChange!: (event: Event) => void
  private _onCollapseContentSlotChange!: (event: Event) => void

  private closeTimeout: ReturnType<typeof setTimeout> | null = null

  static readonly styles = [
    css`
      ${unsafeCSS(YSideMenuItemVarsCss)}
      ${unsafeCSS(YSideMenuItemScopedCss)}
    `,
  ]

  constructor() {
    super()
    this._onMediaSlotChange = this.handleSlotChange('media')
    this._onAnnotationSlotChange = this.handleSlotChange('annotation')
    this._onControlSlotChange = this.handleSlotChange('control')
    this._onChildrenSlotChange = this.handleSlotChange('children')
    this._onCollapseContentSlotChange = this.handleSlotChange('collapseContent')
  }

  private get computedClasses() {
    return {
      [this.baseClass]: true,
      [`${this.baseClass}_active`]: this.isActive ?? false,
      [`${this.baseClass}_opened`]: this.isOpened,
      [`${this.baseClass}_full`]: this.isFull,
      [`${this.baseClass}_collapsed`]: this.isCollapsed,
      [`${this.baseClass}_disabled`]: this.disabled ?? false,
    }
  }

  private get isOpened(): boolean {
    return this.opened ?? this._internalOpened
  }

  private get isFull() {
    return this.variant === EYCoreSideMenuItemVariant.FULL
  }

  private get isCollapsed() {
    return this.variant === EYCoreSideMenuItemVariant.COLLAPSE
  }

  private get shouldRenderMediaSlot() {
    return this.icon !== undefined || this.slotsState.media
  }

  private get shouldRenderAnnotation() {
    return this.annotation || this.slotsState.annotation
  }

  private get shouldRenderCollapseChevron() {
    return this.slotsState.children
  }

  private get shouldRenderControlSlot() {
    return this.slotsState.control || this.slotsState.children
  }

  private get shouldRenderLinkBody() {
    return this.href && !this.disabled
  }

  private get isLabelTooltipActiveInFullMode() {
    return this.isFull && this.isLabelOverflowed && this.isBodyHovered && !this.isControlHovered
  }

  private get isLabelTooltipActiveInCollapseMode() {
    return this.isCollapsed && this.isBodyHovered && !(this.slotsState.children || this.slotsState.collapseContent)
  }

  private get isLabelTooltipActive() {
    return this.isLabelTooltipActiveInFullMode || this.isLabelTooltipActiveInCollapseMode
  }

  private get isLabelTooltipHasArrow() {
    return this.isFull
  }

  private get labelTooltipComputedPlacement(): IYCoreSideMenuItemExternalProps['labelTooltipPlacement'] {
    if (this.isLabelTooltipActiveInCollapseMode) return 'right'

    return this.labelTooltipPlacement
  }

  private get labelTooltipOffset() {
    if (this.isFull) return 10

    return 12
  }

  private get canShowCollapseMenu() {
    return this.isCollapsed && !this.disabled
  }

  private get canToggleByClick() {
    return this.isFull && (this.slotsState.children || this.slotsState.collapseContent) && !this.href && !this.disabled
  }

  private setIsOpened(value: boolean) {
    if (this.opened !== undefined) {
      this._openedChange({ detail: { value } })
    } else {
      this._internalOpened = value
    }
  }

  private handleSlotChange = (slotName: TYCoreSideMenuItemSlot) => (event: Event) => {
    const hasContent = hasSlotContent(event.target as HTMLSlotElement)

    if (this.slotsState[slotName] !== hasContent) {
      this.slotsState[slotName] = hasContent
      this.requestUpdate('slotsState')
    }
  }

  private handleBodyMouseEnter = (event: MouseEvent) => {
    preventAndStopEvent(event)

    this.isBodyHovered = true

    this.clearCloseTimeout()

    if (this.canShowCollapseMenu) {
      this.setIsOpened(true)
    }

    this._mouseenter({ detail: { event } })
  }

  private handleBodyMouseLeave = (event: MouseEvent) => {
    preventAndStopEvent(event)
    this.isBodyHovered = false

    if (this.canShowCollapseMenu && !this.isMenuHovered) {
      this.scheduleCloseMenu()
    }

    this._mouseleave({ detail: { event } })
  }

  private handleMenuMouseEnter = (event: MouseEvent) => {
    preventAndStopEvent(event)
    this.isMenuHovered = true

    this.clearCloseTimeout()
  }

  private handleMenuMouseLeave = (event: MouseEvent) => {
    preventAndStopEvent(event)
    this.isMenuHovered = false

    if (this.canShowCollapseMenu && !this.isBodyHovered) {
      this.scheduleCloseMenu()
    }
  }

  private handleControlMouseEnter = (event: MouseEvent) => {
    preventAndStopEvent(event)

    this.isControlHovered = true
  }

  private handleControlMouseLeave = (event: MouseEvent) => {
    preventAndStopEvent(event)

    this.isControlHovered = false
  }

  private handleBodyClick = (event: ClickEvent) => {
    if (this.disabled) {
      preventAndStopEvent(event)
      return
    }

    this._click({ detail: { event } })

    if (this.canToggleByClick) {
      this.setIsOpened(!this.isOpened)
    }
  }

  private handleBodyFocus = (event: FocusEvent) => {
    preventAndStopEvent(event)

    this._focus({ detail: { event } })
  }

  private handleBodyBlur = (event: FocusEvent) => {
    preventAndStopEvent(event)

    this._blur({ detail: { event } })
  }

  private scheduleCloseMenu() {
    if (this.closeTimeout) {
      clearTimeout(this.closeTimeout)
    }

    this.closeTimeout = setTimeout(() => {
      if (!this.isBodyHovered && !this.isMenuHovered) {
        this.setIsOpened(false)
      }
      this.closeTimeout = null
    }, this.HIDE_MENU_TIME)
  }

  private clearCloseTimeout() {
    if (this.closeTimeout) {
      clearTimeout(this.closeTimeout)
      this.closeTimeout = null
    }
  }

  private labelOverflowChange = (event: OverflowChangeEvent) => {
    this.isLabelOverflowed = event.detail.value
  }

  protected updated(changedProps: Map<string, unknown>) {
    if (changedProps.has('opened')) {
      const prev = changedProps.get('opened') as boolean | undefined
      const next = this.opened
      if (next !== prev && next !== undefined) {
        this._internalOpened = next
      }
    }

    if (changedProps.has('variant') && changedProps.get('variant')) {
      this.setIsOpened(false)
    }
  }

  disconnectedCallback() {
    super.disconnectedCallback()

    if (this.closeTimeout) {
      clearTimeout(this.closeTimeout)
      this.closeTimeout = null
    }
  }

  private renderInnerBody = () => {
    return html`
      ${renderMedia({
          icon: this.icon,
          hidden: !this.shouldRenderMediaSlot,
          onSlotChange: this._onMediaSlotChange,
        })
      }

      ${renderContent({
          baseClass: this.baseClass,
          label: this.label,
          annotation: this.annotation,
          isAnnotationHidden: !this.shouldRenderAnnotation,
          onLabelOverflowChange: this.labelOverflowChange,
          onAnnotationSlotChange: this._onAnnotationSlotChange,
        })
      }

      ${renderControl({
          isChevron: this.shouldRenderCollapseChevron,
          baseClass: this.baseClass,
          isOpened: this.isOpened,
          hidden: !this.shouldRenderControlSlot,
          onSlotChange: this._onControlSlotChange,
          onMouseEnter: this.handleControlMouseEnter,
          onMouseLeave: this.handleControlMouseLeave,
        })
      }
    `
  }

  private renderLinkBody = () => {
    return html`
      <a
        class=${`${this.baseClass}__body`}
        href=${ifDefined(this.href)}
        target=${ifDefined(this.target)}
        @click=${this.handleBodyClick}
        @focus=${this.handleBodyFocus}
        @blur=${this.handleBodyBlur}
        @mouseenter=${this.handleBodyMouseEnter}
        @mouseleave=${this.handleBodyMouseLeave}
      >
        ${this.renderInnerBody()}
      </a>
    `
  }

  private renderRegularBody = () => {
    return html`
      <div
        class=${`${this.baseClass}__body`}
        @click=${this.handleBodyClick}
        @focus=${this.handleBodyFocus}
        @blur=${this.handleBodyBlur}
        @mouseenter=${this.handleBodyMouseEnter}
        @mouseleave=${this.handleBodyMouseLeave}
      >
        ${this.renderInnerBody()}
      </div>
    `
  }

  private renderFullChildren = () => {
    return html`
      <div
        ?hidden=${!this.slotsState.children}
        class=${`${this.baseClass}__children-container`}
      >
        <slot
          name="children"
          @slotchange=${this._onChildrenSlotChange}
        ></slot>
      </div>
    `
  }

  private renderCollapseChildren = () => {
    return html`
      <y-core-dropdown
        .offset=${{ mainAxis: -40, crossAxis: 52 }}
        .isOpen=${this.isOpened}
        trigger="manual"
        tabindex="0"
        class=${`${this.baseClass}__collapse-dropdown`}
        @mouseenter=${this.handleMenuMouseEnter}
        @mouseleave=${this.handleMenuMouseLeave}
      >
        <div
          class=${`${this.baseClass}__collapse-dropdown-container`}
          slot="content"
          ?hidden=${!this.slotsState.children && !this.slotsState.collapseContent}
        >
          <slot
            name="collapse-content"
            @slotchange=${this._onCollapseContentSlotChange}
          >
            <y-core-text
              size=${EYCoreTextSize.H4_SEMIBOLD}
              class=${`${this.baseClass}__collapse-dropdown-children-title`}
            >
              ${this.label}
            </y-core-text>

            <slot
              name="children"
              @slotchange=${this._onChildrenSlotChange}
            ></slot>
          </slot>
        </div>
      </y-core-dropdown>
    `
  }

  private renderChildren = () => {
    if (this.isFull) {
      return this.renderFullChildren()
    }

    if (this.isCollapsed) {
      return this.renderCollapseChildren()
    }

    return nothing
  }

  protected render() {
    return html`
      <div
        tabindex=${this.disabled ? '-1' : '0'}
        aria-disabled=${ifDefined(this.disabled ? 'true' : undefined)}
        class=${classMap(this.computedClasses)}
      >
        <y-core-tip
          .placement=${this.labelTooltipComputedPlacement}
          trigger="manual"
          .isOpen=${this.isLabelTooltipActive}
          .delay=${this.TOOLTIP_DELAY}
          .hasArrow=${this.isLabelTooltipHasArrow}
          .offset=${this.labelTooltipOffset}
        >
          <div slot="activator">
            ${this.shouldRenderLinkBody
              ? this.renderLinkBody()
              : this.renderRegularBody()
            }
          </div>

          <div slot="content">
            <div class=${`${this.baseClass}__label-tooltip-content`}>
              <span>${this.label}</span>
            </div>
          </div>
        </y-core-tip>

        ${this.renderChildren()}
      </div>
    `
  }
}
