import { LitElement, html, css, unsafeCSS, type TemplateResult } from 'lit'
import { customElement, property } from 'lit/decorators.js'
import { classMap } from 'lit/directives/class-map.js'
import { repeat } from 'lit/directives/repeat.js'

import {
  createCoreSearchTextHighlightedProps,
  type IYCoreSearchTextHighlightedProps,
} from '~core/ui/searchTextHighlighted/models/types'
import {
  YCoreSearchTextHighlightedTagName as tagName,
} from '~shared/constants'
import { YC_COMPONENT_ATTRIBUTE_NAME } from '~web/shared/constants/attributes'

import '~core/ui/text'

import YCoreSearchTextHighlightedVarsCss from '~core/ui/searchTextHighlighted/css/SearchTextHighlighted.vars.css?inline'
import YCoreSearchTextHighlightedScopedCss from '~core/ui/searchTextHighlighted/css/SearchTextHighlighted.scoped.css?inline'

type Segment = {
  value: string
  highlighted: boolean
}

type MatchTextPosition = {
  startIdx: number
  endIdx: number
}

const { text, variant, search, ignoredSymbols, stopHighlight, size, highlightTextVariant, caseSensitive, ellipsis } = createCoreSearchTextHighlightedProps()

@customElement(tagName)
export class YCoreSearchTextHighlighted extends LitElement implements Required<IYCoreSearchTextHighlightedProps> {
  @property({ type: String }) text: IYCoreSearchTextHighlightedProps['text'] = text
  @property({ type: String }) search: IYCoreSearchTextHighlightedProps['search'] = search
  @property({ type: String }) size: IYCoreSearchTextHighlightedProps['size'] = size
  @property({ type: String }) variant: IYCoreSearchTextHighlightedProps['variant'] = variant
  @property({ type: Array, attribute: 'ignored-symbols' }) ignoredSymbols: IYCoreSearchTextHighlightedProps['ignoredSymbols'] = ignoredSymbols
  @property({ type: Boolean, attribute: 'stop-highlight' }) stopHighlight: IYCoreSearchTextHighlightedProps['stopHighlight'] = stopHighlight
  @property({ type: Boolean, attribute: 'case-sensitive' }) caseSensitive: IYCoreSearchTextHighlightedProps['caseSensitive'] = caseSensitive
  @property({ type: String, attribute: 'highlight-text-variant' }) highlightTextVariant: IYCoreSearchTextHighlightedProps['highlightTextVariant'] = highlightTextVariant
  @property({ type: Boolean }) ellipsis: IYCoreSearchTextHighlightedProps['ellipsis'] = ellipsis

  private readonly baseClass = tagName

  static readonly styles = [
    css`
      ${unsafeCSS(YCoreSearchTextHighlightedVarsCss)}
      ${unsafeCSS(YCoreSearchTextHighlightedScopedCss)}
    `,
  ]

  private get computedClasses() {
    return {
      [this.baseClass]: true,
      [`${this.baseClass}_size_${this.size}`]: Boolean(this.size),
      [`${this.baseClass}_variant_${this.variant}`]: Boolean(this.variant),
      [`${this.baseClass}_ellipsis`]: Boolean(this.ellipsis),
    }
  }

  private get computedHighlightedClasses() {
    return { [`${this.baseClass}_variant_${this.highlightTextVariant}`]: Boolean(this.highlightTextVariant) }
  }

  get highlighted(): Segment[] {
    if (this.stopHighlight) {
      return [
        {
          value: this.text,
          highlighted: false,
        },
      ]
    }

    return this.highlightSegments(this.text, this.search)
  }

  get regexHighlightFlag(): string {
    return !this.caseSensitive ? 'gi' : 'g'
  }


  private escapeIgnoredSymbols(): string {
    const ignoreSet = new Set(this.ignoredSymbols ?? [])
    return Array.from(ignoreSet)
      .map((char) => char.replace(/[.*+?^${}()|[\]\\-]/g, '\\$&'))
      .join('')
  }

  highlightSegments(text: string, search: string): Segment[] {
    const ignoreString = this.escapeIgnoredSymbols()

    // Экранируем специальные символы в поисковой строке
    const escapedSearch = search.split('').map((char) => {
      return char.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
    })

    const searchString = ignoreString.length > 0
      ? escapedSearch.join(`[${ignoreString}]*`)
      : escapedSearch.join('')

    const regex = new RegExp(searchString, this.regexHighlightFlag)

    const matchTextPositions: MatchTextPosition[] = Array.from(text.matchAll(regex)).map((match) => {
      return {
        startIdx: match.index,
        endIdx: match.index + match[0].length,
      }
    })

    if (search.length === 0 || matchTextPositions.length === 0) return [{ value: text, highlighted: false }]

    return this.buildSegments(this.text, matchTextPositions)
  }

  getHighlightedSegments(segment: Segment, isNeedTransform: boolean): Segment[] {
    if (this.ignoredSymbols?.length && isNeedTransform) return this.excludeIgnoredSymbols(segment)

    return [segment]
  }

  /**
   * Строит сегменты для последующего рендеринга
   * @param text исходная строка
   * @param matchTextPositions массив найденных позиций в исходной строке с учетом игнорируемых символов
   * @param isInvert требуется для управления устанавливаемым цветом при разных сценариях (подсветка текста, исключение игнорируемых символов из подсветки)
   */
  buildSegments(text: string, matchTextPositions: MatchTextPosition[], isInvert = false) {
    const result: Segment[] = []

    const isNeedTransform = !isInvert

    const firstSegment = text.slice(0, matchTextPositions[0].startIdx)

    if (firstSegment) result.push({ value: firstSegment, highlighted: isInvert } as Segment)

    let lastIndex = matchTextPositions[0].startIdx

    for (const match of matchTextPositions) {
      const { startIdx, endIdx } = match

      /** Сегменты между найденными блоками */
      if (lastIndex !== startIdx) {
        result.push({
          value: text.slice(lastIndex, startIdx),
          highlighted: isInvert,
        } as Segment)
      }

      const segment: Segment = {
        value: text.slice(startIdx, endIdx),
        highlighted: !isInvert,
      }

      result.push(...this.getHighlightedSegments(segment, isNeedTransform))

      lastIndex = endIdx
    }

    /** Если за найденными сегментами есть еще текст без подсветки */
    if (lastIndex < text.length) {
      result.push({
        value: text.slice(lastIndex),
        highlighted: isInvert,
      })
    }

    return result
  }

  /** Исключает игнорируемые символы из уже подсвеченного сегмента, разбивая его на отдельные сегменты */
  excludeIgnoredSymbols(highlightedSegment: Segment): Segment[] {
    const valueStringSplit = highlightedSegment.value.split('')

    const ignoreSet = new Set(this.ignoredSymbols?.map((symbol) => symbol.toLowerCase()))

    const hasIgnoredSymbols = valueStringSplit.some((char) => ignoreSet.has(char.toLowerCase()))

    if (!hasIgnoredSymbols) return [highlightedSegment]

    const ignoreSymbolsString = this.escapeIgnoredSymbols()

    const regex = new RegExp(`[${ignoreSymbolsString}]`, this.regexHighlightFlag)

    const matchTextPositions: MatchTextPosition[] = Array.from(highlightedSegment.value.matchAll(regex)).map((match) => {
      return {
        startIdx: match.index,
        endIdx: match.index + match[0].length,
      }
    })

    return this.buildSegments(highlightedSegment.value, matchTextPositions, true)
  }

  connectedCallback() {
    super.connectedCallback()
    this.dataset.locator = tagName
    this.dataset[YC_COMPONENT_ATTRIBUTE_NAME] = ''
  }

  protected render(): TemplateResult {
    return html`
      <div class=${classMap(this.computedClasses)}>
        ${
          repeat(
            this.highlighted,
            (_, index) => index,
            (segment) => {
              return segment.highlighted
                ? html`<span class=${classMap(this.computedHighlightedClasses)}>${segment.value}</span>`
                : html`${segment.value}`
            },
          )
        }
      </div>
    `
  }
}
