/**
 * Определяет, сообщает ли среда о поддержке hover-взаимодействия
 * и "точного" указателя (например, мышь или трекпад).
 *
 * Возвращает `true`, если media query `(hover: hover) and (pointer: fine)` совпадает.
 * Если `window.matchMedia` недоступен, возвращает `true` как совместимый fallback.
 */
export const supportsHoverPointer = (): boolean => {
  if (typeof window.matchMedia !== 'function') return true
  return window.matchMedia('(hover: hover) and (pointer: fine)').matches
}
