import type { PropertyValues } from 'lit'
import { html, LitElement, css, unsafeCSS, nothing } from 'lit'
import { customElement, property, state, query } from 'lit/decorators.js'
import { classMap } from 'lit/directives/class-map.js'
import { repeat } from 'lit/directives/repeat.js'
import { provide } from '@lit/context'

import { flip as flipMiddleware } from '~shared/utils/floating-ui'

import {
  YCoreMultipleSelectFieldTagName as tagName,
  YCoreFieldWrapperTagName,
  YCoreFieldInputTagName,
  YCoreDropdownCellTagName,
} from '~shared/constants'
import { YC_COMPONENT_ATTRIBUTE_NAME } from '~web/shared/constants/attributes'

const baseSingleLineWrapperClass = `${tagName}-single-line-wrapper`

import {
  type IYCoreMultipleSelectFieldProps,
  createCoreMultipleSelectFieldProps,
  isMultipleValueEqualListItems,
  isValueEqualListItem,
  SelectEvent,
  FocusEvent,
  BlurEvent,
  InputEvent,
  type VisibleEvent,
  mapSizeToAvatarSize,
} from './models/types'
import YCoreMultipleSelectFieldVarsCSS from '~core/ui/multipleSelectField/css/MultipleSelectField.vars.css?inline'
import YCoreMultipleSelectFieldScopedCSS from '~core/ui/multipleSelectField/css/MultipleSelectField.scoped.css?inline'

import { interceptEvents } from '~core/utils/event-interceptor'
import { isHandledKey, HANDLED_KEYS } from '~core/utils/list-keyboard-navigation'

import { disabledContextCreated, readonlyContextCreated, errorContextCreated, sizeContextCreated } from '~core/ui/fieldWrapper/providers'

import type { YCoreFieldWrapper } from '~core/ui/fieldWrapper'
import type { YCoreFieldInput } from '~core/ui/fieldInput'

import '~core/ui/text'

import '~core/ui/fieldWrapper'
import '~core/ui/fieldInput'
import '~core/ui/fieldIcon'
import '~core/ui/avatar'

import '~core/ui/dropdown'
import '~core/ui/dropdownList'
import '~core/ui/dropdownCell'
import '~core/ui/simpleChip'

import { yChevronDown, yCheck } from '~shared/icons'
import { type TDispatcher, bubblingEvent } from '~core/utils/event-decorator'
import { renderIcon, renderLabel, renderError, renderAnnotation } from '~core/renderers'
import { booleanConverter } from '~core/utils/converters'
import classMapToString from '~core/utils/classMapToString'

import type { KeydownEvent } from '~core/ui/fieldInput/models/types/events'
import type { IYCoreSelectListItem, TItemValue, TYCoreSelectFieldItemValue } from '~core/ui/selectField/models/types/external'
import type { ClickIconEmitEvent } from '~core/ui/simpleChip/models/types'
import { EYCoreDropdownPlacement, EYCoreDropdownTrigger } from '~core/ui/dropdown/models/types'
import { EYCoreSimpleChipVariant } from '~core/ui/simpleChip/models/types'
import { hasSlotContent } from '~core/utils/lit-slots'
import { EYSizes, type IDropdownListItem } from '~shared/types/global'
import { renderDropdownListContent } from '~core/renderers/dropdown-list-content'
import { SIZES } from '~tokens/index'
import { EYCoreTextSize } from '~core/ui/text/models/types'

const {
  value,
  name,
  placeholder,
  autofocus,
  disabled,
  readonly,
  error,
  errors,
  size,
  required,
  labelText,
  labelTooltipText,
  annotationText,
  labelDebounce,
  isMapOptions,
  items,
  itemLabel,
  itemValue,
  isCustomFilter,
  isFilterable,
  filterValue,
  useVirtualScroll,
  singleLine,
  maskOptions,
  ellipsis,
  labelTooltipPlacement,
  filterCallback,
  labelLocator,
  locator,
} = createCoreMultipleSelectFieldProps()

const BACKSPACE_KEY = 'Backspace'
const MIN_INPUT_WIDTH = 4
const SHOW_DROPDOWN_DELAY = 150

const MIN_CHIP_WIDTH = 69
const MIN_READONLY_CHIP_WIDTH = 60
const MAX_CHIPS_WRAPPER_WIDTH = 120
const MAX_COUNTER_VALUE = 99

@customElement(tagName)
@interceptEvents()
export class YCoreMultipleSelectField extends LitElement implements Required<IYCoreMultipleSelectFieldProps> {
  @provide({ context: disabledContextCreated })
  @property({ type: Boolean }) disabled: IYCoreMultipleSelectFieldProps['disabled'] = disabled
  @provide({ context: readonlyContextCreated })
  @property({ type: Boolean }) readonly: IYCoreMultipleSelectFieldProps['readonly'] = readonly
  @provide({ context: errorContextCreated })
  @property({ type: Boolean, reflect: true, converter: booleanConverter }) error: IYCoreMultipleSelectFieldProps['error'] = error
  @provide({ context: sizeContextCreated })
  @property({ type: String, reflect: true }) size: IYCoreMultipleSelectFieldProps['size'] = size

  @property({ type: Array }) value: IYCoreMultipleSelectFieldProps['value'] = value
  @property({ type: String, attribute: 'filter-value' }) filterValue: IYCoreMultipleSelectFieldProps['filterValue'] = filterValue
  @property({ type: String }) name: IYCoreMultipleSelectFieldProps['name'] = name
  @property({ type: String }) placeholder: IYCoreMultipleSelectFieldProps['placeholder'] = placeholder
  @property({ type: Boolean, reflect: true }) autofocus: NonNullable<IYCoreMultipleSelectFieldProps['autofocus']> = Boolean(autofocus)
  @property({ type: Boolean, reflect: true }) required: IYCoreMultipleSelectFieldProps['required'] = required
  @property({ type: Array }) errors: IYCoreMultipleSelectFieldProps['errors'] = errors
  @property({ type: Number, attribute: 'label-debounce' }) labelDebounce: IYCoreMultipleSelectFieldProps['labelDebounce'] = labelDebounce
  @property({ type: Boolean, attribute: 'is-map-options' }) isMapOptions: IYCoreMultipleSelectFieldProps['isMapOptions'] = isMapOptions
  @property({ type: String, attribute: 'label-text' }) labelText: IYCoreMultipleSelectFieldProps['labelText'] = labelText
  @property({ type: String, attribute: 'label-tooltip-text' }) labelTooltipText: IYCoreMultipleSelectFieldProps['labelTooltipText'] = labelTooltipText
  @property({ type: String, attribute: 'label-tooltip-placement' }) labelTooltipPlacement: IYCoreMultipleSelectFieldProps['labelTooltipPlacement'] = labelTooltipPlacement
  @property({ type: String, attribute: 'annotation-text' }) annotationText: IYCoreMultipleSelectFieldProps['annotationText'] = annotationText
  @property({ type: Array }) items: NonNullable<IYCoreMultipleSelectFieldProps['items']> = items ?? []
  @property({ type: String, attribute: 'item-label' }) itemLabel: NonNullable<IYCoreMultipleSelectFieldProps['itemLabel']> = String(itemLabel)
  @property({ type: String, attribute: 'item-value' }) itemValue: NonNullable<IYCoreMultipleSelectFieldProps['itemValue']> = String(itemValue)
  @property({ type: Boolean, attribute: 'is-custom-filter' }) isCustomFilter: IYCoreMultipleSelectFieldProps['isCustomFilter'] = isCustomFilter
  @property({ type: Boolean, attribute: 'is-filterable' }) isFilterable: IYCoreMultipleSelectFieldProps['isFilterable'] = isFilterable
  @property({ attribute: 'filter-callback' }) filterCallback: IYCoreMultipleSelectFieldProps['filterCallback'] = filterCallback
  @property({ type: Boolean, attribute: 'use-virtual-scroll' }) useVirtualScroll: IYCoreMultipleSelectFieldProps['useVirtualScroll'] = useVirtualScroll
  @property({ type: Boolean, attribute: 'single-line' }) singleLine: IYCoreMultipleSelectFieldProps['singleLine'] = singleLine
  @property({ type: Object, attribute: 'mask-options' }) maskOptions: IYCoreMultipleSelectFieldProps['maskOptions'] = maskOptions
  @property({ type: Boolean }) ellipsis: IYCoreMultipleSelectFieldProps['ellipsis'] = ellipsis
  @property({ type: String, attribute: 'label-locator' }) labelLocator: IYCoreMultipleSelectFieldProps['labelLocator'] = labelLocator
  @property({ type: String }) locator: IYCoreMultipleSelectFieldProps['locator'] = locator

  @bubblingEvent(
    FocusEvent,
    { name: 'focus' },
  )
  _focus!: TDispatcher<FocusEvent>

  @bubblingEvent(
    BlurEvent,
    { name: 'blur' },
  )
  _blur!: TDispatcher<BlurEvent>

  @bubblingEvent(
    SelectEvent,
    { name: 'select' },
  )
  _select!: TDispatcher<SelectEvent>

  @bubblingEvent(
    InputEvent,
    { name: 'input' },
  )
  _input!: TDispatcher<InputEvent>

  @state() private isOpened = false
  @state() private hasAnnotationSlot = false
  @state() private lastDropdownToggleTime = 0
  @state() private hiddenChipsCount = 0
  @state() private visibleChipEndIdx = 0
  @state() private focusedIndex: number | null = null

  @query(YCoreFieldWrapperTagName) public readonly fieldWrapper?: YCoreFieldWrapper
  @query(YCoreFieldInputTagName) public readonly fieldInput?: YCoreFieldInput
  @query(`.${baseSingleLineWrapperClass}_ghost`) public readonly singleLineGhost?: HTMLElement
  @query(`.${baseSingleLineWrapperClass}__chips`) public readonly singleLineChipsWrapper?: HTMLElement

  private resizeObserver: ResizeObserver | null = null

  private readonly baseClass = tagName
  private readonly baseDropdownActivatorClass = `${this.baseClass}__activator`
  private readonly baseDropdownContentClass = `${this.baseClass}__content`
  private readonly baseDropdownListItemsClass = `${this.baseClass}__list-items`
  private readonly baseDropdownListClass = `${this.baseClass}__dropdown-list`
  private readonly baseDropdownListItemClass = `${this.baseClass}__list-item`
  private readonly baseAnnotationClass = `${this.baseClass}__annotation`
  private readonly baseChipClass = `${this.baseClass}__chip`
  private readonly baseChipWrapperClass = `${this.baseClass}__chip-wrapper`
  private readonly baseSingleLineWrapperClass = baseSingleLineWrapperClass
  private readonly baseSingleLineChipsWrapperClass = `${this.baseSingleLineWrapperClass}__chips`
  private readonly baseInputClass = `${this.baseClass}__input`
  private readonly baseInputOverlayClass = `${this.baseClass}__input-overlay`
  private readonly baseArrowIconClass = `${this.baseClass}__arrow-icon`
  private readonly itemsGap = Number(SIZES.spacing_x.value)

  private get computedChipSize() {
    return this.size === 'small' ? EYSizes.SMALL : EYSizes.MEDIUM
  }

  private get computedChipTextSize() {
    if (this.size === EYSizes.SMALL) return EYCoreTextSize.A2_MEDIUM

    return EYCoreTextSize.P2_MEDIUM
  }

  private get computedSize() {
    return this.size ?? EYSizes.MEDIUM
  }

  private get computedAvatarSize() {
    return mapSizeToAvatarSize[this.computedSize]
  }

  private get visibleChips(): IYCoreSelectListItem[] {
    if (!this.singleLine || !this.hiddenChipsCount) return this.selectedItemsByValue

    return this.selectedItemsByValue.slice(0, this.visibleChipEndIdx)
  }

  private get computedClasses() {
    return {
      [this.baseClass]: true,
      [`${this.baseClass}_size_${this.size}`]: true,
      [`${this.baseClass}_focused`]: this.isOpened,
    }
  }
  private get computedLabelClasses() {
    return { [`${this.baseClass}__label`]: true }
  }
  private get computedAnnotationClasses() {
    return {
      [this.baseAnnotationClass]: true,
      [`${this.baseAnnotationClass}_hidden`]: Boolean(!this.hasAnnotation),
    }
  }
  private get computedChipClasses() {
    return {
      [this.baseChipClass]: true,
      [`${this.baseChipClass}_size_${this.size}`]: true,
      [`${this.baseChipClass}_readonly`]: Boolean(this.readonly),
    }
  }
  private get computedInputClasses() {
    return {
      [this.baseInputClass]: true,
      [`${this.baseInputClass}_has-selected-values`]: this.hasSelectedValues,
    }
  }

  private get computedActivatorClasses() {
    return {
      [this.baseDropdownActivatorClass]: true,
      [`${this.baseDropdownActivatorClass}_readonly`]: Boolean(this.readonly),
    }
  }
  private get computedChipWrapperClasses() {
    return {
      [this.baseChipWrapperClass]: true,
      [`${this.baseChipWrapperClass}_size_${this.size}`]: true,
      [`${this.baseChipWrapperClass}_no-selected-values`]: !this.hasSelectedValues,
    }
  }

  private get computedSingleLineWrapperClasses() {
    return {
      [this.baseSingleLineWrapperClass]: true,
      [`${this.baseSingleLineWrapperClass}_size_${this.size}`]: true,
      [`${this.baseSingleLineWrapperClass}_no-selected-values`]: !this.hasSelectedValues,
    }
  }
  private get computedSingleLineChipsWrapperClasses() {
    return {
      [this.baseSingleLineChipsWrapperClass]: true,
      [`${this.baseSingleLineChipsWrapperClass}_has-focus`]: Boolean(this.isOpened && this.isFilterable),
      [`${this.baseSingleLineChipsWrapperClass}_no-selected-values`]: !this.hasSelectedValues,
    }
  }

  private get computedArrowIconClasses() {
    return {
      [this.baseArrowIconClass]: true,
      [`${this.baseArrowIconClass}_rotated`]: this.isOpened,
    }
  }

  private get computedDisabledOrReadonly() {
    return this.disabled || this.readonly
  }

  private get hasAnnotation() {
    return Boolean(this.annotationText) || this.hasAnnotationSlot
  }

  private get filteredItems() {
    if (this.isCustomFilter) return this.items

    const filterFn = this.filterCallback ?? this.defaultItemsFilter

    return filterFn(this.items, this.filterValue ?? '')
  }

  private get dropdownItems() {
    return this.isFilterable ? this.filteredItems : this.items
  }

  private get hasSelectedValues() {
    return this.selectedItemsByValue.length > 0
  }

  private get selectedItemsByValue(): NonNullable<IYCoreSelectListItem[]> {
    if (!Array.isArray(this.value)) {
      return []
    }

    if (isMultipleValueEqualListItems(
      this.value,
      this.isMapOptions,
    )) {
      return this.value
    }

    return this.value.map((valueElement) => this.findItemByValue(valueElement))
      .filter((el) => el !== undefined)
  }

  private get dropdownMiddlewares() {
    return [flipMiddleware({ fallbackAxisSideDirection: 'none' })]
  }

  private get availableWidth(): number {
    if (!this.singleLineChipsWrapper) return 0

    return this.isOpened && this.isFilterable
      ? MAX_CHIPS_WRAPPER_WIDTH
      : this.singleLineChipsWrapper.clientWidth - Number(SIZES.spacing_2_x.value) * 2
  }

  private get maxVisibleChipsCount(): number {
    if (!this.singleLineGhost) return 0

    const availableWidth = this.singleLineGhost.clientWidth - Number(SIZES.spacing_2_x.value) * 2
    const minChipWidth = this.readonly ? MIN_READONLY_CHIP_WIDTH : MIN_CHIP_WIDTH

    return Math.floor(availableWidth / (minChipWidth + this.itemsGap))
  }

  private get countChipLabel(): string {
    return `+${this.hiddenChipsCount > MAX_COUNTER_VALUE ? MAX_COUNTER_VALUE : this.hiddenChipsCount}`
  }

  private getTextWidth(text: string): number {
    const canvas = document.createElement('canvas')
    const context = canvas.getContext('2d')
    if (!context || !this.fieldInput?.inputElement) return MIN_INPUT_WIDTH

    const computedStyle = window.getComputedStyle(this.fieldInput.inputElement)
    context.font = computedStyle.font
    const inputElementPaddingX = parseInt(computedStyle.paddingLeft) + parseInt(computedStyle.paddingRight)

    return Math.ceil(Math.max(MIN_INPUT_WIDTH, context.measureText(text).width) + inputElementPaddingX)
  }

  private get computedInputStyles() {
    const display = !this.isFilterable ? 'display:none;' : ''
    if (!this.filterValue) return display

    const width = `max-width: ${this.getTextWidth(this.filterValue)}px;`

    return `${display}${width}`
  }

  private calculateVisibleChips = () => {
    this.hiddenChipsCount = 0

    if (!this.singleLineGhost || this.selectedItemsByValue.length < 2) return

    const ghostChipElements = Array.from(this.singleLineGhost.querySelectorAll<HTMLElement>(`.${this.baseChipClass}`))
    const ghostCounterElement = Array.from(this.singleLineGhost.querySelectorAll<HTMLElement>(`.${this.baseChipClass}__counter`))

    this.measureSelectedChips(ghostChipElements, ghostCounterElement)
  }

  private measureSelectedChips(chipElements: HTMLElement[], counterElement: HTMLElement[]) {
    const totalChips = this.selectedItemsByValue.length
    const counterWidth = this.getChipWidth(counterElement, 0)
    const lastChipIdx = totalChips - 1

    let widthSum = 0

    for (let chipIdx = 0; chipIdx < totalChips; chipIdx++) {
      const chipWidth = this.getChipWidth(chipElements, chipIdx)
      const counterSpace = chipIdx === lastChipIdx ? 0 : counterWidth

      // Первый чип показываем всегда; для остальных проверяем, помещается ли чип + счётчик
      if (chipIdx > 0 && widthSum + MIN_CHIP_WIDTH + counterSpace > this.availableWidth) {
        this.visibleChipEndIdx = chipIdx
        this.hiddenChipsCount = totalChips - chipIdx
        break
      }

      widthSum += chipWidth
    }
  }


  private getChipWidth(chipElements: HTMLElement[], chipIdx: number): number {
    const chipEl = chipElements[chipIdx] as HTMLElement | undefined
    return (chipEl?.offsetWidth ?? MIN_CHIP_WIDTH) + this.itemsGap
  }

  private hasAvatarState = (item: IYCoreSelectListItem | undefined) => {
    if (!item) return false

    return Boolean(item.img || item.icon || item.initials)
  }

  private handleSlotAnnotationChange = (event: Event) => {
    event.stopPropagation()

    const target = event.target as HTMLSlotElement

    this.hasAnnotationSlot = hasSlotContent(target)
  }

  private findItemByValue(value: IYCoreSelectListItem[TItemValue]): IYCoreSelectListItem | undefined {
    return this.items.find((item) => item[this.itemValue] === value)
  }

  private isValueEqualListItem(value: TYCoreSelectFieldItemValue): value is IYCoreSelectListItem {
    return isValueEqualListItem(
      value,
      this.isMapOptions,
    )
  }

  private getValueFromItem = (item: IYCoreSelectListItem): IYCoreMultipleSelectFieldProps['value'] => {
    const value = this.itemValue && this.isMapOptions && typeof item[this.itemValue] !== 'undefined'
      ? item[this.itemValue]
      : item

    return value as IYCoreMultipleSelectFieldProps['value']
  }

  private getItemLabel = (item: IYCoreSelectListItem): string => {
    return String(item[this.itemLabel])
  }

  private setOrDeleteItemFromValue(item: IYCoreSelectListItem) {
    const currentValue = this.value ?? []

    const filteredValues = currentValue.filter((el) => {
      if (this.isValueEqualListItem(el)) {
        return el[this.itemValue] !== item[this.itemValue]
      }

      return el !== item[this.itemValue]
    })

    const isNeedPushItem = filteredValues.length === currentValue.length

    if (isNeedPushItem) filteredValues.push(this.getValueFromItem(item))

    return filteredValues
  }

  private blurFieldInput = () => {
    this.fieldInput?.inputElement?.blur()
    this.fieldWrapper?.blur()
  }

  private deleteItemFromValue = (item: IYCoreSelectListItem) => (event: ClickIconEmitEvent) => {
    if (this.readonly || !this.value) return

    event.detail.stopPropagation()

    const itemValue = item[this.itemValue]

    this.value = this.value.filter((element) => {
      if (this.isValueEqualListItem(element)) {
        return element[this.itemValue] !== itemValue
      }

      return element !== itemValue
    })

    this._select({ detail: { value: this.value } })

    if (this.value.length === 0 && !this.isOpened) {
      this.blurFieldInput()
    }

    if (this.isOpened) this.setFocusToInput()
  }

  private handleSelect = (item: IYCoreSelectListItem) => (event: PointerEvent) => {
    event.stopPropagation()

    if (this.computedDisabledOrReadonly || !event.currentTarget) return

    this.value = this.setOrDeleteItemFromValue(item)

    this.resetFilterValue()

    this.fieldInput?.inputElement?.focus()

    this._select({ detail: { value: this.value } })
  }

  private changeDropdownVisible(value: boolean) {
    if (this.computedDisabledOrReadonly || this.isFilterable && !this.fieldInput?.inputElement) return
    this.focusedIndex = null
    this.isOpened = value

    if (value) {
      this.setFocusToInput()
    } else {
      this.blurFieldInput()
    }
  }

  private setFocusToInput = () => {
    this.fieldInput?.inputElement?.focus()
  }

  private handleBlur = (event: BlurEvent) => {
    if (this.computedDisabledOrReadonly) return

    this.lastDropdownToggleTime = event.timeStamp

    if (this.isOpened) {
      this.changeDropdownVisible(false)
    }

    this._blur()
  }

  private handleDropdownMouseDown = (event: MouseEvent) => {
    event.preventDefault()
  }

  private handleFocus = (event: FocusEvent) => {
    if (this.computedDisabledOrReadonly) return

    this.lastDropdownToggleTime = event.timeStamp

    if (!this.isOpened) {
      this.changeDropdownVisible(true)
    }

    this._focus()
  }

  private getDifferentTimeBetweenFocus = (timeStamp: Event['timeStamp']) => {
    return timeStamp - this.lastDropdownToggleTime
  }

  private handleClick = (event: Event) => {
    if (this.computedDisabledOrReadonly) return

    // Если дропдаун только что изменил свое состояние, не меняем его
    if (this.getDifferentTimeBetweenFocus(event.timeStamp) < SHOW_DROPDOWN_DELAY) return

    this.changeDropdownVisible(!this.isOpened)
  }

  private handleNavigationKeyDown = (event: KeyboardEvent) => {
    if (!isHandledKey(event.key) || event.key === HANDLED_KEYS.SPACE) return

    event.preventDefault()

    if (event.key === HANDLED_KEYS.ARROW_DOWN) {
      this.handleArrowNext()
      return
    }

    if (event.key === HANDLED_KEYS.ARROW_UP) {
      this.handleArrowPrev()
      return
    }

    if (event.key === HANDLED_KEYS.ENTER) {
      this.handleSelectFocusedItem()
      this.resetFilterValue()
      this.focusedIndex = null
      return
    }

    this.changeDropdownVisible(false)
  }

  private handleKeydown = (event: KeydownEvent) => {
    event.stopPropagation()

    this.handleNavigationKeyDown(event.detail.event)

    if (event.detail.code !== BACKSPACE_KEY || (this.filterValue ?? '').length > 0) return

    if (this.value) {
      this.value = this.value.slice(0, -1)
      this._select({ detail: { value: this.value } })
    }
  }

  private handleInput = (event: InputEvent) => {
    event.stopPropagation()

    if (this.computedDisabledOrReadonly) return

    if (!this.isCustomFilter) {
      this.filterValue = event.detail.value
    }

    this._input({ detail: { value: event.detail.value, event } })

    this.focusedIndex = null
  }

  private handleClickOutside = (event: VisibleEvent) => {
    event.stopPropagation()

    if (this.computedDisabledOrReadonly) return

    // Если дропдаун только что изменил свое состояние, не меняем
    if (this.isOpened && this.getDifferentTimeBetweenFocus(event.timeStamp) < SHOW_DROPDOWN_DELAY) return

    this.isOpened = event.detail.value
  }

  private tryScroll = (element: HTMLElement) => {
    element.scrollIntoView({
      behavior: 'smooth',
      block: 'nearest',
      inline: 'nearest',
    })
  }

  static readonly styles = [
    css`
      ${unsafeCSS(YCoreMultipleSelectFieldVarsCSS)}
      ${unsafeCSS(YCoreMultipleSelectFieldScopedCSS)}
    `,
  ]

  private defaultItemsFilter = (items: IYCoreSelectListItem[], value: string) => {
    return items.filter((item) => this.getItemLabel(item).toLowerCase()
      .includes(value.toLowerCase()))
  }

  private getDropdownItemElementByIndex(index: number): HTMLElement | null {
    if (index < 0 || index >= this.dropdownItems.length) return null

    return this.shadowRoot?.querySelector<HTMLElement>(`${YCoreDropdownCellTagName}[data-item-index="${index}"]`) ?? null
  }

  private handleArrowNext = () => {
    const nextIndex = this.focusedIndex === null ? 0 : this.focusedIndex + 1

    if (nextIndex >= this.dropdownItems.length) return

    this.focusedIndex = nextIndex

    const element = this.getDropdownItemElementByIndex(nextIndex)
    if (element) {
      this.tryScroll(element)
    }
  }

  private handleArrowPrev = () => {
    const nextIndex = this.focusedIndex === null ? 0 : this.focusedIndex - 1

    if (nextIndex < 0) return

    this.focusedIndex = nextIndex

    const element = this.getDropdownItemElementByIndex(nextIndex)
    if (element) {
      this.tryScroll(element)
    }
  }

  private handleSelectFocusedItem = () => {
    if (this.focusedIndex === null || this.focusedIndex < 0 || this.focusedIndex >= this.dropdownItems.length) return

    const item = this.dropdownItems[this.focusedIndex]

    this.value = this.setOrDeleteItemFromValue(item)
    this._select({ detail: { value: this.value } })
    this.setFocusToInput()
  }

  private handleInputOverlayClick = (event: Event) => {
    if (this.getDifferentTimeBetweenFocus(event.timeStamp) < SHOW_DROPDOWN_DELAY) return

    if (this.isOpened) {
      this.changeDropdownVisible(false)
    } else {
      this.setFocusToInput()
    }
  }

  private resetFilterValue = () => {
    const event = new InputEvent('input', {
      bubbles: true,
      composed: true,
    })

    this._input({ detail: { value: '', event } })
    this.filterValue = ''
  }

  private observeForSingleLineMode = () => {
    if (this.singleLineChipsWrapper) {
      this.resizeObserver = new ResizeObserver(() => {
        this.calculateVisibleChips()
      })

      this.resizeObserver.observe(this.singleLineChipsWrapper)
      return
    }

    this.resizeObserver?.disconnect()
  }

  protected renderItemAvatar(item: IYCoreSelectListItem | undefined) {
    if (!this.hasAvatarState(item)) return nothing

    return html`
      <y-core-avatar
        .photo=${item?.img}
        .icon=${item?.icon}
        .initials=${item?.initials}
        .size=${this.computedAvatarSize}
      ></y-core-avatar>
    `
  }

  private renderListItem = (item: IDropdownListItem, index: number) => {
    return html`
      <y-core-dropdown-cell
        locator=${`${YCoreDropdownCellTagName}_${item.id}`}
        data-item-index=${index}
        .focused=${this.focusedIndex === index}
        @click=${this.handleSelect(item)}
        class=${this.baseDropdownListItemClass}
      >
        <div slot="prepend" class=${`${this.baseDropdownListItemClass}__prepend`}>
          ${this.renderItemAvatar(item)}
        </div>

        <div slot="content" class=${`${this.baseDropdownListItemClass}__content`}>
          <div title=${this.getItemLabel(item)} class=${`${this.baseDropdownListItemClass}__label`}>
            ${this.getItemLabel(item)}
          </div>
        </div>

        <div slot="append" class=${`${this.baseDropdownListItemClass}__append`}>
          ${this.selectedItemsByValue.some((el) => String(el[this.itemValue]) === String(item[this.itemValue]))
            ? renderIcon({ icon: yCheck, size: '16px' })
            : nothing
          }
        </div>
      </y-core-dropdown-cell>
    `
  }

  protected renderDropdownList() {
    return renderDropdownListContent(
      this.dropdownItems,
      this.renderListItem,
      { useVirtualScroll: this.useVirtualScroll },
    )
  }

  protected renderMultipleValues() {
    if (!this.hasSelectedValues) return null

    return repeat(
      this.visibleChips,
      (item) => item.id,
      (item) => html`
        <y-core-simple-chip
          variant=${EYCoreSimpleChipVariant.MUTED}
          .background=${item.chipBackgroundColor}
          .color=${item.chipTextColor}
          class=${classMap(this.computedChipClasses)}
          .size=${this.computedChipSize}
          .disabled=${this.disabled}
          .readonly=${this.readonly}
          @click-icon=${this.deleteItemFromValue(item)}
        >
          <y-core-text
            .size=${this.computedChipTextSize}
            .title=${this.getItemLabel(item)}
            variant="inherit"
            class=${`${this.baseChipClass}-text`}
            ellipsis
          >
            ${this.getItemLabel(item)}
          </y-core-text>
        </y-core-simple-chip>
      `,
    )
  }

  protected renderActivatorWrapperContent() {
    return html`
      <div class=${classMap(this.computedChipWrapperClasses)}>
        ${this.renderMultipleValues()}
        <y-core-field-input
            .value=${this.filterValue ?? ''}
            .name=${this.name}
            .placeholder=${this.hasSelectedValues ? undefined : this.placeholder}
            .required=${this.required}
            .autofocus=${this.autofocus}
            .hideSpaceLeft=${this.hasSelectedValues}
            .hideSpaceRight=${!this.readonly}
            .maskOptions=${this.maskOptions}
            .ellipsis=${this.ellipsis}
            autocomplete='off'
            class=${classMapToString(this.computedInputClasses)}
            style=${this.computedInputStyles}
            @input=${this.handleInput}
            @keydown=${this.handleKeydown}
            @focus=${this.handleFocus}
            @blur=${this.handleBlur}
          ></y-core-field-input>
        <div
          class=${this.baseInputOverlayClass}
          @click=${this.handleInputOverlayClick}
        ></div>
      </div>
    `
  }

  protected renderCounter() {
    return this.hiddenChipsCount > 0
      ? html`
        <y-core-simple-chip
          .readonly=${true}
          .disabled=${this.disabled}
          .size=${this.computedChipSize}
          variant=${EYCoreSimpleChipVariant.MUTED}
          class=${`${this.baseChipClass}__counter`}
        >
          <div class=${`${this.baseChipClass}__counter-overlay`}></div>
          <y-core-text .size=${this.computedChipTextSize}>
            ${this.countChipLabel}
          </y-core-text>
        </y-core-simple-chip>
      `
      : nothing
  }

  protected renderGhostContainer() {
    return this.singleLine && this.selectedItemsByValue.length > 0
      ? html`
        <div class=${`${this.baseSingleLineWrapperClass}_ghost`}>
          ${
            repeat(
              this.selectedItemsByValue.slice(0, this.maxVisibleChipsCount),
              (item) => item.id,
              (item) => html`
                <y-core-simple-chip
                  class=${classMap(this.computedChipClasses)}
                  .size=${this.computedChipSize}
                  .readonly=${this.readonly}
                >
                  <y-core-text
                    .size=${this.computedChipTextSize}
                    class=${`${this.baseChipClass}-text`}
                    ellipsis
                  > ${this.getItemLabel(item)} </y-core-text>
                </y-core-simple-chip>
              `,
            )
          }

          ${this.renderCounter()}
        </div>`
      : null
  }

  protected renderActivatorSingleLineWrapperContent() {
    return html`
      <div class=${classMap(this.computedSingleLineWrapperClasses)}>
        ${this.renderGhostContainer()}

        <div class=${classMap(this.computedSingleLineChipsWrapperClasses)}>
          ${this.renderMultipleValues()}

          ${this.renderCounter()}
        </div>

        <y-core-field-input
          .value=${this.filterValue ?? ''}
          .name=${this.name}
          .placeholder=${this.hasSelectedValues ? undefined : this.placeholder}
          .required=${this.required}
          .readonly=${!this.isFilterable}
          .autofocus=${this.autofocus}
          .hideSpaceLeft=${this.hasSelectedValues}
          .hideSpaceRight=${!this.readonly}
          .maskOptions=${this.maskOptions}
          .ellipsis=${this.ellipsis}
          autocomplete='off'
          class=${classMapToString(this.computedInputClasses)}
          style=${this.computedInputStyles}
          @input=${this.handleInput}
          @keydown=${this.handleKeydown}
          @blur=${this.handleBlur}
          @focus=${this.handleFocus}
        ></y-core-field-input>
      </div>
    `
  }

  protected renderDropdownActivatorWrapperContent() {
    return this.singleLine ? this.renderActivatorSingleLineWrapperContent() : this.renderActivatorWrapperContent()
  }

  protected renderDropdownActivator() {
    return html`
      <y-core-field-wrapper
        .disabled=${this.disabled}
        .readonly=${this.readonly}
        .error=${Boolean(this.errors?.length) || this.error}
        .size=${this.size}
        clickable
        @click=${this.handleClick}

      >
        ${this.renderDropdownActivatorWrapperContent()}
        ${!this.readonly
          ? html`
            <y-core-field-icon
              .icon=${yChevronDown}
              hoverable
              class=${classMap(this.computedArrowIconClasses)}
            ></y-core-field-icon>
          `
          : nothing
        }
      </y-core-field-wrapper>
    `
  }

  protected renderDropdownContent() {
    return html`
      <y-core-dropdown-list tabindex="-1" class=${this.baseDropdownListClass} @mousedown=${this.handleDropdownMouseDown}>
        ${html`
          <slot name="dropdown-list-top" slot="top">
          </slot>
        `}

        <div class=${this.baseDropdownListItemsClass} slot="list">
          <slot name="list">
            ${this.renderDropdownList()}
          </slot>
        </div>

        ${html`
          <slot name="dropdown-list-bottom" slot="bottom">
          </slot>
        `}
      </y-core-dropdown-list>`
  }

  connectedCallback() {
    super.connectedCallback()

    this.dataset.locator = tagName
    this.dataset[YC_COMPONENT_ATTRIBUTE_NAME] = ''
  }

  public focus(): void {
    this.fieldInput?.focus()
  }

  public blur(): void {
    this.fieldInput?.blur()
  }

  disconnectedCallback() {
    if (this.resizeObserver) {
      this.resizeObserver.disconnect()
    }

    super.disconnectedCallback()
  }

  checkIsOpenedUpdates(changedProperties: PropertyValues, isOpened: boolean) {
    if (typeof changedProperties.get('isOpened') === 'boolean' && isOpened !== changedProperties.get('isOpened')) {
      if (isOpened) {
        return
      }

      this.resetFilterValue()
    }
  }

  protected updated(changedProperties: PropertyValues) {
    super.updated(changedProperties)

    if (changedProperties.has('singleLine')) {
      this.observeForSingleLineMode()
    }

    if (changedProperties.has('value')) {
      this.calculateVisibleChips()
    }

    this.checkIsOpenedUpdates(changedProperties, this.isOpened)
  }

  protected render() {
    return html`
      <div class=${classMap(this.computedClasses)}>
        ${renderLabel({
          text: this.labelText,
          tooltipText: this.labelTooltipText,
          tooltipPlacement: this.labelTooltipPlacement,
          debounce: this.labelDebounce,
          tooltipActive: !this.disabled,
          required: this.required,
          disabled: this.disabled,
          handleClick: this.setFocusToInput,
          className: classMapToString(this.computedLabelClasses),
        })}
        <y-core-dropdown
          .isOpen=${this.isOpened}
          .trigger=${EYCoreDropdownTrigger.MANUAL}
          .placement=${EYCoreDropdownPlacement.BOTTOM_START}
          .middlewares=${this.dropdownMiddlewares}
          strict-width
          @click-outside=${this.handleClickOutside}
        >
          <div slot="activator" class=${classMap(this.computedActivatorClasses)}>
              ${this.renderDropdownActivator()}
          </div>

          <div slot="content" class=${this.baseDropdownContentClass}>
            ${this.isOpened
              ? this.renderDropdownContent()
              : nothing
            }
          </div>
        </y-core-dropdown>
        ${renderAnnotation({
          text: this.annotationText,
          disabled: this.disabled,
          className: classMapToString(this.computedAnnotationClasses),
          handleSlotAnnotationChange: this.handleSlotAnnotationChange,
        })}
        ${renderError({ errors: this.errors })}
      </div>
    `
  }
}
