import { bubblingEvent } from '~core/utils/event-decorator'
import { ClickEvent, MouseEnterEvent, MouseLeaveEvent, FocusEvent, BlurEvent, OpenedChangeEvent } from './events'

export const Events = {
  click: bubblingEvent(ClickEvent, { name: 'click' }),
  mouseEnter: bubblingEvent(MouseEnterEvent, { name: 'mouseenter' }),
  mouseLeave: bubblingEvent(MouseLeaveEvent, { name: 'mouseleave' }),
  focus: bubblingEvent(FocusEvent, { name: 'focus' }),
  blur: bubblingEvent(BlurEvent, { name: 'blur' }),
  openedChange: bubblingEvent(OpenedChangeEvent, { name: 'opened-change' }),
} as const
