/**
 * @module ToastsPlugin/ToastQueueHost
 * @description Lit-элемент для отображения очереди тостов
 */

import { css, html, LitElement, nothing, unsafeCSS } from 'lit'
import { customElement, state, queryAll, query } from 'lit/decorators.js'
import { repeat } from 'lit/directives/repeat.js'
import { styleMap } from 'lit/directives/style-map.js'

import type { IToastQueueModule } from '~core/ui/globalProvider/context'
import type { IToastQueueModuleItem } from '~core/ui/globalProvider/context/modules/ToastQueueModule'
import type { IToastQueueHost, IToastQueueHostConfig } from './types'
import '~core/ui/toast'
import { YCoreToastQueueHostTagName } from '~shared/constants'
import type { TTimeout } from '~shared/types/global'
import { BreakpointsController } from '~core/utils/breakpoints'
import { supportsHoverPointer } from '~core/utils/supports-hover-pointer'
import YToastQueueHostScopedCSS from './css/ToastQueueHost.scoped.css?inline'
import YToastQueueHostVarsCSS from './css/ToastQueueHost.vars.css?inline'
import {
  BASE_DELAY_BETWEEN_LEAVING_TOASTS,
  DEFAULT_TOAST_QUEUE_HOST_CONFIG,
  TOAST_ENTER_LEAVE_DURATION_MS,
} from '~core/ui/globalProvider/plugins/toasts/constants'

/**
 * Lit-элемент для отображения очереди тостов
 * Реализует интерфейс IToastQueueHost
 * @class YCoreToastQueueHost
 * @extends LitElement
 * @implements {IToastQueueHost}
 */
@customElement(YCoreToastQueueHostTagName)
export class YCoreToastQueueHost extends LitElement implements Required<IToastQueueHost> {
  @state() private items: IToastQueueModuleItem[] = []

  /** Набор модулей очереди, подключенных к этому хосту */
  @state() private module: IToastQueueModule | null = null

  /** Конфигурация хоста */
  @state() private config: IToastQueueHostConfig = DEFAULT_TOAST_QUEUE_HOST_CONFIG

  /** Флаг наведения курсора на область тостов */
  @state() private hovered = false


  private moveAnimations = new WeakMap<HTMLElement, Animation>()

  private pendingFirstRects: Map<string, DOMRect> | null = null

  private pendingPrevElements: Map<string, HTMLElement> | null = null

  private animationFrameId: number | null = null

  @queryAll(`.${YCoreToastQueueHostTagName}__toast-wrap`)
  toastWrappers!: NodeListOf<HTMLElement>

  @query(`.${YCoreToastQueueHostTagName}__container`)
  private containerEl?: HTMLElement

  /** Базовый CSS класс для элемента */
  private readonly baseClass = YCoreToastQueueHostTagName

  /** Набор видимых тостов для управления таймерами */
  private visibleIds = new Set<string>()

  /** Последнее состояние паузы по hover, отправленное в модуль */
  private lastPauseForHover = false

  /** Кэш тостов, которые анимируются на уход */
  private leavingItems = new Map<string, IToastQueueModuleItem>()

  /** Таймеры удаления уходящих тостов */
  private leavingTimers = new Map<string, TTimeout>()

  /** Базовые длительности тостов для расчета задержки */
  private baseDurations = new Map<string, number>()

  /** Флаг мобильного режима (для maxVisible = 1) */
  private isMobile = false

  private readonly breakpoints = new BreakpointsController(this)

  /** Вычисляемое свойство: максимальное количество видимых тостов (не менее 1) */
  private get maxVisible() {
    if (this.breakpoints.smallerOrEqual('XS')) return 1
    return Math.max(1, this.config.maxVisible)
  }

  /** Стили Lit-элемента */
  static readonly styles = [
    css`${unsafeCSS(YToastQueueHostVarsCSS)}`,
    css`${unsafeCSS(YToastQueueHostScopedCSS)}`,
  ]

  /**
   * Добавляет модуль очереди к хосту и подписывается на его обновления
   * @param module - Модуль очереди тостов
   */
  public addQueueModule(module: IToastQueueModule) {
    this.module = module
    module.onUpdated(() => {
      this.syncWithModule()
    })
    this.syncWithModule()
  }

  /**
   * Удаляет модуль очереди из хоста
   */
  public removeQueueModule() {
    if (this.module) {
      this.module = null
      this.syncWithModule()
    }
  }

  /**
   * Обновляет конфигурацию хоста
   * @param cfg - Новая конфигурация
   */
  setConfig(cfg: IToastQueueHostConfig) {
    this.config = {
      ...DEFAULT_TOAST_QUEUE_HOST_CONFIG,
      ...cfg,
    }
    this.updateVisibleToasts()
  }

  /**
   * Уничтожает хост и очищает все ресурсы
   */
  destroy(): void {
    this.module = null
    this.leavingItems.clear()
    this.baseDurations.clear()
    this.visibleIds.clear()
    this.lastPauseForHover = false
    this.leavingTimers.forEach((timer) => { clearTimeout(timer) })
    this.leavingTimers.clear()
    this.remove()
  }

  /**
   * Возвращает длительность анимации ухода тоста
   * @private
   */
  private get leaveDurationMs() {
    return this.isConnected ? TOAST_ENTER_LEAVE_DURATION_MS : 0
  }

  /**
   * Очищает таймер удаления уходящего тоста
   * @private
   */
  private clearLeavingTimer(id: string) {
    const timer = this.leavingTimers.get(id)
    if (!timer) return

    clearTimeout(timer)
    this.leavingTimers.delete(id)
  }

  /**
   * Завершает анимацию ухода тоста
   * @private
   */
  private finishLeaving(id: string) {
    if (!this.leavingItems.has(id)) return

    this.leavingItems.delete(id)
    this.clearLeavingTimer(id)
    this.baseDurations.delete(id)
  }

  /**
   * Запускает анимацию ухода тоста
   * @private
   */
  private startLeaving(item: IToastQueueModuleItem) {
    const id = item.id

    this.leavingItems.set(id, item)

    this.clearLeavingTimer(id)

    const duration = this.leaveDurationMs
    if (duration <= 0) {
      this.finishLeaving(id)
      return
    }

    const timer = setTimeout(() => {
      this.finishLeaving(id)
    }, duration)
    this.leavingTimers.set(id, timer)
  }

  /**
   * Отменяет уходящий тост, если он снова появился
   * @private
   */
  private cancelLeaving(id: string) {
    if (!this.leavingItems.has(id)) return

    this.leavingItems.delete(id)
    this.clearLeavingTimer(id)
  }

  /**
   * Очищает метаданные по удаленному тосту
   * @private
   */
  private cleanupRemovedItem(id: string) {
    this.cancelLeaving(id)
    this.baseDurations.delete(id)
  }

  /**
   * Регистрирует активные тосты
   * @private
   */
  private registerActiveItems(items: IToastQueueModuleItem[]) {
    const currentIds = new Set<string>()
    for (const item of items) {
      currentIds.add(item.id)
      this.cancelLeaving(item.id)
    }
    return currentIds
  }

  /**
   * Обрабатывает удаленные тосты
   * @private
   */
  private handleRemovedItems(
    prevItems: IToastQueueModuleItem[],
    prevVisibleIds: Set<string>,
    prevOverflow: boolean,
    currentIds: Set<string>,
  ) {
    for (const item of prevItems) {
      if (currentIds.has(item.id)) continue
      this.handleRemovedItem(item.id, item, prevVisibleIds, prevOverflow)
    }
  }

  /**
   * Обрабатывает удаленный тост
   * @private
   */
  private handleRemovedItem(
    id: string,
    item: IToastQueueModuleItem,
    prevVisibleIds: Set<string>,
    prevOverflow: boolean,
  ) {
    if (!prevVisibleIds.has(id)) {
      this.cleanupRemovedItem(id)
      return
    }

    if (prevOverflow) {
      this.cleanupRemovedItem(id)
      return
    }

    this.startLeaving(item)
  }

  /**
   * Останавливает уходящие тосты при переполнении
   * @private
   */
  private pruneLeavingInOverflow(isOverflow: boolean) {
    if (!isOverflow) return
    for (const item of this.leavingItems.values()) {
      this.finishLeaving(item.id)
    }
  }

  /**
   * Синхронизирует состояние хоста с состоянием модулей
   * Обрабатывает анимации входа/выхода для тостов
   * @private
   */
  private syncWithModule() {
    const allItems: IToastQueueModuleItem[] = (this.module?.getItems() || []) as IToastQueueModuleItem[]
    const prevItems = this.items

    if (allItems.length <= this.maxVisible) {
      this.captureBeforeUpdate()
    } else {
      this.pendingFirstRects = null
      this.pendingPrevElements = null
    }
    this.items = allItems

    const prevVisibleIds = new Set(this.visibleIds)
    const prevOverflow = prevItems.length > this.maxVisible

    const currentIds = this.registerActiveItems(allItems)

    this.handleRemovedItems(prevItems, prevVisibleIds, prevOverflow, currentIds)
    this.pruneLeavingInOverflow(allItems.length > this.maxVisible)
    this.updateVisibleToasts()
  }

  /**
   * Сравнивает два набора строк на равенство
   * @private
   */
  private areSetsEqual(a: Set<string>, b: Set<string>) {
    if (a.size !== b.size) return false
    for (const id of a) {
      if (!b.has(id)) return false
    }
    return true
  }

  /**
   * Собирает ID видимых тостов с учетом maxVisible
   * @private
   */
  private collectVisibleIds() {
    const visible = new Set<string>()
    const totalCount = this.items.length
    const visibleItems = totalCount > this.maxVisible
      ? [this.items[this.items.length - 1]]
      : this.items

    for (const item of visibleItems) {
      visible.add(item.id)
    }

    return visible
  }

  /**
   * Применяет задержку удаления для новых видимых тостов
   * @private
   */
  private applyRemovalDelay(
    items: IToastQueueModuleItem[],
    newVisible: Set<string>,
  ) {
    if (newVisible.size === 0) return null
    if (items.length > this.maxVisible) return null

    const durationOverrides = new Map<string, number>()

    for (const [index, item] of items.entries()) {
      this.applyRemovalDelayToItem(item, index, newVisible, durationOverrides)
    }

    if (durationOverrides.size === 0) return null

    return durationOverrides
  }

  /**
   * Применяет задержку удаления к конкретному тосту
   * @private
   */
  private applyRemovalDelayToItem(
    item: IToastQueueModuleItem,
    index: number,
    newVisible: Set<string>,
    durationOverrides: Map<string, number>,
  ) {
    if (!newVisible.has(item.id) || item.toast.manualClose) return

    const baseDuration = this.getBaseDuration(item)
    if (baseDuration <= 0) return

    durationOverrides.set(
      item.id,
      baseDuration + index * BASE_DELAY_BETWEEN_LEAVING_TOASTS,
    )
  }

  /**
   * Возвращает базовую длительность тоста
   * @private
   */
  private getBaseDuration(item: IToastQueueModuleItem) {
    const cachedDuration = this.baseDurations.get(item.id)
    if (cachedDuration !== undefined) return cachedDuration

    const baseDuration = item.toast.duration ?? this.config.defaultDuration ?? 0
    this.baseDurations.set(item.id, baseDuration)

    return baseDuration
  }

  /**
   * Обновляет набор видимых тостов и синхронизирует таймеры
   * @private
   */
  private updateVisibleToasts() {
    const nextVisible = this.collectVisibleIds()
    const pauseForHover = this.computePauseForHover()
    const isSameVisibleSet = this.areSetsEqual(this.visibleIds, nextVisible)
    if (isSameVisibleSet && this.lastPauseForHover === pauseForHover) return

    const prevVisible = this.visibleIds
    const newVisible = new Set<string>()

    for (const id of nextVisible) {
      if (!prevVisible.has(id)) newVisible.add(id)
    }

    const durationOverrides = isSameVisibleSet
      ? null
      : this.applyRemovalDelay(this.items, newVisible)

    this.visibleIds = nextVisible
    this.lastPauseForHover = pauseForHover
    this.setModuleVisibleIds(nextVisible, pauseForHover, durationOverrides)
  }

  private computePauseForHover() {
    if (this.config.pauseOnHover === false) return false
    if (!supportsHoverPointer()) {
      this.hovered = false
      return false
    }
    return this.hovered
  }

  private setModuleVisibleIds(
    nextVisible: Set<string>,
    pauseForHover: boolean,
    durationOverrides?: ReadonlyMap<string, number> | null,
  ) {
    const module = this.module
    if (!module) return
    const setVisibleIds = module.setVisibleIds
    if (typeof setVisibleIds !== 'function') return
    setVisibleIds.call(module, nextVisible, pauseForHover, durationOverrides ?? undefined)
  }

  /**
   * Обработчик наведения курсора на область тостов
   * При наведении приостанавливает таймеры всех тостов
   * @private
   */
  private onMouseEnter = () => {
    if (this.config.pauseOnHover === false) return
    if (!supportsHoverPointer()) return
    if (this.hovered) return
    this.hovered = true
    this.pauseAllToasts()
  }

  /**
   * Обработчик убирания курсора с области тостов
   * При убирании возобновляет таймеры всех тостов
   * @private
   */
  private onMouseLeave = () => {
    if (this.config.pauseOnHover === false) return
    if (!supportsHoverPointer()) return
    if (!this.hovered) return
    this.hovered = false
    this.resumeAllToasts()
  }

  /**
   * Приостанавливает таймеры всех тостов во всех модулях
   * @private
   */
  private pauseAllToasts() {
    if (this.module && typeof this.module.pauseAll === 'function') {
      this.module.pauseAll()
    }
  }

  /**
   * Возобновляет таймеры всех тостов во всех модулях
   * @private
   */
  private resumeAllToasts() {
    if (this.module && typeof this.module.resumeAll === 'function') {
      this.module.resumeAll()
    }
  }

  /**
   * Обработчик клика по кнопке закрытия тоста
   * @param id - ID тоста для закрытия
   * @private
   */
  private onCloseClick = (id: string) => {
    if (!this.module) return

    this.module.removeItem(id)
  }

  /**
   * Рендерит один тост с анимацией и состоянием
   * @param item - Элемент тоста из очереди
   * @param counterValue - Значение счетчика скрытых тостов (если их больше maxVisible)
   * @protected
   * @returns Lit-шаблон тоста
   */
  protected renderToast(item: IToastQueueModuleItem, counterValue = 0) {
    const toast = item.toast
    const wrapStyle = { maxWidth: toast.maxWidth ? `min(100%, ${toast.maxWidth})` : '100%' }

    return html`
      <div
        class="${this.baseClass}__toast-wrap"
        data-id=${item.id}
        style=${styleMap(wrapStyle)}
      >
        <y-core-toast
          .variant=${toast.variant}
          .titleText=${toast.titleText}
          .description=${toast.description}
          .maxWidth=${toast.maxWidth}
          .counterValue=${counterValue}
          @close=${() => { this.onCloseClick(item.id) }}
        ></y-core-toast>
      </div>
    `
  }

  /**
   * Вычисляет параметры отображения активных тостов
   * @private
   */
  private getVisibleActiveItems(activeItems: IToastQueueModuleItem[]) {
    const isOverflow = activeItems.length > this.maxVisible
    const hiddenCount = isOverflow ? activeItems.length : 0
    const visibleActive = isOverflow ? [activeItems[activeItems.length - 1]] : activeItems

    return { isOverflow, hiddenCount, visibleActive }
  }

  /**
   * Рендерит массив тостов с учетом ограничения по количеству
   * @protected
   * @returns Lit-шаблон с массивом тостов
   */
  protected renderToasts() {
    const { hiddenCount, visibleActive } = this.getVisibleActiveItems(this.items)

    return html`
      ${repeat(
        visibleActive,
        (entry) => entry.id,
        (entry) => this.renderToast(entry, hiddenCount),
      )}
    `
  }

  /**
   * Рендерит группу тостов для определенной позиции на экране
   * Если тостов больше maxVisible, показывает только последний с счетчиком
   * @protected
   * @returns Lit-шаблон группы тостов
   */
  protected renderToastGroup() {
    return html`
      <div
        class="${this.baseClass}__container"
        data-pos=${this.config.position}
        @mouseenter=${this.onMouseEnter}
        @mouseleave=${this.onMouseLeave}
      >
        ${this.renderToasts()}
      </div>
    `
  }

  protected updated(changedProperties: Map<string, unknown>) {
    const nextIsMobile = this.breakpoints.smallerOrEqual('XS')
    if (this.isMobile !== nextIsMobile) {
      this.isMobile = nextIsMobile
      this.updateVisibleToasts()
    }

    if (changedProperties.has('items')) {
      this.scheduleAnimations()
    }
  }

  disconnectedCallback() {
    super.disconnectedCallback()

    if (this.animationFrameId !== null) {
      cancelAnimationFrame(this.animationFrameId)
      this.animationFrameId = null
    }

    for (const el of Array.from(this.toastWrappers)) {
      const animation = this.moveAnimations.get(el)
      if (animation) animation.cancel()
    }
    this.moveAnimations = new WeakMap()
  }

  private scheduleAnimations() {
    if (this.animationFrameId !== null) return
    this.animationFrameId = requestAnimationFrame(() => {
      this.animationFrameId = null
      this.runAnimations()
    })
  }

  private captureBeforeUpdate() {
    if (!this.toastWrappers.length) {
      this.pendingFirstRects = null
      this.pendingPrevElements = null
      return
    }

    const firstRects = new Map<string, DOMRect>()
    const prevElements = new Map<string, HTMLElement>()

    for (const el of Array.from(this.toastWrappers)) {
      const id = el.dataset.id
      if (!id) continue
      firstRects.set(id, el.getBoundingClientRect())
      prevElements.set(id, el)
    }

    this.pendingFirstRects = firstRects
    this.pendingPrevElements = prevElements
  }

  private runAnimations() {
    const firstRects = this.pendingFirstRects
    const prevElements = this.pendingPrevElements

    this.pendingFirstRects = null
    this.pendingPrevElements = null

    const container = this.containerEl ?? null
    if (!container) return

    const pos = this.config.position
    const offset = pos.startsWith('top-') ? -16 : 16
    const isOverflow = this.items.length > this.maxVisible
    if (isOverflow) return

    const { currentIds, currentElements } = this.collectCurrentElements()
    this.animateLeaving(prevElements, currentIds, firstRects, offset)
    this.animateMoveAndEnter(currentElements, firstRects, offset)
  }

  private collectCurrentElements() {
    const currentIds = new Set<string>()
    const currentElements = new Map<string, HTMLElement>()

    for (const el of Array.from(this.toastWrappers)) {
      const id = el.dataset.id
      if (!id) continue
      currentIds.add(id)
      currentElements.set(id, el)
    }

    return { currentIds, currentElements }
  }

  private animateLeaving(
    prevElements: Map<string, HTMLElement> | null,
    currentIds: Set<string>,
    firstRects: Map<string, DOMRect> | null,
    offset: number,
  ) {
    if (!prevElements) return

    for (const [id, prevEl] of prevElements) {
      if (currentIds.has(id)) continue
      const prevRect = firstRects?.get(id)
      this.animateLeave(prevEl, offset, prevRect ?? null)
    }
  }

  private animateMoveAndEnter(
    currentElements: Map<string, HTMLElement>,
    firstRects: Map<string, DOMRect> | null,
    offset: number,
  ) {
    for (const [id, el] of currentElements) {
      const first = firstRects?.get(id)
      if (!first) {
        this.animateEnter(el, offset)
        continue
      }

      this.animateMoveIfNeeded(el, first)
    }
  }

  private animateMoveIfNeeded(el: HTMLElement, firstRect: DOMRect) {
    const last = el.getBoundingClientRect()
    const dy = firstRect.top - last.top
    if (!dy) return
    this.animateMove(el, dy)
  }

  private animateMove(el: HTMLElement, dy: number) {
    const prev = this.moveAnimations.get(el)
    if (prev) prev.cancel()
    const animation = el.animate(
      [
        { transform: `translateY(${dy}px)` },
        { transform: 'translateY(0)' },
      ],
      { duration: 200, easing: 'ease' },
    )
    this.moveAnimations.set(el, animation)
  }

  private animateEnter(el: HTMLElement, offset: number) {
    el.animate(
      [
        { opacity: 0, transform: `translateY(${offset}px) scale(0.98)` },
        { opacity: 1, transform: 'translateY(0) scale(1)' },
      ],
      { duration: 250, easing: 'cubic-bezier(0.4, 0.0, 0.2, 1)' },
    )
  }

  private animateLeave(el: HTMLElement, offset: number, rect: DOMRect | null) {
    const rectToUse = rect ?? el.getBoundingClientRect()

    const prev = this.moveAnimations.get(el)
    if (prev) prev.cancel()

    el.style.position = 'fixed'
    el.style.width = `${rectToUse.width}px`
    el.style.height = `${rectToUse.height}px`
    el.style.left = `${rectToUse.left}px`
    el.style.top = `${rectToUse.top}px`
    el.style.pointerEvents = 'none'
    el.style.transform = 'translateY(0)'
    el.style.opacity = '1'

    this.renderRoot.appendChild(el)

    const leave = el.animate(
      [
        { opacity: 1, transform: 'translateY(0)' },
        { opacity: 0, transform: `translateY(${offset}px)` },
      ],
      { duration: TOAST_ENTER_LEAVE_DURATION_MS, easing: 'ease' },
    )

    const cleanup = () => {
      clearTimeout(safetyTimeout)
      el.remove()
    }

    const safetyTimeout = setTimeout(
      cleanup,
      TOAST_ENTER_LEAVE_DURATION_MS + 100,
    )

    leave.addEventListener('finish', cleanup, { once: true })
    leave.addEventListener('cancel', cleanup, { once: true })
  }

  /**
   * Основной метод рендеринга Lit-элемента
   * @protected
   * @returns Lit-шаблон всего хоста или nothing, если нет активных модулей
   */
  protected render() {
    if (!this.module && this.leavingItems.size === 0) return nothing

    return html`${this.renderToastGroup()}`
  }
}

declare global {
  interface HTMLElementTagNameMap {
    [YCoreToastQueueHostTagName]: YCoreToastQueueHost
  }
}
