import { uid } from 'radash'
import type { IYCoreToastExternalProps } from '~core/ui/toast/models/types'
import { createCoreToastExternalProps } from '~core/ui/toast/models/types'
import { QueueModule, type IQueueModule, type IQueueModuleItem } from './QueueModule'
import { YCoreToastQueueHostTagName } from '~shared/constants'
import type { IToastQueueHost } from '../../plugins/toasts'

/**
 * Позиция тоста на экране
 */
export type TToastQueuePosition =
  | 'top-left' |
  'top-center' |
  'top-right' |
  'bottom-left' |
  'bottom-center' |
  'bottom-right'

/**
 * Параметры создания тоста
 */
export interface IToastOptions extends Omit<IYCoreToastExternalProps, 'description' | 'maxWidth' | 'counterValue'> {

  /** Уникальный идентификатор тоста */
  id?: string

  /** Требуется ручное закрытие (отключает автозакрытие) */
  manualClose?: boolean

  /** Приостанавливать ли таймер при наведении */
  pauseOnHover?: boolean

  /** Описание (текст) тоста */
  description?: string

  /** Максимальная ширина тоста */
  maxWidth?: string

  /** Значение счетчика */
  counterValue?: number
}

/**
 * Параметры тоста, используемые внутри очереди
 */
export interface IToastItem extends IToastOptions {

  /** Длительность отображения тоста в мс */
  duration?: number

  /** Позиция тоста */
  position: TToastQueuePosition
}

/**
 * Элемент очереди тостов
 */
export interface IToastQueueModuleItem extends IQueueModuleItem {

  /** Параметры тоста */
  toast: IToastItem
}

/**
 * Интерфейс модуля очереди тостов
 */
export interface IToastQueueModule extends IQueueModule {

  /**
   * Добавить тост в очередь
   * @param options Параметры тоста
   * @returns Объект для управления тостом
   */
  notify: (options: IToastOptions) => IToastHandle

  /**
   * Получить текущую конфигурацию очереди
   */
  getConfig: () => IToastQueueConfig

  /**
   * Обновить конфигурацию очереди
   * @param config Частичная конфигурация
   */
  updateConfig: (config: Partial<IToastQueueConfig>) => void

  /**
   * Получить хост-элемент для рендеринга тостов
   */
  getHost: () => IToastQueueHost | null

  /**
   * Уничтожить хост-элемент
   */
  destroyHost: () => void

  /**
   * Ставит на паузу удаление всех тостов
   */
  pauseAll: () => void

  /**
   * Возвращает с паузы удаление всех тостов
   */
  resumeAll: () => void

  /**
   * Устанавливает набор видимых тостов для управления таймерами
   * @param visibleIds Набор ID видимых тостов
   * @param pauseForHover Признак паузы по наведению
   * @param durationOverrides Переопределения длительности показа для конкретных тостов
   */
  setVisibleIds: (
    visibleIds: Set<string>,
    pauseForHover?: boolean,
    durationOverrides?: ReadonlyMap<string, number> | null,
  ) => void
}

/**
 * Объект для управления созданным тостом
 */
export interface IToastHandle extends IToastOptions {

  /** Закрыть тост */
  close: () => void

  /** Promise, который разрешается при закрытии тоста */
  onClose: Promise<void>
}

/**
 * Конфигурация очереди тостов
 */
export interface IToastQueueConfig {

  /** Максимальное количество одновременно видимых тостов */
  maxVisible: number

  /** Позиция тостов по умолчанию */
  position: TToastQueuePosition

  /** Длительность отображения по умолчанию в мс */
  defaultDuration?: number

  /** Приостанавливать ли таймер при наведении по умолчанию */
  pauseOnHover?: boolean

  /** Селектор или идентификатор хоста */
  host?: string
}

/**
 * Модуль очереди тостов.
 * Отвечает за управление отображением уведомлений (тостов).
 *
 * @class ToastQueueModule
 * @extends QueueModule
 * @implements {IToastQueueModule}
 */
export class ToastQueueModule extends QueueModule implements IToastQueueModule {
  /** Конфигурация модуля */
  #config: IToastQueueConfig

  /** Обработчики закрытия тостов */
  #closeHandlers = new Map<string, () => void>()

  /** Хост-элемент для рендеринга */
  #host: IToastQueueHost | null = null

  /** Набор видимых тостов для управления таймерами */
  #visibleIds = new Set<string>()

  /** Переопределенные длительности показа для отдельных тостов */
  #durationOverrides = new Map<string, number>()

  /**
   * @param id Идентификатор модуля
   * @param config Конфигурация очереди
   */
  constructor(id: string, config: IToastQueueConfig) {
    super({ id })
    this.#config = { ...config }
  }

  /**
   * Генерация уникального идентификатора
   * @private
   */
  #uid(): string {
    return uid(20)
  }

  /**
   * Добавить тост в очередь
   * @param options Параметры тоста
   * @returns Объект для управления тостом
   */
  notify(options: IToastOptions): IToastHandle {
    const id = options.id ?? this.#uid()

    let resolveOnClose: (() => void) | null = null
    const onClose = new Promise<void>((resolve) => {
      resolveOnClose = resolve
    })

    const close = () => {
      this.removeItem(id)
      resolveOnClose?.()
      resolveOnClose = null
    }

    this.#closeHandlers.set(id, () => {
      resolveOnClose?.()
      resolveOnClose = null
    })

    const item: IToastQueueModuleItem = {
      id,
      toast: {
        ...createCoreToastExternalProps(),
        ...options,
        duration: this.#config.defaultDuration,
        position: this.#config.position,
        pauseOnHover: options.pauseOnHover ?? this.#config.pauseOnHover,
      },
    }

    const duration = this.#getItemDuration(item)
    this.putItem(item, item.toast.manualClose ? 0 : duration)

    return { ...options, close, onClose }
  }

  /**
   * Удалить тост из очереди по ID
   * @param id Идентификатор тоста
   * @returns Удаленный ID
   */
  removeItem(id: string): string {
    const closeHandler = this.#closeHandlers.get(id)

    if (closeHandler) {
      closeHandler()
      this.#closeHandlers.delete(id)
    }

    this.#durationOverrides.delete(id)

    return super.removeItem(id)
  }

  /**
   * Очистить всю очередь тостов
   * @param callback Функция обратного вызова
   */
  clearAll(callback?: () => void): void {
    this.#closeHandlers.forEach((handler) => { handler() })
    this.#closeHandlers.clear()
    this.#durationOverrides.clear()
    super.clearAll(callback)
  }

  /**
   * Получить текущую конфигурацию
   */
  getConfig(): IToastQueueConfig {
    return { ...this.#config }
  }

  /**
   * Обновить конфигурацию
   * @param config Новые параметры конфигурации
   */
  updateConfig(config: Partial<IToastQueueConfig>): void {
    this.#config = {
      ...this.#config,
      ...config,
    }
  }

  /**
   * Создает или возвращает существующий хост-элемент
   * @returns Элемент хоста тостов
   */
  createHost(): IToastQueueHost {
    if (!this.#host) {
      this.#host = document.createElement(YCoreToastQueueHostTagName) as IToastQueueHost
    }

    return this.#host
  }

  /**
   * Уничтожает хост-элемент
   */
  destroyHost(): void {
    if (this.#host) {
      this.#host.destroy()
      this.#host = null
    }
  }

  /**
   * Возвращает текущий хост-элемент
   * @returns Хост-элемент или null
   */
  getHost(): IToastQueueHost | null {
    return this.#host
  }

  /**
   * Ставит на паузу удаление всех видимых тостов
   */
  pauseAll() {
    this.#visibleIds.forEach((id) => {
      this.pauseItem(id)
    })
  }

  /**
   * Возвращает с паузы удаление всех видимых тостов
   */
  resumeAll() {
    this.#visibleIds.forEach((id) => {
      this.#resumeVisibleItem(id)
    })
  }

  /**
   * Возобновляет или перезапускает таймер для видимого тоста
   * @param id Идентификатор тоста
   */
  #resumeVisibleItem(id: string): void {
    const item = this.getItem(id) as IToastQueueModuleItem | undefined
    if (!item) return

    if (item.pausedAt !== undefined && item.remainingTime !== undefined) {
      this.resumeItem(id)
      return
    }

    if (!item.timeout && !item.toast.manualClose) {
      const duration = this.#getItemDuration(item)
      this.restartItemTimer(id, duration)
    }
  }

  /**
   * Получить длительность отображения тоста
   * @param item Элемент очереди тостов
   * @returns Длительность в мс
   */
  #getItemDuration(item: IToastQueueModuleItem): number {
    const overrideDuration = this.#durationOverrides.get(item.id)
    if (overrideDuration !== undefined) return overrideDuration

    return item.toast.duration ?? this.#config.defaultDuration ?? 0
  }

  /**
   * Синхронизирует таймер конкретного видимого тоста
   * @param id Идентификатор тоста
   * @param pauseForHover Признак паузы по наведению
   */
  #syncVisibleItem(id: string, pauseForHover: boolean): void {
    const item = this.getItem(id) as IToastQueueModuleItem | undefined
    if (!item || item.toast.manualClose) return

    if (pauseForHover) {
      this.resetItemTimer(id)
      return
    }

    this.#resumeVisibleItem(id)
  }

  /**
   * Устанавливает набор видимых тостов для управления таймерами
   * @param visibleIds Набор ID видимых тостов
   * @param pauseForHover Признак паузы по наведению
   */
  setVisibleIds(
    visibleIds: Set<string>,
    pauseForHover = false,
    durationOverrides?: ReadonlyMap<string, number> | null,
  ) {
    const prevVisibleIds = this.#visibleIds
    const nextVisibleIds = new Set(visibleIds)

    if (durationOverrides && durationOverrides.size > 0) {
      durationOverrides.forEach((duration, id) => {
        this.#durationOverrides.set(id, duration)
      })
    }

    prevVisibleIds.forEach((id) => {
      if (!nextVisibleIds.has(id)) {
        this.resetItemTimer(id)
      }
    })

    nextVisibleIds.forEach((id) => {
      this.#syncVisibleItem(id, pauseForHover)
    })

    this.#visibleIds = nextVisibleIds
  }
}
