import { LitElement, css, html, unsafeCSS } from 'lit'
import { customElement } from 'lit/decorators.js'

import { YCoreBadgeTagName as tagName } from '~shared/constants'
import { YC_COMPONENT_ATTRIBUTE_NAME } from '~web/shared/constants/attributes'
import { type IYCoreBadgeProps } from '~core/ui/badge/models/types'

import YCoreBadgeVarsCSS from '~core/ui/badge/css/Badge.vars.css?inline'
import YCoreBadgeScopedCSS from '~core/ui/badge/css/Badge.scoped.css?inline'

@customElement(tagName)
export class YCoreBadge extends LitElement implements Required<IYCoreBadgeProps> {
  private readonly baseClass = tagName

  static readonly styles = [
    css`${unsafeCSS(YCoreBadgeVarsCSS)}`,
    css`${unsafeCSS(YCoreBadgeScopedCSS)}`,
  ]

  connectedCallback() {
    super.connectedCallback()
    this.dataset[YC_COMPONENT_ATTRIBUTE_NAME] = ''
  }

  protected render() {
    return html`<span class=${this.baseClass}></span>`
  }
}
