import type { PropertyValues } from 'lit'
import { LitElement, html, css, unsafeCSS } from 'lit'
import { customElement, property } from 'lit/decorators.js'
import { classMap } from 'lit/directives/class-map.js'

import { createCoreTextProps, type IYCoreTextProps } from './models/types'
import { Events, type OverflowChangeEvent } from './models/types/events'
import { YCoreTextTagName as tagName } from '~shared/constants'
import { YC_COMPONENT_ATTRIBUTE_NAME } from '~web/shared/constants/attributes'

import YCoreTextScopedCss from '~core/ui/text/css/Text.scoped.css?inline'
import YCoreTextVarsCss from '~core/ui/text/css/Text.vars.css?inline'
import type { TDispatcher } from '~core/utils/event-decorator'
import { defineCustomElement } from '~web/shared/utils/components'

const { size, variant, ellipsis, lineclamp, trackOverflow, locator } = createCoreTextProps()

@customElement(tagName)
export class YCoreText extends LitElement implements Required<IYCoreTextProps> {
  @property({ type: String, reflect: true }) size: IYCoreTextProps['size'] = size
  @property({ type: String, reflect: true }) variant: IYCoreTextProps['variant'] = variant
  @property({ type: Boolean }) ellipsis: IYCoreTextProps['ellipsis'] = ellipsis
  @property({ type: Number }) lineclamp: IYCoreTextProps['lineclamp'] = lineclamp
  @property({ type: String }) locator: IYCoreTextProps['locator'] = locator
  @property({ type: Boolean, attribute: 'track-overflow' }) trackOverflow: IYCoreTextProps['trackOverflow'] = trackOverflow

  @Events.overflowChange private _overflowChange!: TDispatcher<OverflowChangeEvent>

  private readonly baseClass = tagName
  private rootElement: HTMLElement | null = null
  private resizeObserver: ResizeObserver | null = null
  private mutationObserver: MutationObserver | null = null
  private _hasOverflow = false
  private _checkScheduled: number | null = null

  static readonly styles = [
    css`
      ${unsafeCSS(YCoreTextVarsCss)}
      ${unsafeCSS(YCoreTextScopedCss)}
    `,
  ]

  private get computedClasses() {
    return {
      [this.baseClass]: true,
      [`${this.baseClass}_size_${this.size}`]: Boolean(this.size),
      [`${this.baseClass}_variant_${this.variant}`]: Boolean(this.variant),
      [`${this.baseClass}_ellipsis`]: Boolean(this.ellipsis),
    }
  }

  private get computedLineclamp() {
    return this.lineclamp ? `-webkit-line-clamp: ${this.lineclamp};` : ''
  }

  private scheduleCheckOverflow() {
    if (!this.trackOverflow) return
    if (this._checkScheduled !== null) return
    this._checkScheduled = requestAnimationFrame(() => {
      this._checkScheduled = null
      this.checkOverflow()
    })
  }

  private firstScheduleCheckOverflow = async() => {
    // Свойству lineclamp требуется несколько кадров для стабилизации контента после рендера.
    // Если текст изначально переполнен, на первых кадрах переполнение может не определяться,
    // поэтому компонент не сгенерирует событие и будет ждать следующего изменения текста.
    // 4 кадра подобраны эмпирически — за это время браузер успевает применить line-clamp
    // и рассчитать актуальные размеры элемента.
    await new Promise(requestAnimationFrame)
    await new Promise(requestAnimationFrame)
    await new Promise(requestAnimationFrame)
    await new Promise(requestAnimationFrame)

    this.scheduleCheckOverflow()
  }

  private cancelScheduledCheck() {
    if (this._checkScheduled !== null) {
      cancelAnimationFrame(this._checkScheduled)
      this._checkScheduled = null
    }
  }

  private destroyObservers() {
    this.cancelScheduledCheck()
    this.resizeObserver?.disconnect()
    this.resizeObserver = null
    this.mutationObserver?.disconnect()
    this.mutationObserver = null
  }

  private checkOverflow = () => {
    if (!this.trackOverflow || !this.rootElement) return

    const hasOverflow = this.rootElement.scrollHeight > this.rootElement.clientHeight

    if (hasOverflow !== this._hasOverflow) {
      this._hasOverflow = hasOverflow
      this._overflowChange({ detail: { value: hasOverflow } })
    }
  }

  private syncObservers() {
    if (!this.shouldEnableObservers()) {
      this.destroyObservers()
      return
    }

    this.ensureMutationObserver()
    this.ensureResizeObserver()
  }

  private shouldEnableObservers(): boolean {
    return Boolean(this.trackOverflow) && this.isConnected
  }

  private ensureMutationObserver() {
    if (this.mutationObserver) return
    this.createMutationObserver()
  }

  private createMutationObserver() {
    this.mutationObserver = new MutationObserver(() => { this.scheduleCheckOverflow() })
    this.mutationObserver.observe(this, {
      childList: true,
      subtree: true,
      characterData: true,
    })
  }

  private ensureResizeObserver() {
    if (!this.rootElement || this.resizeObserver) return
    this.createResizeObserver()
    this.scheduleCheckOverflow()
  }

  private createResizeObserver() {
    if (!this.rootElement) return

    this.resizeObserver = new ResizeObserver(() => { this.scheduleCheckOverflow() })
    this.resizeObserver.observe(this.rootElement)
  }

  connectedCallback() {
    super.connectedCallback()
    this.syncObservers()
    this.dataset.locator = this.locator ?? tagName
    this.dataset[YC_COMPONENT_ATTRIBUTE_NAME] = ''
  }

  disconnectedCallback() {
    this.destroyObservers()
    super.disconnectedCallback()
  }

  protected willUpdate(changedProperties: PropertyValues) {
    super.willUpdate(changedProperties)

    if (changedProperties.has('locator')) {
      this.dataset.locator = this.locator ?? tagName
    }
  }

  protected firstUpdated(): void {
    const rootElement = this.shadowRoot?.querySelector(`.${this.baseClass}`)

    if (rootElement) {
      this.rootElement = rootElement as HTMLElement

      if (this.trackOverflow && !this.resizeObserver) {
        this.createResizeObserver()
      }

      this.firstScheduleCheckOverflow()
    }

    defineCustomElement(tagName, YCoreText)
  }

  protected updated(changedProperties: PropertyValues) {
    super.updated(changedProperties)

    if (changedProperties.has('trackOverflow')) {
      this.syncObservers()
    }

    if (this.trackOverflow) {
      this.scheduleCheckOverflow()
    }
  }

  protected render() {
    return html`<span class=${classMap(this.computedClasses)} style=${this.computedLineclamp}><slot></slot></span>`
  }
}
