import type { MaskitoOptions } from '@maskito/core'

/**
 * Маска, которая на каждый ввод сама выбирает один из вариантов по значению поля.
 *
 * Саму форму маски maskito и так умеет переключать через `mask: () => ...`. Обёртка
 * нужна только из-за процессоров: если варианты приходят из генераторов
 * (напр. maskitoDateOptionsGenerator) со своими preprocessors/postprocessors —
 * их maskito на лету менять не умеет. Поэтому выбираем вариант через resolver и
 * прогоняем его процессоры цепочкой (каждый возвращает только изменённые поля).
 *
 * @param resolver Какую маску использовать для текущего значения.
 */
export function createDynamicMask(resolver: (value: string) => Required<MaskitoOptions>): MaskitoOptions {
  return {
    mask: (state) => {
      const { mask } = resolver(state.value)

      return typeof mask === 'function'
        ? mask(state)
        : mask
    },

    preprocessors: [
      (input, actionType) => resolver(input.elementState.value)
        .preprocessors.reduce((acc, run) => ({ ...acc, ...run(acc, actionType) }), input),
    ],
    postprocessors: [
      (state, initialState) => resolver(state.value)
        .postprocessors.reduce((acc, run) => ({ ...acc, ...run(acc, initialState) }), state),
    ],
  }
}
