import type { Placement } from '~shared/utils/floating-ui'

import type { IYIcon } from '~shared/icons'

import {
  type IYCoreSimpleButtonExternalProps,
  createCoreSimpleButtonExternalProps,
  EYCoreSimpleButtonVariant,
} from '~core/ui/simpleButton/models/types'
import type { IYCoreCounterExternalProps } from '../../../counter/models/types'

export interface IYCoreIconButtonBadgeIndicator {
  type: 'badge'
}

export interface IYCoreIconButtonCounterIndicator
  extends Pick<IYCoreCounterExternalProps, 'value'>,
  Partial<Pick<IYCoreCounterExternalProps, 'maxValue'>> {
  type: 'counter'
}

export type TYCoreIconButtonIndicator = IYCoreIconButtonBadgeIndicator | IYCoreIconButtonCounterIndicator

export type TYCoreIconButtonVariant = Exclude<IYCoreSimpleButtonExternalProps['variant'], `${EYCoreSimpleButtonVariant.OUTLINE}`>

export interface IYCoreIconButtonExternalProps extends Omit<IYCoreSimpleButtonExternalProps, 'hostStyles' | 'alignment' | 'variant'> {
  icon: IYIcon | undefined
  indicator: TYCoreIconButtonIndicator | undefined
  active: boolean
  variant: TYCoreIconButtonVariant
  tooltipText: string | undefined
  tooltipPlacement: Placement | undefined
}

export const createCoreIconButtonExternalProps = (): IYCoreIconButtonExternalProps => {
  const { disabled, loading, size, href, target, fullWidth } = createCoreSimpleButtonExternalProps()
  return {
    disabled,
    loading,
    size,
    variant: EYCoreSimpleButtonVariant.PRIMARY,
    href,
    target,
    fullWidth,
    icon: undefined,
    indicator: undefined,
    active: false,
    tooltipText: undefined,
    tooltipPlacement: undefined,
  }
}
