import { LitElement, html, css, unsafeCSS } from 'lit'
import { customElement, property, state } from 'lit/decorators.js'
import { classMap } from 'lit/directives/class-map.js'
import { unsafeSVG } from 'lit/directives/unsafe-svg.js'

import { type TDispatcher, bubblingEvent } from '~core/utils/event-decorator'

import { YCoreLoaderTagName as tagName } from '~shared/constants'
import { YC_COMPONENT_ATTRIBUTE_NAME } from '~web/shared/constants/attributes'
import { yLoader } from '~shared/icons/build/y-loader.icon'

import YCoreLoaderVarsCss from '~core/ui/loader/css/Loader.vars.css?inline'
import YCoreLoaderScopedCss from '~core/ui/loader/css/Loader.scoped.css?inline'
import {
  createCoreLoaderProps,
  LoaderHideEvent,
  LoaderShowEvent,
  type IYCoreLoaderProps,
} from '~core/ui/loader/models/types'
import { DELAY_BEFORE_SHOW, MIN_SHOW_TIME } from '~core/ui/loader/models/constants'
import { defineCustomElement } from '~web/shared/utils/components'

const { size, variant, isVisible } = createCoreLoaderProps()

@customElement(tagName)
export class YCoreLoader extends LitElement implements Required<IYCoreLoaderProps> {
  @property({ type: String, reflect: true }) size: IYCoreLoaderProps['size'] = size
  @property({ type: String, reflect: true }) variant: IYCoreLoaderProps['variant'] = variant
  @property({ type: Boolean, reflect: true, attribute: 'is-visible' }) isVisible: IYCoreLoaderProps['isVisible'] = isVisible

  @state() private isVisibleLocal = false

  private readonly baseClass = tagName

  private showTimer: ReturnType<typeof setTimeout> | null = null
  private hideTimer: ReturnType<typeof setTimeout> | null = null
  private shownAt: number | null = null

  @bubblingEvent(
    LoaderHideEvent,
    { name: 'hide' },
  )
  _loaderHide!: TDispatcher<LoaderHideEvent>

  @bubblingEvent(
    LoaderShowEvent,
    { name: 'show' },
  )
  _loaderShow!: TDispatcher<LoaderShowEvent>

  static readonly styles = [
    css`${unsafeCSS(YCoreLoaderVarsCss)}`,
    css`${unsafeCSS(YCoreLoaderScopedCss)}`,
  ]

  private get computedClasses() {
    return {
      [this.baseClass]: true,
      [`${this.baseClass}_size_${this.size}`]: Boolean(this.size),
      [`${this.baseClass}_variant_${this.variant}`]: Boolean(this.variant),
    }
  }

  private show() {
    if (this.showTimer) clearTimeout(this.showTimer)
    if (this.hideTimer) clearTimeout(this.hideTimer)

    if (this.isVisibleLocal) return

    this.showTimer = setTimeout(() => {
      this.isVisibleLocal = true
      this.shownAt = Date.now()
      this.showTimer = null
      this._loaderShow()
    }, DELAY_BEFORE_SHOW)
  }

  private hide() {
    if (this.showTimer) {
      clearTimeout(this.showTimer)
      this.showTimer = null
      return
    }

    if (this.isVisibleLocal && this.shownAt) {
      const elapsed = Date.now() - this.shownAt
      const remaining = Math.max(MIN_SHOW_TIME - elapsed, 0)

      if (this.hideTimer) clearTimeout(this.hideTimer)

      this.hideTimer = setTimeout(() => {
        this.isVisibleLocal = false
        this.shownAt = null
        this.hideTimer = null
        this._loaderHide()
      }, remaining)

      return
    }

    this.isVisibleLocal = false
    this.shownAt = null
    this._loaderHide()
  }

  updated(changedProps: Map<string, unknown>) {
    if (changedProps.has('isVisible')) {
      if (this.isVisible) {
        this.show()

        return
      }

      this.hide()
    }
  }

  connectedCallback() {
    super.connectedCallback()

    this.dataset.locator = tagName
    this.dataset[YC_COMPONENT_ATTRIBUTE_NAME] = ''
  }

  protected firstUpdated(): void {
    defineCustomElement(tagName, YCoreLoader)
  }

  protected render() {
    return html`
      <div class=${classMap(this.computedClasses)}>
        ${this.isVisibleLocal ? unsafeSVG(yLoader.data) : null}
      </div>
    `
  }
}
