import { YCoreTextTagName } from '~shared/constants'

export enum EYCoreTextSize {
  H1_SEMIBOLD = 'h1-semibold',
  H2_SEMIBOLD = 'h2-semibold',
  H3_SEMIBOLD = 'h3-semibold',
  H4_SEMIBOLD = 'h4-semibold',
  P0_REGULAR = 'p0-regular',
  P1_REGULAR = 'p1-regular',
  P1_MEDIUM = 'p1-medium',
  P2_REGULAR = 'p2-regular',
  P2_MEDIUM = 'p2-medium',
  S1_MEDIUM = 's1-medium',
  S1_SEMIBOLD = 's1-semibold',
  A1_REGULAR = 'a1-regular',
  A1_MEDIUM = 'a1-medium',
  A2_REGULAR = 'a2-regular',
  A2_MEDIUM = 'a2-medium',
  A3_MEDIUM = 'a3-medium',
  A4_MEDIUM = 'a4-medium',
}

export enum EYCoreTextVariant {
  PRIMARY = 'primary',
  SECONDARY = 'secondary',
  TERTIARY = 'tertiary',
  POSITIVE = 'positive',
  NEGATIVE = 'negative',
  WARNING = 'warning',
  ACCENT = 'accent',
  ACCENT_HIGH = 'accent-high',
  PRIMARY_INVERT = 'primary-invert',
  SECONDARY_INVERT = 'secondary-invert',
  INHERIT = 'inherit',
}

export enum EYCoreTextBreakModes {
  BREAK_WORD = 'break-word',
  BREAK_ALL = 'break-all',
  UNSET = 'unset',
}

export type TYCoreTextSize = `${EYCoreTextSize}`
export type TYCoreTextVariant = `${EYCoreTextVariant}`

/**
 * Свойства компонента Text
 */
export interface IYCoreTextExternalProps {

  /**
   * Размер текста
   * @default 'p2-regular'
   */
  size: TYCoreTextSize | undefined

  /**
   * Стиль текста
   * @default 'primary'
   */
  variant: TYCoreTextVariant | undefined

  /**
   * Ограничение длины текста с многоточием
   * @default false
   */
  ellipsis: boolean | undefined

  /**
   * Количество строк при ограничении длины текста (работает вместе с ellipsis).
   * Если не задан — количество строк определяется CSS-переменной `--y-core-text-line-clamp` (по умолчанию 1).
   * @default undefined
   */
  lineclamp: number | undefined

  /**
   * Управляет отслеживанием overflow у текста
   * @default false
   */
  trackOverflow: boolean | undefined

  /**
   * Вспомогательный дата-атрибут для реализации BB-тестов
   * @default 'y-core-text'
   */
  locator: string | undefined
}

export const createCoreTextExternalProps = (): IYCoreTextExternalProps => {
  return {
    size: EYCoreTextSize.P2_REGULAR,
    variant: EYCoreTextVariant.PRIMARY,
    ellipsis: false,
    lineclamp: undefined,
    trackOverflow: false,
    locator: YCoreTextTagName,
  }
}
