import { LitElement, html, css, unsafeCSS, nothing } from 'lit'
import { customElement, property, state } from 'lit/decorators.js'
import { classMap } from 'lit/directives/class-map.js'

import {
  createCoreBannerProps,
  type IYCoreBannerProps,
  EYCoreBannerVariant,
} from './models/types'
import {
  YCoreBannerTagName as tagName,
} from '~shared/constants'
import { YC_COMPONENT_ATTRIBUTE_NAME } from '~web/shared/constants/attributes'

import { bubblingEvent, type TDispatcher } from '~core/utils/event-decorator'
import { CloseEmitEvent, PrimaryButtonClickEmitEvent } from '~core/ui/simpleBanner/models/types/events'
import { EYCoreTextSize, EYCoreTextVariant } from '~core/ui/text/models/types/external'

import YBannerVarsCss from './css/Banner.vars.css?inline'
import YBannerScopedCss from './css/Banner.scoped.css?inline'
import '~core/ui/simpleBanner'
import '~core/ui/icon'
import { yInfo, yWarning } from '~shared/icons'
import { renderIcon } from '~core/renderers'
import { preventAndStopEvent } from '~web/shared/utils/helpers'

const {
  description,
  primaryButtonText,
  variant,
  open,
  hideCloseIcon,
} = createCoreBannerProps()

@customElement(tagName)
export class YCoreBanner
  extends LitElement
  implements Required<IYCoreBannerProps> {
  @property({ type: String }) description: IYCoreBannerProps['description'] = description
  @property({ type: String, reflect: true }) variant: IYCoreBannerProps['variant'] = variant
  @property({ type: String, attribute: 'primary-button-text' }) primaryButtonText: IYCoreBannerProps['primaryButtonText'] = primaryButtonText
  @property({ type: Boolean, reflect: true }) open: IYCoreBannerProps['open'] = open
  @property({ type: Boolean, reflect: true, attribute: 'hide-close-icon' }) hideCloseIcon: IYCoreBannerProps['hideCloseIcon'] = hideCloseIcon
  @state() private hasMediaSlot = false
  @state() private hasActionsSlot = false

  @bubblingEvent(
    CloseEmitEvent,
    { name: 'close' },
  )
  _close!: TDispatcher<CloseEmitEvent>

  @bubblingEvent(
    PrimaryButtonClickEmitEvent,
    { name: 'primary-button-click' },
  )
  _primaryButtonClick!: TDispatcher<PrimaryButtonClickEmitEvent>

  private readonly baseClass = tagName

  connectedCallback() {
    super.connectedCallback()
    this.dataset.locator = tagName
    this.dataset[YC_COMPONENT_ATTRIBUTE_NAME] = ''
  }

  static readonly styles = [
    css`
      ${unsafeCSS(YBannerVarsCss)}
      ${unsafeCSS(YBannerScopedCss)}
    `,
  ]

  private get computedClasses() {
    return {
      [this.baseClass]: true,
      [`${this.baseClass}_variant_${this.variant}`]: Boolean(this.variant),
      [`${this.baseClass}_closable`]: !this.hideCloseIcon,
    }
  }

  private get shouldRenderMediaSlot() {
    return this.hasMediaSlot
  }

  private get shouldRenderIcon() {
    return !this.hasMediaSlot
  }

  private get shouldRenderActionsSlot() {
    return this.hasActionsSlot
  }


  private renderIcon() {
    if (!this.variant) {
      return nothing
    }

    const iconMap: Record<EYCoreBannerVariant, typeof yInfo | typeof yWarning> = {
      [EYCoreBannerVariant.INFORMATION]: yInfo,
      [EYCoreBannerVariant.MARKETING]: yInfo,
      [EYCoreBannerVariant.WARNING]: yInfo,
      [EYCoreBannerVariant.ERROR]: yWarning,
      [EYCoreBannerVariant.NEUTRAL]: yInfo,
    }

    const icon = iconMap[this.variant]

    return html`
      <div slot="media" class="${this.baseClass}__icon">
        <div class="${this.baseClass}__icon-image">
          ${renderIcon({ icon, size: '24px' })}
        </div>
      </div>
    `
  }

  private handleMediaSlotChange = (event: Event) => {
    const slot = event.target as HTMLSlotElement | null
    if (!slot) {
      this.hasMediaSlot = false
      return
    }
    const assigned = slot.assignedElements({ flatten: true })
    this.hasMediaSlot = assigned.length > 0
  }

  private handleActionsSlotChange = (event: Event) => {
    const slot = event.target as HTMLSlotElement | null

    if (!slot) {
      this.hasActionsSlot = false
      return
    }
    const assigned = slot.assignedElements({ flatten: true })
    this.hasActionsSlot = assigned.length > 0
  }


  private handleClose = (event: Event) => {
    preventAndStopEvent(event)
    this._close()
  }

  private handlePrimaryButtonClick = (event: Event) => {
    preventAndStopEvent(event)
    this._primaryButtonClick()
  }

  protected render() {
    if (!this.open) {
      return nothing
    }

    return html`
      <y-core-simple-banner
        class=${classMap(this.computedClasses)}
        .description=${this.description}
        .descriptionSize=${EYCoreTextSize.P2_REGULAR}
        .primaryButtonText=${this.primaryButtonText}
        .colorText=${this.variant === EYCoreBannerVariant.WARNING ? EYCoreTextVariant.PRIMARY_INVERT : undefined}
        .hideCloseIcon=${this.hideCloseIcon}
        @close=${this.handleClose}
        @primary-button-click=${this.handlePrimaryButtonClick}
        .truncateDescription=${true}
      >
        <slot
          slot="media"
          name="media"
          @slotchange=${this.handleMediaSlotChange}
          ?hidden=${!this.shouldRenderMediaSlot}
        ></slot>
        ${this.shouldRenderIcon ? this.renderIcon() : nothing}

        <slot
          name="actions"
          slot="actions"
          @slotchange=${this.handleActionsSlotChange}
          ?hidden=${!this.shouldRenderActionsSlot}
        ></slot>
      </y-core-simple-banner>
    `
  }
}
