import { createCoreLabelExternalProps, type IYCoreLabelExternalProps } from '~core/ui/label/models/types'

export enum EYCoreCheckboxGroupDirection {
  VERTICAL = 'vertical',
  HORIZONTAL = 'horizontal',
}

export type TYCoreCheckboxGroupDirection = `${EYCoreCheckboxGroupDirection}`

/**
 * Свойства компонента CheckboxGroup
 */
export interface IYCoreCheckboxGroupExternalProps {

  /**
   * Направление позиционирования
   * @default 'vertical'
   */
  direction: TYCoreCheckboxGroupDirection | undefined

  /**
   * Текст лейбла
   */
  labelText: IYCoreLabelExternalProps['text']

  /**
   * Выравнивание текста лейбла
   */
  labelAlignment: IYCoreLabelExternalProps['alignment']

  /**
   * Задержка для определения переполнения текста лейбла
   */
  labelOverflowDebounce: IYCoreLabelExternalProps['debounce']

  /**
   * Текст подсказки для лейбла
   */
  labelTooltipText: IYCoreLabelExternalProps['tooltipText']

  /**
   * Флаг, указывающий, что подсказка для лейбла доступна
   */
  labelTooltipActive: boolean | undefined

  /**
   * Позиция подсказки для метки
   */
  labelTooltipPlacement: IYCoreLabelExternalProps['tooltipPlacement']
}

export const createCoreCheckboxGroupExternalProps = (): IYCoreCheckboxGroupExternalProps => {
  const {
    text: labelText,
    alignment: labelAlignment,
    debounce: labelOverflowDebounce,
    tooltipText: labelTooltipText,
    tooltipPlacement: labelTooltipPlacement,
  } = createCoreLabelExternalProps()

  return {
    direction: EYCoreCheckboxGroupDirection.VERTICAL,
    labelText,
    labelAlignment,
    labelOverflowDebounce,
    labelTooltipText,
    labelTooltipActive: true,
    labelTooltipPlacement,
  }
}
